using System.Text.RegularExpressions;
using Sts2CharForge.Core.Effects;
using Sts2CharForge.Core.Profile;

namespace Sts2CharForge.Core.Generation;

/// <summary>把 profile 渲染成模组工程里的 C# 源码。</summary>
public static class CSharpCodeGen
{
    /// <summary>
    /// 全局 using。
    /// <paramref name="p"/> 给了就按这份配置裁剪：<c>Sts2CharForge.Pets</c> 那个命名空间是
    /// 「伙伴攻击」的扩展方法所在的命名空间，只有真的生成了 <c>cs/PetAttackExtensions.cs</c> 时才存在 ——
    /// 无脑 using 一个不存在的命名空间会直接 **CS0246**（编译不过）。
    /// 不给（null）时按旧行为全写出来。
    /// </summary>
    public static string GlobalUsings(CharacterProfile? p = null) => new CodeWriter()
        .Line("// <auto-generated> 由 Sts2CharForge 生成，改配置后会被覆盖 </auto-generated>")
        .Line("global using System;")
        .Line("global using System.Collections.Generic;")
        .Line("global using System.Linq;")
        .Line("global using System.Threading.Tasks;")
        .Line("global using Godot;")
        .Line("global using MegaCrit.Sts2.Core.Achievements;")
        .Line("global using MegaCrit.Sts2.Core.Combat;")
        .Line("global using MegaCrit.Sts2.Core.Combat.History.Entries;")
        .Line("global using MegaCrit.Sts2.Core.Commands;")
        .Line("global using MegaCrit.Sts2.Core.CardSelection;")
        .Line("global using MegaCrit.Sts2.Core.Entities.Ancients;")
        .Line("global using MegaCrit.Sts2.Core.Entities.Cards;")
        .Line("global using MegaCrit.Sts2.Core.Entities.Characters;")
        .Line("global using MegaCrit.Sts2.Core.Entities.Creatures;")
        .Line("global using MegaCrit.Sts2.Core.Entities.Players;")
        .Line("global using MegaCrit.Sts2.Core.Entities.Potions;")
        .Line("global using MegaCrit.Sts2.Core.Entities.Powers;")
        .Line("global using MegaCrit.Sts2.Core.Entities.Relics;")
        .Line("global using MegaCrit.Sts2.Core.GameActions.Multiplayer;")
        .Line("global using MegaCrit.Sts2.Core.Helpers;")
        .Line("global using MegaCrit.Sts2.Core.Localization;")
        .Line("global using MegaCrit.Sts2.Core.Localization.DynamicVars;")
        .Line("global using MegaCrit.Sts2.Core.Logging;")
        .Line("global using MegaCrit.Sts2.Core.Modding;")
        .Line("global using MegaCrit.Sts2.Core.Models;")
        .Line("global using MegaCrit.Sts2.Core.Models.CardPools;")
        .Line("global using MegaCrit.Sts2.Core.Models.Cards;")
        .Line("global using MegaCrit.Sts2.Core.Models.Characters;")
        .Line("global using MegaCrit.Sts2.Core.Models.Events;")
        .Line("global using MegaCrit.Sts2.Core.Models.PotionPools;")
        .Line("global using MegaCrit.Sts2.Core.Models.Powers;")
        .Line("global using MegaCrit.Sts2.Core.Models.RelicPools;")
        .Line("global using MegaCrit.Sts2.Core.Models.Relics;")
        // 召唤物的 MonsterModel 子类要写 GenerateMoveStateMachine（本体 Osty 的自循环空操作回合）
        .Line("global using MegaCrit.Sts2.Core.MonsterMoves.MonsterMoveStateMachine;")
        .Line("global using MegaCrit.Sts2.Core.Nodes.Combat;")
        .Line("global using MegaCrit.Sts2.Core.Nodes.Vfx;")
        .Line("global using MegaCrit.Sts2.Core.Rooms;")
        .Line("global using MegaCrit.Sts2.Core.Saves.Managers;")
        .Line("global using MegaCrit.Sts2.Core.Unlocks;")
        // 召唤物：「伙伴攻击」的扩展方法 FromPetAttacker 就在这个命名空间里。
        // 只有生成了 cs/PetAttackExtensions.cs 才有这个命名空间（using 一个不存在的命名空间 = CS0246）。
        .LineIf(p is null || PetGen.UsesAttackExtension(p), "global using Sts2CharForge.Pets;")
        .Line("global using MegaCrit.Sts2.Core.ValueProps;")
        .ToString();

    // ==================== 角色类 ====================
    public static string CharacterSource(CharacterProfile p)
    {
        var n = Naming.From(p);

        var deck = new List<string>();
        string outlineHex = Hex(p.Colors.EnergyOutlineColor, "802020");
        // 本体卡引用（卡牌页里那两条「打击 ×5 / 防御 ×5」）：直接写本体的英文类名。
        // 它们不生成自己的卡类（同名会和本体撞 ModelId → DuplicateModelException），只出现在初始卡组里。
        foreach (var vc in p.Cards.Where(c => c.IsVanillaCard))
        {
            string cls = (vc.ClassName ?? "").Trim();
            if (cls.Length == 0) continue;
            for (int k = 0; k < Math.Max(1, vc.StartingCopies); k++)
                deck.Add($"ModelDb.Card<{cls}>()");
        }
        for (int i = 0; i < p.Cards.Count; i++)
        {
            var c = p.Cards[i];
            if (c.IsVanillaCard) continue;
            if (!c.InStartingDeck) continue;
            for (int k = 0; k < Math.Max(1, c.StartingCopies); k++)
                deck.Add($"ModelDb.Card<{n.CardClassName(p, c)}>()");
        }

        var relics = new List<string>();
        for (int i = 0; i < p.Relics.Count; i++)
            if (p.Relics[i].IsStartingRelic) relics.Add($"ModelDb.Relic<{n.RelicClassName(p.Relics[i], i)}>()");
        // 额外资源量：加一个隐藏的起始遗物，负责开场发放初始数量 / 记录跨战斗继承
        if (p.ExtraResource.Enabled) relics.Add($"ModelDb.Relic<{n.ExtraResourceRelicClass}>()");
        // 不再给「没有自定义起始遗物」的角色兜底塞本体燃烧之血（用户要求：不用考虑是否携带初始遗物）

        var w = new CodeWriter();
        w.Line("// <auto-generated> 角色类 </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {n.CharClass} : CharacterModel")
         .Line($"public const string energyColorName = {Lit.Str(n.EnergyColor)};")
         .Line()
         .Line($"public override CharacterGender Gender => CharacterGender.{p.Gender};")
         .Line();

        if (string.IsNullOrWhiteSpace(p.UnlockAfter))
        {
            w.Line("// null = 无需前置角色，一开始就能选");
            w.Line("protected override CharacterModel? UnlocksAfterRunAs => null;");
        }
        else
        {
            w.Line($"// 通关 {p.UnlockAfter} 之后解锁");
            w.Line($"protected override CharacterModel? UnlocksAfterRunAs => ModelDb.Character<{Naming.Pascal(p.UnlockAfter!)}>();");
        }

        w.Line()
         .Line("public override Color NameColor => StsColors.red;")
         .Line()
         .Line("// 左侧能量计数器里数字的描边色（NEnergyCounter 用的是角色上的这个属性，")
         .Line("// 和卡牌上的 EnergyOutlineColor 不是同一个，所以两边都要给）")
         .Line($"public override Color EnergyLabelOutlineColor => new Color(\"{outlineHex}\");");

        if (p.ExtraResource.Enabled && p.ExtraResource.AlwaysShowCounter)
        {
            w.Line()
             .Line("// 额外资源量：始终显示血条下面那一排里的资源计数器（本体默认不显示）")
             .Line("public override bool ShouldAlwaysShowStarCounter => true;");
        }

        w.Line()
         .Line($"public override int StartingHp => {p.StartingHp};")
         .Line()
         .Line($"public override int StartingGold => {p.StartingGold};")
         .Line()
         .Line($"public override CardPoolModel CardPool => ModelDb.CardPool<{n.CardPoolClass}>();")
         .Line()
         .Line($"public override PotionPoolModel PotionPool => ModelDb.PotionPool<{n.PotionPoolClass}>();")
         .Line()
         .Line($"public override RelicPoolModel RelicPool => ModelDb.RelicPool<{n.RelicPoolClass}>();")
         .Line()
         .Line("public override IEnumerable<CardModel> StartingDeck =>")
         .Line("[")
         .Line("    " + string.Join(",\n    ", deck))
         .Line("];")
         .Line()
         .Line("public override IReadOnlyList<RelicModel> StartingRelics =>")
         .Line("[")
         .Line("    " + string.Join(", ", relics))
         .Line("];")
         .Line()
         .Line($"public override float AttackAnimDelay => {Lit.Float(p.AttackAnimDelay)};")
         .Line()
         .Line($"public override float CastAnimDelay => {Lit.Float(p.CastAnimDelay)};")
         .Line()
         .Line("// 音效复用铁甲战士（自定义角色没有自己的 FMOD 资源）")
         .Line("public override string CharacterSelectSfx => ModelDb.Character<Ironclad>().CharacterSelectSfx;")
         .Line()
         .Line("public override string CharacterTransitionSfx => \"event:/sfx/ui/wipe_ironclad\";")
         .Line()
         .Line("public override List<string> GetArchitectAttackVfx() =>")
         .Line("[")
         .Line("    \"vfx/vfx_attack_blunt\",")
         .Line("    \"vfx/vfx_heavy_blunt\",")
         .Line("    \"vfx/vfx_attack_slash\",")
         .Line("    \"vfx/vfx_bloody_impact\",")
         .Line("    \"vfx/vfx_rock_shatter\"")
         .Line("];")
         .Close();
        return w.ToString();
    }

    // ==================== 额外资源量 ====================
    /// <summary>
    /// 额外资源量的载体（一个隐藏的起始遗物）。
    /// 本体没有「自定义资源」这种扩展点，所以额外资源量做在本体已有的「星星」资源上：
    /// 它同样是一个计数器，显示在血条下方、和状态同一行（本体储君用的就是它）。
    /// </summary>
    public static string ExtraResourceSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var x = p.ExtraResource;
        int initial = x.Initial;
        // 「每场战斗只触发一次」这条效果条件要用的字段（用到了才声明 —— 不用就不写，老输出逐字不变）。
        // 必须在下面 AfterCombatEnd 之前算出来（那个方法体里要写复位那一句）。
        bool extraOncePerCombat = x.Effects.Any(e => e.Condition is { Kind: "OncePerCombat" });

        var w = new CodeWriter();
        w.Line("// <auto-generated> 额外资源量（做在本体的星星资源上） </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>")
         .Line("/// 额外资源量：和能量一样是个计数器，显示在角色血条下方、与状态同一行。")
         .Line("/// 本体没有自定义资源的扩展点，所以它复用本体的「星星」资源（PlayerCombatState.Stars）。")
         .Line("/// 这个遗物是起始遗物，只负责开场发放数量 / 记录跨战斗继承，不占用遗物栏的玩法位置。")
         .Line("/// </summary>")
         .Open($"public sealed class {n.ExtraResourceRelicClass} : RelicModel")
         .Line("public override RelicRarity Rarity => RelicRarity.Starter;")
         .Line()
         .Line($"/// <summary>每场战斗开始时发放的初始数量。</summary>")
         .Line($"private const int InitialAmount = {initial};")
         .Line()
         .Line("/// <summary>是否跨战斗继承：true = 开场数量 = 初始数量 + 上一场剩下的。</summary>")
         .Line($"private const bool CarryOver = {(x.CarryOver ? "true" : "false")};")
         .Line()
         .Line("/// <summary>上一场战斗结束时剩下的数量（只有开启继承时才会被记下来）。</summary>")
         .Line("private static int _carried;")
         .Line()
         .Line("/// <summary>照抄本体 DivineDestiny（储君的起始遗物 +7 星）的写法：每场战斗第一回合开始时发一次。</summary>")
         .Open("public override async Task AfterSideTurnStart(CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)")
         .Line("if (!participants.Contains(base.Owner.Creature)) return;")
         .Line("if (base.Owner.PlayerCombatState == null || base.Owner.PlayerCombatState.TurnNumber > 1) return;")
         .Line()
         .Line("// 每场战斗开始时星星都是 0（PlayerCombatState 是新造的），所以这里发多少就是开场有多少。")
         .Line("int amount = CarryOver ? InitialAmount + _carried : InitialAmount;")
         .Line("if (amount <= 0) return;")
         .Line("await PlayerCmd.GainStars(amount, base.Owner);")
         .Close()
         .Line()
         .Line("/// <summary>战斗结束：记下余量给下一场用（关闭继承时清零，等于每场都从初始数量开始）。</summary>")
         .Open("public override Task AfterCombatEnd(CombatRoom room)")
         .Line("_carried = CarryOver ? (base.Owner.PlayerCombatState?.Stars ?? 0) : 0;");
        // 「每场战斗只触发一次」的标记要跟着战斗结束清掉（和遗物链同一句）。
        // ⚠ 不能另开一个 AfterCombatEnd（同一个类里两个同名 override → CS0111），所以清在这里。
        if (extraOncePerCombat)
            w.Line("_condUsedThisCombat = false;   // 「每场战斗只触发一次」的标记：换战斗重新算");
        w.Line("return Task.CompletedTask;")
         .Close();

        // 用户在「遗物」页给这只隐藏起始遗物加的效果（用户要求）。
        // 挂在**战斗开始时**那个钩子上 —— 特意用 BeforeSideTurnStart（**带 choiceContext**，
        // 和普通遗物的「战斗开始时」同一档），而不是复用上面那个 AfterSideTurnStart
        //（那个是照抄本体 DivineDestiny 的写法、没有 choiceContext，需要上下文的效果在那儿做不了）。
        // 两个钩子方法名不同，同一个类里同时存在没问题。
        if (x.Effects.Count > 0)
        {
            w.Line()
             .Line("/// <summary>用户在「额外资源量」页给这只额外资源量遗物加的效果（战斗开始时触发）。</summary>")
             // ⚠ 这一行以前是 `.Open(...)`：`CanonicalVars =>` 后面本来就**直接是数组**（`=> [ … ];`），
             // 多开一层 `{` 之后**再也没关上**（后面几个 Close 分别关的是钩子方法和类），
             // 于是 `BeforeSideTurnStart` 被塞进了 `CanonicalVars` 的块里 —— 生成的 cs/ExtraResource.cs
             // 是一份编译不过的源码（实测：探针一开「额外资源量 + 效果」就报一串 CS1002 / CS1519）。
             // 现在照遗物链（RelicSource）那份写法：`.Line(...)`，不开块。
             .Line("protected override IEnumerable<DynamicVar> CanonicalVars =>")
             .Line("[");
            var relicVars = VarNamesOf(x.Effects);
            foreach (var e in x.Effects.Where(v => !HasNoDynamicVar(v))) w.Line($"    {VarDeclaration(e, relicVars, p)},");
            w.Line("];");
            // 「每场战斗只触发一次」这条条件读的是实例字段 —— 以前这个类里**没有声明它**，
            // 勾了那条条件就会 CS0103（和上面那个括号是同一批老坑）。用到了才声明（不用不写，保持老输出不变）。
            if (extraOncePerCombat)
            {
                w.Line()
                 .Line("/// <summary>「每场战斗只触发一次」条件用的标记（每场战斗结束时清掉）。</summary>")
                 .Line("private bool _condUsedThisCombat;");
            }
            w.Line()
             .Open("public override async Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)")
             .Line("if (!participants.Contains(base.Owner.Creature)) return;");
            var extraChance = ChanceSlices(x.Effects);
            if (extraChance.Count > 0) w.Line(ChanceRollLine());
            int extraIdx = 0;
            foreach (var e in x.Effects)
            {
                string? cond = EffectConditionGuard(e, CondCtx.Relic, chanceSlices: extraChance);
                if (cond is not null)
                {
                    // 和遗物链同一句注释：回读「每条效果自己的条件」靠它（见 ProjectRecovery 的块栈）
                    w.Line($"// 条件（只对「{EffectCatalog.FindKind(e.Kind).Display}」这条效果）：{ConditionText(e.Condition!)}（不满足时这条效果不触发）");
                    w.Open(cond);
                }
                EmitRelicEffect(w, p, e, hasContext: true, relicVars, null, null, extraIdx++);
                if (cond is not null) w.Close();
                if (e.Condition is { Kind: "OncePerCombat" }) w.Line("_condUsedThisCombat = true;");
            }
            w.Close();
        }
        w.Close();
        return w.ToString();
    }

    /// <summary>名字条高度（计数器底部留给名字的像素）。</summary>
    public const int ExtraResourceNameStripHeight = 26;

    /// <summary>是否需要生成「额外资源量外观」补丁（配了名字或自定义图标才需要）。</summary>
    public static bool HasExtraResourceUi(CharacterProfile p)
    {
        if (!p.ExtraResource.Enabled) return false;
        return !string.IsNullOrWhiteSpace(p.ExtraResource.Name)
               || !string.IsNullOrWhiteSpace(p.ExtraResource.Icon);
    }

    /// <summary>
    /// 「额外资源量上限」相关的类名。
    /// 上限 = 额外资源量页填的那个数 + 生成的 <see cref="StarCapPowerClass"/> 的层数
    /// （层数给「增加额外资源量上限值」那个效果用来临时/永久抬高上限）。
    /// </summary>
    public static string StarCapPowerClass(CharacterProfile p) => Naming.From(p).CharClass + "ForgeStarCapPower";

    /// <summary>
    /// 要不要生成「上限」那套（夹上限的补丁 + 承载加成的状态）？
    /// 只要**开了额外资源量**、并且（填了上限 或 存档里用了「增加额外资源量上限值」）就要。
    /// </summary>
    public static bool NeedsStarCap(CharacterProfile p) =>
        p.ExtraResource.Enabled
        && (p.ExtraResource.Max > 0
            || AllEffects(p).Any(e => e is not null && e.Kind == "RaiseResourceCap"));

    /// <summary>
    /// 「额外资源量上限」那个隐藏状态：层数 = **额外给的上限**。
    /// 上限本身是 profile 里的常数（写进 ExtraResourceUiConst），这个状态只承载运行时加成，
    /// 这样「增加额外资源量上限值」既能做「本场战斗 +N」，也能反复叠。
    /// </summary>
    public static string StarCapPowerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        return $$"""
// <auto-generated> 额外资源量上限：层数 = 额外给的上限（配合「增加额外资源量上限值」效果） </auto-generated>
namespace {{n.Namespace}};

/// <summary>
/// 额外资源量（星星）的**上限加成**。
///
/// 为什么单独做一个状态：上限要做成「基础值 + 运行时加成」——
///   基础值 = 额外资源量页里填的「数量上限」（生成期常数，写在 ExtraResourceUiConst.MaxAmount）；
///   加成   = 这个状态的层数（「增加额外资源量上限值」效果往上加）。
/// 真正把数量夹住的是同一份文件里的 StarCapPatch（Harmony 前缀，拦 PlayerCmd.GainStars）。
/// 这个状态只负责「让人看见加成有多少」以及「每场战斗重新来」。
/// </summary>
public sealed class {{StarCapPowerClass(p)}} : PowerModel {
    public override PowerType Type => PowerType.Buff;

    public override PowerStackType StackType => PowerStackType.Counter;

    /// <summary>上限是内部机制，不出现在状态栏里（否则玩家会看到多出来一个莫名其妙的状态）。</summary>
    protected override bool IsVisibleInternal => false;

    /// <summary>战斗结束时清掉：上限加成不跨战斗（基础上限是常数，不受影响）。</summary>
    public override async Task AfterCombatEnd(CombatRoom room) {
        await PowerCmd.Remove(this);
    }
}
""";
    }

    /// <summary>
    /// 把额外资源量的数量夹到「上限」的补丁。
    ///
    /// 为什么必须打补丁：本体 <c>PlayerCombatState.GainStars(decimal)</c> 只有
    /// <c>Stars = Math.Max(Stars + amount, 0)</c> —— **没有上限这个概念**，
    /// 也没有「加星星前」的钩子能改增量（Hook.ShouldGainStars 只能拦、不能改数）。
    /// 所以这里用 Harmony 前缀把传进来的 amount 夹小：
    ///   · 先按增量直接判定：装得下就原样放行（**不改任何数**，不影响 AfterStarsGained 的播报）；
    ///   · 装不下才把增量改成「还能装多少」（上限已经到了就改成 0，原方法对非负数都不抛）。
    /// 上限 = ExtraResourceUiConst.MaxAmount（0 = 不限）+ 那个隐藏状态的层数。
    ///
    /// 为什么拦 <c>PlayerCmd.GainStars</c> 而不是 <c>PlayerCombatState.GainStars</c>：
    ///   ① 只有 PlayerCmd 这一条路带得动 <c>Player</c> 参数（本体里所有涨星星的地方——
    ///      卡牌、药水、状态、控制台——全都走它；<c>PlayerCombatState.GainStars</c> 是它的私有实现，
    ///      全网没有别的调用方），能直接拿到 <c>player.Creature</c> 去读上限加成状态；
    ///   ② <c>PlayerCombatState</c> 上没有公开的「我是谁」属性，拦它就得反射私有字段，
    ///      本体一改私有布局就静默失效。走公开 API 更稳。
    /// </summary>
    public static string StarCapPatchSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        string powerClass = StarCapPowerClass(p);
        return $$"""
// <auto-generated> 额外资源量的数量上限（本体没有这个概念，用 Harmony 前缀夹住 PlayerCmd.GainStars 的增量） </auto-generated>
using HarmonyLib;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Players;

namespace {{n.Namespace}};

[HarmonyPatch(typeof(PlayerCmd), nameof(PlayerCmd.GainStars))]
public static class {{n.CharClass}}ForgeStarCapPatch
{
    /// <summary>前缀：把增量夹到「还能装多少」。返回 true = 照常跑原方法（我们只改了 ref 参数）。</summary>
    public static bool Prefix(Player player, ref decimal amount)
    {
        if (amount <= 0m) return true;
        if (player?.Creature is null) return true;
        int cap = ExtraResourceUiConst.MaxAmount;
        if (cap <= 0) return true;                       // 0 = 不限
        // 运行时加成：那个隐藏状态的层数（「增加额外资源量上限值」效果涨的就是它）
        var bonus = player.Creature.GetPower<{{powerClass}}>();
        if (bonus is not null) cap += bonus.Amount;
        int room = cap - player.PlayerCombatState.Stars;
        if (room <= 0) { amount = 0m; return true; }     // 已经到顶：一点都别加
        if (amount <= (decimal)room) return true;        // 装得下：原样放行，不动任何数
        amount = (decimal)room;
        return true;
    }
}
""";
    }

    /// <summary>
    /// 额外资源量的外观：把本体那个计数器（默认长成「辉星」：一颗星星 + 一个数字）换成自定义图标 + 自定义中文名。
    /// 本体没有「自定义资源」的扩展点，所以只能给计数器节点打补丁；
    /// 而且只对「我们自己角色的计数器 / 我们自己卡池的卡」生效，别的角色（比如本体储君）一点都不动。
    /// </summary>
    public static string ExtraResourceUiSource(CharacterProfile p)
    {
        var n = Naming.From(p);

        // 关掉「显示名字」时不写名字，只换图标
        string displayName = p.ExtraResource.ShowName ? (p.ExtraResource.Name ?? "").Trim() : "";
        string iconRes = ArtGenerator.ExtraResourceIconResPath(p) ?? "";
        int maxAmount = Math.Max(0, p.ExtraResource.Max);

        return $$"""
// <auto-generated> 额外资源量的外观（自定义图标 / 中文名） </auto-generated>
namespace {{n.Namespace}};

/// <summary>外观配置（图标 / 名字 / 名字条高度 / 数量上限）。</summary>
internal static class ExtraResourceUiConst
{
    /// <summary>pck 里的图标路径；没上传时是空串（保持本体星星外观）。</summary>
    internal const string IconPath = {{Lit.Str(iconRes)}};

    /// <summary>显示名；空串 = 不在计数器上显示名字。</summary>
    internal const string DisplayName = {{Lit.Str(displayName)}};

    /// <summary>
    /// 额外资源量的**数量上限**（0 = 不限，和本体一样）。
    /// 是「基础上限」——运行时的加成在 {{StarCapPowerClass(p)}} 的层数上，
    /// 真正夹住数量的是 StarCapPatch（Harmony 前缀拦 PlayerCombatState.GainStars）。
    /// </summary>
    internal const int MaxAmount = {{maxAmount}};

    /// <summary>名字条高度，同时也是图标要让出来的高度（不然名字会压在图标上）。</summary>
    internal const int NameStripHeight = {{ExtraResourceNameStripHeight}};

    internal const int NameFontSize = 18;

    /// <summary>标记「这个计数器属于我们的角色」。</summary>
    internal const string MineMeta = "forge_extra_resource_mine";

    /// <summary>标记「这个计数器已经改造过」（节点可能多次进出场景树，重复改会叠出好几个名字）。</summary>
    internal const string AppliedMeta = "forge_extra_resource_ui";

    /// <summary>
    /// 悬停提示用的键（**我们自己**的键，不是本体的 STAR_COUNT.*）。
    /// 本体那颗星星的提示写死在 NStarCounter._Ready 里（<c>new LocString("static_hover_tips","STAR_COUNT.title")</c>），
    /// 而那两个键是全局的 —— 多个角色模组都改就会互相盖（联机时两个人看到的资源名不一样）。
    /// 所以这里存一份自己的键，由计数器补丁在「这个计数器归我方角色」时换上去。
    /// </summary>
    internal const string TipTable = "static_hover_tips";
    internal const string TipTitleKey = "{{n.CharEntry}}_EXTRA_RESOURCE.title";
    internal const string TipDescKey = "{{n.CharEntry}}_EXTRA_RESOURCE.description";

    /// <summary>
    /// 「资源不够、这张牌打不出去」那句系统提示（思考气泡里那行字）的**我们自己的键**。
    ///
    /// 本体那句来自**全局**键 <c>combat_messages.NOT_ENOUGH_STARS</c>（「我没有足够的[red]辉星[/red]。」）——
    /// 它写死了「辉星」两个字，所以换了资源名之后，一付不起星费就露馅（用户报的就是这个）。
    /// 覆盖那个全局键会影响别的角色 / 联机另一边的玩家，所以这里同样走「自己的键 + 只在玩我方角色时替换」：
    /// 见下面 ForgeNotEnoughMessage 那个**手动打**的补丁（目标是 internal 类，PatchAll 打不上也不敢打）。
    /// </summary>
    internal const string NotEnoughKey = "{{n.CharEntry}}_EXTRA_RESOURCE.notEnough";
}

/// <summary>
/// 血条下方那个资源计数器：
///   · 图标换成你上传的那张图，并隐藏本体星星自带的两层旋转光效
///   · 在计数器下方显示你填的中文名
/// 本体在 Initialize(Player) 里告诉我们这个计数器是谁的，不是我们的角色就一点都不改。
/// </summary>
[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter), nameof(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter._Ready))]
public static class ExtraResourceCounterPatch
{
    /// <summary>本体建好节点之后才轮到我们（Postfix）。</summary>
    [HarmonyLib.HarmonyPostfix]
    private static void AfterReady(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter __instance)
    {
        try
        {
            if (__instance.HasMeta(ExtraResourceUiConst.MineMeta)) ExtraResourceUi.Apply(__instance);
        }
        catch (Exception e)
        {
            // 界面补丁出问题绝不能把战斗搞崩：只记日志，保持本体原样
            Log.Error("额外资源量：计数器外观应用失败（已忽略）：" + e.Message);
        }
    }
}

/// <summary>计数器归谁：本体在 Initialize 里说得很清楚，不是我们的角色就一点都不改。</summary>
[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter), nameof(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter.Initialize))]
public static class ExtraResourceCounterOwnerPatch
{
    [HarmonyLib.HarmonyPostfix]
    private static void AfterInitialize(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter __instance, Player player)
    {
        try
        {
            if (player?.Character is {{n.CharClass}})
            {
                __instance.SetMeta(ExtraResourceUiConst.MineMeta, true);
                ExtraResourceUi.Apply(__instance);
            }
            else
            {
                __instance.RemoveMeta(ExtraResourceUiConst.MineMeta);
            }
        }
        catch (Exception e)
        {
            Log.Error("额外资源量：判断资源计数器归属失败（已忽略）：" + e.Message);
        }
    }
}

/// <summary>
/// 卡面上的资源费用图标（本体也是那颗星星）：换成同一张自定义图，
/// 这样卡面费用和计数器看起来是同一种资源。只改我们自己卡池里的卡。
/// </summary>
[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Nodes.Cards.NCard), nameof(MegaCrit.Sts2.Core.Nodes.Cards.NCard._Ready))]
public static class ExtraResourceCardIconPatch
{
    [HarmonyLib.HarmonyPostfix]
    private static void AfterReady(MegaCrit.Sts2.Core.Nodes.Cards.NCard __instance)
    {
        try
        {
            // 卡牌的 Model 可能在 _Ready 之后才挂上，所以跟着 ModelChanged 再刷一次
            __instance.ModelChanged += _ => ApplyCardIcon(__instance);
            ApplyCardIcon(__instance);
        }
        catch (Exception e)
        {
            Log.Error("额外资源量：卡面资源图标替换失败（已忽略）：" + e.Message);
        }
    }

    private static void ApplyCardIcon(MegaCrit.Sts2.Core.Nodes.Cards.NCard card)
    {
        try
        {
            if (ExtraResourceUiConst.IconPath.Length == 0) return;
            // 别的角色（本体储君等）的星星费用不要跟着变：只认我们自己卡池的卡
            if (card.Model?.Pool is not {{n.CardPoolClass}}) return;

            Texture2D? tex = ExtraResourceUi.LoadIcon();
            if (tex is null) return;

            // ⚠ 只换 %StarIcon（星费那个图标）。以前这里连 %UnplayableStarIcon 一起换 ——
            // 那个节点不是星星，是本体「这张牌打不出去」的**叉号**（card.tscn 里的
            // card_unplayable_icon.tres），换掉它等于把叉画成了资源图标（用户报过）。
            foreach (TextureRect target in ExtraResourceUi.StarIconTargets(card, "%StarIcon"))
                target.Texture = tex;
        }
        catch (Exception e)
        {
            Log.Error("额外资源量：卡面资源图标替换失败（已忽略）：" + e.Message);
        }
    }
}

/// <summary>真正改界面的地方（计数器）。</summary>
internal static class ExtraResourceUi
{
    private static Texture2D? _icon;
    private static bool _iconTried;

    /// <summary>本体那颗星星的贴图名（节点名万一和本体版本对不上时，靠贴图本身认）。</summary>
    private const string VanillaStarTexture = "energy_star";

    /// <summary>加载自定义图标；没配 / 加载不出来都返回 null（界面保持本体原样）。</summary>
    internal static Texture2D? LoadIcon()
    {
        if (_iconTried) return _icon;
        _iconTried = true;
        if (ExtraResourceUiConst.IconPath.Length == 0) return null;
        try
        {
            // 这里特意不用 ResourceLoader.Exists 做前置判断：模组 pck 是运行时挂载的，
            // 某些情况下 Exists 对刚挂载的资源会返回 false —— 那样图标会「静默不生效」，
            // 玩家看到的就是本体的星星，而日志里一条错都没有。直接 Load + 打日志更可靠。
            _icon = GD.Load<Texture2D>(ExtraResourceUiConst.IconPath);
        }
        catch (Exception e)
        {
            Log.Error("额外资源量：图标加载失败（已忽略）：" + e.Message);
        }
        if (_icon is null)
            Log.Warn("额外资源量：图标没加载出来，计数器保持本体外观：" + ExtraResourceUiConst.IconPath);
        return _icon;
    }

    /// <summary>
    /// 找出所有要换成自定义图的 TextureRect：
    ///   1. 先按本体节点名找（计数器是 "Icon"，卡面是 %StarIcon / %UnplayableStarIcon）
    ///   2. 再按「贴图就是本体那颗星星」在整个子树里扫一遍兜底
    /// 本体哪天改了节点名/结构，第 2 步也能兜住，不会再出现「图标静默不生效」。
    /// </summary>
    internal static List<TextureRect> StarIconTargets(Node root, params string[] nodePaths)
    {
        var targets = new List<TextureRect>();
        foreach (string path in nodePaths)
        {
            TextureRect? named = root.GetNodeOrNull<TextureRect>(path);
            if (named is not null && !targets.Contains(named)) targets.Add(named);
        }
        var found = new List<TextureRect>();
        CollectStarTextures(root, found);
        foreach (TextureRect tr in found)
            if (!targets.Contains(tr)) targets.Add(tr);
        return targets;
    }

    private static void CollectStarTextures(Node node, List<TextureRect> found)
    {
        if (node is TextureRect tr && tr.Texture is not null
            && (tr.Texture.ResourcePath ?? "").Contains(VanillaStarTexture, StringComparison.Ordinal))
        {
            found.Add(tr);
        }
        foreach (Node child in node.GetChildren())
            CollectStarTextures(child, found);
    }

    internal static void Apply(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter counter)
    {
        if (counter.HasMeta(ExtraResourceUiConst.AppliedMeta)) return;
        counter.SetMeta(ExtraResourceUiConst.AppliedMeta, true);

        Texture2D? tex = LoadIcon();
        if (tex is not null)
        {
            List<TextureRect> targets = StarIconTargets(counter, "Icon");
            EnsureIcon(counter);

            if (targets.Count == 0)
                Log.Warn("额外资源量：计数器里没找到星星贴图节点，图标没能换掉（本体结构可能变了）");
            else
                Log.Info("额外资源量：计数器图标已替换，命中 " + targets.Count + " 个节点");
        }

        AddNameLabel(counter);
        ApplyHoverTip(counter);
    }

    /// <summary>
    /// 把计数器上那条悬停提示的标题 / 说明换成**我们自己的键**。
    ///
    /// 本体在 <c>NStarCounter._Ready</c> 里写死用 <c>static_hover_tips</c> 的
    /// <c>STAR_COUNT.title</c> / <c>STAR_COUNT.description</c>；那两个键是全局的，所以我们**不覆盖**它们，
    /// 只在这个计数器确实属于我方角色时（<see cref="ExtraResourceUiConst.MineMeta"/>）把提示对象换掉。
    /// 联机时每个客户端装的都是同一套模组，但只有「本地玩家正在玩的角色」那一份会生效
    /// —— 于是各看各的资源名，互不干扰。
    /// </summary>
    internal static void ApplyHoverTip(Node counter)
    {
        if (counter.HasMeta(TipAppliedMeta)) return;
        try
        {
            var getTip = HarmonyLib.AccessTools.FieldRefAccess<MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter, MegaCrit.Sts2.Core.HoverTips.HoverTip>("_hoverTip");
            try
            {
                // 正文自己写好了图标（内联 24×24 小图），所以不用再喂 singleStarIcon 变量
                getTip((MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter)counter) = new MegaCrit.Sts2.Core.HoverTips.HoverTip(
                    new LocString(ExtraResourceUiConst.TipTable, ExtraResourceUiConst.TipTitleKey),
                    new LocString(ExtraResourceUiConst.TipTable, ExtraResourceUiConst.TipDescKey));
                counter.SetMeta(TipAppliedMeta, true);
            }
            catch (Exception e)
            {
                Log.Warn("额外资源量：计数器提示替换失败（保持本体文案）：" + e.Message);
            }
        }
        catch (Exception e)
        {
            Log.Warn("额外资源量：找不到计数器的提示字段（本体结构可能变了）：" + e.Message);
        }
    }

    private const string TipAppliedMeta = "forge_extra_resource_tip";

    private const string NameLabelMeta = "forge_extra_resource_name";

    /// <summary>
    /// 在计数器最下面那条加一句「资源名」（复制本体的数字标签，字体 / 描边都跟着本体）。
    /// 幂等：一个节点只加一次；找不到 %CountLabel（比如传进来的是卡牌节点）就什么都不做。
    /// </summary>
    internal static bool AddNameLabel(Node root)
    {
        if (ExtraResourceUiConst.DisplayName.Length == 0) return false;
        if (root.HasMeta(NameLabelMeta)) return false;
        RichTextLabel? countLabel = root.GetNodeOrNull<RichTextLabel>("%CountLabel");
        if (countLabel?.Duplicate() is not RichTextLabel nameLabel) return false;

        root.SetMeta(NameLabelMeta, true);
        nameLabel.Name = "ExtraResourceName";
        nameLabel.UniqueNameInOwner = false;      // 不能和 %CountLabel 抢唯一名
        nameLabel.Text = "[center]" + ExtraResourceUiConst.DisplayName + "[/center]";
        foreach (string key in new[] { "normal_font_size", "bold_font_size", "italics_font_size", "bold_italics_font_size", "mono_font_size" })
            nameLabel.AddThemeFontSizeOverride(key, ExtraResourceUiConst.NameFontSize);
        nameLabel.AddThemeConstantOverride("outline_size", 8);

        // 贴在计数器框的最下面一条（计数器是 128×128，所以用锚点+偏移，别写死坐标）
        nameLabel.AnchorLeft = 0f;
        nameLabel.AnchorRight = 1f;
        nameLabel.AnchorTop = 1f;
        nameLabel.AnchorBottom = 1f;
        nameLabel.OffsetLeft = 0f;
        nameLabel.OffsetRight = 0f;
        nameLabel.OffsetTop = -ExtraResourceUiConst.NameStripHeight;
        nameLabel.OffsetBottom = 0f;
        root.AddChild(nameLabel);
        return true;
    }

    /// <summary>节点往上数几层，形如 <c>TextureRect &lt; NStarCounter &lt; ...</c>（排查「这个节点到底是谁的」）。</summary>
    internal static string NodeChain(Node? node, int depth = 4)
    {
        var parts = new List<string>();
        Node? cur = node;
        for (int i = 0; i < depth && cur is not null; i++)
        {
            parts.Add(cur.GetType().Name + "(" + cur.Name + ")");
            cur = cur.GetParent();
        }
        return string.Join(" < ", parts);
    }

    /// <summary>
    /// 本体那个「这计数器归谁」的私有字段 <c>_player</c>（反射读，读不到就是 null → 退化到 meta 判断）。
    /// 为什么要它：Initialize 的补丁万一没生效 / 判断没走到，光看 meta 会以为「不是我们的角色」，
    /// 结果就是计数器一直显示本体星星而日志里什么都没有。多一条路更稳。
    /// </summary>
    private static readonly System.Reflection.FieldInfo? PlayerField =
        HarmonyLib.AccessTools.Field(typeof(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter), "_player");

    private static Player? ReadPlayer(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter counter)
    {
        try { return PlayerField?.GetValue(counter) as Player; }
        catch { return null; }
    }

    /// <summary>这个计数器是不是我们角色的（先看 meta，再看本体记的 player，最后看角色类型）。</summary>
    internal static bool IsOurs(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter counter, out Player? player)
    {
        player = ReadPlayer(counter);
        if (counter.HasMeta(ExtraResourceUiConst.MineMeta)) return true;
        if (player?.Character is {{n.CharClass}})
        {
            counter.SetMeta(ExtraResourceUiConst.MineMeta, true);
            return true;
        }
        return false;
    }

    /// <summary>
    /// 把计数器的星星贴图换成我们的图（已经是我们的就什么都不做）。
    /// 每帧调用也无所谓：只有一次引用比较，只有「被别人改回去了」才真的重新贴。
    /// </summary>
    internal static bool EnsureIcon(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter counter)
    {
        Texture2D? tex = LoadIcon();
        if (tex is null) return false;
        bool changed = false;
        foreach (TextureRect icon in StarIconTargets(counter, "Icon"))
        {
            if (!ReferenceEquals(icon.Texture, tex))
            {
                icon.Texture = tex;
                // 名字要占底部一条，图标往上让出这么多
                if (ExtraResourceUiConst.DisplayName.Length > 0)
                    icon.OffsetBottom = -ExtraResourceUiConst.NameStripHeight;
                changed = true;
            }
        }
        if (changed)
        {
            // 本体星星自带两层旋转光效，换了自己的图标后必须藏掉，否则会盖在图标上
            counter.GetNodeOrNull<Control>("Icon/RotationLayers")?.Hide();
        }
        return changed;
    }
}

/// <summary>
/// 每帧兜底：**别的模组**（玩家的其它 mod，比如把「额外资源」也做在同一颗星星上的那些）
/// 可能在我们之后把计数器贴图改回本体那颗星星，或者计数器是「先建好、后设置归属」的，
/// 只靠一次补丁就会输。这里每帧只做「现在这张图还是不是我们的」这一个比较，不是就贴回去。
/// 第一次确认「这个计数器是我们的」时写一条日志，附带诊断信息（图标有没有加载出来 / 角色类名 / 命中几个节点）。
/// </summary>
[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter), nameof(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter._Process))]
public static class ExtraResourceCounterKeepPatch
{
    private const string LoggedMeta = "forge_extra_resource_ui_logged";

    [HarmonyLib.HarmonyPostfix]
    private static void AfterProcess(MegaCrit.Sts2.Core.Nodes.Combat.NStarCounter __instance)
    {
        try
        {
            if (ExtraResourceUiConst.IconPath.Length == 0) return;
            if (!ExtraResourceUi.IsOurs(__instance, out Player? player)) return;

            if (!__instance.HasMeta(LoggedMeta))
            {
                __instance.SetMeta(LoggedMeta, true);
                Texture2D? tex = ExtraResourceUi.LoadIcon();
                int hit = ExtraResourceUi.StarIconTargets(__instance, "Icon").Count;
                bool changed = ExtraResourceUi.EnsureIcon(__instance);
                Log.Info("额外资源量：计数器检查 → 图标" + (tex is null ? "没加载出来" : "已加载")
                    + "，角色=" + (player?.Character?.GetType().Name ?? "null")
                    + "，命中节点=" + hit
                    + "，本次" + (changed ? "重新贴了一次" : "贴图本来就是我们的"));
                return;
            }

            ExtraResourceUi.EnsureIcon(__instance);
        }
        catch
        {
            // 每帧的兜底绝不能刷屏，也不能把战斗搞崩
        }
    }
}

/// <summary>
/// 战斗界面一起来就把「所有用本体星星贴图的地方」换成我们的图标（包含那个资源计数器，也包含手牌的费用星星）。
///
/// 为什么光靠挂在 NStarCounter 上的补丁不够（用户实测就是这样：图标没换、日志一条都没有）：
/// 装了别的模组时（BaseLib 会给节点做工厂、RitsuLib 有「次要资源 / StarCounterLike」一整套接管），
/// 战斗界面里的计数器**可能根本不是本体那个类**，挂在 NStarCounter 上的补丁就永远不触发。
/// 这里按**贴图本身**认：谁在用本体的 energy_star.png，就换谁 —— 跟节点是什么类无关。
/// 而且只在「本地玩家是我们角色」的战斗界面里做，不碰别的角色。
/// </summary>
[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi), nameof(MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi.Activate))]
public static class ExtraResourceCombatUiPatch
{
    [HarmonyLib.HarmonyPostfix]
    private static void AfterActivate(MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi __instance, CombatState state)
    {
        try
        {
            if (ExtraResourceUiConst.IconPath.Length == 0) return;
            Player me = MegaCrit.Sts2.Core.Context.LocalContext.GetMe(state);
            if (me?.Character is not {{n.CharClass}}) return;

            Texture2D? tex = ExtraResourceUi.LoadIcon();
            if (tex is null) return;

            List<TextureRect> targets = ExtraResourceUi.StarIconTargets(__instance, "Icon");
            var owners = new List<string>();
            foreach (TextureRect icon in targets)
            {
                icon.Texture = tex;
                if (ExtraResourceUiConst.DisplayName.Length > 0)
                    icon.OffsetBottom = -ExtraResourceUiConst.NameStripHeight;
                string chain = ExtraResourceUi.NodeChain(icon, 3);
                if (!owners.Contains(chain)) owners.Add(chain);
            }
            // 名字条：只给「看起来像计数器」的那个节点加（有 %CountLabel 才加得上）
            foreach (TextureRect icon in targets)
            {
                Node? owner = icon.Owner;
                if (owner is not null && ExtraResourceUi.AddNameLabel(owner)) break;
            }

            Log.Info("额外资源量：战斗界面星星贴图换了 " + targets.Count + " 处；所属节点=" + string.Join(" | ", owners));
        }
        catch (Exception e)
        {
            Log.Error("额外资源量：战斗界面图标替换失败（已忽略）：" + e.Message);
        }
    }
}

/// <summary>
/// 「资源不够、这张牌打不出去」那句提示：把本体的「辉星」换成我们自己的资源名。
///
/// 为什么必须打补丁：本体那句话来自**全局**本地化键 <c>combat_messages.NOT_ENOUGH_STARS</c>
///（`UnplayableReasonExtensions.GetPlayerDialogueLine` → 思考气泡 `NThoughtBubbleVfx.Create(...)`），
/// 键里写死了「辉星」两个字 —— 换了资源名之后，一付不起星费就会显示「我没有足够的辉星」。
/// 覆盖那个全局键会连带影响别的角色 / 联机另一边的玩家，所以这里改成**只在我方角色的这一局里**
/// 把返回的 LocString 换成我们自己的键（<c>&lt;角色&gt;_EXTRA_RESOURCE.notEnough</c>）。
///
/// ⚠ 本体那个类是 <c>internal</c> 的，编译期 <c>typeof</c> 看不到 —— 所以：
///   · 目标方法只能在运行时按名字找（<see cref="Target"/>，AccessTools.TypeByName）；
///   · 补丁在模组入口里**手动打**（inside try/catch），找不到就只丢这一句提示，绝不影响整个模组加载
///     （带 [HarmonyPatch] 的 PatchAll 一抛异常，角色注册也一起没了）。
/// </summary>
internal static class {{n.CharClass}}ForgeNotEnoughMessage
{
    private static readonly Type? ExtType =
        HarmonyLib.AccessTools.TypeByName("MegaCrit.Sts2.Core.Entities.Cards.UnplayableReasonExtensions");

    /// <summary>要打的那个 internal static 方法（找不到返回 null → 入口里只记一条警告）。</summary>
    internal static System.Reflection.MethodBase? Target =>
        ExtType is null ? null : HarmonyLib.AccessTools.Method(ExtType, "GetPlayerDialogueLine");

    private static ulong _cachedFrame = ulong.MaxValue;
    private static bool _cached;

    internal static void Postfix(ref LocString? __result)
    {
        try
        {
            // 只认本体那句「星费不够」；别的提示（能量不够 / 打不出）一个字都不动
            if (__result is null) return;
            if (__result.LocTable != "combat_messages" || __result.LocEntryKey != "NOT_ENOUGH_STARS") return;
            if (!IsMyRun()) return;                       // 别的角色 / 主菜单：保持本体那句
            if (!LocString.Exists("combat_messages", ExtraResourceUiConst.NotEnoughKey)) return;
            __result = new LocString("combat_messages", ExtraResourceUiConst.NotEnoughKey);
        }
        catch (Exception e)
        {
            Log.Error("额外资源量：替换「资源不够」提示失败（已忽略）：" + e.Message);
        }
    }

    /// <summary>这一局玩的是不是我方角色（和本体状态改名补丁同一套公开链；按帧缓存）。</summary>
    private static bool IsMyRun()
    {
        try
        {
            ulong frame = Engine.GetProcessFrames();
            if (frame == _cachedFrame) return _cached;
            _cachedFrame = frame;
            _cached = ComputeIsMyRun();
            return _cached;
        }
        catch { return false; }
    }

    private static bool ComputeIsMyRun()
    {
        if (!MegaCrit.Sts2.Core.Runs.RunManager.Instance.IsInProgress) return false;
        Player? me = MegaCrit.Sts2.Core.Context.LocalContext.GetMe(MegaCrit.Sts2.Core.Runs.RunManager.Instance.DebugOnlyGetState());
        return me?.Character is {{n.CharClass}};
    }
}

/// <summary>
/// 诊断用：记一次「本体实际用的是哪个能量计数器场景」。/// 用户报过「左侧能量球还是本体美术」——如果这里打出来的路径不是我们生成的
/// <c>scenes/combat/energy_counters/&lt;角色&gt;_energy_counter.tscn</c>，就说明有别的模组
/// （装了 BaseLib / RitsuLib 时会改写这条路径）把我们的球体场景顶掉了，换图当然看不见效果。
/// </summary>
[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Nodes.Combat.NEnergyCounter), nameof(MegaCrit.Sts2.Core.Nodes.Combat.NEnergyCounter.Create))]
public static class ExtraResourceEnergyCounterDiagPatch
{
    private static bool _logged;

    [HarmonyLib.HarmonyPrefix]
    private static void Before(Player player)
    {
        if (_logged) return;
        _logged = true;
        try { Log.Info("额外资源量：左侧能量球用的是场景 = " + (player?.Character?.EnergyCounterPath ?? "(空)")); }
        catch { }
    }
}

""";
    }

    // ==================== 条件选项 ====================
    /// <summary>条件写在哪儿（决定「自己 / 牌堆 / 战斗状态」用哪个表达式）。</summary>
    public enum CondCtx
    {
        /// <summary>卡牌：base.Owner 是 Player，base.CombatState 是当前战斗。</summary>
        Card,
        /// <summary>遗物：base.Owner 是 Player，但遗物模型上没有 CombatState，得走 Owner.Creature.CombatState。</summary>
        Relic,
        /// <summary>自定义状态（能力）的触发器：base.Owner 直接就是那个 Creature。</summary>
        Power,
        /// <summary>
        /// 药水：和 <see cref="Relic"/> **文本上完全一样**（<c>base.Owner</c> 是 Player、
        /// 没有 <c>CombatState</c> 要走 <c>Owner.Creature.CombatState</c>），单独一档只是为了
        /// 读起来清楚 / 以后本体那边有差异时好改。
        ///
        /// <para>用户要求第 6 条「药水方面参考遗物的优化方案」→ 药水页右下角也能选「单条效果的条件」，
        /// 所以这条路必须真的能生成（见 <c>EmitPotionEffect</c>）。</para>
        /// </summary>
        Potion,
    }

    /// <summary>
    /// 条件的 C# 判断表达式。
    /// 表达式一律带 null 判断，避免在牌库 / 结算界面（没有战斗状态时）炸掉。
    /// <paramref name="inOnPlay">true = 这段表达式写在 OnPlay 里（能用 cardPlay.Target）；
    /// false = 写在 IsPlayable / 描金边里（那时玩家还没选目标，所以「指定敌人」这类条件用不了）。</paramref>
    /// </summary>
    public static string ConditionExpr(ConditionSpec c, bool isCard) =>
        ConditionExpr(c, isCard ? CondCtx.Card : CondCtx.Relic);

    public static string ConditionExpr(ConditionSpec c, CondCtx ctx, bool inOnPlay = false)
    {
        // 「自己」= 哪个生物；战斗状态；玩家（额外资源量在玩家身上）
        string ownerCreature = ctx == CondCtx.Power ? "base.Owner" : "base.Owner.Creature";
        string st = ctx switch
        {
            CondCtx.Card => "base.CombatState",
            CondCtx.Relic => "base.Owner.Creature.CombatState",
            // 药水和遗物同形：base.Owner 是 Player，模型上没有 CombatState
            CondCtx.Potion => "base.Owner.Creature.CombatState",
            _ => "base.CombatState",
        };
        string player = ctx == CondCtx.Power ? "base.Owner.Player" : "base.Owner";
        // 手牌 / 牌堆条件：本体这几个 API 收的是 Player（能力牌的 base.Owner 是 Creature，所以先取 .Player）
        string hand = $"{player} is not null && CardPile.GetCards({player}, PileType.Hand)";
        string n = Lit.Dec(c.Amount);
        // 「条件数值的公式」（用户要求⑦：所有能填数值的地方都能写公式）：
        // 写了公式就用现算的表达式取代那个固定数字；计数类夹成 ≥ 0 的 int，百分比类保持 decimal。
        // 写了公式时**不再按固定值的正负判断方向**（公式算出来的正负生成时不知道）——
        // 校验器会给一句提示说清这一点。
        string? condF1 = ConditionFormulaExpr(_formulaOwner, c, "Amount", out _, withPlayTarget: inOnPlay);
        string? condF2 = ConditionFormulaExpr(_formulaOwner, c, "Amount2", out _, withPlayTarget: inOnPlay);
        string ci = condF1 is not null ? $"(int)System.Math.Max(0m, {condF1})" : Lit.Int(Math.Max(1m, Math.Abs(c.Amount)));
        string cp = condF1 is not null ? $"System.Math.Max(0m, {condF1})" : Lit.Int(Math.Max(1m, Math.Abs(c.Amount)));
        // 计数类条件用整数（读起来清楚，也不会出现 ">= 3m" 这种），并且至少压到 1，
        // 免得「每 N 回合」填 0 时生成 % 0 直接抛异常。
        // **填负数 = 反向**（用户要求）：这里的数值一律先取绝对值，方向由 inverted 决定。
        string ni = ci;
        // 生命区间（HpInRange）：下界 / 上界（都取绝对值），任一为负 = 判断成「区间外」
        decimal rangeLo = Math.Abs(c.Amount), rangeHi = Math.Abs(c.Amount2);
        if (rangeLo > rangeHi) (rangeLo, rangeHi) = (rangeHi, rangeLo);
        string lo = condF1 is not null ? cp : Lit.Int(Math.Max(1m, rangeLo));
        string hi = condF2 is not null ? $"System.Math.Max(1m, {condF2})" : Lit.Int(Math.Max(1m, rangeHi));
        bool inverted = c.Amount < 0 && condF1 is null;
        bool outside = (c.Amount < 0 || c.Amount2 < 0) && condF1 is null && condF2 is null;
        string power = Lit.Identifier(c.PowerId ?? "VulnerablePower", "VulnerablePower");
        string target = string.IsNullOrWhiteSpace(c.Target) ? "Self" : c.Target;

        // 「指向对象」：状态层数 / 生命值百分比 这两个条件可以看别人
        string PowerAmount(string creature) => inverted
            ? $"{creature}.GetPowerAmount<{power}>() < {ni}"          // 负数 = 少于 N 层
            : $"{creature}.GetPowerAmount<{power}>() >= {ni}";
        string HpBelow(string creature) => inverted
            ? $"{creature}.CurrentHp * 100 >= {creature}.MaxHp * {cp}" // 负数 = 高于 N%
            : $"{creature}.CurrentHp * 100 <= {creature}.MaxHp * {cp}";
        // 生命区间：在 [lo, hi] 之内 / 之外（含端点）
        string HpInRange(string creature) => outside
            ? $"({creature}.CurrentHp * 100 < {creature}.MaxHp * {lo} || {creature}.CurrentHp * 100 > {creature}.MaxHp * {hi})"
            : $"({creature}.CurrentHp * 100 >= {creature}.MaxHp * {lo} && {creature}.CurrentHp * 100 <= {creature}.MaxHp * {hi})";
        // 敌人列表：过滤掉死掉的（「全部敌人」= 每个活着的敌人都满足，且至少有一个活着的）
        string anyEnemyPower = $"{st} is not null && {st}.Enemies.Any(c => c.IsAlive && {PowerAmount("c")})";
        string allEnemyPower = $"{st} is not null && {st}.Enemies.Any(c => c.IsAlive) && {st}.Enemies.All(c => !c.IsAlive || {PowerAmount("c")})";
        string anyEnemyHp = $"{st} is not null && {st}.Enemies.Any(c => c.IsAlive && {HpBelow("c")})";
        string allEnemyHp = $"{st} is not null && {st}.Enemies.Any(c => c.IsAlive) && {st}.Enemies.All(c => !c.IsAlive || {HpBelow("c")})";
        string anyEnemyRange = $"{st} is not null && {st}.Enemies.Any(c => c.IsAlive && {HpInRange("c")})";
        string allEnemyRange = $"{st} is not null && {st}.Enemies.Any(c => c.IsAlive) && {st}.Enemies.All(c => !c.IsAlive || {HpInRange("c")})";
        // 「指定敌人」= 玩家给这张牌选的目标（cardPlay.Target）。
        // 只有写在 OnPlay 里才拿得到目标；IsPlayable / 描金边那会儿还没选目标，
        // 所以那里会退回「任意一个敌人」（并且校验器会提醒一句）。
        string targetEnemyPower = inOnPlay
            ? $"cardPlay.Target is not null && {PowerAmount("cardPlay.Target")}"
            : anyEnemyPower;
        string targetEnemyHp = inOnPlay
            ? $"cardPlay.Target is not null && {HpBelow("cardPlay.Target")}"
            : anyEnemyHp;
        string targetEnemyRange = inOnPlay
            ? $"cardPlay.Target is not null && {HpInRange("cardPlay.Target")}"
            : anyEnemyRange;

        return c.Kind switch
        {
            "NotPlayedThisTurn" =>
                $"{st} is not null && !CombatManager.Instance.History.CardPlaysFinished.Any(e => e.CardPlay.Card == this && e.HappenedThisTurn({st}))",
            "NotPlayedThisCombat" =>
                "!CombatManager.Instance.History.CardPlaysFinished.Any(e => e.CardPlay.Card == this)",
            "PlayedAtLeast" =>
                $"{st} is not null && CombatManager.Instance.History.CardPlaysFinished.Count(e => e.Actor == {ownerCreature} && e.HappenedThisTurn({st})) {(inverted ? "<" : ">=")} {ni}",
            "HandAtLeast" => inverted ? $"{hand}.Count() < {ni}" : $"{hand}.Count() >= {ni}",
            "HandAtMost" => inverted ? $"{hand}.Count() > {ni}" : $"{hand}.Count() <= {ni}",
            "HandOnlyAttack" => $"{hand}.All(c => c.Type == CardType.Attack)",
            "HandOnlySkill" => $"{hand}.All(c => c.Type == CardType.Skill)",
            "DrawPileEmpty" => $"{player} is not null && !PileType.Draw.GetPile({player}).Cards.Any()",
            "DiscardPileEmpty" => $"{player} is not null && !PileType.Discard.GetPile({player}).Cards.Any()",
            // 生命值 / 状态层数：按「指向对象」看自己 / 指定敌人 / 敌人群体
            "HpBelowPercent" => target switch
            {
                "Enemy" => targetEnemyHp,
                "AnyEnemy" => anyEnemyHp,
                "AllEnemies" => allEnemyHp,
                _ => HpBelow(ownerCreature),
            },
            "HasPowerAtLeast" => target switch
            {
                "Enemy" => targetEnemyPower,
                "AnyEnemy" => anyEnemyPower,
                "AllEnemies" => allEnemyPower,
                _ => PowerAmount(ownerCreature),
            },
            // 生命区间（含「区间外」）：和上面一样按指向对象选看谁
            "HpInRange" => target switch
            {
                "Enemy" => targetEnemyRange,
                "AnyEnemy" => anyEnemyRange,
                "AllEnemies" => allEnemyRange,
                _ => HpInRange(ownerCreature),
            },
            // 额外资源量（本体星星那个计数器）：只有玩家有，所以不看敌人。填负数 = 少于 N 点
            "ExtraResourceAtLeast" => inverted
                ? $"(({player}?.PlayerCombatState?.Stars) ?? 0) < {ni}"
                : $"(({player}?.PlayerCombatState?.Stars) ?? 0) >= {ni}",
            // 「层数刚好达到 N 层」（用户要求）：只在「某个状态层数变化后」那条钩子上成立 ——
            // 那里同时有 power（新的那一份）和 amount（这一次的增量），所以判据是
            // 「现在是 N 层或更多」且「变化之前还不到 N 层」。
            // 别的上下文里没有这两个变量，所以生成成 `false`（永远不成立）—— 校验器会先把它拦住，
            // 这里只是保证「就算漏过校验也不会生成编译不过的代码」。
            "PowerJustReached" => ctx == CondCtx.Power && c.PowerId is { Length: > 0 }
                ? $"power is {c.PowerId} && power.Amount >= {ni} && power.Amount - amount < {ni}"
                : "false",
            // 抽牌堆被洗过牌：本体没有可查询的状态，靠工具生成的记录器（Harmony 补丁记「谁 / 哪一回合 / 洗了几次」）
            "ShuffledThisTurn" => $"{player} is not null && {Naming.AmbientShuffleTrackerClass}.ShuffledThisTurn({player})",
            "ShuffledThisCombat" => $"{player} is not null && {Naming.AmbientShuffleTrackerClass}.ShuffledThisCombat({player})",
            "NoHurtThisTurn" =>
                $"{st} is not null && !CombatManager.Instance.History.Entries.OfType<DamageReceivedEntry>().Any(e => e.Receiver == {ownerCreature} && e.Result.UnblockedDamage > 0 && e.HappenedThisTurn({st}))",
            // 斩杀（本体 Fatal）：判「上一条攻击」有没有真的把目标打死。
            // 生成的两个变量由卡牌 OnPlay 的开头声明、由伤害那一条效果赋值：
            //   AttackCommand? __lastAttack = null;（上一条攻击）
            //   bool __fatalOk = false;（打之前记下的「目标的 Power 允许触发斩杀」——
            //     本体 Feed / HandOfGreed / TheHunt 都是打之前先算 shouldTriggerFatal = target.Powers.All(p => p.ShouldOwnerDeathTriggerFatal())）
            "Fatal" =>
                "__lastAttack is not null && __fatalOk && __lastAttack.Results.SelectMany(hits => hits).Any(r => r.WasTargetKilled)",
            "EveryNTurns" =>
                $"{player}?.PlayerCombatState != null && {player}.PlayerCombatState.TurnNumber % {ni} == 0",
            "OncePerCombat" => "!_condUsedThisCombat",
            // 卡牌时机（需求⑩）：这一条**不是**「打出时的 bool」——带它的效果根本不写进 OnPlay，
            // 而是挂到本体钩子的 override 上（见 EmitCardTimingHooks）。所以这里永远返回 true：
            // 万一有哪条路径真的拿它来判断，也只是「不拦」，不会把卡牌判成永远打不出去。
            "CardTiming" => "true",
            _ => "true",
        };
    }

    /// <summary>
    /// 条件「不满足就 return」的那种写法（遗物的整体触发条件用）：
    /// 「每场战斗一次」是「用过了就退出」，其余条件是「不满足就退出」。
    /// </summary>
    internal static string ConditionGuard(ConditionSpec c) =>
        c.Kind == "OncePerCombat"
            ? "if (_condUsedThisCombat) return;"
            : $"if (!({ConditionExpr(c, isCard: false)})) return;";

    /// <summary>
    /// 一条效果自己的条件：不满足时这条效果跳过（其它效果照常执行）。
    /// kind = 这条效果属于什么（卡牌 / 遗物 / 自定义状态），决定「自己 / 战斗状态」怎么取。
    /// </summary>
    /// <summary>
    /// 「概率生效」的**合并**规则（用户要求）：同一张牌 / 同一只遗物 / 同一个触发时机里，所有勾了概率的
    /// 效果**共用一次掷骰**，各自占一段区间（按它们在列表里的顺序）。
    /// 例：第一条 40%、第二条 60% → 掷出 0~39.999 只跑第一条，40~99.999 只跑第二条
    ///（也就是「第一条没生效时，第二条必然生效」）。
    /// 总和不足 100 时，剩下的概率是「什么都不发生」；总和超过 100 时按比例缩放（校验器会提醒）。
    /// </summary>
    internal static Dictionary<EffectSpec, (double Start, double End)> ChanceSlices(IEnumerable<EffectSpec> effects)
    {
        // 写了「概率公式」的那几条**退出**这个区间划分（它的百分比是运行时才算出来的，
        // 生成时算不出区间）—— 它们各自独立判一次，见 EffectConditionGuard。
        // V0.2.132：勾了「不同效果的概率各自独立判定」（EffectSpec.ChanceIndependent）的也退出 ——
        // 它走的是「自己掷一次」那条路。默认档（false）与以前**逐字节相同**。
        var list = effects.Where(e => e.ChanceEnabled && e.ChancePercent > 0m
            && !e.UsesCountFormula("Chance") && !e.ChanceIndependent).ToList();
        var map = new Dictionary<EffectSpec, (double, double)>();
        if (list.Count == 0) return map;
        double sum = (double)list.Sum(e => e.ChancePercent);
        double scale = sum > 100.0 ? 100.0 / sum : 1.0;
        double cursor = 0;
        foreach (var e in list)
        {
            double len = (double)e.ChancePercent * scale;
            if (len > 100.0) len = 100.0;
            map[e] = (cursor, Math.Min(100.0, cursor + len));
            cursor += len;
        }
        return map;
    }

    /// <summary>需要时给出「共用一次掷骰」的变量声明（没有勾概率的效果就返回 null）。</summary>
    internal static string ChanceRollLine(string ownerExpr = "base.Owner") =>
        $"double __chanceRoll = {ownerExpr}.RunState.Rng.Niche.NextDouble() * 100.0;   // 概率生效：同组效果共用这一次掷骰";

    internal static string? EffectConditionGuard(EffectSpec e, CondCtx ctx, bool inOnPlay = false,
        Dictionary<EffectSpec, (double Start, double End)>? chanceSlices = null)
    {
        string player = ctx == CondCtx.Power ? "base.Owner.Player" : "base.Owner";
        var parts = new List<string>();
        if (e.Condition is not null && !e.Condition.IsNone) parts.Add(ConditionExpr(e.Condition, ctx, inOnPlay));
        // 概率生效：本体自己也是这么掷的（例：Orobas 的 base.Rng.NextFloat() < 0.333f）。
        // 这里用 run 的通用随机数（Rng.Niche），保证同一局里可复现、也不跟抽牌/选目标抢随机序列。
        // 写了「概率公式」的那条（用户要求⑦ 批次 3）：百分比现算 → **自己独立判一次**
        //（不能参与「同组共用一次掷骰、各占一段区间」—— 那段区间是生成时按固定百分比算的）。
        if (CountFormulaExpr(_formulaOwner, e, "Chance", out _) is { } chanceF)
            parts.Add($"__chanceRoll < (double)({chanceF})");
        else if (e.ChanceEnabled && e.ChanceIndependent)
            // V0.2.132：「不同效果的概率之间是否独立」勾上的那一条 —— **自己独立掷一次**
            //（不再和同组其它效果共用一次掷骰 / 各占区间）。默认档不会走到这里，老文本不变。
            parts.Add($"{player}.RunState.Rng.Niche.NextDouble() * 100.0 < {e.ChancePercent.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture)}");
        else if (chanceSlices is not null && chanceSlices.TryGetValue(e, out var slice))
            parts.Add($"__chanceRoll >= {slice.Start.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture)} && __chanceRoll < {slice.End.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture)}");
        else if (e.ChanceEnabled)
            // 没传区间（单独调用）时退回「自己掷一次」的老写法
            parts.Add($"{player}.RunState.Rng.Niche.NextDouble() * 100.0 < {e.ChancePercent.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture)}");
        if (parts.Count == 0) return null;
        return $"if ({string.Join(" && ", parts)})";
    }

    /// <summary>这条效果的守卫说明（生成注释用）：条件 + 概率都写出来。</summary>
    internal static string EffectGuardComment(EffectSpec e)
    {
        var bits = new List<string>();
        if (e.Condition is not null && !e.Condition.IsNone) bits.Add("条件：" + ConditionText(e.Condition));
        if (e.ChanceEnabled)
            bits.Add(string.IsNullOrWhiteSpace(e.ChanceFormula)
                ? $"{e.ChancePercent.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture)}% 概率生效"
                  + (e.ChanceIndependent ? "（各自独立判定）" : "")
                : $"{ForgeFormula.DisplayText(e.ChanceFormula)}% 概率生效（现算，自己独立判一次）");
        return string.Join("；", bits);
    }

    /// <summary>
    /// 全局（牌组）类效果：获得 / 变化 / 删除 —— 直接改玩家的牌组，**跨战斗永久生效**。
    ///
    /// 写法都对着本体源码：
    ///   · 加牌进牌组：<c>owner.RunState.CreateCard(ModelDb.Card&lt;X&gt;(), owner)</c> + <c>CardPileCmd.Add(card, PileType.Deck)</c>
    ///     （本体 AddCursesToDeck 就是这么干的）；
    ///   · 删牌：<c>CardSelectCmd.FromDeckForRemoval</c> + <c>CardPileCmd.RemoveFromDeck</c>
    ///     （本体的篝火「烹饪」CookRestSiteOption 就是这么写的）；
    ///   · 变化：选牌后用 <c>CardCmd.Transform</c> / <c>CardCmd.TransformToRandom</c>
    ///     （和战斗里那版用的是同一对 API，卡在哪一摞都能换）。
    /// </summary>
    private static void EmitGlobalCardEffect(CodeWriter w, EffectSpec e, string owner, bool useX = false,
        CharacterProfile? p = null)
    {
        string n = (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string? target = string.IsNullOrWhiteSpace(e.SpawnCardId) ? null : e.SpawnCardId!.Trim();
        string rng = $"{owner}.RunState.Rng.Niche";
        if (e.UsesSpawnOptions) w.Line(SpawnMarker(e));
        CountModeMarker(w, e);

        switch (e.Kind)
        {
            case "AddCardGlobal":
                if (!e.IsSpawnRandom)
                {
                    w.Line($"// 获得 {n} 张 {target ?? "Shiv"}：直接加进牌组（永久，不是战斗里的手牌 / 抽牌堆）");
                    w.Open($"for (int __addIdx = 0; __addIdx < {n}; __addIdx++)");
                    w.Line($"CardModel gained = {owner}.RunState.CreateCard(ModelDb.Card<{target ?? "Shiv"}>(), {owner});");
                    if (e.SpawnUpgraded) w.Line("CardCmd.Upgrade(gained);   // 加进牌组时就是升级过的");
                    EmitSpawnKeyword(w, e, "gained", p);   // 需求 ⑦：加进牌组的这张卡也带上关键词
                    w.Line("await CardPileCmd.Add(gained, PileType.Deck);");
                    w.Close();
                    break;
                }
                // 按范围随机：从卡池里抽，再逐张加进牌组
                w.Line($"// 按范围随机获得 {n} 张「{EffectCatalog.SpawnFilterZh(e.SpawnFilter)}」加进牌组（永久）");
                w.Line($"var __addPool = {SpawnPoolExpr(e, p, owner)};");
                w.Open($"for (int __addIdx = 0; __addIdx < {n}; __addIdx++)");
                w.Line($"CardModel? __pickCard = {rng}.NextItem(__addPool);");
                w.Line("if (__pickCard is null) break;");
                w.Line($"CardModel gained = {owner}.RunState.CreateCard(__pickCard, {owner});");
                if (e.SpawnUpgraded) w.Line("CardCmd.Upgrade(gained);   // 加进牌组时就是升级过的");
                EmitSpawnKeyword(w, e, "gained", p);   // 需求 ⑦：加进牌组的这张卡也带上关键词
                w.Line("await CardPileCmd.Add(gained, PileType.Deck);");
                w.Close();
                break;

            case "RemoveCardGlobal":
                if (e.CountIsAll)
                {
                    // 「全部」：整个牌组里能删的牌一次全删（不弹选牌界面）。
                    w.Line(SelfContainedMarker(e));   // 这一档没有选牌语句可认，回读靠它
                    w.Line("// 全部：把牌组里能删的牌**全部**删掉（不弹选牌界面）");
                    w.Line($"foreach (CardModel c in PileType.Deck.GetPile({owner}).Cards.Where(c => c.IsRemovable).ToList()) await CardPileCmd.RemoveFromDeck(c);");
                    break;
                }
                if (e.CardPick == "Chosen")
                {
                    w.Line($"// 自己选 {n} 张牌从牌组里删掉（本体的「移除卡牌」界面）");
                    w.Line($"var toRemove = (await CardSelectCmd.FromDeckForRemoval({owner}, new CardSelectorPrefs(CardSelectorPrefs.RemoveSelectionPrompt, {n}) {{ Cancelable = true, RequireManualConfirmation = true }})).ToList();");
                    w.Line("foreach (CardModel c in toRemove) await CardPileCmd.RemoveFromDeck(c);");
                }
                else
                {
                    w.Line($"// 随机从牌组里删 {n} 张牌");
                    w.Open($"for (int __pickIdx = 0; __pickIdx < {n}; __pickIdx++)");
                    w.Line($"CardModel? pick = {rng}.NextItem(PileType.Deck.GetPile({owner}).Cards.Where(c => c.IsRemovable));");
                    w.Line("if (pick is null) break;");
                    w.Line("await CardPileCmd.RemoveFromDeck(pick);");
                    w.Close();
                }
                break;

            // 升级牌组里的牌（永久）：本体「香盒 Pomander / 混沌之香 AromaOfChaos」的写法 ——
            // CardSelectCmd.FromDeckForUpgrade（那个界面只列能升级的牌）+ CardCmd.Upgrade。
            // 和战斗里那个「升级卡牌」不是一回事：这个直接改玩家的牌组（写进存档、跨战斗）。
            case "UpgradeCardGlobal":
                if (e.CountIsAll)
                {
                    // 「全部」：牌组里能升级的牌一次全升级（不弹选牌界面）。
                    w.Line(SelfContainedMarker(e));   // 这一档没有选牌语句可认，回读靠它
                    w.Line("// 全部：把牌组里能升级的牌**全部**升级（不弹选牌界面）");
                    w.Line($"foreach (CardModel c in PileType.Deck.GetPile({owner}).Cards.Where(c => c.IsUpgradable).ToList()) CardCmd.Upgrade(c);");
                    break;
                }
                if (e.CardPick == "Chosen")
                {
                    w.Line($"// 自己选 {n} 张牌组里的牌升级（本体的「升级卡牌」界面）");
                    w.Line($"var toUpgradeDeck = (await CardSelectCmd.FromDeckForUpgrade({owner}, new CardSelectorPrefs(CardSelectorPrefs.UpgradeSelectionPrompt, {n}))).ToList();");
                    w.Line("foreach (CardModel c in toUpgradeDeck) CardCmd.Upgrade(c);");
                }
                else
                {
                    w.Line($"// 随机把牌组里 {n} 张能升级的牌升级");
                    w.Open($"for (int __pickIdx = 0; __pickIdx < {n}; __pickIdx++)");
                    w.Line($"CardModel? pick = {rng}.NextItem(PileType.Deck.GetPile({owner}).Cards.Where(c => c.IsUpgradable));");
                    w.Line("if (pick is null) break;");
                    w.Line("CardCmd.Upgrade(pick);");
                    w.Close();
                }
                break;

            case "TransformCardGlobal":
                if (e.IsSpawnRandom)
                    w.Line($"var __transformPool = {SpawnPoolExpr(e, p, owner)};   // 变化范围：{EffectCatalog.SpawnFilterZh(e.SpawnFilter)}");
                if (e.CountIsAll)
                {
                    // 「全部」：整个牌组一次全变化（不弹选牌界面）。
                    w.Line(SelfContainedMarker(e));   // 这一档没有选牌语句可认，回读靠它
                    w.Line("// 全部：把牌组里的牌**全部**变化（不弹选牌界面）");
                    w.Open($"foreach (CardModel c in PileType.Deck.GetPile({owner}).Cards.ToList())");
                    EmitTransformGlobalBody(w, e, owner, rng, "c", target, p);
                    w.Close();
                    break;
                }
                if (e.CardPick == "Chosen")
                {
                    w.Line($"// 自己选 {n} 张牌组里的牌变化：{(e.IsSpawnRandom ? "按范围随机" : target ?? "随机变化")}");
                    w.Line($"var toTransformDeck = (await CardSelectCmd.FromDeckGeneric({owner}, new CardSelectorPrefs(CardSelectorPrefs.TransformSelectionPrompt, {n}), null, null)).ToList();");
                    w.Line("foreach (CardModel c in toTransformDeck)");
                    w.Open("");
                    EmitTransformGlobalBody(w, e, owner, rng, "c", target, p);
                    w.Close();
                }
                else
                {
                    w.Line($"// 随机把牌组里 {n} 张牌变化：{(e.IsSpawnRandom ? "按范围随机" : target ?? "随机变化")}");
                    w.Open($"for (int __pickIdx = 0; __pickIdx < {n}; __pickIdx++)");
                    w.Line($"CardModel? pick = {rng}.NextItem(PileType.Deck.GetPile({owner}).Cards);");
                    w.Line("if (pick is null) break;");
                    EmitTransformGlobalBody(w, e, owner, rng, "pick", target, p);
                    w.Close();
                }
                break;
        }
    }

    /// <summary>牌组里的牌变成什么：按范围随机抽一张 / 指定的那张 / 本体的随机变化；抽到的还能直接是升级过的。</summary>
    private static void EmitTransformGlobalBody(CodeWriter w, EffectSpec e, string owner, string rng, string cardVar, string? target,
        CharacterProfile? p = null)
    {
        if (e.IsSpawnRandom)
        {
            w.Line($"CardModel? __newDeck = {rng}.NextItem(__transformPool);");
            w.Open("if (__newDeck is not null)");
            w.Line($"CardModel __made = {owner}.RunState.CreateCard(__newDeck, {owner});");
            if (e.SpawnUpgraded) w.Line("CardCmd.Upgrade(__made);   // 变出来就是升级过的");
            w.Line($"await CardCmd.Transform({cardVar}, __made);");
            EmitSpawnKeyword(w, e, "__made", p);   // 需求 ⑦：变出来的这张卡带上关键词
            w.Close();
            return;
        }
        // 需求 ⑦：和战斗里那条变化一样，要拿到本体返回的新卡才能加关键词（这一段只在选了关键词时生成）
        if (e.HasSpawnKeyword)
        {
            bool randomVanilla = target is null;
            w.Line("// 变化出来的卡要带关键词：先接住本体返回的 cardAdded（新卡是它新建的）");
            w.Line($"var __tr = await {(randomVanilla
                ? $"CardCmd.TransformToRandom({cardVar}, {rng})"
                : $"CardCmd.Transform({cardVar}, {owner}.RunState.CreateCard(ModelDb.Card<{target}>(), {owner}))")};");
            // 同战斗里那条：TransformToRandom 返回不可空结构体，Transform 返回可空结构体，取值写法分开
            EmitSpawnKeyword(w, e, randomVanilla ? "__tr.cardAdded?" : "__tr?.cardAdded?", p);
            return;
        }
        w.Line(target is null
            ? $"await CardCmd.TransformToRandom({cardVar}, {rng});"
            : $"await CardCmd.Transform({cardVar}, {owner}.RunState.CreateCard(ModelDb.Card<{target}>(), {owner}));");
    }

    /// <summary>给别的生成器（自定义状态）用的入口：全局牌组类效果。</summary>
    internal static void EmitGlobalCardEffectPublic(CodeWriter w, EffectSpec e, string owner, bool amountIsStack,
        CharacterProfile? p = null)
    {
        var probe = new EffectSpec
        {
            Kind = e.Kind,
            Amount = e.Amount,
            AmountIsX = amountIsStack,     // 借「数值 = 本状态的层数」这条路：按 base.Amount 张处理
            SpawnCardId = e.SpawnCardId,
            CardPick = e.CardPick,
            SpawnFilter = e.SpawnFilter,
        };
        EmitGlobalCardEffect(w, probe, owner, useX: amountIsStack, p: p);
    }

    /// <summary>
    /// 「转化为先古卡」的预览界面顶部那行说明用的本地化键（本体 <c>NSimpleCardsViewScreen.ShowScreen</c>
    /// 第二个参数是 LocString，潘多拉传的是自己的 relics 表键）。
    /// 所有配对行共用这一条，写到 <c>relics.json</c> 的 <c>ANCIENT_TRANSCEND.infoText</c>。
    /// </summary>
    public const string AncientPreviewLocKey = "ANCIENT_TRANSCEND.infoText";

    /// <summary>
    /// 选牌界面那个 <c>CardSelectorPrefs</c> 的构造表达式（选牌类效果共用）。
    ///
    /// 三档（需求：「消耗任意张手牌」）：
    ///   · 恰好 N 张（<see cref="EffectCatalog.CountModes.Exact"/>，默认）→ <c>new CardSelectorPrefs(prompt, N)</c>
    ///     —— **和以前逐字一致**；
    ///   · 最多 N 张（<c>UpTo</c>）→ <c>new CardSelectorPrefs(prompt, 0, N)</c>，本体「净化 Purity」的写法
    ///     （<c>MinSelect != MaxSelect</c> 时本体自己会变成「要点确认才结算」）；
    ///   · 任意张（<c>Any</c>）→ <c>new CardSelectorPrefs(prompt, 0, 999999999)</c>，本体自己用的就是这个大数。
    /// 提示语只能是**静态**属性（<c>CardSelectorPrefs.Prompt</c> 是实例属性，写了会 CS0120）。
    /// </summary>
    internal static string SelectPrefsExpr(EffectSpec e, string prompt, string n, bool playerIsBaseOwner = true)
    {
        _ = playerIsBaseOwner;   // 保留参数是为了调用处读起来清楚（玩家是谁由 prompt 那侧决定）
        string count = e.CountMode switch
        {
            CountModes.UpTo => $"0, {n}",
            CountModes.Any => $"0, {CountModes.AnyMax}",
            _ => n,
        };
        return $"new CardSelectorPrefs({prompt}, {count})";
    }

    /// <summary>「任意张 / 全部」时没有数字可显示（卡面 / 校验都用它判断）。</summary>
    internal static bool CountIsAny(EffectSpec e) => e.CountIsAny;

    /// <summary>「全部」：不弹选牌界面，直接对那一摞里符合条件的每一张动手（本体「恶魔之焰」那种）。</summary>
    internal static bool CountIsAll(EffectSpec e) => e.CountIsAll;

    /// <summary>
    /// 「取几张」不是默认档（最多 N / 任意张 / 全部）时写一行标记 —— 回读靠它还原
    /// （V0.2.163 起；默认档「恰好 N 张」**一个字符都不写**，老工程的输出逐字不变）。
    /// </summary>
    internal static void CountModeMarker(CodeWriter w, EffectSpec e)
    {
        if (e.CountMode != CountModes.Exact) w.Line($"// CET:CountMode={e.CountMode}");
    }

    /// <summary>「最多 N 张 / 任意张」时选牌界面的上限表达式（Any 用一个很大的数，本体自己也是这么写的）。</summary>
    internal static string RangeN(EffectSpec e, string n) =>
        e.CountMode == CountModes.Any ? CountModes.AnyMax.ToString() : n;

    /// <summary>注释 / 卡面描述里那句「几张」（任意张 = 「任意」、全部 = 「所有」）。</summary>
    internal static string CountZh(EffectSpec e, string n) =>
        e.CountIsAll ? "所有" : e.CountIsAny ? "任意" : n;

    /// <summary>
    /// 「转化为先古卡」：照本体「古老牙齿 ArchaicTooth」的语义 ——
    /// 在**牌组**里按「组」找牌，原地换成先古卡（批量 <c>CardCmd.Transform</c>），升级 / 附魔继承。
    ///
    /// 需求原文：「本体中有一些遗物会替换卡牌成先古卡牌」+「能够选一组卡全变成不同的先古卡吗」
    /// +「来源只用组就行」+ 池子用完「不换」（下策 b）。
    ///
    /// 生成形态（每行一段，行与行互不干扰）：
    /// <code>
    /// var __fgAncient0_0_src = PileType.Deck.GetPile(base.Owner).Cards.Where(c => c.IsRemovable &amp;&amp; 组条件).ToList();
    /// var __fgAncient0_0_pool = new List&lt;CardModel&gt; { ModelDb.Card&lt;Break&gt;(), … };   // 这一行勾的先古卡
    /// for (…) { … 升级 / 附魔继承 … }
    /// var __fgAncient0_0_done = (await CardCmd.Transform(__fgAncient0_0_tx, null, CardPreviewStyle.None)).ToList();
    /// </code>
    /// 关键点：
    ///   · 条件里带 <c>c.IsRemovable</c>（本体「永恒」的牌不能被变化，潘多拉也这么判）；
    ///   · 循环上界是 <c>src.Count</c> 与 <c>pool.Count</c> 的**较小值** → 池子不够时后面几张**保持原样**（不循环复用）；
    ///   · 一行之内不重复（池子按勾选顺序发，取过的不再用）。
    /// </summary>
    public static void EmitAncientTranscend(CodeWriter w, CharacterProfile p, EffectSpec e, int rowIndex)
    {
        var rows = e.AncientRows;
        if (rows is null || rows.Count == 0)
        {
            w.Line("// ⚠「转化为先古卡」的配对表是空的：这条效果什么都不做（到「遗物」页给它加一行「源组 → 先古卡」）。");
            return;
        }
        for (int r = 0; r < rows.Count; r++)
        {
            var row = rows[r];
            if (row is null || string.IsNullOrWhiteSpace(row.Group)) continue;
            var pool = (row.AncientCards ?? new List<string>())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Select(x => x.Trim())
                .Distinct(StringComparer.Ordinal)
                .ToList();
            string tag = $"__fgAncient{rowIndex}_{r}";
            w.Line($"// ---- 转化为先古卡 第 {r + 1} 行：{EffectCatalog.SpawnFilterZh(row.Group)} → "
                + (pool.Count == 0 ? "（还没勾先古卡）" : string.Join("、", pool)) + " ----");
            if (pool.Count == 0)
            {
                w.Line("// ⚠ 这一行还没勾任何先古卡：跳过（校验器也会报错）。");
                continue;
            }
            string cond = SpawnPoolCond(row.Group, p);      // 复用「范围限定」那套判据（组 / 关键词）
            string poolExpr = "new List<CardModel> { " + string.Join(", ", pool.Select(x => $"ModelDb.Card<{x}>()")) + " }";
            w.Line($"var {tag}_src = PileType.Deck.GetPile(base.Owner).Cards.Where(c => c.IsRemovable && ({cond})).ToList();");
            w.Line($"var {tag}_pool = {poolExpr};");
            w.Line(SelfContainedMarker(e));
            w.Line("// 换成**不同**的先古卡：池子按顺序一张牌一个；池子不够时后面那几张保持原样（不重复复用）");
            w.Open($"if ({tag}_src.Count > {tag}_pool.Count)");
            w.Line($"Log.Warn(\"转化为先古卡：这一行匹配到 \" + {tag}_src.Count + \" 张，但只勾了 \" + {tag}_pool.Count + \" 张先古卡 —— 多出来的保持原样\");");
            w.Close();
            w.Line($"var {tag}_tx = new List<CardTransformation>();");
            w.Open($"for (int {tag}_i = 0; {tag}_i < {tag}_src.Count && {tag}_i < {tag}_pool.Count; {tag}_i++)");
            w.Line($"CardModel {tag}_from = {tag}_src[{tag}_i];");
            w.Line($"CardModel {tag}_to = base.Owner.RunState.CreateCard({tag}_pool[{tag}_i], base.Owner);");
            w.Open($"if ({tag}_from.IsUpgraded)");
            w.Line($"    CardCmd.Upgrade({tag}_to);   // 保留升级（本体古老牙齿的做法）");
            w.Close();
            w.Open($"if ({tag}_from.Enchantment is not null)");
            w.Line($"    CardCmd.Enchant((EnchantmentModel){tag}_from.Enchantment.MutableClone(), {tag}_to, {tag}_from.Enchantment.Amount);   // 保留附魔");
            w.Close();
            w.Line($"{tag}_tx.Add(new CardTransformation({tag}_from, {tag}_to));");
            w.Close();
            // ⚠ CardPreviewStyle 的命名空间是 Nodes.CommonUi（不在生成工程的 global using 里），
            // 必须写全名，否则 CS0103（实测踩过）。
            w.Line($"var {tag}_done = (await CardCmd.Transform({tag}_tx, null, MegaCrit.Sts2.Core.Nodes.CommonUi.CardPreviewStyle.None)).ToList();");
            w.Line($"// 预览（本体潘多拉那套界面）：{tag}_done 里就是这一次变出来的牌");
            w.Line("__fgAncientPreview.AddRange(" + tag + "_done);");
        }
    }

    /// <summary>
    /// 「转化为先古遗物」：照本体「欧洛巴斯之触 TouchOfOrobas」——
    /// 拾起时把身上的**一个遗物**原地换成另一个（<c>RelicCmd.Replace</c>，位置不变）。
    ///
    /// 需求原文：「那先古遗物的替换遗物也搞一个类似的吧」（前一条是「转化为先古卡」）。
    ///
    /// 生成形态：
    /// <code>
    /// RelicModel? __fgSwapSrc = base.Owner.Relics.FirstOrDefault(r => r.Rarity == RelicRarity.Starter);   // 源（按筛选档）
    /// if (__fgSwapSrc is not null) {
    ///     RelicModel __fgSwapTo = ModelDb.Relic&lt;BlackBlood&gt;().ToMutable();
    ///     await RelicCmd.Replace(__fgSwapSrc, __fgSwapTo);
    ///     Log.Info("转化为先古遗物：把 X 换成了 Y");
    /// } else Log.Warn("…身上没有符合条件的遗物，这一条什么也没做");
    /// </code>
    /// 关键点：
    ///   · 源筛选三档：不限（身上第一个遗物）/ 只要初始遗物（本体欧洛巴斯之触的判据）/ 指定某一类本体遗物；
    ///   · 目标遗物就是效果里填的「遗物类名」（自己的遗物走非限定类名解析；本体遗物直接 ModelDb.Relic&lt;T&gt;）；
    ///   · **只换第一个匹配到的**（本体也是 `First`），没有匹配到就什么都不做（不静默：打一行日志）。
    /// </summary>
    public static void EmitAncientRelicSwap(CodeWriter w, CharacterProfile p, EffectSpec e)
    {
        string? target = string.IsNullOrWhiteSpace(e.SpawnCardId) ? null : e.SpawnCardId!.Trim();
        w.Line($"// ---- 转化为先古遗物：源 = {EffectCatalog.RelicSwapFilterZh(e.SpawnFilter)}"
            + $" → {target ?? "（还没选目标遗物）"} ----");
        if (target is null)
        {
            w.Line("// ⚠ 这一条还没选「目标遗物」：跳过（校验器也会报错）。");
            return;
        }
        string filter = e.SpawnFilter switch
        {
            EffectCatalog.RelicFilterStarter => "r.Rarity == RelicRarity.Starter",
            _ => EffectCatalog.RelicFilterClass(e.SpawnFilter) is string cls
                ? $"r.Id.Entry == \"{cls}\""
                : "true",
        };
        w.Line($"RelicModel? __fgSwapSrc = base.Owner.Relics.FirstOrDefault(r => {filter});");
        w.Open("if (__fgSwapSrc is not null)");
        w.Line($"RelicModel __fgSwapTo = ModelDb.Relic<{target}>().ToMutable();");
        w.Line("await RelicCmd.Replace(__fgSwapSrc, __fgSwapTo);   // 原地替换，位置不变（本体欧洛巴斯之触的写法）");
        w.Line("Log.Info(\"转化为先古遗物：把 \" + __fgSwapSrc.Id.Entry + \" 换成了 \" + __fgSwapTo.Id.Entry);");
        w.Close();
        w.Line("else Log.Warn(\"转化为先古遗物：身上没有符合条件的遗物（"
            + EffectCatalog.RelicSwapFilterZh(e.SpawnFilter).Replace("\"", "'") + "），这一条什么也没做\");");
    }

    /// <summary>
    /// 「范围限定 / 范围界定」那套判据的**单个卡谓词**（不含 <c>c =&gt; </c> 前缀）。
    /// 和 <see cref="SpawnPoolExpr"/> 共用同一份语义：组 / 自定义关键词按类名白名单，
    /// 内置那几条按类型 / 稀有度。
    /// </summary>
    internal static string SpawnPoolCond(string? filter, CharacterProfile? p)
    {
        if (EffectCatalog.IsKeywordFilter(filter) || EffectCatalog.IsCardGroupFilter(filter))
        {
            var group = EffectCatalog.IsCardGroupFilter(filter)
                ? EffectCatalog.CardGroupCards(p, filter)
                : EffectCatalog.KeywordGroupCards(p, filter);
            if (group.Count == 0) return "false";     // 这一组一张牌都没有：谁都不匹配
            var kn = Naming.From(p!);
            string names = string.Join(", ", group.Select(c => $"\"{kn.CardClassName(p!, c)}\""));
            return $"new[] {{ {names} }}.Contains(c.Id.Entry)";
        }
        return filter switch
        {
            "Attack" => "c.Type == CardType.Attack",
            "Skill" => "c.Type == CardType.Skill",
            "Power" => "c.Type == CardType.Power",
            "Curse" => "c.Rarity == CardRarity.Curse",
            "Status" => "c.Type == CardType.Status || c.Rarity == CardRarity.Status",
            _ => "true",
        };
    }

    /// <summary>给自定义状态用的入口：获得卡牌奖励（roomVar 非空 = 钩子里有 CombatRoom，走本体「战斗奖励」那条路）。</summary>
    internal static void EmitCardRewardPublic(CodeWriter w, EffectSpec e, string owner, bool amountIsStack, string? roomVar = null) =>
        EmitCardReward(w, e, owner, useX: amountIsStack, roomVar: roomVar);

    // ==================== 状态悬停提示（ExtraHoverTips） ====================
    //
    // 本体里「卡面 / 遗物 / 药水描述里提到某个状态」时，鼠标移上去能弹出那个状态的说明 ——
    // 靠的是模型自己声明 ExtraHoverTips（例：本体的 Abrasive 写
    // protected override IEnumerable<IHoverTip> ExtraHoverTips => [HoverTipFactory.FromPower<DexterityPower>()]）。
    //
    // 我们生成的卡牌/遗物/药水以前没有这一段，于是：
    //   · 本体状态被改写后（改了名字和描述），悬停看不到任何说明 → 用户报了这一点；
    //   · 自定义状态（能力牌用）提到时也没有说明 → 遗物/药水同理。
    // 现在按「这条效果施加的状态 + 条件里盯的状态」自动生成这一段（下回合生效的走延迟状态类）。
    // 文本取自本体的 powers 本地化表：本体状态改写后我们覆盖了同名的键，所以弹出来的就是新名字 + 新描述。

    /// <summary>把这条效果用到的状态写成 HoverTipFactory.FromPower&lt;X&gt;(N) 调用（没有就返回空）。</summary>
    internal static List<string> HoverTipsOf(IEnumerable<EffectSpec> effects, bool isCard = false,
        CharacterProfile? owner = null)
    {
        var list = new List<string>();
        var all = effects as IList<EffectSpec> ?? effects.ToList();
        foreach (var e in all)
        {
            if (e.Kind is "ApplyPower" or "TempPower" && !string.IsNullOrWhiteSpace(e.PowerId))
            {
                // 临时增益指向的是**生成的那个临时 Power**（它自己有一条 powers 本地化：「临时 X / 本回合+X，回合结束消失」），
                // 指向本体那个状态的话，悬停里就只会说「气势」而看不出这是临时的。
                string type = e.Kind == "TempPower"
                    ? TempPowerClassName(e, owner)
                    : e.NextTurn ? DelayedPowerClassName(e, owner) : e.PowerId!.Trim();
                // 「数值 = 层数 / X」时数量说不准，就不写数量（本体自己也有不写数量的写法）
                string amount = (e.AmountIsXEffective || e.AmountIsStack || e.Amount <= 0)
                    ? ""
                    : ((int)e.Amount).ToString(System.Globalization.CultureInfo.InvariantCulture);
                list.Add($"MegaCrit.Sts2.Core.HoverTips.HoverTipFactory.FromPower<{type}>({amount})");
            }
            // 条件里盯的状态：「拥有破绽至少 N 层」鼠标移上去也该有说明
            if (e.Condition is not null && !e.Condition.IsNone
                && e.Condition.Kind == "HasPowerAtLeast" && !string.IsNullOrWhiteSpace(e.Condition.PowerId))
                list.Add($"MegaCrit.Sts2.Core.HoverTips.HoverTipFactory.FromPower<{e.Condition.PowerId!.Trim()}>()");
            // 击晕：本体里它是怪物意图（不是状态），本体卡「口哨」用的就是这条静态提示
            if (e.Kind == "Stun")
                list.Add("MegaCrit.Sts2.Core.MonsterMoves.Intents.StunIntent.GetStaticHoverTip()");
        }

        // 额外资源量（本体的「星星」计数器）：本体没有专门给卡牌用的静态提示，
        // 这里用**我们自己的**那两条文本（`<角色>_EXTRA_RESOURCE.title/.description`）——
        // ⚠ 不能再用本体的 STAR_COUNT.*：那两个键是全局的，多个角色模组共存（联机时要装同一套）时
        //   互相覆盖，两个人看到的资源名会不一样（而且我们自己的卡不该跟着别的模组的改名走）。
        string resPrefix = Naming.From(owner ?? new CharacterProfile()).CharEntry;
        if (all.Any(e => e.Kind == "ExtraResource"))
            list.Add("new MegaCrit.Sts2.Core.HoverTips.HoverTip(new LocString(\"static_hover_tips\", "
                + Lit.Str(resPrefix + "_EXTRA_RESOURCE.title")
                + "), new LocString(\"static_hover_tips\", " + Lit.Str(resPrefix + "_EXTRA_RESOURCE.description") + "))");

        // 获得能量：本体卡就是这么提示的（base.EnergyHoverTip）
        if (isCard && all.Any(e => e.Kind == "Energy"))
            list.Add("base.EnergyHoverTip");

        // 「获得卡牌奖励」：本体有现成的静态提示（StaticHoverTip.CardReward）
        if (all.Any(e => e.Kind == "CardReward"))
            list.Add("MegaCrit.Sts2.Core.HoverTips.HoverTipFactory.Static(MegaCrit.Sts2.Core.HoverTips.StaticHoverTip.CardReward)");

        return list.Distinct(StringComparer.Ordinal).ToList();
    }

    /// <summary>生成 ExtraHoverTips 覆写（没用到状态就返回空字符串）。isPublic = 药水（基类是 public）。</summary>
    /// <param name="extraTips">
    /// 额外的提示表达式（目前用于自定义关键词）：排在状态提示**前面**，
    /// 因为卡面上关键词也是排在描述最前面的。
    /// </param>
    /// <param name="upgradedKeywordTips">
    /// V0.2.136：「升级后获得 / 失去的自定义关键词」那两条提示（获得 / 失去各一组，都可以为空）。
    /// 两组都空时走的还是**老路径**（表达式体 <c>=&gt; [ … ]</c>，逐字节不变）；
    /// 有一组非空时才改成带方法体的条件版本（按 <c>base.IsUpgraded</c> 加/不加那条）。
    /// </param>
    internal static string HoverTipsOverride(IEnumerable<EffectSpec> effects, bool isPublic, bool isCard = false,
        IEnumerable<string>? extraTips = null, CharacterProfile? owner = null,
        (List<string> Add, List<string> Del)? upgradedKeywordTips = null, bool refreshFormulaPreview = false)
    {
        var tips = new List<string>();
        if (extraTips is not null) tips.AddRange(extraTips);
        tips.AddRange(HoverTipsOf(effects, isCard, owner));
        // 用了「斩杀」条件 → 挂上本体那条「斩杀」悬停说明（本体 Feed / HandOfGreed / TheHunt 都是
        // `HoverTipFactory.Static(StaticHoverTip.Fatal)`），不然玩家只看到卡面上一句「斩杀时…」不知道是什么。
        if (effects.Any(x => x.Condition is { Kind: "Fatal" }))
            tips.Add("MegaCrit.Sts2.Core.HoverTips.HoverTipFactory.Static(MegaCrit.Sts2.Core.HoverTips.StaticHoverTip.Fatal)");
        tips = tips.Distinct(StringComparer.Ordinal).ToList();

        var upAdd = (upgradedKeywordTips?.Add ?? new List<string>()).Distinct(StringComparer.Ordinal).ToList();
        var upDel = (upgradedKeywordTips?.Del ?? new List<string>()).Distinct(StringComparer.Ordinal).ToList();
        bool anyUpgradeTips = upAdd.Count > 0 || upDel.Count > 0;
        // refreshFormulaPreview：遗物 / 药水用了「数值公式」时**必须**生成这个 override
        //（哪怕一条状态提示都没有）—— 它是我们唯一的「显示前现算」挂点，见 FormulaPreviewRefreshMethod。
        if (tips.Count == 0 && !anyUpgradeTips && !refreshFormulaPreview) return "";

        string access = isPublic ? "public override" : "protected override";

        // V0.2.164：要现算就先跑一句再返回。⚠ 属性**不能**直接写方法体（`P { 语句; }` 不是合法 C#，
        // 会报 CS8124「元组必须包含至少两个元素」——探针真编译抓出来的），必须写成 get 访问器。
        if (refreshFormulaPreview && !anyUpgradeTips)
        {
            var w3 = new CodeWriter();
            w3.Line();
            w3.Line("    // 鼠标悬停描述里的状态时弹出的说明（文本来自本体 powers / static_hover_tips 表；本体状态被改写后就是新名字 + 新描述）");
            w3.Line("    // （同一条属性顺带把「数值公式」的预览值现算一遍，见 __RefreshFormulaPreview）");
            w3.Line($"    {access} IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> ExtraHoverTips");
            w3.Line("    {");
            w3.Line("        get");
            w3.Line("        {");
            w3.Line("            __RefreshFormulaPreview();");
            w3.Line("            return");
            w3.Line("            [");
            for (int i = 0; i < tips.Count; i++)
                w3.Line($"                {tips[i]}{(i == tips.Count - 1 ? "" : ",")}");
            w3.Line("            ];");
            w3.Line("        }");
            w3.Line("    }");
            return w3.ToString();
        }

        if (anyUpgradeTips)
        {
            // ⚠ 这一段**只在这两栏真填了东西时**才生成（老存档走的还是下面那个表达式体，逐字节不变）。
            // 为什么要按 IsUpgraded 分两段而不是全部塞进去：塞进去的话，没升级时悬停也会弹出「升级后才有的
            // 关键词」说明 —— 卡面上没那行字却悬停有说明，看着像 bug。
            //
            // 写法：**表达式体的迭代器方法**（`=> [ … ]` 里按条件展开），只替换掉老写法的那两行。
            // 为什么不写成 `{ get { yield return … } }`：生成端要自己数大括号，
            // 而这里嵌在类里（外层还有类的大括号）—— 实测那样写会少一个大括号、CS1513。
            // 表达式体没有这个风险（老写法本来就是这么写的，只是列表内容换成了条件展开）。
            var w2 = new CodeWriter();
            w2.Line();
            w2.Line("    // 鼠标悬停描述里的状态时弹出的说明（文本来自本体 powers / static_hover_tips 表；本体状态被改写后就是新名字 + 新描述）");
            w2.Line("    // 「升级后获得 / 失去的自定义关键词」按 base.IsUpgraded 条件加/不加那条 ——");
            w2.Line("    // 自定义关键词是**封闭枚举之外**的显示等价物（卡面那行 [gold]…[/gold]。+ 本地化键 + 这里的悬停说明），");
            w2.Line("    // 游戏侧没有任何按它判定的逻辑，所以这一段**只影响显示**，不是机制层面的变化。");
            w2.Line($"    {access} IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> ExtraHoverTips =>");
            w2.Line("    [");
            var upTips = tips.Concat(upAdd).Distinct(StringComparer.Ordinal).ToList();
            if (upTips.Count > 0)
            {
                w2.Line("        ..(base.IsUpgraded ? new MegaCrit.Sts2.Core.HoverTips.IHoverTip[]");
                w2.Line("        {");
                for (int i = 0; i < upTips.Count; i++)
                    w2.Line($"            {upTips[i]}{(i == upTips.Count - 1 ? "" : ",")}");
                w2.Line("        } : Array.Empty<MegaCrit.Sts2.Core.HoverTips.IHoverTip>()),");
            }
            for (int i = 0; i < tips.Count; i++)
                w2.Line($"        {tips[i]}{(i == tips.Count - 1 ? "" : ",")}");
            w2.Line("    ];");
            return w2.ToString();
        }

        var w = new CodeWriter();
        w.Line();
        w.Line("    // 鼠标悬停描述里的状态时弹出的说明（文本来自本体 powers / static_hover_tips 表；本体状态被改写后就是新名字 + 新描述）");
        w.Line($"    {access} IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> ExtraHoverTips =>");
        w.Line("    [");
        for (int i = 0; i < tips.Count; i++)
            w.Line($"        {tips[i]}{(i == tips.Count - 1 ? "" : ",")}");
        w.Line("    ];");
        return w.ToString();
    }

    /// <summary>
    /// 卡牌的一对「升级后获得 / 失去的自定义关键词」提示（V0.2.136）。
    /// 没填就返回 null —— 调用方据此走老路径（<see cref="HoverTipsOverride"/> 的表达式体）。
    /// </summary>
    internal static (List<string> Add, List<string> Del)? UpgradeKeywordTips(CharacterProfile p, CardSpec c)
    {
        var add = KeywordGen.TipsFor(p, c.UpgradeAddedCustomKeywords);
        var del = KeywordGen.TipsFor(p, c.UpgradeRemovedCustomKeywords);
        if (add.Count == 0 && del.Count == 0) return null;
        return (add, del);
    }

    //
    // ==================== 本体「缓慢」：直接设百分比 ====================
    //
    // 用户报过：「施加 30 层缓慢」在游戏里只看到「缓慢」、吃不到 30 层的加成。
    // 原因在本体 SlowPower：
    //   · DisplayAmount => DynamicVars["SlowAmount"].IntValue * 10  ← 状态栏显示的是它
    //   · ModifyDamageMultiplicative => 1 + 0.1 * SlowAmount        ← 实际加伤用的也是它
    //   · AfterCardPlayed => SlowAmount++（每打出一张牌 +10%）、敌人回合开始清零
    // 也就是说「缓慢」的层数（Amount）跟它的效果完全无关，本体自己施加时也只给 1 层。
    // 所以想让敌人「当场受到伤害 +30%」，只能把 SlowAmount 直接写成 3（= 30%）。
    // 生成的是 SlowPowerHelper.SetPercent(目标, 30)，那个助手文件只在用到时才生成。

    /// <summary>这条效果是不是「直接把缓慢设成 N%」。</summary>
    internal static bool IsSlowPercentEffect(EffectSpec e) => e.SlowPercentEffective > 0 && e.IsSlowPower;

    // ==================== 「获得能量 / 获得金币」填负数 = 扣除 ====================
    //
    // 用户要求：填 -2 就该扣 2 点。
    // 为什么不能直接把这个负数交给本体的 Gain 系列 ——
    //   PlayerCmd.GainEnergy：第一句 `if (!(amount > 0m)) return;`（非正数什么都不做）
    //   PlayerCmd.GainGold  ：先 Hook 改数值，然后 `if (!(amount > 0m)) return;`
    // 两条都是「非正数直接返回」，所以 -2 传进去等于没写。扣必须走：
    //   PlayerCmd.LoseEnergy(amount, player)          → PlayerCombatState.LoseEnergy（内部 Math.Clamp(…, 0, …)）
    //   PlayerCmd.LoseGold(amount, player, Lost)      → player.Gold = int.Max(0, gold - amount)
    // 两个都会把结果夹在 0，不会把能量 / 金币扣成负数。LoseGold 自己**不检查正负**（传负数会变成加钱），
    // 所以这里一律套一层 System.Math.Abs。

    /// <summary>
    /// 这条「获得能量 / 获得金币」的数值是负数吗（负数 = 扣除）。
    ///
    /// 判据（V0.2.139 起把「数值公式」这一档也判进来了）：
    ///   ① 「数值 = X」的卡牌 → 不算（正负要到运行时才知道，判不出来，只能按「获得」生成）；
    ///   ② 固定数值 &lt; 0 → 算负数；
    ///   ③ 写了**数值公式**、而且这条公式在生成期能折成一个负数常数 → 也算负数。
    ///
    /// 为什么 ③ 必须加：卡牌链上那 5 种支持公式的效果（伤害 / 格挡 / 失去生命 / 回复生命 / 施加状态）
    /// 只要数值不是 0，<c>ProfileFactory.MigrateAmountsToFormulas</c> 就会把固定数值**迁进公式那一栏**
    /// （界面从此只编辑公式）—— 于是「填 -2」进到生成端时 <c>Amount</c> 还是 -2、而 <c>AmountFormula</c>
    /// 已经是 <c>"-2"</c>，旧判据里那个 <c>!UsesAmountFormula</c> 直接把负数分档关掉了：
    /// 用户报的「在生成器填负值的力量不生效」在**卡牌链**上就是这个原因（三个 -2 全被当成正数生成）。
    /// 公式是纯表达式（没有副作用），这里折一次常数不改变任何其它行为。
    /// </summary>
    internal static bool IsNegativeAmount(EffectSpec e, bool useX) =>
        e.Amount < 0 && !(useX && e.AmountIsXEffective)
        || IsNegativeFormulaAmount(e, useX);

    /// <summary>
    /// 这条效果的**数值公式**在生成期折出来是不是负数（见 <see cref="IsNegativeAmount"/> 的 ③）。
    ///
    /// 拿不到配置（<see cref="_formulaOwner"/> 为 null）/ 公式里有运行时量（X、内置只读量…）/
    /// 解析失败 → 一律返回 false（**不乱猜正负**，按老的「获得」那档生成，校验器会拦住写不了的公式）。
    /// </summary>
    internal static bool IsNegativeFormulaAmount(EffectSpec e, bool useX)
    {
        if (useX && e.AmountIsXEffective) return false;
        if (!e.UsesAmountFormula) return false;
        if (_formulaOwner is null) return false;
        var r = ForgeNumbers.ResolveText(_formulaOwner, e.AmountFormulaText, 0, ForgeNumbers.Place.PrologueVars);
        return r.Constant && r.Value < 0m;
    }

    /// <summary>取绝对值的那层壳（负数效果用；字面量和 DynamicVars 取值都适用）。</summary>
    internal static string AbsExpr(string expr) => $"System.Math.Abs({expr})";

    /// <summary>「获得 N 点能量」那一行（N 是负数时生成 LoseEnergy，数值取绝对值）。</summary>
    internal static string GainEnergyLine(EffectSpec e, string amt, bool useX, string ownerExpr) =>
        IsNegativeAmount(e, useX)
            ? $"await PlayerCmd.LoseEnergy({AbsExpr(amt)}, {ownerExpr});   // 负数 = 失去（本体 GainEnergy 对非正数直接返回）"
            : $"await PlayerCmd.GainEnergy({amt}, {ownerExpr});";

    /// <summary>
    /// 「施加增益/减益 N 层」那一行。
    ///
    /// 负数分**两档**走（判据 = 那个状态本体允不允许负层数，见 <see cref="EffectCatalog.AllowsNegativeLayers"/>）：
    ///
    /// <list type="number">
    /// <item><b>允许负层数</b>（力量 / 敏捷 / 专注 / 尖啸 / 萎缩）：直接把负数施加进去
    ///   （<c>PowerCmd.Apply&lt;StrengthPower&gt;(…, -2m, …)</c>）。本体「尖啸 PiercingWail」扣敌人力量
    ///   就是这条写法 —— 目标身上**本来 0 层**也能扣成 -2。写法与「临时增益」那条**已有**的正确实现
    ///   （<see cref="TempPowersSource"/> 的 <c>negative &amp;&amp; vanillaNegative</c> 分支）完全一致，不留第二套。</item>
    /// <item><b>不允许负层数</b>（虚弱 / 易伤…）：不能直接 Apply —— 那会**新建一个层数为负**的状态
    ///   （什么也不做的挂件），而不是「扣掉目标身上已有的 N 层」。所以先取已有实例再
    ///   <c>PowerCmd.ModifyAmount(-|N|)</c> 扣；目标身上没有这个状态时什么都不做（层数不能凭空变负）。</item>
    /// </list>
    ///
    /// ⚠ V0.2.139 之前是**一律**走第 2 档 —— 于是「力量 -2」在目标身上本来没有力量时被静默跳过
    /// （用户报的「填负值的力量不生效」）。
    /// </summary>
    internal static string ApplyPowerLine(EffectSpec e, bool useX, string? type, string targetExpr, string amt, string applierExpr)
        => ApplyPowerLine(e, useX, type, targetExpr, amt, applierExpr, cardSourceExpr: "this");

    /// <summary>
    /// 同上，但**显式**指定 <c>cardSource</c> 那个实参。
    ///
    /// 为什么必须显式：<c>PowerCmd.Apply</c> / <c>ModifyAmount</c> 的最后一个参数是 <c>CardModel?</c>。
    /// 卡牌那边写 <c>this</c> 没问题（卡牌自己就是 CardModel），**但遗物和药水不是 CardModel** ——
    /// 传 <c>this</c> 会让编译器去选 <c>Apply&lt;T&gt;(ctx, IEnumerable&lt;Creature&gt;? targets, …)</c> 那个重载，
    /// 然后报两条看不懂的错：
    ///   参数 2: 无法从 Creature 转换为 IEnumerable&lt;Creature&gt;
    ///   参数 5: 无法从 …Relic1 转换为 MegaCrit.Sts2.Core.Models.CardModel?
    /// 整个模组编译不过。V0.2.37「获得类数值支持负数」把遗物 / 药水也并到这个辅助函数上时踩过这个坑
    /// （用户实测：遗物「每回合开始 → 获得状态」生成出来编译失败）。所以遗物 / 药水 / 自定义状态一律传 <c>null</c>。
    /// </summary>
    internal static string ApplyPowerLine(EffectSpec e, bool useX, string? type, string targetExpr, string amt, string applierExpr, string cardSourceExpr)
        => ApplyPowerLine(e, useX, type, targetExpr, amt, applierExpr, cardSourceExpr, ctxVar: "choiceContext");

    /// <summary>
    /// 同上，但**显式**指定 <c>cardSource</c> 与<b>选择上下文那个变量名</b>。
    ///
    /// 为什么必须显式：<c>PowerCmd.Apply</c> / <c>ModifyAmount</c> 的最后一个参数是 <c>CardModel?</c>。
    /// 卡牌那边写 <c>this</c> 没问题（卡牌自己就是 CardModel），**但遗物和药水不是 CardModel** ——
    /// 传 <c>this</c> 会让编译器去选 <c>Apply&lt;T&gt;(ctx, IEnumerable&lt;Creature&gt;? targets, …)</c> 那个重载，
    /// 然后报两条看不懂的错：
    ///   参数 2: 无法从 Creature 转换为 IEnumerable&lt;Creature&gt;
    ///   参数 5: 无法从 …Relic1 转换为 MegaCrit.Sts2.Core.Models.CardModel?
    /// 整个模组编译不过。V0.2.37「获得类数值支持负数」把遗物 / 药水也并到这个辅助函数上时踩过这个坑
    /// （用户实测：遗物「每回合开始 → 获得状态」生成出来编译失败）。所以遗物 / 药水 / 自定义状态一律传 <c>null</c>。
    ///
    /// <paramref name="ctxVar"/>（V0.2.139）：那四条链（卡牌 / 遗物 / 药水 / 状态）的钩子签名里都有
    /// <c>choiceContext</c> 这个参数，所以默认就是它；**锻造链**不是 —— 它那个上下文变量名由
    /// <c>ForgeGraphGen.EmitCtx.ChoiceVar</c> 决定（造不出来时是 <c>null!</c>，写死 <c>choiceContext</c>
    /// 会 CS0103）。统一走这个参数，四条链 + 锻造链共用同一份写法，不留第二套。
    /// </summary>
    internal static string ApplyPowerLine(EffectSpec e, bool useX, string? type, string targetExpr, string amt, string applierExpr, string cardSourceExpr, string ctxVar)
        => IsNegativeAmount(e, useX)
            ? (EffectCatalog.AllowsNegativeLayers(e.PowerId)
                // 允许负层数：照本体「尖啸」那套**直接施加负数**（0 层也能扣成负的）。
                // 写法与临时增益那条已有实现（TempPowersSource）对齐，别写第二套。
                ? $"await PowerCmd.Apply<{type}>({ctxVar}, {targetExpr}, {amt}, {applierExpr}, {cardSourceExpr});   // 负数 = 施加负层数（{EffectCatalog.PowerName(e.PowerId, type ?? "该状态")}本体允许负层数，本体「尖啸」就是这么写的）"
                // 不允许负层数：先取实例再 ModifyAmount 扣（本体「扣层数」就是这条）
                : $"{{ PowerModel? __negPower = {targetExpr}.GetPower<{type}>(); if (__negPower is not null) await PowerCmd.ModifyAmount({ctxVar}, __negPower, -({AbsExpr(amt)}), {applierExpr}, {cardSourceExpr}); }}   // 负数 = 扣除已有层数（该状态本体不允许负层数；目标身上没有这个状态时什么都不做）")
            : $"await PowerCmd.Apply<{type}>({ctxVar}, {targetExpr}, {amt}, {applierExpr}, {cardSourceExpr});";

    /// <summary>
    /// 「施加状态」那一整段 = <see cref="ApplyPowerLine"/> **外面套一层调试日志**（V0.2.142）。
    ///
    /// 开关关着时（默认）返回的就是 <see cref="ApplyPowerLine"/> 的原文 —— **逐字节相同**（红线①）；
    /// 打开时返回「执行前记层数 → 原来那条语句 → 执行后打一行」三段，
    /// 其中「本来没有这个状态」与「已经有了」两种情形都会打出来（这正是加开关的目的）。
    /// </summary>
    internal static string ApplyPowerInstr(EffectSpec e, bool useX, string? type, string targetExpr, string amt,
        string applierExpr, string cardSourceExpr, string ctxVar)
    {
        string core = ApplyPowerLine(e, useX, type, targetExpr, amt, applierExpr, cardSourceExpr, ctxVar);
        if (!DebugLogGen.On) return core;
        return DebugLogGen.PowerBefore(e, targetExpr, type ?? "PowerModel", amt)
            + core
            + DebugLogGen.PowerAfter(e, targetExpr, type ?? "PowerModel");
    }

    /// <summary>同上（cardSourceExpr / ctxVar 用默认值那一档）。</summary>
    internal static string ApplyPowerInstr(EffectSpec e, bool useX, string? type, string targetExpr, string amt, string applierExpr, string cardSourceExpr)
        => ApplyPowerInstr(e, useX, type, targetExpr, amt, applierExpr, cardSourceExpr, "choiceContext");

    /// <summary>同上（cardSourceExpr 默认 <c>this</c>）。</summary>
    internal static string ApplyPowerInstr(EffectSpec e, bool useX, string? type, string targetExpr, string amt, string applierExpr)
        => ApplyPowerInstr(e, useX, type, targetExpr, amt, applierExpr, "this", "choiceContext");

    /// <summary>「获得 N 枚金币」那一行（N 是负数时生成 LoseGold，数值取绝对值）。</summary>
    internal static string GainGoldLine(EffectSpec e, string amt, bool useX, string ownerExpr) =>
        IsNegativeAmount(e, useX)
            ? $"await PlayerCmd.LoseGold({AbsExpr(amt)}, {ownerExpr});   // 负数 = 扣除（本体 GainGold 对非正数直接返回）"
            : $"await PlayerCmd.GainGold({amt}, {ownerExpr});";

    /// <summary>
    /// 存档里**所有**效果：普通卡 + 诅咒 + 先古卡 + 遗物 + 药水 + 自定义状态的触发器。
    ///
    /// 为什么要有这个统一入口：生成那些「只在用到时才生成」的辅助类（负债 Power / 额外回合 /
    /// 下回合生效 / 临时增益 / 强化指定卡牌 / 临时关键词 / 缓慢助手…）之前，都要先问一句「有没有人用」。
    /// 这些判断以前**各写一遍、而且大多只扫 p.Cards** —— 漏掉任何一个来源，生成出来的代码就会引用
    /// 一个没生成的类，dotnet 直接报 CS0246，整个模组编译不过。用户实测踩过两次：
    ///   · 卡牌用了「伙伴替主人承伤」效果、但那只召唤物没勾那个勾选框 → 守卫 Power 类没生成；
    ///   · 诅咒 / 先古卡（后加的两栏）里的效果不在 p.Cards 里 → 同样漏。
    /// 所以以后凡是「用到才生成」的判断，一律走这里，别自己再拼一遍。
    /// </summary>
    public static IEnumerable<EffectSpec> AllEffects(CharacterProfile p) =>
        p.AllCards.SelectMany(c => c.Effects)
            // 第 10 批：遗物能挂多条触发时机 → 每条时机的效果都要收（只收第 1 条会漏掉后面那几条时机
            // 用到的「用到才生成」的东西：伙伴类 / 战斗计数器 / PowerRemoval 补丁…）
            .Concat(p.Relics.SelectMany(RelicEffects))
            .Concat(p.Potions.SelectMany(s => s.Effects))
            .Concat(p.CustomPowers.SelectMany(cp => cp.Triggers).SelectMany(t => t.Effects));

    /// <summary>存档里有没有这几种效果（「用到才生成」的判断统一用它）。</summary>
    public static bool UsesKind(CharacterProfile p, params string[] kinds) =>
        AllEffects(p).Any(e => kinds.Contains(e.Kind, StringComparer.Ordinal));

    /// <summary>这个存档里所有「直接把缓慢设成 N%」的效果（用于统计/生成助手文件）。</summary>
    internal static IEnumerable<EffectSpec> SlowPercentEffects(CharacterProfile p) =>
        AllEffects(p).Where(IsSlowPercentEffect);

    /// <summary>需要生成「缓慢」数值助手文件吗。</summary>
    public static bool NeedsSlowPowerHelper(CharacterProfile p) => SlowPercentEffects(p).Any();

    /// <summary>施加完「缓慢」之后，把它的内部数值直接写成 N%（creatureExpr = 目标生物）。</summary>
    internal static void EmitSlowPercentFix(CodeWriter w, EffectSpec e, string creatureExpr)
    {
        if (!IsSlowPercentEffect(e)) return;
        w.Line($"SlowPowerHelper.SetPercent({creatureExpr}, {e.SlowPercentEffective});   // 本体「缓慢」：直接设成 {e.SlowPercentEffective}%（它显示/生效的是每打出一张牌 +10%，跟层数无关）");
    }

    /// <summary>同上，但目标是一群敌人（遗物/药水那条「一次性对全体施加」的写法）。</summary>
    internal static void EmitSlowPercentFixForAll(CodeWriter w, EffectSpec e)
    {
        if (!IsSlowPercentEffect(e)) return;
        w.Open("foreach (Creature __slowFoe in base.Owner.Creature.CombatState.HittableEnemies)");
        w.Line($"SlowPowerHelper.SetPercent(__slowFoe, {e.SlowPercentEffective});   // 本体「缓慢」：直接设成 {e.SlowPercentEffective}%");
        w.Close();
    }

    /// <summary>生成 cs/SlowPowerHelper.cs。</summary>
    public static string SlowPowerHelperSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        return $$"""
        // <auto-generated> 本体「缓慢」的数值助手 </auto-generated>
        namespace {{n.Namespace}};

        /// <summary>
        /// 本体「缓慢」（SlowPower）和别人不一样：状态栏显示的数字、以及实际用来加伤的数字**都不是层数**，
        /// 而是它内部的 DynamicVar「SlowAmount」×10：
        ///   · DisplayAmount => DynamicVars["SlowAmount"].IntValue * 10（状态栏显示的就是它）
        ///   · ModifyDamageMultiplicative => 1 + 0.1 * SlowAmount（每 1 点 = 受到伤害 +10%）
        ///   · AfterCardPlayed => SlowAmount++（本回合每打出一张牌 +10%），敌人回合开始时清零
        /// 所以「施加 30 层缓慢」既看不到 30、也吃不到加成（本体自己施加时也只给 1 层）。
        /// 想让敌人当场「受到伤害 +30%」，就得把 SlowAmount 直接写成 3 —— 那就是这里做的事。
        /// </summary>
        internal static class SlowPowerHelper
        {
            /// <summary>PowerModel.InvokeDisplayAmountChanged 是 protected，只能反射调；调一下状态栏才会立刻刷新。</summary>
            private static readonly System.Reflection.MethodInfo? _refresh =
                HarmonyLib.AccessTools.Method(typeof(PowerModel), "InvokeDisplayAmountChanged");

            /// <summary>
            /// 把目标身上「缓慢」的数值设成 percent%（按 10% 一档，四舍五入）。
            /// 调用前请先施加 SlowPower；身上没有「缓慢」时什么都不做。
            /// </summary>
            internal static void SetPercent(Creature creature, int percent)
            {
                try
                {
                    if (creature is null) return;
                    PowerModel? power = creature.Powers.FirstOrDefault(x => x is SlowPower);
                    if (power is null) return;

                    decimal units = System.Math.Round(System.Math.Max(0, percent) / 10m, System.MidpointRounding.AwayFromZero);
                    power.DynamicVars["SlowAmount"].BaseValue = units;
                    // 悬停提示里的「受到伤害增加 X%」读的是 DisplayAmount 这个变量（AfterCardPlayed 里也是这么同步的）
                    power.DynamicVars["DisplayAmount"].BaseValue = units * 10m;
                    try { _refresh?.Invoke(power, null); } catch { }
                }
                catch (System.Exception ex) { Log.Error("缓慢：设置百分比失败（已忽略）：" + ex.Message); }
            }
        }
        """;
    }

    /// <summary>全局（牌组）类效果吗？这类效果不需要战斗上下文，卡牌 / 遗物 / 状态里都能用。</summary>
    internal static bool IsGlobalCardEffect(string? kind) =>
        kind is "AddCardGlobal" or "TransformCardGlobal" or "RemoveCardGlobal" or "CardReward";

    /// <summary>
    /// 获得卡牌奖励。
    ///
    /// 有 CombatRoom 的时候（状态 / 遗物的「战斗胜利后」）走本体那条路：
    /// <c>room.AddExtraReward(player, new CardReward(CardCreationOptions.ForRoom(player, room.RoomType), N, player))</c>
    /// —— 这就是本体「王国资产」（RoyaltiesPower.AfterCombatEnd 发金币）和「猎杀」（TheHunt）的写法：
    /// 奖励挂进本场战斗的结算界面（多一条「选一张卡」），这里不弹选牌界面，也就不依赖 choiceContext。
    /// （实测在战斗结束的钩子里当场弹选牌界面是不行的：日志里连「已加入牌组」都没有，效果等于没跑。）
    ///
    /// 没有 CombatRoom 的时候（战斗中打出的牌）保持原来的做法：当场抽 N 张让玩家选一张加进牌组。
    /// </summary>
    private static void EmitCardReward(CodeWriter w, EffectSpec e, string owner, bool useX = false, string? roomVar = null)
    {
        string n = (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());

        // 独立作用域：同一个地方配了两条「获得卡牌奖励」时，里面的局部变量不会重名（重名直接编译不过）
        w.Open("");

        if (roomVar is not null)
        {
            w.Line("// 卡牌奖励：挂进本场战斗的结算奖励里（本体「王国资产」「猎杀」就是这么加的），打赢后多一条「选一张卡」的奖励");
            w.Line("// 注意：选项里不能带 CardCreationFlags（比如 ForNonCombatWithDefaultOdds 会带 NoUpgradeRoll）——");
            w.Line("// 战斗结束存档时 CardReward.ToSerializable 会因此抛 NotImplementedException。ForRoom 不带 flag，是安全的。");
            w.Line($"MegaCrit.Sts2.Core.Runs.CardCreationOptions __rewardOptions = {roomVar}.RoomType == MegaCrit.Sts2.Core.Rooms.RoomType.Event");
            w.Line("    // 事件房本体 ForRoom 会直接抛异常，这里手造一份同样不带 flag 的");
            w.Line($"    ? new MegaCrit.Sts2.Core.Runs.CardCreationOptions(new CardPoolModel[] {{ {owner}.Character.CardPool }}, MegaCrit.Sts2.Core.Runs.CardCreationSource.Other, MegaCrit.Sts2.Core.Runs.CardRarityOddsType.RegularEncounter)");
            w.Line($"    : MegaCrit.Sts2.Core.Runs.CardCreationOptions.ForRoom({owner}, {roomVar}.RoomType);");
            w.Line($"{roomVar}.AddExtraReward({owner}, new MegaCrit.Sts2.Core.Rewards.CardReward(__rewardOptions, {n}, {owner}));");
            w.Line($"Log.Info({Lit.Str("战斗奖励里已加入卡牌奖励（N 选一）：")} + {n});");
            w.Close();
            return;
        }

        w.Line("// 获得卡牌奖励：按本体的奖励卡生成规则抽牌（用你自己角色的卡池），让玩家选一张加进牌组");
        w.Line($"var __rewardOptions = MegaCrit.Sts2.Core.Runs.CardCreationOptions.ForNonCombatWithDefaultOdds(new CardPoolModel[] {{ {owner}.Character.CardPool }});");
        w.Line($"List<CardModel> __rewardCards = MegaCrit.Sts2.Core.Factories.CardFactory.CreateForReward({owner}, {n}, __rewardOptions).Select(r => r.Card).ToList();");
        w.Line($"CardModel? __pickedReward = await CardSelectCmd.FromChooseACardScreen(choiceContext, __rewardCards, {owner}, canSkip: true);");
        w.Line("CardModel __granted = __pickedReward ?? __rewardCards.FirstOrDefault();");
        w.Line("if (__granted is not null) { await CardPileCmd.Add(__granted, PileType.Deck); Log.Info(" + Lit.Str("卡牌奖励已加入牌组：") + " + __granted.Id.Entry); }");
        w.Close();
    }

    /// <summary>
    /// 条件在界面上/卡面描述里的说明（生成注释与本地化都用它）。
    /// resourceName：额外资源量在游戏里的名字（用户自己填的，如「冰附魔」）——传了就把条件里的
    /// 「额外资源量」换成它，否则卡面上会出现「拥有额外资源量至少 4 点」和计数器上的「冰附魔」两个名字。
    /// </summary>
    public static string ConditionText(ConditionSpec c, string? resourceName = null) =>
        EffectCatalog.ConditionZh(c.Kind, c.Amount, c.Amount2, c.PowerId, c.TargetZh, resourceName, c.Timing);

    /// <summary>
    /// 同上，但把「数值 N / 数值 M 写了公式」那一档也带上（V0.2.128：锻造页【条件】模块的数值栏
    /// 也能写公式，卡面文案要印公式 —— 和卡牌页『条件数值公式』同一套口径，见 EffectCatalog.ConditionZh）。
    /// </summary>
    public static string ConditionText(ConditionSpec c, string? resourceName, string? amountFormula, string? amount2Formula) =>
        EffectCatalog.ConditionZh(c.Kind, c.Amount, c.Amount2, c.PowerId, c.TargetZh, resourceName, c.Timing,
            amountFormula, amount2Formula);

    // ==================== 三个池 ====================
    public static string CardPoolSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        string frame = p.Colors.CardFrameColor is { Length: > 0 } cfc && Profile.CardColorSpec.NormalizeHex(cfc).Length > 0
            ? $"{n.CharSlug}_frame"                                   // 自定义颜色 → 用生成的 hsv 材质
            : (p.Colors.CardFrame is { Length: > 0 } f ? f : "card_frame_red");
        string deckHex = Hex(p.Colors.DeckEntryColor, "D62000");
        string outlineHex = Hex(p.Colors.EnergyOutlineColor, "802020");
        w.Line("// <auto-generated> 卡池 </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {n.CardPoolClass} : CardPoolModel")
         .Line($"public override string Title => {Lit.Str(n.PoolTitle)};")
         .Line()
         .Line($"public override string EnergyColorName => {Lit.Str(n.EnergyColor)};")
         .Line()
         .Line($"public override string CardFrameMaterialPath => {Lit.Str(frame)};")
         .Line()
         .Line($"public override Color DeckEntryCardColor => new Color({Lit.Str(deckHex)});")
         .Line()
         .Line($"public override Color EnergyOutlineColor => new Color({Lit.Str(outlineHex)});")
         .Line()
         .Line("public override bool IsColorless => false;")
         .Line()
         .Open("protected override CardModel[] GenerateAllCards()")
         .Line("return")
         .Line("[");
        // 注意：卡池 = 「这张卡属于哪个角色」，必须包含全部自有卡（含起始卡组里的）。
        // 否则本体 CardModel.Pool 会抛 InvalidProgramException: Card XXX is not in any card pool!
        // 「是否加入奖励/商店」由下面的 FilterThroughEpochs 过滤，不要在这里过滤。
        // 本体卡引用（打击 / 防御）不进这里：它们本来就属于本体的卡池，卡池里也不能掺本体的卡。
        // 诅咒 / 先古卡也必须进来（它们同样要有个「属于哪儿」）—— 放进池子**不会**让它们跑进普通奖励：
        // 本体的稀有度只会掷出 Common / Uncommon / Rare，而 Ancient 被 CardFactory 显式排除。
        foreach (var card in p.AllCards)
        {
            if (card.IsVanillaCard) continue;
            // 无色卡（用户要求）：不进**本角色**的卡池 —— 生成的 cs/ModEntry.cs 会用
            // `ModHelper.AddModelToPool<ColorlessCardPool, T>()` 把它登记进本体的无色卡池，
            // 这样它自动拿本体的无色卡框 / 能量前缀（所以「不受自定义卡框影响」）。
            // ⚠ 一张卡只能属于一个池：两边都登记时 CardModel.Pool 的反查（FirstOrDefault）结果不确定。
            if (card.IsColorless) continue;
            w.Line($"    ModelDb.Card<{n.CardClassName(p, card)}>(),");
        }
        // 卡池里**绝不掺本体（铁甲战士）的卡**：奖励只出这个角色自己的卡。
        // 本体的硬性要求只有一条：CardFactory.CreateForReward 会「互不重复地抽 N 张」（普通战斗三选一 N=3），
        // 池子不够就会抛 InvalidOperationException → 奖励界面不弹 → 死档。
        // 所以这里不兜底，改成生成前的校验直接拦住（少于 3 张奖励可用的卡就不让生成，见 ProfileValidator）。
        w.Line("];").Close()
         .Line()
         .Line("// 没勾「加入卡池」的卡：仍然属于本角色，但不会出现在奖励/商店里")
         .Open("protected override IEnumerable<CardModel> FilterThroughEpochs(UnlockState unlockState, IEnumerable<CardModel> cards)")
         .Line("var keep = cards.ToList();");
        var excluded = new List<string>();
        // 诅咒 / 先古卡 / 状态牌本来就不该出现在奖励里，这里一并按「不进池」处理（双保险：万一以后本体的稀有度表变了）
        foreach (var card in p.AllCards)
            if (!card.IsVanillaCard && !card.IsColorless && (!card.InCardPool || card.IsCurseCard || card.IsAncientCard || card.IsStatusCard))
                excluded.Add($"ModelDb.Card<{n.CardClassName(p, card)}>()");
        if (excluded.Count > 0)
        {
            w.Line($"keep.RemoveAll(c => c.Id == {excluded[0]}.Id");
            for (int i = 1; i < excluded.Count; i++)
                w.Line($"    || c.Id == {excluded[i]}.Id");
            w.Line(");");
        }
        w.Line("return keep;").Close()
         .Close();
        return w.ToString();
    }

    public static string RelicPoolSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 遗物池 </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {n.RelicPoolClass} : RelicPoolModel")
         .Line($"public override string EnergyColorName => {Lit.Str(n.EnergyColor)};")
         .Line()
         .Line("public override Color LabOutlineColor => StsColors.red;")
         .Line()
         .Open("protected override IEnumerable<RelicModel> GenerateAllRelics()")
         .Line("return")
         .Line("[");
        // 同上：池成员必须全覆盖（本体 RelicModel.Pool 用 First 查找，找不到会抛异常）
        for (int i = 0; i < p.Relics.Count; i++)
            w.Line($"    ModelDb.Relic<{n.RelicClassName(p.Relics[i], i)}>(),");
        // 额外资源量的隐藏起始遗物也必须进池：
        // 本体 RelicModel.Pool 是 First(...) 查找，找不到就抛 InvalidOperationException ——
        // 实测症状是「在选人界面点这个角色就报错，然后游戏继续用铁甲战士开局」。
        // 它是 Starter 稀有度，奖励只会抽 Common/Uncommon/Rare/Shop，所以不会被当成奖励发出来。
        if (p.ExtraResource.Enabled)
        {
            w.Line();
            w.Line("    // 额外资源量的载体（隐藏起始遗物）：必须在池里，否则本体查 Pool 会抛异常");
            w.Line($"    ModelDb.Relic<{Naming.From(p).ExtraResourceRelicClass}>(),");
        }
        w.Line("];").Close()
         .Line()
         .Line("// 没勾「加入遗物池」的：仍属于本角色，但不会出现在奖励/商店里")
         .Open("public override IEnumerable<RelicModel> GetUnlockedRelics(UnlockState unlockState)")
         .Line("var keep = base.GetUnlockedRelics(unlockState).ToList();");
        var rexcl = new List<string>();
        for (int i = 0; i < p.Relics.Count; i++)
            if (!p.Relics[i].InRelicPool) rexcl.Add($"ModelDb.Relic<{n.RelicClassName(p.Relics[i], i)}>()");
        if (rexcl.Count > 0)
        {
            w.Line($"keep.RemoveAll(r => r.Id == {rexcl[0]}.Id");
            for (int i = 1; i < rexcl.Count; i++)
                w.Line($"    || r.Id == {rexcl[i]}.Id");
            w.Line(");");
        }
        w.Line("return keep;").Close()
         .Close();
        return w.ToString();
    }

    public static string PotionPoolSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 药水池 </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {n.PotionPoolClass} : PotionPoolModel")
         .Line($"public override string EnergyColorName => {Lit.Str(n.EnergyColor)};")
         .Line()
         .Line("public override Color LabOutlineColor => StsColors.red;")
         .Line()
         .Open("protected override IEnumerable<PotionModel> GenerateAllPotions()")
         .Line("return")
         .Line("[");
        for (int i = 0; i < p.Potions.Count; i++)
            w.Line($"    ModelDb.Potion<{n.PotionClassName(p.Potions[i], i)}>(),");
        w.Line("];").Close()
         .Line()
         .Line("// 没勾「加入药水池」的：仍属于本角色，但不会出现在掉落里")
         .Open("public override IEnumerable<PotionModel> GetUnlockedPotions(UnlockState unlockState)")
         .Line("var keep = base.GetUnlockedPotions(unlockState).ToList();");
        var pexcl = new List<string>();
        for (int i = 0; i < p.Potions.Count; i++)
            if (!p.Potions[i].InPotionPool) pexcl.Add($"ModelDb.Potion<{n.PotionClassName(p.Potions[i], i)}>()");
        if (pexcl.Count > 0)
        {
            w.Line($"keep.RemoveAll(p => p.Id == {pexcl[0]}.Id");
            for (int i = 1; i < pexcl.Count; i++)
                w.Line($"    || p.Id == {pexcl[i]}.Id");
            w.Line(");");
        }
        w.Line("return keep;").Close()
         .Close();
        return w.ToString();
    }

    // ==================== 动态变量 ====================
    // 注意：这两个是 public —— 界面的自检（--uicheck）会直接调它们核对变量名（App 看不到 internal）。
    public static string VarNameOf(EffectSpec e) => e.Kind switch
    {
        "Damage" => "Damage",
        "Block" => "Block",
        "Draw" => "Cards",
        "Energy" => "Energy",
        // 透支能量：和「获得能量」共用本体的 EnergyVar（键 = Energy）—— 卡面 {Energy:diff()}、
        // 升级增量、同一张牌上的别名（Energy2）全都照旧能用
        "OverdraftEnergy" => "Energy",
        "Heal" => "Heal",
        "HpLoss" => "HpLoss",
        "MaxHp" => "MaxHp",
        "Gold" => "Gold",
        "ApplyPower" => e.PowerId ?? "Power",
        // 临时增益：变量名也用那个状态的类名（卡面 {StrengthPower:diff()}），
        // 同一张牌上同时有「施加」和「临时施加」同一个状态时，VarNamesOf 会自动给第二个起别名。
        "TempPower" => e.PowerId ?? "Power",
        // 强化指定卡牌：只是「强化多少」这一个数字（打出的 Power 层数）。
        // 同一张牌上给两张不同的卡各强化一次时，VarNamesOf 会自动给第二个起别名（Boost2）。
        "BoostCard" => "Boost",
        // 升级卡牌：数值 = 升级几张，用本体的 CardsVar（键 = Cards）—— 卡面 {Cards:diff()} 跟着升级变
        "UpgradeCard" => "Cards",
        // 预见：数值 = 看抽牌堆顶几张，同样用 CardsVar
        "Scry" => "Cards",
        // 刮削：数值 = 抽几张（本体「刮削 Scrape」），同样用 CardsVar
        "ScrapeDraw" => "Cards",
        // 从三摞拿牌到手牌：数值 = 拿几张，同样用 CardsVar（本体有 Cards 属性，直接 base.DynamicVars.Cards）
        "TakeFromDraw" => "Cards",
        "TakeFromDiscard" => "Cards",
        "TakeFromExhaust" => "Cards",
        // 消耗 / 丢弃卡牌：数值也是「几张牌」，同样用 CardsVar
        "ExhaustCard" => "Cards",
        "DiscardCard" => "Cards",
        // 生成 / 变化卡牌：数值也是「几张牌」，同样用 CardsVar（卡面 {Cards:diff()} 跟着升级增量变）
        "GenerateCard" => "Cards",
        "TransformCard" => "Cards",
        // 复制卡牌：数值 = 从牌堆里选几张，同样用 CardsVar（键 = Cards）；「复制的份数」不是变量，
        // 生成时直接写字面量（它不随升级变 —— 界面上它是整数栏，也没有升级增量那一栏）
        "CopyCard" => "Cards",
        // 重放卡牌：数值 = 从牌堆里选几张，同样用 CardsVar；「重放次数」也是字面量
        "ReplayCard" => "Cards",
        // 毒性爆发：数值 = 上几层中毒，用本体的 PowerVar<PoisonPower>（键 = PoisonPower）
        "Outbreak" => "PoisonPower",
        // 大限已至：升级增量（如果填了）落在计算三件套的 CalculatedDamage 上
        "TimesUp" => "CalculatedDamage",
        // 额外资源量 = 本体的星星：本体有现成的 StarsVar（默认名 "Stars"），
        // 用它才能让卡面 {Stars:diff()} 随升级变（用户报过「升级后卡面还显示 2」）。
        "ExtraResource" => "Stars",
        // 「增加额外资源量上限值」：普通 DynamicVar（键 = ResourceCap）——
        // 卡面写「额外资源量上限 +{ResourceCap:diff()}」，升级增量也落在它身上。
        "RaiseResourceCap" => "ResourceCap",
        // ===== 召唤伙伴 =====
        // 用带名字的普通 DynamicVar（默认名是 PetHp / PetDamage），不走「兜底 Value」——
        // 兜底那条会给每一个这种效果都起名叫 Value、再靠别名区分，卡面描述里就成了 {Value2:diff()}
        // 这种看不懂的占位符。起了明确的名字，描述里的 {PetHp:diff()} / {PetDamage:diff()} 才读得懂，
        // OnUpgrade 的 UpgradeValueBy 也照常生效（升级后卡面数字会跟着变）。
        //   · SummonPet → PetHp：召唤时的生命（数值填 0 = 用「召唤物」页里配置的血量，那时不声明变量）
        //   · PetAttack → PetDamage：宠物这一击的伤害
        "SummonPet" => "PetHp",
        "PetAttack" => "PetDamage",
        // ===== 新增的那批宠物效果 =====
        // 「按生命值算的伙伴攻击」三个 Kind 各自一个变量名：一来卡面描述里的 {名字:diff()} 读得懂，
        // 二来回读时**按变量名**就能直接认出是哪一种倍率（比去猜 lambda 里的表达式稳得多）。
        "PetDamageByMaxHp" => "PetMaxHpDamage",
        "PetDamageByCurHp" => "PetCurHpDamage",
        "PetDamageByMissingHp" => "PetMissingHpDamage",
        // 治疗 / 失去生命 / 最大生命：这三个用的就是**本体那三种变量**（HealVar / HpLossVar / MaxHpVar），
        // 变量名是本体固定死的 "Heal" / "HpLoss" / "MaxHp"。
        // 名字必须和声明一致：声明写的是 new HealVar(6m)（键 = Heal）、打出时读 base.DynamicVars.Heal，
        // 卡面占位符与 OnUpgrade 也走同一个键 —— 以前这里写成 PetHeal / PetHpLoss / PetMaxHp，
        // 于是卡面上那个 {PetHeal:diff()} 找不到同名变量（数字显示不出来），
        // 升级时 base.DynamicVars["PetHeal"] 还会直接抛 KeyNotFoundException（牌组界面打不开）。
        "PetHeal" => "Heal",
        "PetLoseHp" => "HpLoss",
        "PetGainMaxHp" => "MaxHp",
        // 牺牲伙伴：收益是格挡 / 伤害 / 获得状态各一套名字（同一张牌上两条牺牲也能靠别名区分）
        "PetSacrifice" => e.PetSacrificeGain switch
        {
            "Damage" => "PetSacrificeDamage",
            "Power" => "PetSacrificePower",
            _ => "PetSacrificeBlock",
        },
        "PetApplyPower" => "PetPower" + (e.PowerId ?? ""),
        _ => "Value",
    };

    internal static string VarPropertyOf(EffectSpec e) => e.Kind switch    {
        "Damage" => "Damage",
        "Block" => "Block",
        "Draw" => "Cards",
        // 升级卡牌 / 预见：数值也是「几张牌」，用本体的 CardsVar（有同名属性，可以直接 base.DynamicVars.Cards）
        "UpgradeCard" => "Cards",
        "Scry" => "Cards",
        // 刮削：数值 = 抽几张牌，同样用 CardsVar（有同名属性）
        "ScrapeDraw" => "Cards",
        // 复制卡牌 / 重放卡牌：数值 = 选几张牌，也用本体的 CardsVar（卡面 {Cards:diff()} 跟着升级变）
        "CopyCard" => "Cards",
        "ReplayCard" => "Cards",
        // 从抽牌堆 / 弃牌堆 / 消耗牌堆拿牌到手牌：数值 = 拿几张，同样用本体的 CardsVar。
        // 为什么要给它变量（用户报的：「自定义描述里 {Value:diff()} 原样印在卡面上」）：
        // 这三种效果以前**不声明任何变量**，卡面只能写死数字 —— 写 {Value:diff()} 就会在游戏里
        // **原样印出来**（本体按 DynamicVar 的键取，取不到就印占位符）。同一张牌上拿两次（抽牌堆 + 弃牌堆）
        // 时，第二个自动起别名 Cards2（VarNamesOf 干的），卡面写 {Cards2:diff()}。
        "TakeFromDraw" => "Cards",
        "TakeFromDiscard" => "Cards",
        "TakeFromExhaust" => "Cards",
        // 消耗 / 丢弃卡牌：数值也是「几张牌」，同样用 CardsVar
        "ExhaustCard" => "Cards",
        "DiscardCard" => "Cards",
        // 生成 / 变化卡牌：数值也是「几张牌」，同样用本体的 CardsVar
        "GenerateCard" => "Cards",
        "TransformCard" => "Cards",
        "Energy" => "Energy",
        // 透支能量：和「获得能量」共用本体的 EnergyVar（键 = Energy）—— 卡面 {Energy:diff()}、
        // 升级增量、同一张牌上的别名（Energy2）全都照旧能用
        "OverdraftEnergy" => "Energy",
        "Heal" => "Heal",
        "HpLoss" => "HpLoss",
        "MaxHp" => "MaxHp",
        "Gold" => "Gold",
        "ExtraResource" => "Stars",
        // 本体没有 PetHp / PetDamage / PetMaxHpDamage … 这些属性，只能走索引器（见 VarAccess）
        "SummonPet" or "PetAttack" or "PetDamageByMaxHp" or "PetDamageByCurHp" or "PetDamageByMissingHp"
            or "PetHeal" or "PetLoseHp" or "PetGainMaxHp" or "PetSacrifice" or "PetApplyPower" => "Value",
        _ => "Value",
    };

    /// <summary>
    /// 一个模型（卡牌 / 遗物 / 药水）里，每条效果对应的动态变量名。
    ///
    /// **为什么必须唯一**：本体的 <c>DynamicVarSet</c> 用变量名当键，重名会直接抛
    /// <c>ArgumentException: DynamicVarSet contains duplicate key 'Damage'</c>；
    /// 这个异常发生在 <c>CardModel.DynamicVars</c> 构造时（创建卡牌就炸），
    /// 会把整场战斗的回合循环打断 —— 表现就是「抽不了牌、结束不了回合」。
    /// 用户实测踩过：起始遗物开战生成「刀」，而「刀」有两张 DamageVar。
    ///
    /// 规则：同一种变量第二次出现起叫 <c>Damage2</c> / <c>Block2</c> / <c>PoisonPower2</c> …，
    /// 生成代码里的声明、取值、升级、描述占位符都用这个名字。
    /// </summary>
    public static Dictionary<EffectSpec, string> VarNamesOf(IEnumerable<EffectSpec> effects)
    {
        var seen = new Dictionary<string, int>(StringComparer.Ordinal);
        var map = new Dictionary<EffectSpec, string>();
        foreach (var e in effects)
        {
            if (HasNoDynamicVar(e)) continue;
            string baseName = VarNameOf(e);
            int n = seen.TryGetValue(baseName, out int c) ? c + 1 : 1;
            seen[baseName] = n;
            map[e] = n == 1 ? baseName : baseName + n.ToString(System.Globalization.CultureInfo.InvariantCulture);
        }
        return map;
    }

    /// <summary>某个效果在它所属模型里的变量名（没登记就退回默认名）。</summary>
    public static string VarNameOf(EffectSpec e, Dictionary<EffectSpec, string>? map) =>
        map is not null && map.TryGetValue(e, out string? name) ? name : VarNameOf(e);

    /// <summary>
    /// 「填入参数」按钮用的候选：这个模型（卡牌 / 遗物 / 药水）里能写进自定义描述的数值占位符。
    ///
    /// 本体读描述的占位符时是按 <c>DynamicVar</c> 的**键**取的（<c>{Damage}</c>），卡牌还能写
    /// <c>{Damage:diff()}</c> 让卡面在升级后显示升级值 —— 所以卡片给带 :diff() 的那种，
    /// 遗物 / 药水（不能升级）给普通的。
    /// 只列**这条模型真的声明过**的变量（抄一个不存在的键，游戏里会原样印出 {XXX} 或显示不出来）。
    /// </summary>
    public static List<(string Token, string Desc)> ParamHints(IEnumerable<EffectSpec> effects, bool isCard)
    {
        var list = new List<(string, string)>();
        var all = effects as IList<EffectSpec> ?? effects.ToList();
        var map = VarNamesOf(all);
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var e in all)
        {
            if (HasNoDynamicVar(e)) continue;
            string key = DisplayVarNameOf(e, map);
            if (key.Length == 0 || !seen.Add(key)) continue;
            string token = isCard ? $"{{{key}:diff()}}" : $"{{{key}}}";
            list.Add((token, EffectCatalog.FindKind(e.Kind).Display));
        }
        return list;
    }

    // ⚠ V0.2.130 用户要求删掉整块「卡面显示牌堆张数」：原来这里有一份 PileCountHints
    //   （{DrawPile} / {DiscardPile} / {ExhaustPile} 三个占位符），连同「填入参数…」菜单里
    //   那三个候选与那句提示一起删了。老存档里写了这三个占位符的自定义描述会原样留在文本里
    //   （本体运行时替换不了它们，卡面上就按字面显示）—— 这是用户明确要求的取舍，见 QUEUE 第 17 批。

    /// <summary>
    /// 一张牌**真的声明过**的全部动态变量键（含重名别名 <c>Cards2</c> —— 本体要求同种变量各自起名，
    /// 见 <see cref="VarNamesOf"/>）。校验器拿它比对卡面描述里的 <c>{X}</c> / <c>{X:diff()}</c>：
    /// 键不在这里 = 本体取不到值 = 卡面上原样印出 <c>{X:diff()}</c>（用户实测报过）。
    ///
    /// 为什么不能直接用 <see cref="ParamHints"/>：那是「填入参数…」菜单的候选，**每种变量只列一条**
    /// （<c>seen.Add(key)</c> 去了重），也不包含别名那一份 —— 拿它比对会把合法的
    /// <c>{Cards2:diff()}</c>（同一种效果出现两次时第二个的别名）误报成「没声明过」。
    ///
    /// 这里刻意取**超集**（把每条效果按它的显示名 + 内部名都收进来）：宁可漏报，不能误报把正常存档拦死。
    /// </summary>
    public static HashSet<string> DeclaredVarKeysOf(IEnumerable<EffectSpec> effects)
    {
        var all = effects as IList<EffectSpec> ?? effects.ToList();
        var map = VarNamesOf(all);
        var keys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var e in all)
        {
            if (HasNoDynamicVar(e)) continue;
            string display = DisplayVarNameOf(e, map);
            if (display.Length > 0) keys.Add(display);
            string inner = VarNameOf(e, map);
            if (inner.Length > 0) keys.Add(inner);
        }
        return keys;
    }

    /// <summary>
    /// 这个模型的动态变量「基础名」清单（用来校验有没有同种变量出现多次）。
    /// 本体 DynamicVarSet 用变量名当键，重名会直接抛异常 → 整场战斗的回合循环死掉
    /// （表现：抽不了牌、结束不了回合 —— 用户实测踩过）。生成时会自动给第二个起别名。
    /// </summary>
    public static IReadOnlyList<string> VarKeysOf(IEnumerable<EffectSpec> effects) =>
        effects.Where(e => !HasNoDynamicVar(e)).Select(VarNameOf).ToList();

    internal static string VarAccess(EffectSpec e, Dictionary<EffectSpec, string>? map = null)
    {
        string name = VarNameOf(e, map);
        // 只有本体确实有同名属性的变量才能用属性写法（Damage / Block / Cards / Energy / Stars）；
        // 起了别名（Damage2 这种）或只有索引器的（Power / PetHp / PetDamage）一律用 ["名字"]。
        // PetHp / PetDamage 是**我们自己起的名字**，本体 DynamicVars 上当然没有这两个属性 → 必须走索引器。
        bool hasProperty = e.Kind is "Damage" or "Block" or "Draw" or "Energy" or "ExtraResource"
            or "UpgradeCard" or "Scry" or "ScrapeDraw"
            // 从三摞拿牌 / 生成 / 变化 / 消耗 / 丢弃卡牌：用的也是本体的 CardsVar（有同名属性）
            or "TakeFromDraw" or "TakeFromDiscard" or "TakeFromExhaust"
            or "GenerateCard" or "TransformCard" or "ExhaustCard" or "DiscardCard";
        return hasProperty && name == VarPropertyOf(e)
            ? $"base.DynamicVars.{VarPropertyOf(e)}.BaseValue"
            : $"base.DynamicVars[{Lit.Str(name)}].BaseValue";
    }

    /// <summary>X 费用卡牌里 X 的变量名（在 OnPlay 开头取一次）。</summary>
    internal const string XVar = "x";

    /// <summary>
    /// 注释里写的人类可读张数：填了升级增量时写成 <c>2（升级后 3）</c>，别把
    /// <c>(int)base.DynamicVars.Cards.BaseValue</c> 这种表达式印进注释（用户会读到生成代码）。
    /// </summary>
    internal static string CountComment(EffectSpec e, string n)
        => e.UpgradeAmount != 0
            ? $"{Math.Max(1, (int)e.Amount)}（升级后 {Math.Max(1, (int)(e.Amount + e.UpgradeAmount))}）"
            : n;

    /// <summary>取数值：X 费用卡牌上「数值 = X」就用 X，否则用固定数值。</summary>
    internal static string AmountExpr(EffectSpec e, bool useX, Dictionary<EffectSpec, string>? map = null) =>
        useX && e.AmountIsXEffective ? XVar : VarAccess(e, map);

    /// <summary>
    /// 「取几张」这类效果的**张数表达式**（消耗 / 丢弃 / 升级 / 变化 / 复制 / 重放 / 预见 / 生成 / 从牌堆拿牌…）。
    ///
    /// ⚠ 为什么不能直接写字面量（<c>(int)e.Amount</c>）：这些种类**声明了动态变量**（CardsVar），
    /// 「升级增量」写在 OnUpgrade 的 <c>UpgradeValueBy</c> 里，而卡面描述写的是 <c>{Cards:diff()}</c> ——
    /// 如果生成代码里还是写死的 `1`，就会变成「卡面写 3 张、实际只生成 1 张」（用户报的
    /// 「生成卡牌的升级增量好像没反应」就是这个）。所以**填了升级增量**时改成读动态变量。
    ///
    /// 没填升级增量（<c>UpgradeAmount == 0</c>）时仍写字面量：老存档 / 默认配置生成出来的代码**逐字不变**。
    /// </summary>
    internal static string CountExprAt(EffectSpec e, Dictionary<EffectSpec, string>? map, bool useX)
    {
        if (useX && e.AmountIsXEffective) return XVar;
        if (e.UpgradeAmount != 0 && !HasNoDynamicVar(e)) return $"(int){VarAccess(e, map)}";
        return Math.Max(1, (int)e.Amount).ToString();
    }

    /// <summary>取命中次数 / 对群数：X 费用卡牌上可以填 X（本体旋风斩 / 天际钻头）。</summary>
    /// <summary>
    /// 这条伤害要不要写 <c>.WithHitCount(...)</c>：固定次数 &gt; 1 / <c>= X</c> / **写了「命中次数」公式** 都要写。
    ///
    /// 用户报的坑：以前只判「固定次数 &gt; 1 / = X」，**填了公式但固定值还是 1** 时整条 <c>WithHitCount</c> 都不写 ——
    /// 于是「命中次数 = 2+A」生成出来只打一下（卡面却印着「2+A 次」，两处对不上）。
    /// 固定值 1 且没写公式时照旧不写（老存档生成的代码一个字都不变）。
    /// </summary>
    public static bool RepeatIsMulti(EffectSpec e, bool useX) =>
        (useX && e.RepeatIsX) || e.RepeatCount > 1 || !string.IsNullOrWhiteSpace(e.RepeatFormula);

    /// <summary>「命中次数 / 对群数」在一次攻击里怎么求值（公式优先，其次 = X，最后固定值）。</summary>
    internal static string RepeatExpr(EffectSpec e, bool useX)
    {
        if (CountFormulaExpr(_formulaOwner, e, "Repeat", out _) is { } rf)
            return $"(int)System.Math.Clamp({rf}, 1m, 20m)";
        return useX && e.RepeatIsX ? XVar : Math.Max(1, e.RepeatCount).ToString();
    }

    /// <summary>
    /// 「现在正在生成哪张卡的代码」—— 次数类公式（用户要求⑦）求值要 <c>__fgPlayer</c> / <c>__fgSelf</c>
    /// 那两个局部变量，而它们只有卡牌那条链会先算；可这些次数被埋在很深的发射器里
    ///（<c>EmitAttack</c> / <c>EmitStun</c> / <c>EmitPerCreature</c> / <c>EmitCopyCard</c>…），
    /// 一层层加参数会把几十个调用点全改一遍 —— 所以在这里放一个**生成期**的当前卡牌：
    /// 由 <see cref="EmitCardEffect"/> 进出时设置 / 还原（生成是单线程的，且用 [ThreadStatic] 兜底）。
    /// 非卡牌那条链上它是 null → 次数公式不参与（配置检查本来也会拦住）。
    /// </summary>
    [ThreadStatic] private static CharacterProfile? _formulaOwner;

    /// <summary>
    /// 条件里写了「数值公式」时，把整条条件写进生成代码的一行标记（回读按它重建）。
    ///
    /// 为什么不是只标记公式：条件在生成代码里已经变成一整句 C# 表达式
    ///（`CardPile.GetCards(...).Count() >= (int)Math.Max(0m, (…TurnNumber…))`），
    /// 从它既反推不回公式、也认不出条件种类 —— 所以种类 / 固定数值 / 状态 / 指向对象 / 子时机一起带上。
    /// 键值之间用 <c>|</c> 分隔（公式里不会出现 <c>|</c>，解析器只认字母数字和运算符）。
    /// </summary>
    public static string ConditionMarker(ConditionSpec c)
    {
        string Esc(string? v) => (v ?? "").Replace("|", "/");
        return string.Join("|", new[]
        {
            $"Kind={Esc(c.Kind)}",
            $"Amount={c.Amount.ToString(System.Globalization.CultureInfo.InvariantCulture)}",
            $"Amount2={c.Amount2.ToString(System.Globalization.CultureInfo.InvariantCulture)}",
            $"Power={Esc(c.PowerId)}",
            $"Target={Esc(c.Target)}",
            $"Timing={Esc(c.Timing)}",
            $"WhenUnmet={Esc(c.WhenUnmet)}",
            $"AmountFormula={Esc(ForgeFormula.DisplayText(c.AmountFormula))}",
            $"Amount2Formula={Esc(ForgeFormula.DisplayText(c.Amount2Formula))}",
        });
    }

    /// <summary>
    /// 条件里的「数值 N / 数值 M」写了公式时，它在生成代码里的表达式（用户要求⑦）。
    /// 解析 / 求值完全复用「数值公式」那一套（<see cref="ForgeFormula.CardResolver"/>）：
    /// 参数 M / N…、X / Y、内置只读量、min/max 那几类函数都照旧。
    /// 返回 null = 这一栏没写公式（或者不在卡牌那条链上 —— <paramref name="p"/> 为 null）。
    /// </summary>
    public static string? ConditionFormulaExpr(CharacterProfile? p, ConditionSpec c, string which, out string error,
        bool withPlayTarget = true)
    {
        error = "";
        if (p is null || c is null) return null;
        bool second = string.Equals(which, "Amount2", StringComparison.Ordinal);
        if (second ? !c.UsesAmount2Formula : !c.UsesAmountFormula) return null;
        var root = ForgeFormula.TryParse(second ? c.Amount2Formula : c.AmountFormula, out error);
        if (root is null) return null;
        // 条件用**内联**解析器（IsPlayable / 描金边那两个表达式体属性里没法先声明局部变量）
        return ForgeFormula.Emit(root, ForgeFormula.ConditionResolver(p, withPlayTarget ? "cardPlay?.Target" : null), out error);
    }

    /// <summary>
    /// 这条条件的公式表达式里有没有用到「打出的目标」（<c>cardPlay.Target</c>）——
    /// 用到了就写不进 <c>IsPlayable</c> / 描金边（那两处还没有 cardPlay），只能包住这条效果本身
    /// （和「指定敌人」那类条件同一个处理）。
    /// </summary>
    public static bool ConditionFormulaNeedsPlayTarget(CharacterProfile? p, ConditionSpec? c)
    {
        if (p is null || c is null || !c.UsesAnyFormula) return false;
        foreach (string which in new[] { "Amount", "Amount2" })
            if (ConditionFormulaExpr(p, c, which, out _, withPlayTarget: true) is { } expr
                && expr.Contains("cardPlay", StringComparison.Ordinal))
                return true;
        return false;
    }

    /// <summary>
    /// **触发时机上的数值**（用户要求：遗物 / 状态两边都要有）在生成代码里的守卫行。
    ///
    /// 分两族：
    ///   · **计数族**（打出一张牌后 / 消耗·弃掉·抽到一张牌后 / 生成卡牌时）→ 「**每累计 N 次触发一次**」，
    ///     范围**本回合 / 本场战斗**。用本体战斗历史**无状态**算：这一次之前已经有多少 = 历史累计 − 1
    ///     （本体是在调钩子**之前**就记账的），于是「(之前 + 1) % N == 0」就是「每 N 次」。
    ///   · **阈值族**（自己受到伤害后 / 造成伤害后 / 失去生命时 / 获得格挡后）→ 「**数值 ≥ N 才触发**」。
    ///
    /// 没填（amount ≤ 0）或者这条时机不支持 → 返回空数组（一个字符都不生成，老存档逐字不变）。
    /// </summary>
    /// <param name="valueExpr">阈值族要比的那个数（伤害 = <c>result.UnblockedDamage</c>、
    /// 失去生命 = <c>-delta</c>、格挡 = <c>amount</c>）。</param>
    public static IReadOnlyList<string> TriggerAmountLines(string kind, decimal amount, string scope,
        string creatureExpr, string stateExpr, string playerExpr, string? valueExpr = null,
        string counterClass = "ForgeCombatCounters")
    {
        if (amount <= 0m)
            return Array.Empty<string>();
        if (valueExpr is not null)
            return new[] { $"if ({valueExpr} < {Lit.Dec(amount)}) return;   // 数值 ≥ {amount:0.##} 才触发" };
        string count = CountExpr(kind, scope, creatureExpr, stateExpr, playerExpr);
        if (count.Length == 0)
        {
            // 敌人死亡：本体战斗历史里**没有死亡记录**，所以由工具自己记一个计数器（见 CombatCountersSource）——
            // 第一次调用时按 ICombatState 自动清零，不需要额外的重置钩子。
            if (kind == "EnemyDeath")
                return new[]
                {
                    $"int __deaths = {counterClass}.BumpEnemyDeath({stateExpr});   // 本场战斗第几个敌人死亡（工具自己记的）",
                    $"if (__deaths % {Lit.Int(amount)} != 0) return;   // 每 {amount:0.##} 个敌人死亡触发一次（本场战斗内计数）",
                };
            return Array.Empty<string>();
        }
        // 本体是**先记账再调钩子**，所以历史里已经包含这一次 → 「累计 % N == 0」就是「每 N 次触发一次」
        return new[] { $"if ({count} % {Lit.Int(amount)} != 0) return;   // 每累计 {amount:0.##} 次触发一次（范围：{(scope == "Combat" ? "本场战斗" : "本回合")}）" };
    }

    /// <summary>
    /// 触发时机计数器那个类的名字（敌人死亡计数用；每个角色一份，避免两个模组撞类名）。
    /// </summary>
    public static string CombatCountersClass(CharacterProfile p) => Naming.From(p).CharClass + "ForgeCombatCounters";

    /// <summary>
    /// 「敌人死亡计数」那个小运行时（本体战斗历史里没有死亡记录，只能自己记）：
    /// 静态计数器 + 按 <c>ICombatState</c> 自动清零（换一场战斗就重新数），所以**不需要**额外的重置钩子。
    /// 只有真的用到时才写进工程（见 ModGenerator）。
    /// </summary>
    public static string CombatCountersSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 工具自己记的战斗计数器 </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>")
         .Line("/// 【敌人死亡计数】本体在战斗历史（CombatHistory）里**没有记录死亡**，所以「每 N 个敌人死亡」")
         .Line("/// 这种数值只能由工具自己数：这里放一个静态计数器，第一次被问到时按 ICombatState 认一场战斗、")
         .Line("/// 换了战斗自动从 0 重新数（不需要在战斗开始时做什么）。")
         .Line("/// </summary>")
         .Open($"public static class {CombatCountersClass(p)}")
         .Line("private static MegaCrit.Sts2.Core.Combat.ICombatState? __state;")
         .Line("private static int __deaths;")
         .Line()
         .Line("/// <summary>数一个敌人死亡，返回「这是本场战斗第几个」（从 1 开始）。</summary>")
         .Open("public static int BumpEnemyDeath(MegaCrit.Sts2.Core.Combat.ICombatState? state)")
         .Open("if (!ReferenceEquals(__state, state))")
         .Line("__state = state;")
         .Line("__deaths = 0;")
         .Close()
         .Line("return ++__deaths;")
         .Close()
         .Line()
         .Line("/// <summary>本场战斗已经死了几个敌人（没开始数就是 0）。</summary>")
         .Line("public static int EnemyDeaths(MegaCrit.Sts2.Core.Combat.ICombatState? state) => ReferenceEquals(__state, state) ? __deaths : 0;")
         .Close();
        return w.ToString();
    }

    /// <summary>
    /// 「获得的能量」那个小运行时的类名。**固定**（不是每个角色一份）：因为内置量表
    /// （<see cref="FormulaBuiltins"/>）里的表达式是每个角色共用的一份文本，
    /// 类名跟着角色变的话那份文本就没法写死了 —— 好在它是 <c>static</c> 工具类，
    /// 不同角色模组的命名空间不同，不会撞（<c>ForgeFormulaRuntime</c> 也是这么干的）。
    /// </summary>
    public const string EnergyGainTrackerClass = "ForgeEnergyGainTracker";

    /// <summary>
    /// 「获得的能量（本回合 / 本场战斗）」那个小运行时 + 补丁。
    ///
    /// 为什么必须自己写：本体只在 <c>PlayerCombatState.Energy</c> 上存一个当前值（外加一个
    /// <c>EnergyChanged</c> 事件），**没有**「获得了多少」这种累计读数，战斗历史（CombatHistory）里
    /// 也只有「花掉能量（EnergySpentEntry）」没有「获得能量」。所以由工具自己打补丁记。
    ///
    /// 打在哪：<c>PlayerCombatState.GainEnergy(decimal)</c> —— 本体所有「获得能量」最后都走它
    /// （<c>PlayerCmd.GainEnergy</c> 算完修改量就调这个**同步**方法），而它旁边的
    /// <c>ResetEnergy()</c>（回合开始把能量补满）和 <c>AddMaxEnergyToCurrent()</c>
    /// 都**不**走它 —— 正好符合语义：回满不算「获得」，否则这个读数每回合都会莫名多出 3 点。
    /// 只打同步方法（不打 async 的 <c>PlayerCmd.GainEnergy</c>，异步状态机上的补丁时机很坑）。
    ///
    /// 怎么记：本体每场战斗都会 <c>new</c> 一个 <c>PlayerCombatState</c>（<c>Player.ResetCombatState</c>），
    /// 所以按 <c>PlayerCombatState</c> 实例记 —— 换一场战斗自然从头算；
    /// 「本回合」按 <c>PlayerCombatState.TurnNumber</c> 认，换回合自动清零（不需要额外的重置钩子）。
    /// 键用 <c>ConditionalWeakTable</c>（弱引用键），打完的战斗状态不会被这份记录拖住。
    /// </summary>
    public static string EnergyGainTrackerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 「获得的能量」记录器 + 补丁（本体没有这个读数，只能自己记） </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>")
         .Line("/// 【获得的能量】本体只在 PlayerCombatState.Energy 上放一个当前值，没有「这回合 / 这场战斗获得了多少」，")
         .Line("/// 所以工具自己打一个后缀补丁记在 PlayerCombatState.GainEnergy(decimal) 上（回合开始补满的不算「获得」）。")
         .Line("/// </summary>")
         .Open($"internal static class {EnergyGainTrackerClass}")
         .Open("private sealed class Rec")
         .Line("public int Turn;")
         .Line("public int TurnGained;")
         .Line("public int CombatGained;")
         .Close()
         .Line()
         .Line("// 键是战斗内的 PlayerCombatState（本体每场战斗 new 一个）：弱引用键，旧的记录会跟着一起回收。")
         .Line("private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<PlayerCombatState, Rec> Recs = new();")
         .Line()
         .Line("/// <summary>记一笔「获得了 amount 点能量」（补丁调用；纯记录，出错也不影响获得能量本身）。</summary>")
         .Open("public static void Note(PlayerCombatState? state, decimal amount)")
         .Line("if (state is null || amount <= 0m) return;")
         .Open("try")
         .Open("if (!Recs.TryGetValue(state, out Rec? rec))")
         .Line("rec = new Rec { Turn = state.TurnNumber };")
         .Line("Recs.Add(state, rec);")
         .Close()
         .Line("// 换回合：本回合重新开始数")
         .Open("if (rec.Turn != state.TurnNumber)")
         .Line("rec.Turn = state.TurnNumber;")
         .Line("rec.TurnGained = 0;")
         .Close()
         .Line("rec.TurnGained += (int)amount;")
         .Line("rec.CombatGained += (int)amount;")
         .Close()
         .Open("catch (Exception)")
         .Line("// 纯记录，出错也不能影响「获得能量」本身")
         .Close()
         .Close()
         .Line()
         .Line("/// <summary>本回合获得了多少能量（回合开始补满的那部分不算；没记过就是 0）。</summary>")
         .Open("public static int GainedThisTurn(Player? player)")
         .Line("PlayerCombatState? state = player?.PlayerCombatState;")
         .Line("if (state is null || !Recs.TryGetValue(state, out Rec? rec)) return 0;")
         .Line("return rec.Turn == state.TurnNumber ? rec.TurnGained : 0;   // 换回合了就当 0")
         .Close()
         .Line()
         .Line("/// <summary>本场战斗获得了多少能量（换一场战斗自然从头算）。</summary>")
         .Open("public static int GainedThisCombat(Player? player)")
         .Line("PlayerCombatState? state = player?.PlayerCombatState;")
         .Line("return state is not null && Recs.TryGetValue(state, out Rec? rec) ? rec.CombatGained : 0;")
         .Close()
         .Close()
         .Line()
         .Line("/// <summary>打在**同步**方法 PlayerCombatState.GainEnergy(decimal) 上的后缀补丁。</summary>")
         .Line("[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState), \"GainEnergy\")]")
         .Open($"internal static class {EnergyGainTrackerClass}Patch")
         .Line("[HarmonyLib.HarmonyPostfix]")
         .Open("private static void After(PlayerCombatState __instance, decimal amount)")
         .Line($"try {{ {EnergyGainTrackerClass}.Note(__instance, amount); }}")
         .Line("catch (Exception e) { Log.Warn(\"能量记录失败：\" + e.Message); }   // 纯记录，出错也不能影响获得能量本身")
         .Close()
         .Close();
        return w.ToString();
    }

    /// <summary>
    /// 这份存档有没有用到「获得的能量」那两个读数（用到才生成那个小运行时 + 补丁）。
    ///
    /// 认法：把存档序列化成 JSON 文本找那两个内置名 —— 公式可能写在**任何**地方
    /// （卡牌效果的数值 / 次数 / 条件公式、遗物、自定义状态的触发条件、自定义参数的「从哪来」…），
    /// 一个个字段去翻太容易漏；JSON 里凡是用户填过的都会出现。
    /// 序列化万一失败就**宁可多生成**（多一个用不到的类无害，缺了会编译不过）。
    /// </summary>
    public static bool UsesEnergyGainTracker(CharacterProfile p)
    {
        string json;
        try { json = System.Text.Json.JsonSerializer.Serialize(p, ProfileFactory.JsonOpts); }
        catch { return true; }
        return json.Contains("EnergyGainedThis", StringComparison.Ordinal);
    }

    /// <summary>
    /// 「某个状态被移除时」那个小运行时 + 补丁的类名。固定名（同 <see cref="EnergyGainTrackerClass"/>）：
    /// 内置 / 生成端都直接写这个名字。
    /// </summary>
    public const string PowerRemovalClass = "ForgePowerRemoved";

    /// <summary>
    /// 「某个状态被移除时」（用户要求）：
    ///
    /// 本体**没有任何全局的「状态被移除」钩子** ——
    ///   · <c>PowerModel.AfterRemoved(Creature oldOwner)</c> 是**那个状态自己**的实例钩子（遗物 / 别的状态收不到）；
    ///   · <c>AfterPowerAmountChanged</c> 只覆盖「层数被扣到 0」那一半，被「清除状态」直接
    ///     <c>PowerCmd.Remove</c> 掉的**完全不走**那条路（本体 <c>PowerCmd.Remove</c> 只调 RemoveInternal + AfterRemoved）。
    ///
    /// 所以工具自己打一个补丁：<c>PowerModel.RemoveInternal()</c> 是本体所有移除的唯一出口
    /// （<c>PowerCmd.Remove</c> / <c>Creature.RemoveAllPowersInternalExcept</c> / 战斗结束清状态…全都走它），
    /// 后缀里拿到「哪个状态从谁身上被移除了」，再把这个通知转发给：
    ///   · 该生物所属**玩家身上的遗物**（凡是配了这条触发时机的那些）；
    ///   · 该生物身上**还留着的自定义状态**里配了这条触发时机的那些；以及**被移除的那个状态自己**。
    ///
    /// 那个方法（<see cref="PowerRemovedMethod"/>）是 async 的，而补丁是同步的 → 用本体自带的
    /// <c>TaskHelper.RunSafely(...)</c> 起一个「安全的后台任务」（本体自己也是这么处理 fire-and-forget 的）。
    /// 只有真的用到时才写这个文件（见 ModGenerator）。
    /// </summary>
    public static string PowerRemovalSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 「某个状态被移除时」的通知补丁（本体没有全局的「状态被移除」钩子） </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>")
         .Line("/// 【某个状态被移除时】本体只在那个状态自己身上回调（<c>PowerModel.AfterRemoved</c>），")
         .Line("/// 遗物 / 别的状态都收不到；而且「被效果直接清除」根本不走层数变化那条路。")
         .Line("/// 这个补丁打在 <c>PowerModel.RemoveInternal()</c> 上 —— 它是本体**所有**移除的唯一出口。")
         .Line("/// </summary>")
         .Line("[HarmonyLib.HarmonyPatch(typeof(PowerModel), \"RemoveInternal\")]")
         .Open($"internal static class {PowerRemovalClass}Patch")
         .Line("[HarmonyLib.HarmonyPostfix]")
         .Open("private static void After(PowerModel __instance)")
         .Line($"try {{ {PowerRemovalClass}.Notify(__instance); }}")
         .Line("catch (Exception e) { Log.Warn(\"状态移除通知失败：\" + e.Message); }   // 纯通知，出错也不能影响移除本身")
         .Close()
         .Close()
         .Line()
         .Open($"internal static class {PowerRemovalClass}")
         .Line("/// <summary>把「哪个状态从谁身上被移除了」通知给关心它的遗物 / 状态。</summary>")
         .Open("public static void Notify(PowerModel power)")
         .Line("Creature? owner = power.Owner;   // 本体移除时只把自己从 Powers 里摘掉，Owner 还在")
         .Line("if (owner is null) return;")
         .Line("// 通知范围 = **这一场战斗里的所有生物**（不只「被移除那个状态所在的那只」）—— V0.2.162 修：")
         .Line("// 老写法只遍历 power.Owner 身上的状态 / 它所属玩家的遗物，于是「挂在玩家身上、盯**敌人**身上")
         .Line("// 的状态被移除」这种配置**永远收不到通知**（用户实测报的「状态里监听某状态移除时无法触发」），")
         .Line("// 生成出来的守卫里那个「任意敌人」分支也就形同虚设。每条时机自己的守卫会筛掉不该管的通知，")
         .Line("// 所以这里只管发全 —— 每只生物各发一次，不会重复触发。")
         .Line("int __notified = 0;")
         .Line("var __listeners = new List<Creature>();")
         .Open("if (owner.CombatState is { } __cs)")
         .Open("foreach (Creature __c0 in __cs.Creatures)")
         .Line("if (__c0 is not null) __listeners.Add(__c0);")
         .Close()
         .Close()
         .Line("if (!__listeners.Contains(owner)) __listeners.Add(owner);   // 拿不到战斗状态时至少还有它自己")
         .Open("foreach (Creature __who in __listeners)")
         .Line("// 1) 遗物侧：这只生物所属玩家身上带这条触发时机的遗物")
         .Open("if (__who.Player is { } player)")
         .Open("foreach (RelicModel __relic in player.Relics.ToList())")
         .Open("switch (__relic)")
         .Line("// 每个「配了『某个状态被移除时』的遗物」各一行（生成时按存档决定）");
        foreach (var (r, idx) in RelicsWithPowerRemoved(p))
            w.Line($"case {n.RelicClassName(r, idx)} __r: __notified++; TaskHelper.RunSafely(__r.{PowerRemovedMethod}(power)); break;");
        w.Line("default: break;")
         .Close()
         .Close()
         .Close()
         .Line("// 2) 状态侧：这只生物身上**还留着**的自定义状态")
         .Open("foreach (PowerModel __p in __who.Powers.ToList())")
         .Open("switch (__p)")
         .Line("// 每个「配了『某个状态被移除时』的自定义状态」各一行");
        foreach (string cls in PowersWithPowerRemoved(p))
            w.Line($"case {cls} __c: __notified++; TaskHelper.RunSafely(__c.{PowerRemovedMethod}(power)); break;");
        w.Line("default: break;")
         .Close()
         .Close()
         // ⚠ 这里必须把 `foreach (Creature __who …)` 也关掉：第 3 段（「被移除的那个就是自己」）
         // 只能在循环**外面**判一次，否则每只生物都会把同一条时机再触发一遍（V0.2.162 改这段时踩过）。
         .Close()
         .Line("// 3) 被移除的那个状态**自己**也配了这条时机时（它已经从 Powers 里摘掉了，所以单独判一次）")
         .Open("switch (power)")
         .Line("// 每个「自己就是被移除的那个」也各一行");
        foreach (string cls in PowersWithPowerRemoved(p))
            w.Line($"case {cls} __me: __notified++; TaskHelper.RunSafely(__me.{PowerRemovedMethod}(power)); break;");
        w.Line("default: break;")
         .Close();
        // 「生成调试日志」开着时，把这次通知也写一行进游戏日志（排查「这条时机没触发」用：
        // 0 = 一个盯这条时机的遗物 / 状态都没通知到（存档里没配，或补丁文件压根没生成）；
        // ≥1 = 通知到了，那问题在那条时机自己的守卫（「盯谁」那一栏）里）
        if (p.DebugLog)
            w.Line("Log.Info(\"[模组调试] 状态被移除：\" + power.GetType().Name + \"（通知了 \" + __notified + \" 个盯这条时机的遗物 / 状态）\");");
        w.Close()
         .Close()
         .Close();
        return w.ToString();
    }

    /// <summary>配了「某个状态被移除时」的遗物（连同它在存档里的下标 —— 生成类名要用）。</summary>
    private static IEnumerable<(RelicSpec Relic, int Index)> RelicsWithPowerRemoved(CharacterProfile p)
    {
        for (int i = 0; i < p.Relics.Count; i++)
        {
            var r = p.Relics[i];
            if (r is null) continue;
            // 遗物**自己**的触发时机里（第 10 批：可能有好几条）有「某个状态被移除时」
            if (r.Triggers.Any(t => t is not null && string.Equals(t.Kind, "PowerRemoved", StringComparison.Ordinal)))
            { yield return (r, i); continue; }
            // 或者它的**锻造节点图**挑了这条时机（第 9 批 ④ 后半段把这条时机补进锻造页的菜单）——
            // 那种图和遗物自己的触发时机是两个钩子，图会生成一个 `OnForgePowerRemovedAsync` 普通方法
            //（见 RelicTriggerSignature）；补丁里不把这个类列进来的话，那个方法永远不会被调用
            //（菜单里选得到、生成出来什么也不做）。
            if (r.ForgeGraph is { IsEmpty: false } g)
            {
                var trig = g.TriggerNode;
                if (trig is not null && string.Equals(trig.Get("Timing"), "PowerRemoved", StringComparison.Ordinal))
                    yield return (r, i);
            }
        }
    }

    /// <summary>配了「某个状态被移除时」的自定义状态（生成类名；空类名按存档里的下标自动起名，见 CustomPowerGen.ClassNameOf）。</summary>
    private static IEnumerable<string> PowersWithPowerRemoved(CharacterProfile p)
    {
        for (int i = 0; i < p.CustomPowers.Count; i++)
        {
            var cp = p.CustomPowers[i];
            if (cp is null) continue;
            if (!cp.Triggers.Any(t => t is not null && Effects.PowerTriggers.Canonical(t.Kind) == "PowerRemoved")) continue;
            yield return CustomPowerGen.ClassNameOf(p, cp, i);
        }
    }

    /// <summary>这份存档有没有用到「某个状态被移除时」（用到才生成那个补丁文件）。</summary>
    public static bool UsesPowerRemovedTrigger(CharacterProfile p) =>
        // 遗物自己选了这条时机 **或** 它的锻造节点图选了这条（见 RelicsWithPowerRemoved）
        RelicsWithPowerRemoved(p).Any()
        || PowersWithPowerRemoved(p).Any();

    /// <summary>
    /// 「在游戏中隐藏那只额外资源量载体遗物」（用户要求）。
    ///
    /// 那只 <c>&lt;角色&gt;ExtraResourceRelic</c> 只是载体（开场发资源量 / 记跨战斗继承），
    /// 不该占遗物栏的一格 —— 但本体**没有**「隐藏某个遗物」的接口：
    /// 遗物栏（<c>NRelicInventory.Initialize</c>）是遍历 <c>Player.Relics</c> 逐个
    /// <c>Add(relic, startsShown: true, index: -1)</c> 建出来的，没有可见性判断。
    ///
    /// <para>
    /// <b>V0.2.138 修的那条卡死</b>：这里以前打的是**前缀补丁**，遇到载体遗物就
    /// <c>return false</c> 跳过原方法 → 遗物栏的节点列表 <c>_relicNodes</c> 比
    /// <c>Player.Relics</c> 少一项 → 之后再获得任何遗物时
    /// <c>OnRelicObtained</c> 按模型算出来的 <c>index</c> 插进这个短列表就**越界**
    /// （<c>List.Insert</c> 抛 ArgumentOutOfRangeException，异步任务死掉 = 玩家眼里卡死）。
    /// </para>
    ///
    /// <para>
    /// 现在改成**后缀补丁**：原方法（private，签名 <c>(RelicModel relic, bool startsShown, int index)</c>）
    /// 一个字都不动地照跑 —— 节点照建、照 <c>Insert</c> 进 <c>_relicNodes</c>、照进 Godot 树，
    /// 列表长度与顺序**永远**和 <c>Player.Relics</c> 一致；补丁只在跑完之后把**刚建出来的那个节点**
    /// 设成 <c>Visible = false</c>（纯视觉）。遗物本身照旧挂在角色身上 →
    /// 发放 / 继承 / 存档兼容完全不变。
    /// </para>
    ///
    /// <para>
    /// <b>只补 <c>Add</c> 这一个方法，「新获得动画」不需要单独挡。</b>
    /// 挂在 <c>AnimateRelic</c> 上的**后缀**补丁里 <c>return</c> 只是从它**自己**的 Postfix 返回
    /// （原方法早就跑完了，动画该播还是播）—— 那是空操作。要真拦住只能用前缀 skip，
    /// 而那是**多余**的：动画只 tween 节点里 icon 的 <c>Modulate.a</c> / <c>Position</c> / <c>Scale</c>，
    /// **不碰 <c>Visible</c>**；父节点已经 <c>Visible = false</c> ⇒ 整棵子树都不渲染，
    /// 动画自己在不可见节点上跑完、没有任何可见效果。
    /// （V0.2.138 实现中途曾多挂过一个 <c>AnimateRelic</c> 后缀当「跳过动画」—— 空操作 + 注释与事实相反，
    /// 已在同一版里删掉。）
    /// </para>
    ///
    /// 只有真的勾了「在游戏中隐藏」才生成这个文件。
    /// </summary>
    public static string HideCarrierRelicSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var cls = n.ExtraResourceRelicClass;
        var w = new CodeWriter();
        w.Line("// <auto-generated> 把「额外资源量」那只载体遗物从遗物栏里藏起来（只做视觉隐藏） </auto-generated>")
         .Line("using System.Collections.Generic;")
         .Line("using MegaCrit.Sts2.Core.Models;")
         .Line("using MegaCrit.Sts2.Core.Nodes.Relics;")
         .Line("using HarmonyLib;")
         .Line()
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>")
         .Line("/// 把「额外资源量」那只载体遗物从遗物栏里藏起来 —— **只做视觉隐藏**。")
         .Line("///")
         .Line("/// 本体没有「隐藏某个遗物」的接口（遗物栏 NRelicInventory 是遍历 Player.Relics、")
         .Line("/// 对每一个都 Add 一次建出来的，没有可见性判断），RelicModel 上也没有「别显示我」的虚属性，")
         .Line("/// 所以只能补在界面节点上。这里打的是**后缀补丁**：")
         .Line("///   原方法一个字都不改地照跑（节点照建、照插进 _relicNodes、照进 Godot 树），")
         .Line("///   遗物栏的节点列表长度与顺序**永远**和 Player.Relics 一致；")
         .Line("///   跑完之后才把刚建出来的那个节点设成 Visible = false（纯视觉）。")
         .Line("/// ⚠ 绝不能改成前缀补丁 return false 跳过原方法：那会让遗物栏的节点列表比 Player.Relics")
         .Line("///   少一项，之后再获得任何遗物时按模型算出来的 index 插进去就**越界**（卡死）。")
         .Line("/// 遗物本身照旧挂在角色身上 —— 发放 / 跨战斗继承 / 存档兼容完全不变。")
         .Line("/// 「新获得遗物」的飞入动画不用管：它只 tween 节点里 icon 的透明度/位置/缩放，不碰 Visible，")
         .Line("/// 父节点不可见 ⇒ 整棵子树都不渲染，动画自己在不可见节点上跑完、没有任何可见效果。")
         .Line("/// </summary>")
         .Line("[HarmonyPatch(typeof(NRelicInventory), \"Add\")]")
         .Open("internal static class ForgeHideCarrierRelicPatch")
         .Line("/// <summary>")
         .Line("/// 后缀：原方法已经跑完（节点已在 _relicNodes 里、也进树了），这时才去藏它。")
         .Line("/// 参数 __0 = 原方法的第 1 个参数 relic<b>（只读，不参与任何计算）</b>；")
         .Line("/// index / startsShown 一律不碰 —— 索引一致就是靠这个。")
         .Line("/// </summary>")
         .Line("[HarmonyPostfix]")
         .Open($"private static void Postfix(NRelicInventory __instance, RelicModel __0)")
         .Line($"if (__0 is not {cls}) return;")
         .Line("IReadOnlyList<NRelicInventoryHolder> nodes = __instance.RelicNodes;")
         .Line("// 从后往前找：刚建出来的那一个在列表尾部（Initialize 是 Add 到末尾，OnRelicObtained 是插在模型里的同一位置）。")
         .Open("for (int i = nodes.Count - 1; i >= 0; i--)")
         .Line("// 认模型实例（和本体自己的 Remove / AnimateRelic 一样按 Relic.Model 找）：")
         .Line("// 运行期一个遗物只有一个 RelicModel 实例，游戏自己也用 Player.Relics.IndexOf 找它。")
         .Line("if (nodes[i].Relic is not { } relicNode || !ReferenceEquals(relicNode.Model, __0)) continue;")
         .Line("nodes[i].Visible = false;   // 只藏节点：列表项 / 索引 / Godot 树一个都不动")
         .Line("return;")
         .Close()    // 关 for
         .Close()    // 关 Postfix
         .Close();   // 关 ForgeHideCarrierRelicPatch（文件里就只有这一个补丁类）

        return w.ToString();
    }

    /// <summary>这份存档要不要生成「隐藏载体遗物」那个补丁（勾了隐藏 + 额外资源量启用）。</summary>
    public static bool UsesHiddenCarrierRelic(CharacterProfile p) =>
        p.ExtraResource.Enabled && p.ExtraResource.HideInGame;

    /// <summary>
    /// 「数值公式」用哪一种「现算预览值」的动态变量（认不出来返回 null = 这个效果种类没有对应的变量）。
    /// 只有 <see cref="EffectSpec.FormulaSupports"/> 那 5 种能写公式，它们各自都有本体的变量类型可以继承。
    /// </summary>
    internal static string? FormulaVarClassOf(string kind) => kind switch
    {
        "Damage" => "ForgeFormulaDamageVar",
        "Block" => "ForgeFormulaBlockVar",
        "HpLoss" => "ForgeFormulaHpLossVar",
        "Heal" => "ForgeFormulaHealVar",
        // 施加状态：值是那个状态的层数，变量名就是状态的类名（和 PowerVar<T> 一致）
        "ApplyPower" => "ForgeFormulaPowerVar",
        _ => null,
    };

    /// <summary>
    /// 「数值公式」在**动态变量**里的写法（卡面预览用）：公式原文 → C# 表达式，
    /// 里面的「自己 / 玩家 / 打出的目标」换成变量子类的参数 <c>card</c> / <c>target</c>。
    ///
    /// 为什么用 <see cref="ForgeFormula.ConditionResolver"/>：它会把自定义参数**内联展开**
    ///（参数在 OnPlay 里是局部变量 __pM，变量子类里拿不到），并给出 <c>base.Owner</c> 版的表达式 ——
    /// 这里再把 <c>base.Owner</c> 换成 <c>(card.Owner)</c> 就行（先换长的那个）。
    ///
    /// ⚠ 这个表达式最终落在 <c>static (card, target) =&gt; …</c> 这个**静态匿名函数**里，
    ///   静态匿名函数**不许出现 `base`**（CS8821「静态匿名函数不能包含对 this 或 base 的引用」）。
    ///   而 <c>XSpent</c> / <c>YSpent</c> 这两条读数用的正是 <c>base.EnergyCost</c> /
    ///   <c>base.ResolveEnergyXValue()</c> / <c>base.HasStarCostX</c> / <c>base.ResolveStarXValue()</c>
    ///   —— 只换 <c>base.Owner</c> 换不到它们，于是「伤害填 XSpent」的卡会整个编不过（探针真编译抓出来的）。
    ///   最后那一句把**剩下的所有 `base.`** 也换成 <c>(card).</c>（那四个成员在 CardModel 上都是公开的）。
    /// </summary>
    internal static string FormulaPreviewExpr(CharacterProfile p, EffectSpec e)
    {
        var resolver = ForgeFormula.ConditionResolver(p, "(target)");
        string expr = ForgeFormula.Emit(ForgeFormula.TryParse(e.AmountFormula, out _), resolver, out _) ?? "0m";
        return expr.Replace("base.Owner.Creature", "(card.Owner.Creature)", StringComparison.Ordinal)
                   .Replace("base.Owner", "(card.Owner)", StringComparison.Ordinal)
                   .Replace("base.", "(card).", StringComparison.Ordinal);   // XSpent / YSpent 那四个成员
    }

    /// <summary>
    /// 这份存档有没有用到「数值公式的现算变量」（用到才生成 cs/FormulaVars.cs）。
    /// V0.2.164：遗物 / 药水也能写「数值公式」了 —— 它们的 <c>CanonicalVars</c> 同样会声明
    /// <c>ForgeFormulaDamageVar</c> 这类变量（见 <see cref="VarDeclaration"/>），所以这三条链也算数，
    /// 不然生成出来的工程会 CS0246（找不到那个变量类）。
    /// </summary>
    public static bool UsesFormulaVars(CharacterProfile p) =>
        p.Cards.Any(c => c is not null && c.Effects.Any(e => e is not null
            && e.UsesAmountFormula && FormulaVarClassOf(e.Kind) is not null))
        || p.Relics.Any(r => r is not null && r.Effects.Any(HasFormulaVar))
        || p.Potions.Any(s => s is not null && s.Effects.Any(HasFormulaVar));
    // ⚠ 自定义状态**不列进来**：状态类不声明 CanonicalVars（它的数值直接内联进钩子里），
    // 所以那三条链里只有遗物 / 药水会用到这些变量类。

    /// <summary>这条效果会不会声明一个「数值公式」的现算变量（<see cref="FormulaVarClassOf"/> 认得出来的那 5 种）。</summary>
    private static bool HasFormulaVar(EffectSpec? e) =>
        e is not null && e.UsesAmountFormula && FormulaVarClassOf(e.Kind) is not null;

    // ==================== V0.2.164：「数值公式」铺到遗物 / 药水 / 自定义状态 ====================

    /// <summary>
    /// 遗物 / 药水 / 自定义状态的「数值公式」→ **内联** C# 表达式（null = 没写公式 / 这种效果不支持公式）。
    ///
    /// 为什么这三条链走内联、卡牌走前置局部变量：卡牌每次打出（或卡牌时机钩子）之前会先跑
    /// <see cref="ForgeGraphGen.EmitCardFormulaPrologue"/> 把 <c>__pM</c> / <c>__X</c> / <c>__Y</c> 算好；
    /// 遗物 / 药水 / 状态的执行点（触发器钩子 / OnUse）**没有**那套前置 —— 而这三条链的
    /// 「自己 / 玩家」就是 <c>base.Owner</c>（遗物 / 药水的 Owner 是 Player，状态的 Owner 是 Creature），
    /// 直接内联展开即可（和锻造节点图那边同一套 <see cref="ForgeFormula.InlineResolver"/>）。
    ///
    /// 代价：公式如果在循环里会被求值多次 —— 公式是纯表达式（只读模型数据），没有副作用，安全。
    /// </summary>
    /// <param name="targetExpr">
    /// 「指定敌人」那类参数在这条链上取谁。遗物 / 药水 / 状态没有「玩家选中的目标」，
    /// 惯例是取**可打的第一个敌人**（和这些链上「作用对象 = 单体敌人」的执行口径一致）。
    /// </param>
    internal static string? InlineAmountFormula(CharacterProfile? p, EffectSpec e, string playerExpr, string selfExpr,
        string? targetExpr = null)
    {
        if (p is null || e is null || !e.UsesAmountFormula) return null;
        var root = ForgeFormula.TryParse(e.AmountFormula, out _);
        if (root is null) return null;   // 解析不出来的由校验器报错，这里退回固定数值
        return ForgeFormula.Emit(root, ForgeFormula.InlineResolver(p, playerExpr, selfExpr, targetExpr), out _);
    }

    /// <summary>「指定敌人」在遗物 / 药水 / 状态这三条链上取谁（可打的第一个敌人）。</summary>
    internal static string FirstEnemyOf(string playerExpr) => $"ForgeFormulaRuntime.FirstEnemy({playerExpr})";

    /// <summary>
    /// 【V0.2.164】遗物 / 药水的「数值公式」**悬停时现算**那几行（没用到公式返回空列表）。
    ///
    /// 为什么需要：卡面 / 遗物描述里的 <c>{Heal:diff()}</c> 读的是动态变量的 <c>PreviewValue</c>，
    /// 卡牌由本体在显示前调 <c>UpdateCardPreview</c> 刷新；**遗物 / 药水没有这个回调**，
    /// 所以轮到我们自己在「取悬停说明」那一步刷新一次（挂在 <c>ExtraHoverTips</c> 上，
    /// 本体 <c>HoverTips</c> 会读它，而说明文本是**渲染时**才格式化的 → 赶得上）。
    /// 顺带把 <c>BaseValue</c> 也写上：本体 <c>ClearPreview()</c> 会把 PreviewValue 重置回 BaseValue。
    /// </summary>
    internal static List<string> FormulaPreviewRefreshLines(CharacterProfile? p, IEnumerable<EffectSpec> effects,
        Dictionary<EffectSpec, string>? varMap, string playerExpr, string selfExpr)
    {
        var lines = new List<string>();
        if (p is null) return lines;
        string target = FirstEnemyOf(playerExpr);
        foreach (var e in effects.Where(x => x is not null
                     && x.UsesAmountFormula && FormulaVarClassOf(x.Kind) is not null))
        {
            string? expr = InlineAmountFormula(p, e, playerExpr, selfExpr, target);
            if (expr is null) continue;
            string name = Lit.Str(DisplayVarNameOf(e, varMap));
            lines.Add($"base.DynamicVars[{name}].BaseValue = ({expr});");
            lines.Add($"base.DynamicVars[{name}].PreviewValue = ({expr});");
        }
        return lines;
    }

    /// <summary>
    /// 【V0.2.164】遗物 / 药水的 <c>__RefreshFormulaPreview()</c> 方法（没用到公式返回空字符串）。
    /// 名字固定；调用点只有生成出来的 <c>ExtraHoverTips</c>（见 <see cref="HoverTipsOverride"/>）。
    /// </summary>
    internal static string FormulaPreviewRefreshMethod(CharacterProfile? p, IEnumerable<EffectSpec> effects,
        Dictionary<EffectSpec, string>? varMap, string playerExpr, string selfExpr)
    {
        var lines = FormulaPreviewRefreshLines(p, effects, varMap, playerExpr, selfExpr);
        if (lines.Count == 0) return "";
        var w = new CodeWriter();
        w.Line();
        w.Line("    // 「数值公式」的悬停数字：遗物 / 药水的描述里 {Heal:diff()} 读的是变量的 PreviewValue，");
        w.Line("    // 而它们不像卡牌那样有「显示前回调」—— 所以轮到我们自己在取悬停说明时现算一遍。");
        w.Open("    private void __RefreshFormulaPreview()");
        foreach (string line in lines) w.Line(line);
        w.Close();
        return w.ToString();
    }

    /// <summary>
    /// 「数值公式」+「升级增量」合并成**打出时**用的表达式（用户实测：「升级增量怎么没效果了」）。
    ///
    /// 为什么需要它：打了数值公式的卡，打出时用的是公式算出来的那个值（不读 CanonicalVars 里那个变量），
    /// 而升级增量在本体那边是 <c>OnUpgrade</c> 里的 <c>base.DynamicVars["X"].UpgradeValueBy(N)</c> —— 改的是变量。
    /// 两边不搭界，于是升级前后打出来一样多。这里把增量并进表达式：
    ///   · 纯常数公式（<c>5</c>，老存档迁过来的固定值就是这种）→ <c>(base.IsUpgraded ? 8m : 5m)</c>：
    ///     和本体老写法一致，回读 <c>ProjectRecovery.FillExpr</c> 直接认得；
    ///   · 真·现算公式（<c>M*2</c>）→ <c>(base.IsUpgraded ? ((M*2) + 3m) : (M*2))</c>：各写一次，只在需要的那支求值。
    /// </summary>
    internal static string UpgradeAwareAmount(EffectSpec e, string formula) =>
        TryFormulaConstant(e.AmountFormula, out decimal baseValue)
            ? $"(base.IsUpgraded ? {Lit.Dec(baseValue + e.UpgradeAmount)} : {Lit.Dec(baseValue)})"
            : $"(base.IsUpgraded ? ({formula} + {Lit.Dec(e.UpgradeAmount)}) : {formula})";

    /// <summary>公式原文是不是「纯数字」（老存档迁过来的固定值，或用户手填的常数）。</summary>
    internal static bool TryFormulaConstant(string? formula, out decimal value)
    {
        value = 0m;
        string t = (formula ?? "").Trim();
        if (t.Length == 0) return false;
        foreach (char ch in t)
            if (!char.IsDigit(ch) && ch != '.' && ch != '-' && ch != '+') return false;
        return decimal.TryParse(t, System.Globalization.NumberStyles.Float,
            System.Globalization.CultureInfo.InvariantCulture, out value);
    }

    /// <summary>
    /// 「数值公式」那几个**现算预览值**的动态变量（用到才生成）。
    ///
    /// 为什么必须自己写：卡面 <c>{Damage:diff()}</c> 显示的是 <c>PreviewValue</c>，而普通
    /// <c>DamageVar</c> 只会拿构造时那个固定基准值 —— 填了公式（例 M/2）就会在卡面上印一个假数字。
    /// 这几个子类把「基准值」改成预览时现算的公式值（**先设 BaseValue 再调 base.UpdateCardPreview**，
    /// 于是力量 / 敏捷 / 易伤那些加成照旧叠上去），玩家看到的就是真实数字。
    ///
    /// 变量名和本体一致（Damage / Block / HpLoss / Heal / 状态类名）→ 卡面占位符、升级增量、
    /// 回读全都不用改。
    /// </summary>
    public static string FormulaVarsSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 「数值公式」用的动态变量（卡面上显示公式算出来的数字） </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>")
         .Line("/// 【数值公式的卡面数字】卡面 <c>{Damage:diff()}</c> 这类占位符显示的是 <c>PreviewValue</c>，")
         .Line("/// 而普通变量只会拿构造时的固定基准值 —— 填了公式的卡会显示一个假数字。")
         .Line("/// 这几个子类的做法：预览时**先**把公式算出来写进 BaseValue，**再**调本体的")
         .Line("/// <c>base.UpdateCardPreview</c>（力量 / 敏捷这些加成照旧叠上去），于是卡面显示的就是真实值。")
         .Line("/// 变量名和本体一致（Damage / Block / HpLoss / Heal / 状态类名）→ 卡面占位符与升级增量都不用改。")
         .Line("/// </summary>");
        AppendFormulaVar(w, "ForgeFormulaDamageVar", "DamageVar", "0m, ValueProp.Move", "0m, ValueProp.Move", "ValueProp.Move");
        w.Line();
        AppendFormulaVar(w, "ForgeFormulaBlockVar", "BlockVar", "0m, ValueProp.Move", "0m, ValueProp.Move", "ValueProp.Move");
        w.Line();
        AppendFormulaVar(w, "ForgeFormulaHpLossVar", "HpLossVar", "0m", "0m", null);
        w.Line();
        AppendFormulaVar(w, "ForgeFormulaHealVar", "HealVar", "0m", "0m", null);
        w.Line();
        // 施加状态：PowerVar<T> 是泛型，子类也得是泛型（值 = 那个状态的层数）
        w.Line("/// <summary>「施加状态」的数值公式：变量名就是那个状态的类名（和 PowerVar&lt;T&gt; 一样）。</summary>")
         .Open("internal sealed class ForgeFormulaPowerVar<T> : PowerVar<T> where T : PowerModel")
         .Line("private readonly Func<CardModel, Creature?, decimal> _formula;")
         .Line("private readonly decimal _upgrade;")
         .Line("public ForgeFormulaPowerVar(Func<CardModel, Creature?, decimal> formula, decimal upgrade = 0m) : base(0m) { _formula = formula; _upgrade = upgrade; }")
         .Line("public ForgeFormulaPowerVar(string name, Func<CardModel, Creature?, decimal> formula, decimal upgrade = 0m) : base(name, 0m) { _formula = formula; _upgrade = upgrade; }")
         .Open("public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)")
         .Open("if (card.Owner is not null)")
         .Line("BaseValue = _formula(card, target) + (card.IsUpgraded ? _upgrade : 0m);   // 公式值 + 升级增量，下面的 base 再叠力量 / 易伤那些加成")
         .Close()
         .Line("base.UpdateCardPreview(card, previewMode, target, runGlobalHooks);")
         .Close()
         .Close();
        return w.ToString();

        // 每个变量子类长得一模一样（只是基类 / 构造参数不同），抽出来省得抄五遍抄错。
        void AppendFormulaVar(CodeWriter w2, string cls, string baseCls, string ctorArgs, string nameCtorArgs, string? _)
        {
            w2.Line($"/// <summary>{baseCls} 的「公式现算」版本（卡面数字 = 公式值 + 升级增量 + 本体那些加成）。</summary>")
              .Open($"internal sealed class {cls} : {baseCls}")
              .Line("private readonly Func<CardModel, Creature?, decimal> _formula;")
              .Line("private readonly decimal _upgrade;")
              .Line($"public {cls}(Func<CardModel, Creature?, decimal> formula, decimal upgrade = 0m) : base({ctorArgs}) {{ _formula = formula; _upgrade = upgrade; }}")
              .Line($"public {cls}(string name, Func<CardModel, Creature?, decimal> formula, decimal upgrade = 0m) : base(name, {nameCtorArgs}) {{ _formula = formula; _upgrade = upgrade; }}")
              .Open("public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)")
              .Open("if (card.Owner is not null)")
              .Line("BaseValue = _formula(card, target) + (card.IsUpgraded ? _upgrade : 0m);   // 公式值 + 升级增量，下面的 base 再叠力量 / 敏捷那些加成")
              .Close()
              .Line("base.UpdateCardPreview(card, previewMode, target, runGlobalHooks);")
              .Close()
              .Close();
        }
    }

    /// <summary>这份存档有没有用到「敌人死亡计数」（用到才生成那个小运行时）。</summary>
    public static bool UsesEnemyDeathCounter(CharacterProfile p) =>
        // 第 10 批：遗物有多条触发时机 → 每一条都要看（只看第 1 条会漏掉「第 2 条是每 N 个敌人死亡」
        // 那种存档，生成出来会 CS0103「找不到 ForgeCombatCounters」）
        p.Relics.Any(r => r is not null && r.Triggers.Any(t => t is not null
            && t.Kind == "EnemyDeath" && t.Amount > 0m))
        || p.CustomPowers.Any(cp => cp is not null && cp.Triggers.Any(t => t is not null
            && Effects.PowerTriggers.Canonical(t.Kind) == "EnemyDeath" && t.TriggerAmount > 0m));

    /// <summary>
    /// 同上，但给「一条效果包一层 if」的写法用（自定义状态那条链上多条触发时机共用一个钩子）：
    /// 返回条件表达式（<c>null</c> = 这条时机没有数值 / 没填 → 不用包）。
    /// </summary>
    public static string? TriggerAmountCond(string kind, decimal amount, string scope,
        string creatureExpr, string stateExpr, string playerExpr, string? valueExpr = null)
    {
        if (amount <= 0m) return null;
        if (valueExpr is not null) return $"{valueExpr} >= {Lit.Dec(amount)}";
        string count = CountExpr(kind, scope, creatureExpr, stateExpr, playerExpr);
        return count.Length == 0 ? null : $"{count} % {Lit.Int(amount)} == 0";
    }

    /// <summary>阈值族要比的那个数（认不出来返回 null = 这条时机是计数族 / 不支持）。</summary>
    public static string? TriggerValueExpr(string kind) => kind switch
    {
        "DamageReceived" or "DamageDealt" => "result.UnblockedDamage",
        "HpLost" => "-delta",
        "BlockGained" => "amount",
        _ => null,
    };

    /// <summary>计数族那条时机在「本回合 / 本场战斗」里的累计次数表达式（认不出来返回空串）。</summary>
    public static string CountExpr(string kind, string scope, string creatureExpr, string stateExpr, string playerExpr)
    {
        string turn = scope == "Combat" ? "" : $" && e.HappenedThisTurn({stateExpr})";
        const string H = "MegaCrit.Sts2.Core.Combat.History.Entries.";
        return kind switch
        {
            "CardPlayed" => $"CombatManager.Instance.History.CardPlaysFinished.Count(e => e.Actor == {creatureExpr}{turn})",
            "CardExhausted" => $"CombatManager.Instance.History.Entries.OfType<{H}CardExhaustedEntry>().Count(e => e.Card.Owner.Creature == {creatureExpr}{turn})",
            "CardDiscarded" => $"CombatManager.Instance.History.Entries.OfType<{H}CardDiscardedEntry>().Count(e => e.Card.Owner.Creature == {creatureExpr}{turn})",
            "CardDrawn" => $"CombatManager.Instance.History.Entries.OfType<{H}CardDrawnEntry>().Count(e => e.Card.Owner.Creature == {creatureExpr}{turn})",
            "CardGenerated" => $"CombatManager.Instance.History.Entries.OfType<{H}CardGeneratedEntry>().Count(e => e.Creator == {playerExpr}{turn})",
            _ => "",
        };
    }

    /// <summary>标记里写的数值（回读用）：0.## + m，和别处的十进制字面量一个写法。</summary>
    public static string TriggerAmountForMarker(decimal value) => Lit.Dec(value);

    /// <summary>这条触发时机有没有「数值」可填（决定界面上那一栏显不显示）。</summary>
    public static bool TriggerSupportsAmount(string kind) =>
        CountExpr(kind, "Turn", "x", "y", "z").Length > 0
        || kind is "DamageReceived" or "DamageDealt" or "HpLost" or "BlockGained" or "EnemyDeath"
        // V0.2.152：「某个状态层数到达 N 层时」的 N。
        // 以前这一档**不在名单里 → 界面上根本没有 N 输入框**：于是 N 永远停在默认值 1，
        // 生成出来是「层数跨过 1 那一下触发」（用户想要的是到达他自己填的那一层），
        // 状态描述里也只能印一个字母 N（用户报「我状态层数达到了却没生成卡牌」
        // 「在游戏中怎么也是 N，而不是填的数」两条都是这个）。
        // 注意它**不算**计数族（TriggerAmountNeedsScope 用的是 CountExpr，不会给它显示「本回合 / 本场战斗」）。
        or "PowerReached";

    /// <summary>有数值可填但又需要「本回合 / 本场战斗」范围的（只有计数族需要）。</summary>
    public static bool TriggerAmountNeedsScope(string kind) =>
        CountExpr(kind, "Turn", "x", "y", "z").Length > 0;

    /// <summary>
    /// 「花掉能量 / 花掉额外资源量」触发时机上的**数值**（用户要求）：<b>每累计花掉 N 点触发一次</b>，
    /// 范围可选**本回合 / 本场战斗**。
    ///
    /// 实现是**无状态**的（不用自己记计数器、也不用生成补丁）：直接读本体的战斗历史
    ///   · 能量：<c>EnergySpentEntry</c>（每条记录一次「这一张牌花了多少」）；
    ///   · 额外资源量：<c>StarsModifiedEntry</c> 里 <c>Amount &lt; 0</c> 的那几条（负数是花掉）。
    /// 本体是在**调钩子之前**就把这一笔记进历史的（见 <c>CardModel.SpendEnergy</c> / <c>SpendStars</c>：
    /// 先 <c>History.EnergySpent(...)</c> 再 <c>Hook.AfterEnergySpent(...)</c>），
    /// 所以「这一次之前已经花了多少」= 历史累计 − 这一次的 <c>amount</c>；
    /// 循环里第 i 个点对应的累计值就是 <c>之前 + i + 1</c>，能被 N 整除就触发 → 正好是「每 N 点一次」。
    /// </summary>
    public static string SpentSumExpr(string kind, string scope, string creatureExpr, string stateExpr)
    {
        string turn = scope == "Combat" ? "" : $" && e.HappenedThisTurn({stateExpr})";
        return kind == "StarsSpent"
            ? $"(int)(-CombatManager.Instance.History.Entries.OfType<MegaCrit.Sts2.Core.Combat.History.Entries.StarsModifiedEntry>()"
              + $".Where(e => e.Actor == {creatureExpr} && e.Amount < 0{turn}).Sum(e => e.Amount))"
            : $"(int)CombatManager.Instance.History.Entries.OfType<MegaCrit.Sts2.Core.Combat.History.Entries.EnergySpentEntry>()"
              + $".Where(e => e.Actor == {creatureExpr}{turn}).Sum(e => e.Amount)";
    }

    /// <summary>
    /// 每累计 N 点触发一次的**循环内那一句**（放在「按点数循环」的最前面）。
    /// <paramref name="idxVar"/> = 那一层的循环变量，<paramref name="beforeVar"/> = 进循环前算好的「之前花了多少」。
    /// </summary>
    public static string SpendTickLine(decimal amount, string idxVar, string beforeVar) =>
        $"if (({beforeVar} + {idxVar} + 1) % {Lit.Int(Math.Max(1m, amount))} != 0) continue;   // 每累计 {amount:0.##} 点触发一次";

    /// <summary>同上，但给「一条效果包一层 if」的写法用（自定义状态那条链里多条触发时机共用一个循环）。</summary>
    public static string SpendTickCond(decimal amount, string idxVar, string beforeVar) =>
        $"({beforeVar} + {idxVar} + 1) % {Lit.Int(Math.Max(1m, amount))} == 0";

    /// <summary>「每累计 N 点触发一次（范围：本回合 / 本场战斗）」那句注释。</summary>
    public static string SpendThresholdComment(decimal amount, string scope) =>
        $"// 数值：每累计花掉 {amount:0.##} 点触发一次（范围：{(scope == "Combat" ? "本场战斗" : "本回合")}）";

    /// <summary>「这一次之前已经花了多少」那一句（放在循环之前）。</summary>
    public static string SpendBeforeLine(string kind, string scope, string creatureExpr, string stateExpr) =>
        $"int __spentBefore = {SpentSumExpr(kind, scope, creatureExpr, stateExpr)} - amount;   // 这一次之前已经花了多少（本体先记账再调钩子）";

    /// <summary>
    /// 次数类公式（生效次数 / 命中次数 / 复制份数 / 重放次数）在生成代码里的表达式。
    /// 解析与求值完全复用「数值公式」那一套（<see cref="ForgeFormula.CardResolver"/>）——
    /// 参数 M / N…、X / Y、内置只读量、min/max 那些函数都照旧。
    /// 返回 null = 这个字段没写公式（或者写了但那条链不支持，见 <see cref="EffectSpec.ShowsCountFormula"/>）。
    /// </summary>
    public static string? CountFormulaExpr(CharacterProfile? p, EffectSpec e, string key, out string error)
    {
        error = "";
        if (p is null || e is null || !e.UsesCountFormula(key)) return null;
        var root = ForgeFormula.TryParse(e.CountFormula(key), out error);
        if (root is null) return null;
        return ForgeFormula.Emit(root, ForgeFormula.CardResolver(p), out error);
    }


    /// <summary>
    /// 格挡数值。统一用 decimal 那条重载（BlockVar 重载内部也只是转发 BaseValue + Props），
    /// 这样起了别名的变量（Block2）也能直接用 —— 索引器返回的是 DynamicVar，转不成 BlockVar。
    /// </summary>
    internal static string BlockValueAccess(Dictionary<EffectSpec, string>? map = null, EffectSpec? e = null)
    {
        if (e is null) return "base.DynamicVars.Block.BaseValue";
        return VarAccess(e, map);
    }

    /// <summary>
    /// 一个效果的动态变量声明。
    ///
    /// <paramref name="p"/> 非空时，「按生命值算」的宠物效果会把里面的 <c>&lt;Pet&gt;Cmd</c> 占位符
    /// **就地换成真正的那只宠物**（一张牌可以指多只宠物，所以只能逐条换，不能全文替换）。
    /// 以前只有普通卡那条路做了替换，诅咒 / 先古卡 / 遗物 / 药水的 CanonicalVars 会把
    /// <c>__PETCMD__</c> 原样写进生成代码 → <c>CS0103</c>（用户实测：「一键构建」老是在编译这一步失败）。
    /// 现在统一在这里做，而且**找不到那只召唤物时退成「固定 0」的普通变量** ——
    /// 占位符绝不会再进生成代码（这种情况校验器本来就会报错拦住，这只是兜底）。
    /// </summary>
    internal static string VarDeclaration(EffectSpec e, Dictionary<EffectSpec, string>? map = null,
        CharacterProfile? p = null)
    {
        string decl = VarDeclarationCore(e, map, p);
        if (!decl.Contains(PetCmdPlaceholder, StringComparison.Ordinal)) return decl;
        string? petCls = p is null ? null : PetGen.Resolve(p, e.PetSummon)?.ClassName;
        if (petCls is not null) return PatchPetPlaceholder(decl, petCls);
        string name = VarNameOf(e, map);
        bool named = name != VarNameOf(e);
        string prefix = named ? Lit.Str(name) + ", " : "";
        // 连宠物都认不出来时退成「固定 0」的普通变量：收益是格挡 / 状态都声明 BlockVar，只有伤害声明 DamageVar。
        bool block = e.Kind == "PetSacrifice" && e.PetSacrificeGain != "Damage";
        return block ? $"new BlockVar({prefix}0m, ValueProp.Move)" : $"new DamageVar({prefix}0m, ValueProp.Move)";
    }

    private static string VarDeclarationCore(EffectSpec e, Dictionary<EffectSpec, string>? map = null,
        CharacterProfile? p = null)
    {
        string name = VarNameOf(e, map);
        bool named = name != VarNameOf(e);
        string prefix = named ? Lit.Str(name) + ", " : "";
        // 「数值公式」（用户要求：卡面要看到**算出来的数字**，不是「M/2」这种公式文本）：
        // 声明一个「现算预览值」的动态变量（见 FormulaVarsSource）—— 本体的 {Damage:diff()} 显示的是
        // PreviewValue，普通 DamageVar 只会拿固定基准值，填了公式就会在卡面骗人。
        if (e.UsesAmountFormula && p is not null && FormulaVarClassOf(e.Kind) is { } fxCls)
        {
            // 施加状态那个是泛型（变量名就是状态的类名）：ForgeFormulaPowerVar<VulnerablePower>(…)
            string fxOpen = e.Kind == "ApplyPower" ? $"{fxCls}<{e.PowerId}>" : fxCls;
            // 升级增量也交给变量（公式变量每次预览都会用公式覆盖 BaseValue，不把增量带上卡面就永远显示升级前的数字）。
            // 增量为 0 时**一个字符都不加**，让没升级增量的卡保持原来的生成文本。
            string fxUpgrade = e.UpgradeAmount != 0m ? ", " + Lit.Dec(e.UpgradeAmount) : "";
            return $"new {fxOpen}({prefix}static (card, target) => {FormulaPreviewExpr(p, e)}{fxUpgrade})";
        }
        return e.Kind switch
        {
            "Damage" => $"new DamageVar({prefix}{Lit.Dec(e.Amount)}, ValueProp.Move)",
            "Block" => $"new BlockVar({prefix}{Lit.Dec(e.Amount)}, ValueProp.Move)",
            "Draw" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            // 升级卡牌 / 预见：数值也是「几张牌」，共用本体的 CardsVar（键 = Cards，同名时自动起别名）
            "UpgradeCard" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            "Scry" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            // 刮削：数值 = 抽几张，共用本体的 CardsVar
            "ScrapeDraw" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            // 从三摞拿牌到手牌：数值 = 拿几张，共用本体的 CardsVar（卡面 {Cards:diff()} / 第二个 {Cards2:diff()}）。
            // 用户报的问题：这三种效果以前不声明变量，卡面只能写死数字；写成 {Value:diff()} 会在游戏里
            // **原样印出来**（截图上「从抽牌堆里拿取{Value:diff()}张牌」就是这么来的）。
            "TakeFromDraw" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            "TakeFromDiscard" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            "TakeFromExhaust" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            // 消耗 / 丢弃卡牌：数值 = 几张牌，同样给 CardsVar（和「升级卡牌 / 预览」一致：
            // 卡面写 {Cards:diff()} 就能显示、还能跟着升级增量走）
            "ExhaustCard" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            "DiscardCard" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            // 生成卡牌 / 变化卡牌：数值 = 生成 / 变化几张，同样给 CardsVar。
            // 用户报过「填了升级增量还是不变」——根因就是这两条以前不声明变量，
            // 升级增量在 OnUpgrade 里没有对应的 base.DynamicVars[...] 可写。
            "GenerateCard" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            "TransformCard" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            // 复制卡牌 / 重放卡牌：数值 = 选几张（本体的「二刀流 / 转化」用的也是 CardsVar，
            // 卡面 {Cards:diff()} 跟着升级变）
            "CopyCard" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            "ReplayCard" => $"new CardsVar({prefix}{Lit.Int(e.Amount)})",
            // 毒性爆发：数值 = 上几层中毒，用本体的 PowerVar<PoisonPower>（键 = PoisonPower）——
            // 本体 Outbreak 就是这么声明的，卡面 {PoisonPower:diff()} 与升级增量都跟着它走
            "Outbreak" => $"new PowerVar<PoisonPower>({prefix}{Lit.Dec(e.Amount)})",
            // 大限已至：伤害 = 目标身上的灾厄层数，用本体的计算三件套（跟三种「按生命值算的伙伴攻击」同一套写法）
            "TimesUp" => TimesUpVars(),
            "Energy" => $"new EnergyVar({prefix}{Lit.Int(e.Amount)})",
            // 透支能量：同样用 EnergyVar（数值 = 透支的点数；升级增量 / 别名都照常）
            "OverdraftEnergy" => $"new EnergyVar({prefix}{Lit.Int(e.Amount)})",
            "Heal" => $"new HealVar({prefix}{Lit.Dec(e.Amount)})",
            "HpLoss" => $"new HpLossVar({prefix}{Lit.Dec(e.Amount)})",
            "MaxHp" => $"new MaxHpVar({prefix}{Lit.Dec(e.Amount)})",
            "Gold" => $"new GoldVar({prefix}{Lit.Int(e.Amount)})",
            // 额外资源量：用本体的 StarsVar，这样卡面描述 {Stars:diff()} 会随升级变（用户报过「升级后还显示 2」）
            "ExtraResource" => $"new StarsVar({prefix}{Lit.Int(e.Amount)})",
            // 「增加额外资源量上限值」：普通 DynamicVar（键 = ResourceCap），升级增量走 UpgradeValueBy
            "RaiseResourceCap" => $"new DynamicVar({Lit.Str(name)}, {Lit.Dec(e.Amount)})",
            "ApplyPower" => $"new PowerVar<{e.PowerId}>({prefix}{Lit.Dec(e.Amount)})",
            // 临时增益：同样用那个状态的 PowerVar（卡面数字随升级变），只是打出去时施加的是生成的临时 Power
            "TempPower" => $"new PowerVar<{e.PowerId}>({prefix}{Lit.Dec(e.Amount)})",
            // 强化指定卡牌：用普通 DynamicVar（键 = Boost）—— 打出的其实是**生成的**强化 Power，
            // 而 PowerVar<T> 会去 ModelDb 里找 T 的预览值，普通 DynamicVar 更直接、也不会多一次模型查询。
            "BoostCard" => $"new DynamicVar({Lit.Str(name)}, {Lit.Dec(e.Amount)})",
            // 召唤伙伴：本体没有「宠物生命 / 宠物伤害」这两种变量类型，用带名字的普通 DynamicVar
            // （名字是 PetHp / PetDamage，卡面描述里的 {…:diff()} 与升级增量都按它走）
            "SummonPet" => $"new DynamicVar({Lit.Str(name)}, {Lit.Dec(e.Amount)})",
            "PetAttack" => $"new DynamicVar({Lit.Str(name)}, {Lit.Dec(e.Amount)})",
            // ===== 新增的那批宠物效果 =====
            // 「按生命值算的伙伴攻击」：必须用本体的**计算三件套**（见 CalcDamageVars），
            // 缺任何一件都会在 CalculatedVar.GetExtraVar() 处抛 KeyNotFoundException。
            "PetDamageByMaxHp" => CalcDamageVars(PetHpExpr("MaxHp")),
            "PetDamageByCurHp" => CalcDamageVars(PetHpExpr("CurrentHp")),
            "PetDamageByMissingHp" => CalcDamageVars(PetHpExpr("MissingHp")),
            "PetHeal" => $"new HealVar({prefix}{Lit.Dec(e.Amount)})",
            "PetLoseHp" => $"new HpLossVar({prefix}{Lit.Dec(e.Amount)})",
            "PetGainMaxHp" => $"new MaxHpVar({prefix}{Lit.Dec(e.Amount)})",
            "PetSacrifice" => PetSacrificeVarDecl(e, name),
            // 给伙伴施加状态：和普通「施加增益/减益」同名会撞（DynamicVarSet 按名字去重，重名直接抛异常），
            // 所以这里的变量名是 PetPower<PowerId>（回读也按这个名字把数值配回去）。
            "PetApplyPower" => $"new PowerVar<{e.PowerId}>({Lit.Str(name)}, {Lit.Dec(e.Amount)})",
            // 兜底：不认识的种类也用**唯一别名**（不能写死 "Value"，否则两条这种效果就会撞名 →
            // 本体 DynamicVarSet 抛 duplicate key 'Value' → 开新局直接崩（黑屏））
            _ => $"new DynamicVar({Lit.Str(name)}, {Lit.Dec(e.Amount)})",
        };
    }

    // ==================== 宠物效果（新增的那批）的动态变量 ====================

    /// <summary>
    /// 「伙伴的生命值」在**倍率 lambda 里**的写法（lambda 的第二参数就是那只宠物）。
    ///
    /// 为什么用 <c>pet</c> 这个名字：生成出来的 lambda 形如
    /// <c>delegate(CardModel card, Creature? _) { Creature? pet = &lt;Pet&gt;Cmd.Get(card.Owner); return (pet != null) ? pet.MaxHp : 0; }</c>，
    /// 三处（最大生命 / 当前生命 / 已损失）只有最后那个 <c>return</c> 表达式不同 —— 回读时也是按它区分三种 Kind。
    /// </summary>
    internal static string PetHpExpr(string mode) => mode switch
    {
        "CurrentHp" => "(decimal)pet.CurrentHp",
        "MissingHp" => "(decimal)(pet.MaxHp - pet.CurrentHp)",
        _ => "(decimal)pet.MaxHp",
    };

    /// <summary>三个「按生命值算的伙伴攻击」用的计算三件套：CalculationBase + ExtraDamage + CalculatedDamage。</summary>
    internal static string CalcDamageVars(string petValueExpr) =>
        "new CalculationBaseVar(0m), new ExtraDamageVar(1m), "
        + "new CalculatedDamageVar(ValueProp.Move).WithMultiplier(" + PetMultiplierLambda(petValueExpr) + ")";

    /// <summary>牺牲伙伴按生命值算格挡时的计算三件套：CalculationBase + CalculationExtra + CalculatedBlock。</summary>
    internal static string CalcBlockVars(string petValueExpr) =>
        "new CalculationBaseVar(0m), new CalculationExtraVar(1m), "
        + "new CalculatedBlockVar(ValueProp.Move).WithMultiplier(" + PetMultiplierLambda(petValueExpr) + ")";

    /// <summary>
    /// 「大限已至」的计算三件套：伤害 = **目标身上**的灾厄层数（本体 Time's Up 就是这么写的：
    /// <c>new CalculatedDamageVar(ValueProp.Move).WithMultiplier((_, target) =&gt; target?.GetPowerAmount&lt;DoomPower&gt;() ?? 0)</c>）。
    /// lambda 同样必须是静态的（见 <see cref="PetMultiplierLambda"/>），这里第二个参数就是**被打的目标**，
    /// 所以直接用 <c>target</c>，不用去查宠物。
    /// </summary>
    internal static string TimesUpVars() =>
        "new CalculationBaseVar(0m), new ExtraDamageVar(1m), "
        + "new CalculatedDamageVar(ValueProp.Move).WithMultiplier("
        + "delegate(CardModel _, Creature? target) { return (target != null) ? (decimal)target.GetPowerAmount<DoomPower>() : 0; })";

    /// <summary>
    /// 倍率 lambda。**必须是静态的**：本体 <c>CalculatedVar.cs:50-53</c> 一发现
    /// <c>multiplierCalc.Target is AbstractModel</c> 就抛 <c>InvalidOperationException("Multiplier calc must be static!")</c>；
    /// 写成匿名方法 <c>delegate(CardModel card, Creature? _)</c> 就不会捕获实例（<c>this</c>）→ Target 是 null。
    /// 里面只用参数 <paramref name="petValueExpr"/> 里的 <c>card</c>（那只宠物用 <c>&lt;Pet&gt;Cmd.Get(card.Owner)</c> 查），
    /// **绝不能**捕获任何局部变量 / 字段。
    /// </summary>
    internal static string PetMultiplierLambda(string petValueExpr) =>
        "delegate(CardModel card, Creature? _) { "
        + "Creature? pet = " + PetCmdExpr + ".Get(card.Owner); "
        + "return (pet != null) ? " + petValueExpr + " : 0; }";

    /// <summary>
    /// 倍率 lambda 里的宠物类名占位。写进 CanonicalVars 那一刻并不知道是哪只，
    /// 所以先写占位符，最后用 <see cref="PatchPetPlaceholder"/> 按**这条效果自己的**召唤物替换
    /// （一张牌可以指多只宠物，所以必须逐条替换，不能全文替换）。
    /// </summary>
    internal const string PetCmdPlaceholder = "__PETCMD__";

    private const string PetCmdExpr = PetCmdPlaceholder;

    /// <summary>把占位符换成真正的那只宠物的命令助手（<c>&lt;Pet&gt;Cmd</c>）。</summary>
    internal static string PatchPetPlaceholder(string code, string? petClassName)
    {
        if (!code.Contains(PetCmdPlaceholder, StringComparison.Ordinal)) return code;
        string cmd = string.IsNullOrWhiteSpace(petClassName) ? "" : petClassName.Trim() + "Cmd";
        return code.Replace(PetCmdPlaceholder, cmd.Length == 0 ? "PetCmd" : cmd);
    }

    /// <summary>
    /// 牺牲伙伴的收益变量：固定值走普通 BlockVar / DamageVar，按生命值算走计算三件套。
    ///
    /// 收益是「获得增益 / 减益」时**也走格挡那一套**（<c>BlockVar</c> / <c>CalculatedBlockVar</c>）：
    /// 本体只有 CalculatedDamage / CalculatedBlock 两套「计算变量」，没有「计算状态层数」这一种，
    /// 而层数本来就只是一个数字 —— 复用现成的这一套，卡面占位符（固定值 <c>{PetSacrificePower:diff()}</c>、
    /// 按生命值算 <c>{CalculatedBlock:diff()}</c>）与升级增量全都照旧生效，不用再造第三套变量。
    /// </summary>
    private static string PetSacrificeVarDecl(EffectSpec e, string name)
    {
        bool block = e.PetSacrificeGain != "Damage";
        if (e.PetSacrificeFormula == "Fixed")
            return block
                ? $"new BlockVar({Lit.Str(name)}, {Lit.Dec(e.Amount)}, ValueProp.Move)"
                : $"new DamageVar({Lit.Str(name)}, {Lit.Dec(e.Amount)}, ValueProp.Move)";
        string petExpr = e.PetSacrificeFormula == "CurHp"
            ? PetHpExpr("CurrentHp")
            : "(decimal)pet.MaxHp * " + Lit.Dec(e.PetSacrificeMultiplier);
        return block ? CalcBlockVars(petExpr) : CalcDamageVars(petExpr);
    }

    /// <summary>
    /// 这条效果「按生命值算收益」时用的是哪一套计算变量 —— 固定值返回 null。
    /// 生成时写进注释标记（<c>// CET:PetFormula=…</c>），回读时照着认回来，
    /// 不用去猜 lambda 里的表达式（宠物类名 / 公式都能认，宠物死了也照样认得出）。
    /// </summary>
    public static string? PetFormula(EffectSpec e)    {
        if (e.Kind is "PetDamageByMaxHp" or "PetDamageByCurHp" or "PetDamageByMissingHp")
            return PetFormulaOfKind(e.Kind);
        if (e.Kind != "PetSacrifice") return null;
        return e.PetSacrificeFormula switch
        {
            "Fixed" => "fixed",
            "CurHp" => "curhp",
            _ => "maxhp",
        };
    }

    private static string PetFormulaOfKind(string kind) => kind switch
    {
        "PetDamageByCurHp" => "curhp",
        "PetDamageByMissingHp" => "missinghp",
        _ => "maxhp",
    };

    /// <summary>
    /// 这条效果的生成代码标记（回读用）。写在这条效果的**第一行**上（单行，回读好抓）。
    ///
    /// 为什么要标记：三个「按生命值算的伙伴攻击」的生成代码几乎一模一样（只有倍率 lambda 里
    /// <c>pet.MaxHp</c> / <c>pet.CurrentHp</c> / <c>pet.MaxHp - pet.CurrentHp</c> 不同），
    /// 「牺牲伙伴」的收益公式（固定 / 最大生命×倍率 / 当前生命）也藏在 CanonicalVars 里 ——
    /// 回读时**不同步改就会静默丢配置**（本项目最容易踩的坑），所以生成时直接把这些信息写进注释。
    /// </summary>
    public static string MarkerText(EffectSpec e)
    {        string? formula = PetFormula(e);
        string kind = KindMarker(e);
        if (formula is null)
            // 给伙伴施加状态：把 PowerId 也写进标记（回读时不用去猜 Apply<T> 里的 T；
            // 下回合生效时会写成 ForgeDelayed<T>，也只认我们标记里的这个）
            return e.Kind == "PetApplyPower" && !string.IsNullOrWhiteSpace(e.PowerId)
                ? $"{kind} CET:PetPower={e.PowerId!.Trim()}"
                : kind;
        string mul = e.Kind == "PetSacrifice" && e.PetSacrificeFormula == "MaxHp"
            ? " CET:PetMul=" + Lit.Dec(e.PetSacrificeMultiplier)
            : "";
        // 牺牲伙伴选「获得增益 / 减益」时还要把状态类名写进标记 —— 光看 PowerCmd.Apply<T> 里的 T
        // 也能认出来，但那条语句同时被「施加增益 / 减益」用着，显式写全才能保证回读一对一还原。
        string petPower = e.Kind == "PetSacrifice" && e.PetSacrificeGain == "Power"
            && !string.IsNullOrWhiteSpace(e.PowerId)
            ? " CET:PetPower=" + e.PowerId!.Trim()
            : "";
        return $"{kind} CET:PetFormula={formula}{mul}{petPower}";
    }

    /// <summary>回读用的效果种类标记名（几种变体各自一个，回读时一对一还原）。</summary>
    internal static string KindMarker(EffectSpec e) => e.Kind switch
    {
        "PetDamageByMaxHp" or "PetDamageByCurHp" or "PetDamageByMissingHp" => "PetCalcAttack",
        "PetSacrifice" => e.PetSacrificeGain switch
        {
            "Damage" => "PetSacrificeDamage",
            "Power" => "PetSacrificePower",
            _ => "PetSacrificeBlock",
        },
        _ => e.Kind,
    };

    /// <summary>把这些效果里「按生命值算收益」的那条找出来（一张牌最多一条：本体的计算变量名是固定的）。</summary>
    internal static EffectSpec? CalculatedPetEffect(IEnumerable<EffectSpec> effects) =>
        effects.FirstOrDefault(x => PetFormula(x) is not null);

    /// <summary>这个效果的 CanonicalVars 声明里会不会出现宠物命令（&lt;Pet&gt;Cmd）—— 只有「按生命值算」的那几种会。</summary>
    /// <remarks>
    /// <c>"fixed"</c>（牺牲伙伴选「固定 N」）**不算**：那种收益声明的是普通 BlockVar / DamageVar
    /// （<c>new BlockVar("PetSacrificeBlock", 6m, …)</c>），既没有宠物命令、也**没有 CalculationBase** ——
    /// 把它算成「按生命值算」会让升级增量被写到 <c>base.DynamicVars.CalculationBase.UpgradeValueBy(…)</c> 上，
    /// 而那个变量根本没声明 → 本体的 DynamicVars 按名字取 → 抛 KeyNotFoundException。
    /// 这个异常发生在「卡牌被升级 / 牌组界面预览升级」时，表现是**牌组界面一片空白打不开**
    /// （用户实测报过：牺牲伙伴固定伤害 + 升级增量的卡，一开牌组就看不到牌）。
    /// </remarks>
    internal static bool CanonicalVarNeedsPetCmd(EffectSpec e) => PetFormula(e) is not null and not "fixed";

    /// <summary>
    /// 这条效果「需要**已经召唤出来**的那只宠物」：宠物不在场时它整条跳过（生成 <c>if (__pet is not null)</c>），
    /// 而且整张牌跟着打不出去 / 描红框。
    ///
    /// <c>SummonPet</c> **不算** —— 它自己就会召（没有也能打，Summon 内部新建一只）。
    /// </summary>
    internal static bool NeedsExistingPet(EffectSpec e) =>
        e.Kind is "PetAttack"
            or "PetDamageByMaxHp" or "PetDamageByCurHp" or "PetDamageByMissingHp"
            or "PetHeal" or "PetLoseHp" or "PetGainMaxHp" or "PetSacrifice" or "PetApplyPower"
            or "PetGuardOn" or "PetGuardOff";

    /// <summary>
    /// 这条效果会不会让**整张牌**在「伙伴还没上场」时打不出去（本体那套 <c>IsPlayable</c> + 描红框）。
    ///
    /// 和 <see cref="NeedsExistingPet"/> 的区别：那个回答的是「这条效果要不要拿到宠物这个变量、
    /// 拿不到就跳过这一条」；这个只回答「整张牌能不能打」。
    ///
    /// **「替主人承伤」开 / 关不算**：它本来就是「现场给伙伴挂个状态」这种可有可无的附加效果，
    /// 而且**「召唤伙伴 + 替主人承伤」是最常见的组合** —— 把整张牌卡在「必须先有一只已经上场的小八」上，
    /// 这张召唤牌就永远打不出去了。用户实测就是这个：卡牌「召唤小八替你挨打」在战斗里是红的、点不动
    /// （生成的代码里写着 `IsPlayable => xiaobaCmd.Get(base.Owner) != null`，而小八正是这张牌负责召的）。
    /// 挂守卫那段生成时本来就包了 `if (__pet is not null)`，所以伙伴不在场时它只是静默跳过，不会报错。
    /// </summary>
    internal static bool BlocksPlayWithoutPet(EffectSpec e) =>
        NeedsExistingPet(e) && e.Kind is not ("PetGuardOn" or "PetGuardOff");

    /// <summary>
    /// 「全部友方」这一档的过滤后缀（V0.2.132，需求：「全部友方（可以选择包不包括召唤物）」）。
    ///
    /// <para>默认（<c>AllAlliesExcludePets = false</c>）返回**空串** —— 拼出来的过滤条件与 V0.2.131
    /// 逐字节相同（<c>c =&gt; c.IsAlive &amp;&amp; c != base.Owner.Creature</c>），老存档的生成文本一个字节不变。</para>
    ///
    /// <para>勾了「不包括召唤物」才补一句 <c>&amp;&amp; c.PetOwner is null</c>
    ///（本体 <c>Creature.PetOwner</c> 非空 = 那是这个玩家召唤出来的宠物）。</para>
    /// </summary>
    internal static string AllyFilterSuffix(EffectSpec e) =>
        e.AllAlliesExcludePets ? " && c.PetOwner is null" : "";

    /// <summary>
    /// 「全体单位」那一档的守卫行（V0.2.132 新档）：<c>CombatState</c> 可能为 null（战斗外），先判一下。
    /// 和 AllAllies 用同一个取法（<c>base.Owner.Creature.CombatState</c>），卡牌 / 遗物 / 药水 / 状态四条链通用。
    /// </summary>
    internal const string AllUnitsGuardLine = "if (base.Owner.Creature.CombatState is not null)";

    /// <summary>
    /// 「全体单位」那一档的循环头：<c>CombatState.Creatures</c> = <c>_allies.Concat(_enemies)</c>
    ///（本体 CombatState.cs:71），也就是**两边所有单位**（含自己 / 队友 / 召唤物 / 敌人）；
    /// 再按 <c>IsAlive</c> 滤掉尸体。
    /// </summary>
    internal const string AllUnitsForeachLine =
        "foreach (Creature unit in base.Owner.Creature.CombatState.Creatures.Where(c => c.IsAlive).ToList())";

    /// <summary>
    /// 把「对某个生物做一件事」按作用对象展开（格挡 / 回复生命 / 失去生命 / 最大生命 现在支持打敌人）。
    /// Self = 自己；Enemy = 这张牌指定的目标（遗物/药水没有目标时退回「可打的第一个敌人」）；
    /// AllEnemies = 所有可打的敌人；RandomEnemies = 随机 N 个（N 可以 = X）；
    /// AllAllies = 同一边的玩家单位（排除自己，可选排除召唤物）；
    /// AllUnits = 场上两边所有存活单位（V0.2.132 新增）。
    /// </summary>
    private static void EmitPerCreature(CodeWriter w, EffectSpec e, bool useX,
        string selfExpr, string? cardTargetExpr, string enemiesExpr, Func<string, string> body)
    {
        switch (e.TargetSide)
        {
            case "AllEnemies":
                w.Open($"foreach (Creature foe in {enemiesExpr})");
                w.Line(body("foe"));
                w.Close();
                break;

            case "AllUnits":
                // 全体单位（V0.2.132）：自己 + 队友 + 召唤物 + 敌人，只要活着就各来一次。
                // ⚠ 战斗状态从 selfExpr 取（**不要**写死 base.Owner.Creature）：三条链传进来的 selfExpr
                // 都是「那个生物的表达式」—— 卡牌 / 遗物是 base.Owner.Creature，自定义状态是 base.Owner
                //（状态钩子里 base.Owner 本身就是 Creature，写 base.Owner.Creature 会 CS1061）。
                w.Open($"if ({selfExpr}.CombatState is not null)");
                w.Open($"foreach (Creature unit in {selfExpr}.CombatState.Creatures.Where(c => c.IsAlive).ToList())");
                w.Line(body("unit"));
                w.Close();
                w.Close();
                break;

            case "RandomEnemies":
                w.Line($"List<Creature> foes = {enemiesExpr}.ToList();")
                 // 循环变量用 __ 前缀：外面可能还套着「生效次数」的 for (int i…)，同名会 CS0136
                 .Open($"for (int __foeIdx = 0; __foeIdx < {RepeatExpr(e, useX)} && foes.Count > 0; __foeIdx++)")
                 .Line("Creature foe = base.Owner.RunState.Rng.CombatTargets.NextItem(foes);");
                if (!e.AllowDuplicates) w.Line("foes.Remove(foe);");
                w.Line(body("foe"));
                w.Close();
                break;

            case "Enemy" when cardTargetExpr is not null:
                // 卡牌：用玩家选中的那个目标；没选（不该发生）就什么都不做
                w.Open($"if ({cardTargetExpr} is not null)")
                 .Line(body(cardTargetExpr))
                 .Close();
                break;

            case "Enemy":
                // 遗物 / 药水：没有「玩家选的目标」，取可打的第一个敌人
                w.Open("")
                 .Line($"Creature? foe = {enemiesExpr}.FirstOrDefault();")
                 .Open("if (foe is not null)")
                 .Line(body("foe"))
                 .Close()
                 .Close();
                break;

            case "Ally" when cardTargetExpr is not null:
                // 指定队友（用户要求）：本体 TargetType.AnyAlly 会弹目标选择，选中的那个队友就在
                // cardPlay.Target 里 —— 和「指定敌人」是**同一个字段**，只是这张牌的 TargetType 不同。
                // 再自查一次「不是自己、且和我同一边」：本体 AnyAlly 的定义就是「任意队友（不含自己）」。
                w.Open($"if ({cardTargetExpr} is not null && {cardTargetExpr} != base.Owner.Creature"
                     + $" && {cardTargetExpr}.Side == base.Owner.Creature.Side)")
                 .Line(body(cardTargetExpr))
                 .Close();
                break;

            case "Ally":
                // 遗物 / 药水没有「玩家选中的目标」：退回自己（校验器会提醒这条只对卡牌有意义）
                w.Line(body(selfExpr));
                break;

            case "AllAllies":
                // 全部队友 = 同一边（战斗状态里的 PlayerCreatures）里除自己以外的存活者。
                // 本体「全体友方」用的就是 combatState.PlayerCreatures（本体卡 BladeSymphony 那种）。
                // 用 base.Owner.Creature.CombatState 而不是 base.CombatState：卡牌 / 遗物两条链都通用。
                // V0.2.132：勾了「不包括召唤物」时在过滤条件末尾补一句（默认档拼出来与以前逐字节相同）。
                w.Open("if (base.Owner.Creature.CombatState is not null)")
                 .Open("foreach (Creature ally in base.Owner.Creature.CombatState.PlayerCreatures"
                     + ".Where(c => c.IsAlive && c != base.Owner.Creature" + AllyFilterSuffix(e) + ").ToList())")
                 .Line(body("ally"))
                 .Close()
                 .Close();
                break;

            default:
                w.Line(body(selfExpr));
                break;
        }
    }

    /// <summary>
    /// 这套「伙伴攻击」打的是**敌人**（attacker 是宠物），所以卡牌要变成需要选目标的那种。
    /// 三个按生命值算的伙伴攻击同样如此（Targeting(cardPlay.Target) / TargetingAllOpponents）。
    /// </summary>
    internal static bool PetAttackKind(string kind) =>
        kind is "PetAttack" or "PetDamageByMaxHp" or "PetDamageByCurHp" or "PetDamageByMissingHp";

    private static bool NeedsTargetNullCheck(CardSpec c) =>
        // 「指定队友」同样要用 cardPlay.Target（本体 AnyAlly 选中的那个队友就在这个字段里），
        // 所以那张牌也要在本体给出目标之前先判空。
        c.Effects.Any(e => e.TargetSide is "Enemy" or "Ally"
            && (e.Kind is "Damage" or "ApplyPower" or "TempPower" or "Stun" or "Block" or "Heal" or "HpLoss" or "MaxHp"
                || PetAttackKind(e.Kind)
                || (e.Kind == "PetSacrifice" && e.PetSacrificeGain == "Damage")));

    // ==================== 卡牌 ====================
    /// <summary>
    /// 一张卡的 C# 源码。
    /// <paramref name="index"/> 只用于「按列表下标」的老式编号，**不要**用它算类名 ——
    /// 初始的打击 / 防御固定排在列表最前面，列表下标和「自有卡序号」会差 2
    /// （用户报过：没填类名的卡，文件叫 SevenCard9.cs 里却声明成 SevenCard11，
    ///  卡池引用的 SevenCard9 找不到 → 编译报 CS0246）。统一走
    /// <see cref="Naming.CardClassName(CharacterProfile, CardSpec)"/>，和文件名 / 卡池 / 本地化一致。
    /// </summary>
    /// <summary>
    /// 自定义**诅咒**的源码。
    ///
    /// 和普通卡的区别（全部照本体的诅咒写：Decay / Doubt / Shame / BadLuck / Writhe）：
    ///   · 构造函数 <c>base(&lt;费用&gt;, CardType.Curse, CardRarity.Curse, TargetType.None)</c> ——
    ///     默认费用 -1（打不出去）；用户在配置里填 ≥0 就用他的值，并且**不再**强制「不能被打出」
    ///     （用户要求：诅咒 / 先古 / 状态三类都能调费用。填 ≥0 = 这张牌能打出去，但效果仍然写在
    ///     <c>OnTurnEndInHand</c> 里，所以「打出去」本身不做事，只是能把它从手里处理掉）；
    ///   · <c>MaxUpgradeLevel => 0</c> —— 诅咒不能升级；
    ///   · 关键字固定带「不能被打出」，固有 / 永恒由用户勾（本体「厄运」= 永恒 + 不能被打出）；
    ///   · 效果写在 <c>OnTurnEndInHand</c> 里，并且要一起声明 <c>HasTurnEndInHandEffect => true</c>
    ///     （本体的注释写得很清楚：覆写 OnTurnEndInHand 必须同时把这个属性改成 true，否则根本不会被调用）；
    ///   · <c>VisualCardPool</c> 指到本体的诅咒卡池 —— 卡框 / 牌堆底色按本体诅咒显示（灰色），
    ///     但模型本身注册在**你自己的卡池**里（本体的硬规则：每张卡都必须属于某个卡池，
    ///     否则 <c>ModelDb.Preload</c> 直接抛「Card … is not in any card pool」，模组加载失败）。
    /// </summary>
    public static string CurseSource(CharacterProfile p, CardSpec c, int index)
    {
        _ = index;
        var n = Naming.From(p);
        string cls = n.CardClassName(p, c);

        var w = new CodeWriter();
        w.Line("// <auto-generated> 自定义诅咒 </auto-generated>");
        if (c.HasCustomDescription)
            w.Line($"// CET:CustomDescReplace={(c.CustomDescriptionReplaces ? 1 : 0)} CET:CustomDescription={EscapeMarker(c.CustomDescription)}");
        // V0.2.136：诅咒也照写这两行（校验器会提示「升不了级、永远不会生效」，但**不写**的话
        // 「生成 → 回读」会把关键词搬到普通那一栏 —— 实测：诅咒的「升级后获得」恢复成了「一直都有」）
        if (c.UpgradeCustomKeywordsAny)
            EmitUpgradeKeywordMarkers(p, c, w);
        w.Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {cls} : CardModel")
         .Line("// 诅咒不能升级（本体所有诅咒都是 MaxUpgradeLevel => 0）")
         .Line("public override int MaxUpgradeLevel => 0;")
         .Line()
         .Line("// 不进战斗里的随机生成：本体那些「随机生成一张牌」的效果不会甩出你的诅咒")
         .Line("public override bool CanBeGeneratedInCombat => false;")
         .Line();
        // 卡框：默认用本体的诅咒卡池（灰色）；在「诅咒 / 先古卡」页给诅咒设了边框颜色就用生成的外观池
        string? curseStylePool = p.CurseStyle.Any ? n.CurseStylePoolClass : null;
        if (curseStylePool is null)
            w.Line("// 外观按本体的诅咒卡池显示（灰色卡框 / 牌堆底色），模型本身注册在你自己的卡池里")
             .Line("// —— 本体的硬规则：每张卡都必须属于某个卡池，否则 Preload 会抛「is not in any card pool」")
             .Line("public override CardPoolModel VisualCardPool => ModelDb.CardPool<CurseCardPool>();");
        else
            w.Line("// 外观用你在「诅咒 / 先古卡」页给诅咒设的那个外观池（卡框颜色），模型本身注册在你自己的卡池里")
             .Line($"public override CardPoolModel VisualCardPool => ModelDb.CardPool<{curseStylePool}>();");
        w.Line();

        // 关键字：默认固定「不能被打出」+ 用户勾的（固有 / 永恒…）。
        // 费用 ≥ 0 的诅咒是**能打出去的**（用户要求：三类牌的费用都能调）→ 这时不再强制「不能被打出」，
        // 用户想让它照样打不出去就自己勾；费用 -1（默认）= 本体那套打不出去的诅咒。
        var kws = new List<string>();
        if (c.Cost < 0) kws.Add("Unplayable");                       // 默认（-1 费）：本体那套打不出去的诅咒
        foreach (string k in c.KeywordList)
            if (k != "Unplayable" || c.Cost >= 0) kws.Add(k);        // 费用 ≥0 时用户勾了就照用（能打出去的那张由他自己决定）
        if (c.Cost < 0)
            w.Line("// 诅咒一律「不能被打出」；固有 / 永恒由你在「诅咒」页勾（本体「厄运」= 永恒 + 不能被打出）");
        else
            w.Line($"// 这张诅咒的费用是 {c.Cost}（≥0 = 能打出去），所以**不**强制「不能被打出」；" +
                   "想让它照样打不出去，请在下面勾上「不能被打出」。");
        w.Line($"public override IEnumerable<CardKeyword> CanonicalKeywords => [{string.Join(", ", kws.Select(k => "CardKeyword." + k))}];");

        var curseVars = VarNamesOf(c.Effects);
        w.Line()
         .Line("protected override IEnumerable<DynamicVar> CanonicalVars =>")
         .Line("[");
        foreach (var e in c.Effects.Where(x => !HasNoDynamicVar(x))) w.Line($"    {VarDeclaration(e, curseVars, p)},");
        w.Line("];");

        // 悬停说明（描述里提到的状态 / 自定义关键词）
        w.Raw(HoverTipsOverride(c.Effects, isPublic: false, isCard: true,
            extraTips: KeywordGen.TipsFor(p, c.CustomKeywordList), owner: p,
            upgradedKeywordTips: UpgradeKeywordTips(p, c)));

        w.Line()
         .Line($"public {cls}() : base({c.Cost}, CardType.Curse, CardRarity.Curse, TargetType.None) {{ }}");

        if (c.Effects.Count > 0)
        {
            w.Line()
             .Line("// 本体给诅咒用的钩子：在你的回合结束时，如果这张牌还在你的手牌里就执行")
             .Line("// （本体 Decay / Doubt / Shame / BadLuck 全是这个写法；覆写它的同时必须把上面那个属性改成 true）")
             .Line("public override bool HasTurnEndInHandEffect => true;")
             .Line()
             .Open("protected override async Task OnTurnEndInHand(PlayerChoiceContext choiceContext)");
            // 概率生效：同一张诅咒的所有效果共用一次掷骰（和卡牌 / 遗物一致）
            var curseChance = ChanceSlices(c.Effects);
            if (curseChance.Count > 0) w.Line(ChanceRollLine());
            int petAllSeq = 0;
            foreach (var e in c.Effects)
            {
                string? cond = EffectConditionGuard(e, CondCtx.Relic, chanceSlices: curseChance);
                if (cond is not null)
                {
                    w.Line($"// 条件（只对「{EffectCatalog.FindKind(e.Kind).Display}」这条效果）：{ConditionText(e.Condition)}（不满足时这条效果不触发）");
                    w.Open(cond);
                }
                string? petAllGroup = PetGen.IsAll(e.PetSummon) && e.Kind == "SummonPet" ? "c" + petAllSeq++ : null;
                EmitCurseHookEffect(w, p, e, curseVars, petAllGroup);
                if (cond is not null) w.Close();
            }
            w.Close();
        }

        if (c.CurseRemoveAfterCombat)
        {
            w.Line()
             .Line("/// <summary>战斗结束时它还在牌组里，就自己消失（本体诅咒「罪恶 Guilty」的做法）。</summary>")
             .Open("public override async Task AfterCombatEnd(CombatRoom room)")
             .Open("if (base.Pile is not null && base.Pile.Type == PileType.Deck)")
             .Line("await CardPileCmd.RemoveFromDeck(this);")
             .Close()
             .Close();
        }

        w.Close();
        return w.ToString();
    }

    /// <summary>
    /// 诅咒的「在你的回合结束时，如果这张牌在你的手牌中」效果 —— 直接复用**遗物**那套语句：
    /// 遗物和诅咒都没有 <c>CardPlay</c>（没有「这张牌打出去时玩家选中的目标」），
    /// 能用的语句完全一样。效果里的「指定敌人」按遗物同样的约定取可打的第一个敌人；
    /// 不支持的种类会写一行注释说明（不会静默丢掉）。
    /// </summary>
    internal static void EmitCurseHookEffect(CodeWriter w, CharacterProfile p, EffectSpec e,
        Dictionary<EffectSpec, string>? varMap = null, string? petAllGroup = null) =>
        EmitRelicEffect(w, p, e, hasContext: true, varMap, roomVar: null, petAllGroup);

    public static string CardSource(CharacterProfile p, CardSpec c, int index)
    {
        // 「数值公式 / 次数类公式 / 条件数值公式」（用户要求⑦）求值都要 __fgPlayer / __fgSelf，
        // 而这些公式会被埋在很深的发射器里（效果体 / 条件守卫 / 各个钩子）——
        // 所以整张卡生成期间都把「当前是哪张卡」放在那个生成期变量里（见 _formulaOwner）。
        CharacterProfile? prevFormulaOwner = _formulaOwner;
        _formulaOwner = p;
        try
        {
            return CardSourceCore(p, c, index);
        }
        finally
        {
            _formulaOwner = prevFormulaOwner;
        }
    }

    private static string CardSourceCore(CharacterProfile p, CardSpec c, int index)
    {
        _ = index;
        var n = Naming.From(p);
        string cls = n.CardClassName(p, c);
        string targetType = ResolveTargetType(c);
        // 「生成调试日志」（V0.2.142）用的临时变量序号每次生成一个源文件都从头开始 ——
        // 「同一份存档生成两次文本逐字节相同」是既有红线（见 DebugLogGen._seq）。
        DebugLogGen.Reset();

        var w = new CodeWriter();
        w.Line("// <auto-generated> 自定义卡牌 </auto-generated>");
        // 卡牌自定义描述：单写一行标记（换行转义成 \n），回读时按它还原。
        // 为什么不从 cards.json 里认：那张表里的描述是「自动描述 + 你写的那段」拼起来的，
        // 回读时看不出从哪里开始是用户写的（自动描述要用整个存档才能重算出来）。
        if (c.HasCustomDescription)
            w.Line($"// CET:CustomDescReplace={(c.CustomDescriptionReplaces ? 1 : 0)} CET:CustomDescription={EscapeMarker(c.CustomDescription)}");
        // 「升级后的自定义描述」（同一行还有一段，回读时按 CET:UpgradedCustomDescription 认）
        if (c.HasUpgradedCustomDescription)
            w.Line($"// CET:UpgradedCustomDescription={EscapeMarker(c.UpgradedCustomDescription)}");
        // V0.2.136「升级后获得 / 失去的自定义关键词」：**只在真填了才写这两行** ——
        // 老存档一个字符都不多（红线①）。为什么必须写标记而不是靠反推：
        // 这两栏只影响显示（描述那行 + ExtraHoverTips 的条件分支），生成代码里没有任何
        // 「按自定义关键词判定」的逻辑可认，而 cards.json 的描述又被 {IfUpgraded} 包过一层 ——
        // 从描述反推要再写一套 IfUpgraded 解析 + 靠中文名对回本地化键，歧义面比一行标记大得多。
        // 存的是**规范化后的本地化键**（和界面勾选、生成时用的同一套，见 KeywordGen.NormalizeReferences）。
        // ⚠ 升不了级的牌（诅咒 / 状态牌）也照写：校验器会提示「永远不会生效」，但跳过不写会让
        //   「生成 → 回读」把关键词搬到普通那一栏（实测：诅咒的「升级后获得」恢复成了「一直都有」）。
        if (c.UpgradeCustomKeywordsAny)
            EmitUpgradeKeywordMarkers(p, c, w);
        w.Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {cls} : CardModel")
         .Line("protected override IEnumerable<DynamicVar> CanonicalVars =>")
         .Line("[");
        var cardVars = VarNamesOf(c.Effects);
        // 需求⑩「卡牌时机」：带这个条件的效果**不写进 OnPlay**，而是各自挂到本体的钩子上（见 EmitCardTimingHooks）。
        // 这里先把效果分好组，并把「代码里出现的顺序」定成：OnPlay 的效果在前、各时机块在后。
        // 变量声明（CanonicalVars）与升级增量都按这个顺序写 —— 回读（ProjectRecovery）也是照同一个顺序
        // 把各方法体拼起来解析的，变量（NextVar 按顺序配对）才不会串到别的效果上。
        // 没有这个条件的存档：下面三项全都等于原来的 c.Effects，生成结果一个字符都不变。
        var timingGroups = CardTimingGroups(c.Effects);
        bool hasTiming = timingGroups.Count > 0;
        // 「将此牌放回手牌」（ReturnSelfToHand）：同样**不写进 OnPlay** —— OnPlay 跑完本体才把打出的牌
        // 放进弃牌堆，在 OnPlay 里搬会被那一步覆盖掉。它单独生成一个 AfterCardPlayedLate 钩子
        //（本体「回响 MakeItSo」用的就是这个钩子），见 EmitSelfReturnHook。
        bool hasSelfReturn = c.Effects.Any(e => IsSelfReturn(e) && !IsInertZero(e));
        // 「抽到这张牌时它本场战斗费用 -N」同理：写在卡自己的 AfterCardDrawn 钩子里（见 EmitSelfDrawHook）
        bool hasSelfDraw = c.Effects.Any(e => IsSelfDrawCost(e) && !IsInertZero(e));
        bool hasCardHooks = hasTiming || hasSelfReturn || hasSelfDraw;
        IReadOnlyList<EffectSpec> onPlayEffects = hasCardHooks
            ? c.Effects.Where(e => !IsCardTiming(e.Condition) && !IsSelfReturn(e) && !IsSelfDrawCost(e)).ToList()
            : c.Effects;
        IReadOnlyList<EffectSpec> varOrder = hasCardHooks
            ? onPlayEffects.Concat(timingGroups.SelectMany(g => g.Effects)).ToList()
            : c.Effects;
        cardVars = VarNamesOf(varOrder);
        // 「按生命值算」的宠物效果：倍率 lambda 里要写 <Pet>Cmd.Get(card.Owner)，但 CanonicalVars
        // 声明那一刻还不知道是哪只（一张牌可以同时指向两只不同的宠物）→ 先写占位符，
        // 这里按**每条效果自己的**召唤物逐个替换（不能全文替换，否则多只宠物会串）。
        bool needsPetCmd = varOrder.Any(x => !HasNoDynamicVar(x) && CanonicalVarNeedsPetCmd(x));
        bool anyPetCmdMissing = varOrder.Any(x => CanonicalVarNeedsPetCmd(x) && PetGen.Resolve(p, x.PetSummon) is null);
        foreach (var e in varOrder.Where(x => !HasNoDynamicVar(x)))
            w.Line($"    {VarDeclaration(e, cardVars, p)},");
        // ⚠ V0.2.130：原来这里在 c.ShowPileCounts 为真时声明三个 ForgePileCountVar
        //   （{DrawPile} / {DiscardPile} / {ExhaustPile}）—— 用户要求整块去掉，连变量声明一起删。
        w.Line("];");
        if (needsPetCmd && anyPetCmdMissing)
            w.Line("// ⚠ 上面这条「按生命值算」的宠物效果没有可用的召唤物：到「召唤物」页添加一只并勾上「启用」"
                + "（校验器会把这种配置拦住，不会真的生成出来）");

        // 本体卡标签（CardTag）：行为无关的元数据，别的模型拿它查牌。
        // 最关键的就是 Strike / Defend —— 本体那些「升级你的初始打击 / 防御」「只对打击牌生效」的
        // 遗物 / 事件 / 卡牌都是按 CardTag 找牌的（妮欧的护符 NeowsTalisman、叶敷剂 LeafyPoultice、
        // 大胶囊 LargeCapsule、幽灵种子 GhostSeed、完美打击 PerfectedStrike…），不标它们就找不到你的牌。
        if (c.TagList.Count > 0)
        {
            w.Line()
             .Line("// 本体卡标签（CardTag）：别的模型按它查牌（例：升级初始打击 / 防御的遗物）")
             .Line($"protected override HashSet<CardTag> CanonicalTags => new HashSet<CardTag> {{ {string.Join(", ", c.TagList.Select(t => "CardTag." + t))} }};");
        }
        // 本体的「防御」牌都有这个（本体用它判断挡格相关的表现）
        if (c.TagList.Contains("Defend"))
            w.Line("public override bool GainsBlock => true;");

        // 卡牌关键字：消耗 / 虚无 / 固有 / 保留 / 不能被打出 / 奇巧
        var keywords = c.KeywordList;
        if (keywords.Count > 0)
        {
            string kw = string.Join(", ", keywords.Select(k => "CardKeyword." + k));
            w.Line()
             .Line("// 卡牌关键字（本体 CardKeyword）")
             .Line($"public override IEnumerable<CardKeyword> CanonicalKeywords => [{kw}];");
        }

        // 临时保留 / 临时奇巧：现在由「给予卡牌关键词」效果实现（数值 0 = 这张牌自己 + 勾「是否为临时关键词」），
        // 卡牌级的那两个勾选框已按用户要求取消。

        // X 费用（本体储君「天际钻头」/ 亡灵契约师「挽歌」这种）：本体用 HasEnergyCostX 表示，
        // 构造函数里费用写 0，实际消耗由本体结算，X 值用 ResolveEnergyXValue() 取。
        //
        // V0.2.131：界面上那三个「= X」勾选框没了，改成在费用框 / 额外资源量费用框里写 X / Y ——
        // 判据统一走 IsCostX / IsStarCostX（老字段照旧认，所以老存档生成文本逐字不变）。
        bool costIsX = IsCostX(c);
        bool starCostIsX = IsStarCostX(c);
        bool usesX = c.Effects.Any(e => e.UsesX);
        bool xIsStar = starCostIsX && !costIsX;
        // V0.2.131：「额外资源量费用」框里写的原文（数字 / 生成期式子 / Y）——
        // 生成出来的只有 `CanonicalStarCost => N` 或 `HasStarCostX => true`，反推不回原文，
        // 而回读时旧口径会**凭空补一条负数效果**（那条效果会多出一段空代码 + 悬停说明）→ 幂等会破。
        // 老存档（这个框是空的）不会走这里，所以生成文本一个字都不变。
        if (!string.IsNullOrWhiteSpace(c.StarCostFormula))
            w.Line("// CET:StarCostFormula=" + EscapeMarker(c.StarCostFormula));
        if (costIsX || starCostIsX || usesX)
        {
            w.Line();
            if (costIsX)
                w.Line("// 费用为 X：打出时消耗全部能量，X = 消耗掉的能量（本体 Whirlwind / 天际钻头 的做法）")
                 .Line("protected override bool HasEnergyCostX => true;");
            if (starCostIsX)
                w.Line("// 额外资源量费用为 X：打出时消耗全部额外资源量，X = 消耗掉的资源量（本体 Stardust 的做法）")
                 .Line("public override bool HasStarCostX => true;");
        }

        // 额外资源量花费：负数效果 = 打出这张牌需要的额外资源量（或用户在「额外资源量费用」框里显式写的那个数）。
        // 直接复用本体的星星费用机制，本体就会在资源不足时禁止打出
        // （UnplayableReason.StarCostTooHigh），并把卡面费用数字显示成红色。
        int starCost = StarCostOf(p, c);
        if (starCost > 0 && !starCostIsX)
        {
            w.Line()
             .Line("// 额外资源量花费（本体星星费用：不够时本体自带判定禁止打出）")
             .Line($"public override int CanonicalStarCost => {starCost};");
        }

        // 条件选项（每一条效果各自一份）：
        // 「不满足时打不出去」→ 汇进本体 IsPlayable（Clash / GrandFinale 的做法），这些条件全都满足才能打；
        // 「能打出但这条效果不生效」→ 只把这一条效果包在 if 里，别的效果照常执行。
        // 老存档用的是「整张牌一个条件」（c.Condition），也一起算进来（只能有一个 IsPlayable，所以必须合并写）。
        var gateConds = new List<string>();
        var glowConds = new List<string>();
        // 宠物类效果：一张卡只要有「需要已召唤宠物」的效果（SummonPet 不算 —— 它自己会召），
        // 就生成两句守卫：没伙伴时这张牌打不出去 + 描红框提示（本体 Osty 的牌就是这么做的：
        // BoneShards / Poke / Sacrifice … 全是 ShouldGlowRedInternal => base.Owner.IsOstyMissing）。
        // 这里的「有没有伙伴」= <Pet>Cmd.Get(base.Owner) != null（Get 会判活，死了也算没有）。
        //
        // 注意这里分两份：
        //   · petNeeds —— 需要**宠物这个变量**（OnPlay 开头查一次，逐条效果再判一次 null 跳过）；
        //   · petGates —— 会让**整张牌打不出去**的那些（见 BlocksPlayWithoutPet）。
        // 「替主人承伤」开 / 关只在 petNeeds 里：它本来就是可有可无的附加效果，
        // 而「召唤伙伴 + 替主人承伤」是最常见的组合 —— 把整张牌卡在「必须先有小八」上，
        // 这张召唤牌就永远打不出去了（用户实测：「小八替你挨打」那张牌是红的、点不动）。
        var petNeeds = new List<string>();
        var petGates = new List<string>();
        // 「这张牌自己会先把这只召出来」的宠物：那张牌不该再被「必须先有这只」卡住打不出去。
        // 例：一张「召唤小八，然后让它攻击」的牌 —— 第一次打出时小八还不存在，
        // 如果按「已有伙伴」判定可打出，这张牌永远打不出去（同一个坑的另一半）。
        var summonedHere = new HashSet<string>(StringComparer.Ordinal);
        foreach (var e in c.Effects.Where(x => x.Kind == "SummonPet"))
            foreach (var d in PetGen.ResolveMany(p, e.PetSummon)) summonedHere.Add(d.ClassName);
        // 注意这里遍历的是 onPlayEffects：卡牌时机的宠物效果挂在钩子里，不该在 OnPlay 上加伙伴守卫 /
        // 查询变量（`Creature? __pet = …` 是在 OnPlay 开头声明的，钩子里用不到）。
        foreach (var e in onPlayEffects)
        {
            if (!NeedsExistingPet(e)) continue;
            var defs = PetGen.ResolveMany(p, e.PetSummon);
            if (defs.Count == 0) continue;   // 校验器会拦住（找不到召唤物），这里不生成取不到的类名
            // 「全部召唤物」：只要**任意一只**在场，这张牌就能打（每只各自再判一次在场，见逐只展开那里）
            string need = defs.Count == 1
                ? $"{defs[0].ClassName}Cmd.Get(base.Owner) != null"
                : "(" + string.Join(" || ", defs.Select(d => $"{d.ClassName}Cmd.Get(base.Owner) != null")) + ")";
            if (!petNeeds.Contains(need, StringComparer.Ordinal)) petNeeds.Add(need);
            // 真的会卡住「打不出去」的才进 petGates：效果自己不需要已有宠物（承伤开关）、
            // 或者这张牌自己就会把它召出来的，都不算
            bool gated = BlocksPlayWithoutPet(e) && !defs.Any(d => summonedHere.Contains(d.ClassName));
            if (gated && !petGates.Contains(need, StringComparer.Ordinal)) petGates.Add(need);
        }
        // 条件都用「满足才算数」的写法（c.Condition 生成出来的就是「满足」表达式），
        // 所以伙伴守卫也用 != null，一起 && 起来即可：没伙伴 → 打不出去 / 描红框。
        gateConds.AddRange(petGates);
        glowConds.AddRange(petGates);
        // 「指定敌人」这种条件要等玩家选了目标才知道结果，写不进 IsPlayable / 描金边（那时还没选目标）。
        // 这类条件只在效果那一层生效（包住对应的效果）。
        static bool NeedsPlayTarget(ConditionSpec? c) =>
            c is not null && c.NeedsTarget && string.Equals(c.Target, "Enemy", StringComparison.OrdinalIgnoreCase);
        if (c.Condition is not null && !c.Condition.IsNone)
        {
            string legacy = ConditionExpr(c.Condition, CondCtx.Card);
            if (NeedsPlayTarget(c.Condition))
                w.Line($"// 条件：{ConditionText(c.Condition)}（作用对象是「指定敌人」→ 只能用在效果上，打不出判定/描金边里忽略）");
            else
            {
                glowConds.Add(legacy);
                if (c.Condition.UnplayableWhenUnmet) gateConds.Add(legacy);
                w.Line($"// 条件：{ConditionText(c.Condition)}（老存档的「整张牌」条件；"
                     + (c.Condition.UnplayableWhenUnmet ? "不满足时这张牌打不出去）" : "不满足时整张牌的效果都不生效）"));
            }
            // 「整张牌」这个条件的数值写了公式时（用户要求⑦）：IsPlayable / 描金边里只剩算完的表达式，
            // 从它反推不回公式 —— 写一行**整张牌专用**的标记（不用效果那一行的 CET:CondFull，
            // 不然回读会把「某条效果的条件」认成「整张牌的条件」，反过来也一样）。
            if (c.Condition.UsesAnyFormula)
                w.Line("// CET:CardCondFull=" + EscapeMarker(ConditionMarker(c.Condition)));
        }
        foreach (var e in c.Effects)
        {
            if (e.Condition is null || e.Condition.IsNone) continue;
            // 卡牌时机（需求⑩）：这一类不是「打出时算一个 bool」，写不进 IsPlayable / 描金边
            //（它挂在本体的钩子上，见 EmitCardTimingHooks），所以这里跳过、由生成钩子那段写自己的注释。
            if (IsCardTiming(e.Condition)) continue;
            // 斩杀（Fatal）：判的是「上一条攻击有没有把目标打死」，只有**打出之后**才知道结果 ——
            // 写不进 IsPlayable / 描金边（那两个地方还没有 __lastAttack，而且语义也不对），
            // 所以只包住那条效果（和「指定敌人」那类条件一样）。
            // 条件数值写了公式、而且公式里引用了「打出的目标」时同理（那两处没有 cardPlay）。
            bool needsPlayTarget = NeedsPlayTarget(e.Condition) || e.Condition.Kind == "Fatal"
                || ConditionFormulaNeedsPlayTarget(p, e.Condition);
            string expr = ConditionExpr(e.Condition, CondCtx.Card, inOnPlay: true);
            if (!needsPlayTarget)
            {
                glowConds.Add(ConditionExpr(e.Condition, CondCtx.Card));
                if (e.Condition.UnplayableWhenUnmet) gateConds.Add(ConditionExpr(e.Condition, CondCtx.Card));
            }
            w.Line($"// 条件（只对「{EffectCatalog.FindKind(e.Kind).Display}」这条效果）：{ConditionText(e.Condition)}"
                 + (e.Condition.Kind == "Fatal"
                        ? " → 上一次攻击把目标打死才算（写不进「打不出去」，只能包住这条效果）"
                        : needsPlayTarget
                            ? " → 打出的目标满足才算（写不进「打不出去」，只能包住这条效果）"
                            : e.Condition.UnplayableWhenUnmet ? " → 不满足时这张牌打不出去" : " → 不满足时这条效果不生效"));
        }
        if (glowConds.Count > 0)
        {
            if (gateConds.Count > 0)
                w.Line($"protected override bool IsPlayable => {string.Join(" && ", gateConds.Select(x => $"({x})"))};");
            // 条件都满足时给牌描金边（本体「取回 / 死亡之门」就是这么提示玩家的）
            w.Line($"protected override bool ShouldGlowGoldInternal => {string.Join(" && ", glowConds.Select(x => $"({x})"))};");
        }
        // 缺伙伴时描红框提示（本体的 Osty 牌全是这个写法：base.Owner.IsOstyMissing）
        // 只按「真的会卡住打不出」的那些算（petGates）——「替主人承伤」不在此列，不然
        // 「召唤 + 承伤」的牌一上场就是红的（用户实测）。
        if (petGates.Count > 0)
            w.Line($"protected override bool ShouldGlowRedInternal => {string.Join(" || ", petGates.Select(x => $"!({x})"))};");

        // 鼠标悬停卡面描述里的状态 → 弹出本体 powers 表里那条说明（本体状态改写后就是新的名字 + 新的描述）
        // 自定义关键词 + 内置的「临时保留 / 临时奇巧」也走这一段（文本来自我们写进本体 card_keywords 表的键）
        // V0.2.136：「升级后获得 / 失去的自定义关键词」也走这一段（按 base.IsUpgraded 条件加/不加）
        w.Raw(HoverTipsOverride(c.Effects, isPublic: false, isCard: true,
            extraTips: KeywordGen.TipsFor(p, c.CustomKeywordList), owner: p,
            upgradedKeywordTips: UpgradeKeywordTips(p, c)));

        // 先古卡：不进战斗里的随机生成，也不进普通卡牌奖励
        // （本体 CardFactory 里 Ancient 就是被显式排除的：要么先古遗物给，要么你自己的效果给）
        if (c.IsAncientCard)
            w.Line()
             .Line("// 先古卡：只由先古之民 / 你自己的效果给出，不进普通战斗奖励（本体 CardFactory 显式排除 Ancient）")
             .Line("public override bool CanBeGeneratedInCombat => false;")
             .Line("public override bool CanBeGeneratedByModifiers => false;");
        // 先古卡的外观池：只在「诅咒 / 先古卡」页给先古卡设了边框颜色时才生成
        if (c.IsAncientCard && p.AncientStyle.Any)
            w.Line()
             .Line("// 外观用你在「诅咒 / 先古卡」页给先古卡设的那个外观池（卡框颜色）")
             .Line($"public override CardPoolModel VisualCardPool => ModelDb.CardPool<{n.AncientStylePoolClass}>();");

        // 可被无限升级（用户要求）：本体默认 MaxUpgradeLevel => 1，覆写后升级次数没有上限。
        // 本体 UpgradeInternal() = 「CurrentUpgradeLevel++ → OnUpgrade()」，而我们的升级增量全写在
        // OnUpgrade() 里 → 每升一级数值再涨一次；卡面标题本体自己会显示成「名字+N」。
        if (c.InfinitelyUpgradable)
            w.Line()
             .Line("// 可被无限升级：本体默认 MaxUpgradeLevel => 1（只能升一次），这里覆写成没有上限")
             .Line("public override int MaxUpgradeLevel => int.MaxValue;");

        // 状态牌不能升级（本体「粘液 Slimed」就是 MaxUpgradeLevel => 0）。
        // 必须显式覆写：本体默认是 1，牌组界面会给每张牌调 UpgradeInternal 画升级预览，
        // 状态牌留着升级钩子就可能在「升级预览」里表现出不该有的数值变化。
        if (c.IsStatusCard && !c.InfinitelyUpgradable)
            w.Line()
             .Line("// 状态牌不能升级（本体「粘液 Slimed」也是 MaxUpgradeLevel => 0）")
             .Line("public override int MaxUpgradeLevel => 0;");

        w.Line()
         .Line($"public {cls}() : base({(costIsX ? 0 : CardCostOf(p, c))}, CardType.{c.CardType}, CardRarity.{c.Rarity}, TargetType.{targetType}) {{ }}")
         .Line()
         .Open("protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)");

        // 所有效果都挂在「卡牌时机」/「放回手牌」这类钩子上时，OnPlay 里一句都没有 —— 补一句 await，
        // 免得生成出「async 方法里没有 await」（CS1998）。这是新配置才会走到的分支（老存档不变）。
        if (c.Effects.Count > 0 && onPlayEffects.Count == 0)
            w.Line("// 这张牌的效果全都挂在钩子上（打出时不做事），见下面那几个 override")
             .Line("await Task.CompletedTask;");

        // X 值：整张牌里只取一次，后面的效果都用这个变量
        if (usesX)
        {
            if (costIsX || xIsStar)
            {
                string call = xIsStar ? "ResolveStarXValue()" : "ResolveEnergyXValue()";
                // 「升级后 X + N」：老勾选框 XPlusOnUpgrade → N = 1；「升级后费用」框里写 X+1 / X+2 → 1 / 2
                int xPlus = CostXPlus(c);
                string plus = xPlus > 0 ? $" + (base.IsUpgraded ? {xPlus} : 0)" : "";
                w.Line($"// X = {(xIsStar ? "打出时消耗掉的额外资源量" : "打出时消耗掉的能量")}{(xPlus > 0 ? $"（升级后 X + {xPlus}）" : "")}");
                w.Line($"int x = {call}{plus};");
            }
            else
            {
                w.Line("// 这张牌的费用不是 X，所以 X 按 0 处理（界面上会给出警告）");
                w.Line("int x = 0;");
            }
            w.Line();
        }

        // 「数值公式」：把用到的自定义参数 / X / Y 先算一次（只算真的用到的那几个）。
        // 放在 X 那一块之后、目标判空之前：__fgTarget = cardPlay?.Target 不解引用，判空之前算它是安全的。
        ForgeGraphGen.EmitCardFormulaPrologue(w, p, onPlayEffects, xPlus: CostXPlus(c));

        if (NeedsTargetNullCheck(c))
        {
            w.Line("ArgumentNullException.ThrowIfNull(cardPlay.Target, \"cardPlay.Target\");");
            w.Line();
        }
        // 斩杀条件（本体 Fatal）：要「上一条攻击的结果」+「打之前记下的、目标是否允许触发斩杀」两个变量。
        // 声明在这里（OnPlay 开头），赋值在每一条「造成伤害」效果那一行 —— 这样
        // 「斩杀」写在伤害后面时读的就是那一条的结果。
        bool usesFatal = c.Effects.Any(e => e.Condition is { } ec && ec.Kind == "Fatal")
                         || (c.Condition is { Kind: "Fatal" });
        if (usesFatal)
        {
            w.Line("// 斩杀（本体 Fatal）：__lastAttack = 上一条攻击的结果；__fatalOk = 打之前记下的「目标允许触发斩杀」");
            w.Line("MegaCrit.Sts2.Core.Commands.Builders.AttackCommand? __lastAttack = null;");
            w.Line("bool __fatalOk = false;");
            w.Line();
        }
        // 「能打出但效果不生效」：老存档的整张牌条件不满足时整段效果都跳过
        bool wrapEffects = c.Condition is not null && !c.Condition.IsNone && !c.Condition.UnplayableWhenUnmet;
        if (wrapEffects)
        {
            w.Open($"if ({ConditionExpr(c.Condition, CondCtx.Card)})");
        }
        // 召唤 / 伙伴攻击要「先找到宠物」：找到一次，整张牌后面的召唤、伙伴攻击都用这个变量。
        // 为什么要守卫：宠物不在场（没召唤 / 已经死了）时，伙伴攻击不该让整张牌报错 ——
        // 攻击者不存在的话 AttackCommand 直接抛 InvalidOperationException。
        // 现在是**列表**：一张牌的效果可以分别指向不同的召唤物，所以按「这张牌用到的每一只」各查一次，
        // 变量名按宠物类名取（__<宠物类名首字母小写>）。
        // 注意：只有「需要已经召唤出来的那只」的效果才需要这个变量（见 NeedsExistingPet）；
        // 纯召唤牌不声明它（否则生成代码里会留一个没用到的局部变量，白挨一条编译警告）。
        var petLookup = new Dictionary<string, string>(StringComparer.Ordinal);      // 宠物类名 → 局部变量名
        foreach (var e in onPlayEffects.Where(NeedsExistingPet))
        {
            // 「全部召唤物」会把这张牌用到的**每一只**都查一遍（各占一个 __xxx 变量）
            foreach (var d in PetGen.ResolveMany(p, e.PetSummon))
                if (!petLookup.ContainsKey(d.ClassName)) petLookup[d.ClassName] = PetAttackVarName(d.ClassName);
        }
        bool hasPetAction = onPlayEffects.Any(e => e.PetAction);
        if (hasPetAction)
        {
            w.Line();
            w.Open("if (base.Owner.PlayerCombatState is not null)");
            if (petLookup.Count > 0)
            {
                w.Line("// 宠物可能还没召唤（或上一场战斗结束时被本体清掉了）：每只先找一次，后面所有伙伴攻击都用它");
                foreach (var kv in petLookup)
                    w.Line($"Creature? {kv.Value} = {kv.Key}Cmd.Get(base.Owner);");
            }
            else
            {
                w.Line("// 召唤伙伴：不需要先查宠物 —— Summon 内部会自己找（活着就加血、没有就新召一只）");
            }
        }
        // 每条效果各自的条件：不满足只跳过这一条（WrapInIf 里的效果本身不能带条件）
        // 概率生效：整张牌所有勾了概率的效果**共用一次掷骰**（合并概率，用户要求）
        var cardChanceSlices = ChanceSlices(onPlayEffects);
        // 有「概率公式」的效果也要掷骰（它自己独立判一次），所以这里两种都算上
        if (cardChanceSlices.Count > 0 || onPlayEffects.Any(e => e.UsesCountFormula("Chance"))) w.Line(ChanceRollLine());
        int petAllGroup = 0;
        // 「生成调试日志」（V0.2.142，默认关）：这一段里发射的所有效果都属于「这张牌」——
        // 打开开关时日志里才会写「卡牌「XX」(ClassName)」；关着时这个 using 什么都不做（红线①）。
        using (DebugLogGen.Begin(p, "卡牌", c.Name, cls, "base.Owner.Creature"))
        {
        foreach (var e in onPlayEffects)
        {
            // 条件里也能写「数值公式」（用户要求⑦）：求值同样要 __fgPlayer / __fgSelf ——
            // 所以这里先告诉 ConditionExpr「现在生成的是这张卡」（和次数公式共用那个生成期变量）。
            CharacterProfile? prevCondOwner = _formulaOwner;
            _formulaOwner = p;
            string? cond;
            try
            {
                cond = EffectConditionGuard(e, CondCtx.Card, inOnPlay: true, chanceSlices: cardChanceSlices);
            }
            finally
            {
                _formulaOwner = prevCondOwner;
            }
            bool hasGuard = cond is not null;

            // 「全部召唤物」（PetGen.AllId）：按**已启用的那几只**逐只展开成多份代码（生成时就定死，
            // 不是运行时遍历）—— 每只自己判在场，不在场的那只整段跳过。
            // 展开出来的每一份都会写一行「// CET:PetAll=<组号>」，回读时靠它把多份合并回一条「全部召唤物」。
            if (PetGen.IsAll(e.PetSummon) && EffectCatalog.IsPetKind(e.Kind))
            {
                var allDefs = PetGen.ResolveMany(p, e.PetSummon);
                if (hasGuard) w.Open(cond!);
                if (allDefs.Count == 0)
                {
                    // 兜底：校验器会把「一只都没启用」拦住，这里只保证万一跑到了也生成得出能编译的代码
                    EmitCardEffect(w, p, e, usesX, cardVars, null, captureFatal: usesFatal);
                }
                else
                {
                    w.Line($"// 【全部召唤物】这一条对 {allDefs.Count} 只各来一遍："
                        + string.Join("、", allDefs.Select(d => d.DisplayName)) + "（不在场的那只自动跳过）");
                    string group = "g" + petAllGroup++;
                    foreach (var d in allDefs)
                    {
                        w.Line($"// CET:PetAll={group}");
                        bool needPet = NeedsExistingPet(e);
                        string pv = petLookup.GetValueOrDefault(d.ClassName) ?? PetAttackVarName(d.ClassName);
                        if (needPet) w.Open($"if ({pv} is not null)");
                        EmitCardEffect(w, p, e, usesX, cardVars, needPet ? pv : null, d, effectComment: null, petLookup, captureFatal: usesFatal);
                        if (needPet) w.Close();
                    }
                }
                if (hasGuard) w.Close();
                continue;
            }

            string? petVar = NeedsExistingPet(e) && PetGen.Resolve(p, e.PetSummon) is { } pd
                ? petLookup.GetValueOrDefault(pd.ClassName)
                : null;
            bool petGuard = petVar is not null;
            if (hasGuard || petGuard)
            {
                // 外层是效果自己的条件、内层是「宠物在不在场」；两者都要满足才执行这条
                if (hasGuard) w.Open(cond!);
                if (petGuard) w.Open($"if ({petVar} is not null)");
            }
            EmitCardEffect(w, p, e, usesX, cardVars, petVar, petDef: null, effectComment: null, petLookup, captureFatal: usesFatal);
            if (petGuard) w.Close();
            if (hasGuard) w.Close();
        }
        }   // ← 关闭「生成调试日志」的来源作用域（using）
        // 关闭最外层的「PlayerCombatState 不为 null」守卫 —— 只要这张牌有召唤/伙伴攻击就开过它
        // （注意：不能用 petLookup 判断 —— 纯召唤牌不开宠物查询变量，但守卫一样要关，否则生成的代码缺一个 }）
        if (hasPetAction) w.Close();
        if (wrapEffects) w.Close();
        // 锻造节点图里【触发时机 = 卡牌被打出时】的那部分：挂到这里一起执行
        // （图是"另一套逻辑"，但打出牌的时机只有一个 OnPlay，所以在这里调用那个分部方法）。
        // 两块布都设成「打出时」时是两个不同的方法名（升级前 / 升级后），否则一个类里两个同名方法会 CS0111。
        // 两张布都在时按**这张牌升级了没有**二选一 —— 两个都调会把两套效果各跑一遍。
        if (ForgeGraphGen.UsesGraph(c) && ForgeGraphGen.HasPlayTiming(c))
        {
            bool hasBase = ForgeGraphGen.HasPlayTimingIn(c.ForgeGraph);
            bool hasUp = c.UpgradedForgeGraph is { IsEmpty: false } && ForgeGraphGen.HasPlayTimingIn(c.UpgradedForgeGraph);
            if (hasBase && hasUp)
                w.Line($"if (base.IsUpgraded) await {ForgeGraphGen.PlayMethodName(true)}(choiceContext, cardPlay);   // 升级后走「升级后」那张布")
                 .Line($"else await {ForgeGraphGen.PlayMethodName(false)}(choiceContext, cardPlay);                   // 没升级走「升级前」");
            else if (hasUp)
                w.Line($"await {ForgeGraphGen.PlayMethodName(true)}(choiceContext, cardPlay);   // 锻造节点图（升级后）");
            else
                w.Line($"await {ForgeGraphGen.PlayMethodName(false)}(choiceContext, cardPlay);   // 锻造节点图：【触发时机】= 卡牌被打出时");
        }
        w.Close();

        // 需求⑩：卡牌时机的效果 —— 挂到本体对应钩子的 override 上（不在 OnPlay 里）
        if (hasTiming) EmitCardTimingHooks(w, p, timingGroups, cardVars, CostXPlus(c));
        // 「将此牌放回手牌」：打完牌之后把它搬回手牌（本体 MakeItSo 用的就是 AfterCardPlayedLate）
        if (hasSelfReturn) EmitSelfReturnHook(w, p, c.Effects, cardVars);
        // 「抽到这张牌时它本场战斗费用 -N」：卡自己的 AfterCardDrawn（本体 KinglyKick 用的就是它）
        if (hasSelfDraw) EmitSelfDrawHook(w, p, c.Effects, cardVars);

        var upgradeable = c.Effects.Where(e => e.UpgradeAmount != 0 && !HasNoDynamicVar(e)).ToList();
        int cardCostNow = CardCostOf(p, c);
        int? targetCost = c.UpgradeCost;
        // V0.2.131：「升级后费用」框里写的**常量式子**（`2` / `1+1` / `A+3`）也当目标费用用。
        // 写的是 X / X+N 时不走这里 —— 那是「X 费 + 升级后 X 加几」，已经在上面 xPlus 那一段处理掉了。
        if (!string.IsNullOrWhiteSpace(c.UpgradeCostFormula))
        {
            var upR = ForgeNumbers.ResolveCost(p, c.UpgradeCostFormula, "X", allowPlus: true, "升级后费用");
            if (upR.IsConstant) targetCost = upR.Value;
        }
        // 锻造卡还多一条：两块布的【能量】模块填的费用不一样时，以「升级后」那块为准
        // （本体「升级后费用变少」就是 OnUpgrade 里 EnergyCost.UpgradeBy(负数)）。
        if (c.IsForged && c.UpgradedForgeGraph is { IsEmpty: false })
        {
            int upCost = ForgeGraphGen.EnergyCostOf(c.UpgradedForgeGraph);
            if (upCost != cardCostNow) targetCost = upCost;
        }
        bool costChange = targetCost is not null && targetCost.Value != cardCostNow && !costIsX;
        // V0.2.131「升级后额外资源量费用」：本体 CardModel 上就有 protected void UpgradeStarCostBy(int addend)
        //（和 OnUpgrade() 同一个 Family 可见性，另有 BaseStarCost / CurrentStarCost / WasStarCostJustUpgraded
        // 那套机制）→ 照 EnergyCost.UpgradeBy 的同款思路写差值。
        int starCostNow = StarCostOf(p, c);
        int? targetStar = c.UpgradeStarCost;
        bool starCostChange = targetStar is not null && targetStar.Value != starCostNow && !starCostIsX;
        var kwAdd = c.UpgradeKeywords?.Added ?? (IReadOnlyList<string>)Array.Empty<string>();
        var kwDel = c.UpgradeKeywords?.Removed ?? (IReadOnlyList<string>)Array.Empty<string>();
        if (upgradeable.Count > 0 || costChange || starCostChange || kwAdd.Count > 0 || kwDel.Count > 0)
        {
            w.Line()
             .Open("protected override void OnUpgrade()");
            // 「按生命值算」的宠物效果（三个伙伴攻击 / 牺牲伙伴）的升级增量要写到 **CalculationBase** 上：
            // 它们的 CanonicalVars 里那个 CalculatedDamage/CalculatedBlock 是**固定名字**的（本体的
            // DynamicVars.CalculatedDamage 是按名字取的），升级只能抬 CalculationBase（框架会自动重算预览）。
            // 一张牌最多一条这种效果（校验器会拦住第二条），但求稳还是把增量**累加**起来写一次。
            decimal calcBaseDelta = 0m;
            foreach (var e in upgradeable)
            {
                if (CanonicalVarNeedsPetCmd(e)) { calcBaseDelta += e.UpgradeAmount; continue; }
                w.Line($"base.DynamicVars[{Lit.Str(VarNameOf(e, cardVars))}].UpgradeValueBy({Lit.Dec(e.UpgradeAmount)});");
            }
            if (calcBaseDelta != 0m)
                w.Line($"base.DynamicVars.CalculationBase.UpgradeValueBy({Lit.Dec(calcBaseDelta)});"
                    + "   // 「按生命值算」的宠物效果：升级加的是固定加值（最大生命/当前生命那部分照旧跟着宠物走）");
            if (costChange)
            {
                // 改费用用的是本体自己的办法：OnUpgrade 里调用 EnergyCost.UpgradeBy(增量)
                int delta = targetCost!.Value - cardCostNow;
                w.Line($"base.EnergyCost.UpgradeBy({delta});   // 升级后费用 {targetCost.Value}（原 {cardCostNow}）");
            }
            if (starCostChange)
                w.Line($"UpgradeStarCostBy({targetStar!.Value - starCostNow});   // 升级后额外资源量费用 {targetStar.Value}（原 {starCostNow}）");
            // 升级后的关键字：本体「残影 / 幻影 / 寒冰」就是这么写的
            foreach (string kw in kwAdd)
                w.Line($"AddKeyword(CardKeyword.{kw});   // 升级后获得「{Profile.KeywordUpgradeSpec.Zh(kw)}」");
            foreach (string kw in kwDel)
                w.Line($"RemoveKeyword(CardKeyword.{kw});   // 升级后失去「{Profile.KeywordUpgradeSpec.Zh(kw)}」");
            w.Close();
        }
        // 锻造节点图（「锻造」页那块布）：图和效果是**两套**，各写各的 ——
        // 图非空时把它的钩子（OnPlay / 各个 override）附加在类末尾；图是空的则一个字符都不写。
        if (ForgeGraphGen.UsesGraph(c))
        {
            string fields = ForgeGraphGen.TimingFields(p, c);
            if (fields.Length > 0) w.Raw(fields);
            string hooks = ForgeGraphGen.CardHooks(p, c, isUpgraded: false);
            if (hooks.Length > 0) w.Raw(hooks);
            if (c.UpgradedForgeGraph is { IsEmpty: false })
            {
                string fieldsUp = ForgeGraphGen.TimingFields(p, c, upgraded: true);
                if (fieldsUp.Length > 0) w.Raw(fieldsUp);
                string up = ForgeGraphGen.CardHooks(p, c, isUpgraded: true);
                if (up.Length > 0) w.Raw(up);
            }
        }
        w.Close();
        return w.ToString();
    }

    // ==================== 卡牌时机（需求⑩） ====================
    //
    // 原文：`条件增加“卡牌时机”，当选择时在底下新增下拉栏，内包含“被消耗”、“被生成”、“被保留”、“被丢弃”、“被变化”，
    // 参考原版“战鼓”，再加一个“被给予自定义关键词”，当此卡被给予关键词时条件生效。`
    //
    // 这一条和别的 20 个条件**架构上不同**：别的都是「打出这张牌时算一个 bool」，而「这张牌被消耗了」这件事
    // 打出的时候根本还没发生（可能是别的牌的效果、可能是回合结束时虚无、也可能永远不发生）。
    // 本体「战鼓」DrumOfBattle 的做法就是覆写卡自己的钩子：
    //     public override async Task AfterCardExhausted(PlayerChoiceContext choiceContext, CardModel card, bool causedByEthereal)
    //     { if (card == this && base.CombatState != null) { … } }
    // 所以带这个条件的效果一律**不写进 OnPlay**，而是生成成对应钩子的 override；同一个时机有多条效果
    // 就合并进同一个 override，按效果列表顺序执行（和本体多效果卡的写法一致）。

    /// <summary>
    /// 「卡牌时机」子时机 → 生成出来的**方法名**。回读（<see cref="ProjectRecovery"/>）按它把方法体抠出来，
    /// 所以这里和 <see cref="EmitCardTimingHooks"/> 里写的签名必须一致（改一处就得改另一处）。
    /// 被变化 / 被给予自定义关键词用的是**另一个方法名**（本体那个钩子是同步 void，效果体在私有异步方法里；
    /// 给关键词那条压根不是本体钩子，是我们自己的入口）。
    /// </summary>
    public static string CardTimingMethodName(string timing) => timing switch
    {
        "Exhausted" => "AfterCardExhausted",
        "Generated" => "AfterCardGeneratedForCombat",
        "Retained" => "AfterFlush",
        "Discarded" => "AfterCardDiscarded",
        "Transformed" => "ForgeOnTransformedFrom",
        "GivenKeyword" => "ForgeOnGivenCustomKeyword",
        _ => "AfterCardExhausted",
    };

    /// <summary>这条效果的条件是不是「卡牌时机」（需求⑩）。</summary>
    internal static bool IsCardTiming(ConditionSpec? c) =>
        c is not null && !c.IsNone && string.Equals(c.Kind, "CardTiming", StringComparison.Ordinal);

    /// <summary>
    /// 把这个存档里所有「卡牌时机」的效果按子时机分组（顺序 = <see cref="EffectCatalog.CardTimings"/> 的顺序）。
    /// 顺序固定下来是为了「生成 → 回读」对得上：CanonicalVars 与回读解析都按同一个顺序走。
    /// </summary>
    private static List<(string Timing, List<EffectSpec> Effects)> CardTimingGroups(IEnumerable<EffectSpec> effects)
    {
        var list = effects.Where(e => IsCardTiming(e.Condition)).ToList();
        var groups = new List<(string Timing, List<EffectSpec> Effects)>();
        if (list.Count == 0) return groups;
        foreach (var opt in EffectCatalog.CardTimings)
        {
            var mine = list.Where(e => string.Equals(e.Condition!.Timing, opt.Id, StringComparison.Ordinal)).ToList();
            if (mine.Count > 0) groups.Add((opt.Id, mine));
        }
        // 子时机认不出来（老存档被改坏 / 手写）的兜底：挂到第一项「被消耗」上，不丢效果（校验器会报错拦住生成）
        var known = new HashSet<string>(groups.Select(g => g.Timing), StringComparer.Ordinal);
        var unknown = list.Where(e => !known.Contains(e.Condition!.Timing ?? "") && EffectCatalog.FindCardTiming(e.Condition!.Timing) is null).ToList();
        if (unknown.Count > 0) groups.Add((EffectCatalog.DefaultCardTiming, unknown));
        return groups;
    }

    /// <summary>
    /// 生成「卡牌时机」的钩子 override。每个子时机一段，签名照本体抄（注释里各写清了为什么挂那儿）：
    ///   被消耗   → AbstractModel.AfterCardExhausted(choiceContext, card, causedByEthereal)   [async，判 card == this]
    ///   被丢弃   → AbstractModel.AfterCardDiscarded(choiceContext, card)                       [async，判 card == this]
    ///   被生成   → AbstractModel.AfterCardGeneratedForCombat(card, creator)                    [async，判 card == this]
    ///   被保留   → AbstractModel.AfterFlush(choiceContext, player, flushedCards, retainedCards)[async，判 retainedCards 里有自己]
    ///   被变化   → CardModel.AfterTransformedFrom()                                            [**同步 void、无 context**，见下面的说明]
    ///   被给予自定义关键词 → 我们自己的「给予卡牌关键词」那一步直接调用（本体没有这个事件）
    /// </summary>
    private static void EmitCardTimingHooks(CodeWriter w, CharacterProfile p,
        List<(string Timing, List<EffectSpec> Effects)> groups, Dictionary<EffectSpec, string> cardVars, int xPlus = 0)
    {
        foreach (var (timing, effects) in groups)
        {
            // 要不要声明 `CardPlay? cardPlay = null;`：由**生成出来的文本**决定（有没有真的引用 cardPlay），
            // 比按效果种类列一张表猜更准（例：格挡自始至终都把 cardPlay 传给 CreatureCmd.GainBlock）。
            // 同一份文本也用来判断「这几条效果里有没有 await」—— 没有的话要给 async 方法补一句，
            // 免得生成出 CS1998（async 方法里没有 await）。
            string bodyText = TimingBodyText(effects, p, cardVars);
            bool needsCardPlay = bodyText.Contains("cardPlay", StringComparison.Ordinal);
            bool bodyAwaits = bodyText.Contains("await ", StringComparison.Ordinal);
            switch (timing)
            {
                case "Discarded":
                    w.Line()
                     .Line("// 卡牌时机「被丢弃」（需求⑩）：覆写 AbstractModel.AfterCardDiscarded（本体这个钩子会广播给场上所有模型，先判 card == this）")
                     .Open("public override async Task AfterCardDiscarded(PlayerChoiceContext choiceContext, CardModel card)")
                     .Line("if (card != this || base.CombatState is null) return;")
                     .Line("// CET:CardTiming=Discarded");
                    if (needsCardPlay) EmitCardPlayPlaceholder(w);
                    EmitCardTimingBody(w, p, effects, cardVars, xPlus);
                    w.Close();
                    break;

                case "Generated":
                    // 为什么不用 CardModel.AfterCreated()：本体那个钩子是 `public virtual void AfterCreated()`（同步 void、
                    // 没有 choiceContext），里面没法 await 本体的命令（本体的卡也一个都没覆写它）。
                    // 本体的另一条钩子 AfterCardGeneratedForCombat(card, creator) 是 async 的，而且是
                    // **战斗里生成卡牌时**广播的（CardPileCmd.AddGeneratedCardsToCombat → Hook.AfterCardGeneratedForCombat），
                    // 我们的「生成卡牌」效果生成的卡走的正是这条路（AddToCombatAndPreview / AddGeneratedCardsToCombat），
                    // 所以「被生成」挂它 —— 而且生成出来的卡这时已经在战斗牌堆里，能收到广播。
                    // 它同样**没有** choiceContext，但它是 async 的：用本体分发事件时那个 HookPlayerChoiceContext
                    // 自己造一个就行（Hook.cs 里就是这么 new 的），效果体照常 await。
                    w.Line()
                     .Line("// 卡牌时机「被生成」（需求⑩）：覆写 AbstractModel.AfterCardGeneratedForCombat")
                     .Line("// （为什么不是 CardModel.AfterCreated：那个是同步 void、没有 choiceContext，没法 await 本体的命令；")
                     .Line("//   而这一条是 async 的，并且战斗里「生成卡牌」正是广播它 —— 见 CardPileCmd.AddGeneratedCardsToCombat）")
                     .Open("public override async Task AfterCardGeneratedForCombat(CardModel card, Player? creator)")
                     .Line("if (card != this || base.CombatState is null) return;")
                     .Line("// CET:CardTiming=Generated")
                     .Line("// 本体这条钩子没有 choiceContext：用本体分发事件时用的 HookPlayerChoiceContext 造一个（Hook.cs 里就是这么 new 的）")
                     .Line("var choiceContext = new HookPlayerChoiceContext(this, MegaCrit.Sts2.Core.Context.LocalContext.NetId ?? 0UL, base.CombatState, MegaCrit.Sts2.Core.Entities.Multiplayer.GameActionType.Combat);");
                    if (!bodyAwaits) w.Line("await Task.CompletedTask;   // 这几条效果都不 await（补一句，免得 async 方法里没有 await）");
                    if (needsCardPlay) EmitCardPlayPlaceholder(w);
                    EmitCardTimingBody(w, p, effects, cardVars, xPlus);
                    w.Close();
                    break;

                case "Retained":
                    // 本体**没有** AfterCardRetained 之类的钩子，但它丢手牌那一步会把「这回合要留下的牌」
                    // 单独交出来：CombatManager.FlushPlayerHand → Hook.AfterFlush(state, player, ctx, cardsToFlush, cardsToRetain)。
                    // 判据就写在那里（本体 CardModel.ShouldRetainThisTurn 的定义）：
                    //   · 有 CardKeyword.Retain 关键词 → 留；
                    //   · 这一回合被 GiveSingleTurnRetain() 标记过（本体单回合保留）→ 留；
                    //   · Hook.ShouldFlush(state, player) 为 false 时（「整手牌都不丢」那种效果）→ 所有手牌都归进 retainedCards。
                    // 三条路都会让这张牌出现在 retainedCards 里，所以「retainedCards.Contains(this)」就是准的判据。
                    //
                    // 为什么不用 CardModel.OnTurnEndInHandWrapper 自己判：HasTurnEndInHandEffect 会让本体
                    // 把这张牌当成「回合结束时在手上触发的牌」，在跑完 OnTurnEndInHand 之后**无条件把它丢进弃牌堆 / 消耗**
                    // （CombatManager.ResolveTurnEndCardEffects），那正好把「保留」这件事破坏掉了 ——
                    // 玩家会看到一张写着「被保留时…」的牌根本不留在手上。AfterFlush 是只读的通知，没有这个副作用。
                    w.Line()
                     .Line("// 卡牌时机「被保留」（需求⑩）：覆写 AbstractModel.AfterFlush —— 本体丢手牌时会把「这回合留下的牌」交出来")
                     .Line("// 判据 = 本体 CombatManager.FlushPlayerHand 归进 retainedCards：有 Retain 关键词 / 这回合被单回合保留 / 整手牌都不丢")
                     .Open("public override async Task AfterFlush(PlayerChoiceContext choiceContext, Player player, IReadOnlyCollection<CardModel> flushedCards, IReadOnlyCollection<CardModel> retainedCards)")
                     .Line("if (player != base.Owner || base.CombatState is null) return;")
                     .Line("if (!retainedCards.Contains(this)) return;   // 这张牌这回合没被保留（被丢进弃牌堆了）")
                     .Line("// CET:CardTiming=Retained");
                    if (needsCardPlay) EmitCardPlayPlaceholder(w);
                    EmitCardTimingBody(w, p, effects, cardVars, xPlus);
                    w.Close();
                    break;

                case "Transformed":
                    // 本体 CardCmd.Transform 里：`original.AfterTransformedFrom(); replacement2.AfterTransformedTo();`
                    // 需求里说的「被变化」= **这张牌被变成了别的牌**，所以选 AfterTransformedFrom
                    //（AfterTransformedTo 是「这张牌是变化出来的那一张」，那更像「被生成」）。
                    // 这个钩子是**同步 void、也没有 choiceContext**，效果体只能放进一个 private async Task，
                    // 用本体自己分发事件时用的 HookPlayerChoiceContext 起一个上下文
                    //（Hook.cs 里就是 `new HookPlayerChoiceContext(model, netId, combatState, GameActionType.Combat)`）。
                    w.Line()
                     .Line("// 卡牌时机「被变化」（需求⑩）：本体 CardCmd.Transform 里 original.AfterTransformedFrom() —— 「这张牌被变成了别的牌」")
                     .Line("//（不选 AfterTransformedTo：那是「这张牌是变化出来的那一张」，语义上属于「被生成」。）")
                     .Open("public override void AfterTransformedFrom()")
                     .Line("// 本体这个钩子是**同步 void、没有 choiceContext**，没法直接 await 命令，所以另起一个异步方法；")
                     .Line("// 上下文用 HookPlayerChoiceContext（本体分发这类事件时用的就是它，见 Hook.cs）。")
                     .Line("if (base.CombatState is null) return;")
                     .Line("var choiceContext = new HookPlayerChoiceContext(this, MegaCrit.Sts2.Core.Context.LocalContext.NetId ?? 0UL, base.CombatState, MegaCrit.Sts2.Core.Entities.Multiplayer.GameActionType.Combat);")
                     .Line("_ = choiceContext.AssignTaskAndWaitForPauseOrCompletion(ForgeOnTransformedFrom(choiceContext));")
                     .Close()
                     .Line()
                     .Open("private async Task ForgeOnTransformedFrom(PlayerChoiceContext choiceContext)")
                     .Line("// CET:CardTiming=Transformed");
                    if (!bodyAwaits) w.Line("await Task.CompletedTask;   // 这几条效果都不 await（补一句，免得 async 方法里没有 await）");
                    if (needsCardPlay) EmitCardPlayPlaceholder(w);
                    EmitCardTimingBody(w, p, effects, cardVars, xPlus);
                    w.Close();
                    break;

                case "GivenKeyword":
                    // 本体**没有**「被给予关键词」事件（关键词只有 AddKeyword / RemoveKeyword 两个动作，没有广播）。
                    // 但「给一张牌加上自定义关键词」这件事**本来就是我们自己做的**（生成出来的
                    // `AddGivenCustomKeyword` / `EmitGiveKeywordTo` 那一套），所以不需要另造机制：
                    // 在那一步直接调用这张牌的这个方法就行（见 EmitGiveKeywordTo 里的 notify 与
                    // GivenKeywordPatchSource 里生成的转发器 ForgeGivenKeywordTiming）。
                    w.Line()
                     .Line("// 卡牌时机「被给予自定义关键词」（需求⑩）：由生成出来的「给予卡牌关键词」那一步直接调用")
                     .Line("// （本体没有这个事件；给自定义关键词本来就是我们自己做的，见生成的关键词补丁里的 ForgeGivenKeywordTiming）")
                     .Open("public async Task ForgeOnGivenCustomKeyword(PlayerChoiceContext choiceContext)")
                     .Line("// CET:CardTiming=GivenKeyword")
                     .Line("if (base.CombatState is null) return;");
                    if (needsCardPlay) EmitCardPlayPlaceholder(w);
                    EmitCardTimingBody(w, p, effects, cardVars, xPlus);
                    w.Close();
                    break;

                case "HpLost":
                    // 「这张牌在你手上时，你失去生命」—— 本体 AbstractModel.AfterCurrentHpChanged(creature, delta)：
                    // 生命值真的变了才广播，delta 为负就是**掉了血**（CreatureCmd 里扣血那段传的就是负数，
                    // 见 CreatureCmd.cs:404/534）。和自定义状态里的「自己失去生命时」是同一个钩子、同一套判据。
                    // 谁进战斗都会收到这个广播，所以先判「掉血的是不是我的主人」「delta 是不是负的」，
                    // 再判这张牌**在不在手上**（不在手上就不该触发 —— 打出去之后它就不在手上了）。
                    // 钩子是 async Task（没有 choiceContext 参数），效果体照常 await。
                    w.Line()
                     .Line("// 卡牌时机「失去生命时」：覆写 AbstractModel.AfterCurrentHpChanged（delta < 0 = 生命值真的少了；")
                     .Line("// 伤害 / 自己「失去生命」/ 直接扣血都算，回血不算）")
                     .Open("public override async Task AfterCurrentHpChanged(Creature creature, decimal delta)")
                     .Line("if (creature != base.Owner.Creature || delta >= 0m) return;   // 只认「自己掉血」")
                     .Line("if (base.CombatState is null) return;")
                     .Line("if (base.Pile?.Type != PileType.Hand) return;   // 这张牌得在你手上（打出去了 / 在牌堆里就不触发）")
                     .Line("// CET:CardTiming=HpLost");
                    if (!bodyAwaits) w.Line("await Task.CompletedTask;   // 这几条效果都不 await（补一句，免得 async 方法里没有 await）");
                    if (needsCardPlay) EmitCardPlayPlaceholder(w);
                    EmitCardTimingBody(w, p, effects, cardVars, xPlus);
                    w.Close();
                    break;

                default:   // Exhausted（也是兜底）
                    w.Line()
                     .Line("// 卡牌时机「被消耗」（需求⑩）：本体「战鼓」DrumOfBattle 的做法 —— 覆写 AbstractModel.AfterCardExhausted")
                     .Line("//（本体这个钩子会广播给场上所有模型，所以先判 card == this 只认自己）")
                     .Open("public override async Task AfterCardExhausted(PlayerChoiceContext choiceContext, CardModel card, bool causedByEthereal)")
                     .Line("if (card != this || base.CombatState is null) return;")
                     .Line("// CET:CardTiming=Exhausted");
                    if (needsCardPlay) EmitCardPlayPlaceholder(w);
                    EmitCardTimingBody(w, p, effects, cardVars, xPlus);
                    w.Close();
                    break;
            }
        }
    }

    /// <summary>
    /// 这些钩子里没有「打出记录」（cardPlay）。有几条本体 API 只是需要一个「来源卡」参数
    /// （<c>DamageCmd.Attack(...).FromCard(this, cardPlay)</c> / <c>CreatureCmd.GainBlock(..., cardPlay)</c>），
    /// 传 null 就是「没有具体的打出记录」。真正会**解引用** cardPlay.Target 的效果（打出的那个目标）
    /// 校验器会直接拦掉（见 ProfileValidator 的 TimingUsesPlayedTarget）。
    /// </summary>
    private static void EmitCardPlayPlaceholder(CodeWriter w) =>
        w.Line("// 这些钩子里没有「打出记录」：下面把 cardPlay 传 null（那几条本体 API 允许它），")
         .Line("// 「打出的目标」类效果（会解引用 cardPlay.Target）校验器会拦住，不允许挂在卡牌时机上。")
         .Line("CardPlay? cardPlay = null;");

    /// <summary>一组时机效果生成出来的代码文本（只用来判断「有没有引用 cardPlay / 有没有 await」）。</summary>
    private static string TimingBodyText(IReadOnlyList<EffectSpec> effects, CharacterProfile p,
        Dictionary<EffectSpec, string> cardVars)
    {
        var scratch = new CodeWriter();
        EmitCardTimingBody(scratch, p, effects, cardVars);
        return scratch.ToString();
    }

    /// <summary>
    /// 「卡牌时机」那一组效果的代码体（同一个时机里的多条效果按列表顺序依次执行）。
    /// 条件就是时机本身（已经体现在挂在哪个钩子上），所以这里**不再包条件 if**，只处理「概率生效」。
    /// </summary>
    /// <summary>
    /// 「数值公式」用到的东西先算成局部变量（见 <see cref="ForgeGraphGen.EmitCardFormulaPrologue"/>）。
    /// 这里只是给卡牌时机那段注释用的文案辅助：概率写了公式时印公式。
    /// </summary>
    private static string ChanceTextOf(EffectSpec e) => string.IsNullOrWhiteSpace(e.ChanceFormula)
        ? e.ChancePercent.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture) + "%"
        : ForgeFormula.DisplayText(e.ChanceFormula) + "%（现算）";

    private static void EmitCardTimingBody(CodeWriter w, CharacterProfile p, IReadOnlyList<EffectSpec> effects,
        Dictionary<EffectSpec, string> cardVars, int xPlus = 0)
    {
        var slices = ChanceSlices(effects);
        // 「概率公式」那条不参与区间划分（见 ChanceSlices），但它照样要掷骰 → 这里也把它算上
        if (slices.Count > 0 || effects.Any(e => e.UsesCountFormula("Chance"))) w.Line(ChanceRollLine());
        // 「数值公式」：这些钩子里也要现算一次（用法和 OnPlay 一样）。
        // 注意必须放在 EmitCardEffect 之前，而且这类钩子会补一句 `CardPlay? cardPlay = null;`
        //（TimingBodyText 会扫到公式里的 cardPlay 从而把那一句加上），所以 __fgTarget 也拿得到。
        ForgeGraphGen.EmitCardFormulaPrologue(w, p, effects, xPlus: xPlus);
        foreach (var e in effects)
        {
            w.Line($"// 卡牌时机「{EffectCatalog.CardTimingZh(e.Condition?.Timing)}」→「{EffectCatalog.FindKind(e.Kind).Display}」这条效果"
                 + (e.ChanceEnabled ? $"（{ChanceTextOf(e)} 概率生效）" : ""));
            string? guard = null;
            if (CountFormulaExpr(_formulaOwner, e, "Chance", out _) is { } timingChanceF)
                guard = $"if (__chanceRoll < (double)({timingChanceF}))";
            else if (slices.TryGetValue(e, out var slice))
                guard = $"if (__chanceRoll >= {slice.Start.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture)}"
                      + $" && __chanceRoll < {slice.End.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture)})";
            if (guard is not null) w.Open(guard);
            // X 一律按 0 处理（useX: false → 用 CanonicalVars 里那个数值）：这些钩子里没有打出时的 X，
            // 校验器会拦住「数值 = X」的配置，这里只是保证万一跑到也不生成引用不到变量的代码。
            EmitCardEffect(w, p, e, useX: false, varMap: cardVars, petVar: null, petDef: null,
                effectComment: null, petLookup: null, captureFatal: false);
            if (guard is not null) w.Close();
        }
    }

    /// <summary>这条效果是不是「将此牌放回手牌」。</summary>
    internal static bool IsSelfReturn(EffectSpec? e) =>
        e is not null && string.Equals(e.Kind, "ReturnSelfToHand", StringComparison.Ordinal);

    /// <summary>这条效果是不是「抽到这张牌时它本场战斗费用 -N」。</summary>
    internal static bool IsSelfDrawCost(EffectSpec? e) =>
        e is not null && string.Equals(e.Kind, "CheapenSelfOnDraw", StringComparison.Ordinal);

    /// <summary>
    /// 「抽到这张牌时它本场战斗的费用 -N」的钩子：<c>AfterCardDrawn</c>。
    ///
    /// 照抄本体卡「王者一击 KinglyKick」（`src/Core/Models/Cards/KinglyKick.cs`）：
    /// <code>
    /// public override Task AfterCardDrawn(PlayerChoiceContext choiceContext, CardModel card, bool fromHandDraw)
    /// {
    ///     if (card != this) return Task.CompletedTask;
    ///     base.EnergyCost.AddThisCombat(-1);
    ///     return Task.CompletedTask;
    /// }
    /// </code>
    /// 为什么用 <c>AddThisCombat</c> 而不是 <c>SetThisCombat(当前 - N)</c>：
    ///   · 本体的收费是按「基础费 + 本场加成」算的，AddThisCombat 直接记一笔「本场 -N」，
    ///     抽到几次就叠几次，也不会被别的改费效果冲掉（本体 KinglyKick 就是这么干的）；
    ///   · 本体自己会夹住下限，费用不会变成负数。
    /// 条件和概率照别的效果同一套（EffectConditionGuard）。
    /// 每条效果前面写一行 <c>// CET:Effect=CheapenSelfOnDraw …</c> 标记，回读靠它还原（见 ProjectRecovery）。
    /// </summary>
    private static void EmitSelfDrawHook(CodeWriter w, CharacterProfile p, IReadOnlyList<EffectSpec> effects,
        Dictionary<EffectSpec, string> cardVars)
    {
        var list = effects.Where(e => IsSelfDrawCost(e) && !IsInertZero(e)).ToList();
        if (list.Count == 0) return;
        w.Line()
         .Line("/// <summary>")
         .Line("/// 【抽到这张牌时它本场战斗的费用 -N】：本体卡「王者一击 KinglyKick」用的就是这个钩子。")
         .Line("/// 抽到几次叠几次（本场战斗内一直有效，没有回合数限制）。")
         .Line("/// </summary>")
         .Open("public override Task AfterCardDrawn(PlayerChoiceContext choiceContext, CardModel card, bool fromHandDraw)");
        foreach (var e in list)
        {
            string comment = EffectGuardComment(e);
            if (comment.Length > 0) w.Line("// " + comment);
            w.Line(SelfContainedMarker(e));
            int n = Math.Max(1, (int)Math.Round(e.Amount, MidpointRounding.AwayFromZero));
            string body = $"if (card == this) base.EnergyCost.AddThisCombat(-{n});";
            string? guard = EffectConditionGuard(e, CondCtx.Card, inOnPlay: true);
            if (guard is not null)
            {
                w.Open(guard);
                w.Line(body);
                w.Close();
            }
            else
            {
                w.Line(body);
            }
        }
        w.Line("return Task.CompletedTask;");
        w.Close();
    }

    /// <summary>
    /// 「将此牌放回手牌」的钩子：<c>AfterCardPlayedLate</c>。
    ///
    /// 为什么必须挂这个钩子（对着本体源码确认过）：本体 <c>PlayCardAction</c> 是**打完这张牌之后**
    /// 才把它放进弃牌堆的，而 <c>AfterCardPlayedLate</c> 正好是那时广播的 —— 本体「回响 MakeItSo」
    /// 用的就是它（`if (cardPlay.Card == this &amp;&amp; base.Pile.Type != PileType.Hand) await CardPileCmd.Add(this, PileType.Hand);`）。
    /// 写在 OnPlay 里搬牌会被随后的入堆动作覆盖，所以这个效果不能走 EmitCardEffect。
    ///
    /// 条件 / 概率照别的效果同一套（EffectConditionGuard）—— 这个钩子里有 cardPlay，
    /// 所以「指定敌人」这类条件读到的是**这张牌打出去时选的那个目标**，语义正确。
    /// 每条效果前面写一行 <c>// CET:Effect=ReturnSelfToHand …</c> 标记，回读靠它还原（见 ProjectRecovery）。
    ///
    /// 顺序说明：回读时这几条效果会回到效果列表**末尾**（和「卡牌时机」那几类一样）——
    /// 因为它们的代码在 OnPlay 之外，标记行也在那个钩子体里，而钩子体是最后拼进解析流的。
    /// </summary>
    private static void EmitSelfReturnHook(CodeWriter w, CharacterProfile p, IReadOnlyList<EffectSpec> effects,
        Dictionary<EffectSpec, string> cardVars)
    {
        var list = effects.Where(e => IsSelfReturn(e) && !IsInertZero(e)).ToList();
        if (list.Count == 0) return;
        w.Line()
         .Line("/// <summary>")
         .Line("/// 【将此牌放回手牌】：打出这张牌之后，把它从弃牌堆搬回手牌（值为 1 时生效）。")
         .Line("/// 为什么不在 OnPlay 里搬：本体是**打完牌之后**才把这张牌放进弃牌堆的（PlayCardAction），")
         .Line("/// 在 OnPlay 里搬会被那一步覆盖 —— 本体的「回响 MakeItSo」也是覆写这个钩子。")
         .Line("/// </summary>")
         .Open("public override async Task AfterCardPlayedLate(PlayerChoiceContext choiceContext, CardPlay cardPlay)");
        foreach (var e in list)
        {
            string comment = EffectGuardComment(e);
            if (comment.Length > 0) w.Line("// " + comment);
            w.Line(SelfContainedMarker(e));
            string? guard = EffectConditionGuard(e, CondCtx.Card, inOnPlay: true);
            if (guard is not null) w.Open(guard);
            w.Open("if (cardPlay is not null && cardPlay.Card == this && base.Pile is not null && base.Pile.Type != PileType.Hand)");
            w.Line("await CardPileCmd.Add(this, PileType.Hand);");
            w.Close();
            if (guard is not null) w.Close();
        }
        w.Close();
    }

    /// <summary>
    /// 这张牌（或遗物 / 药水 / 自定义状态）里有没有「卡牌时机 = <paramref name="timing"/>」的效果。    /// 生成「给予卡牌关键词」那一步时要用它决定要不要转发给卡牌的钩子
    /// （没有这个时机的存档 → 一个字符都不变，见 EmitGiveKeywordTo）。
    /// </summary>
    public static bool UsesCardTiming(CharacterProfile p, params string[] timings)
    {
        bool Hit(ConditionSpec? c) => IsCardTiming(c)
            && (timings.Length == 0 || timings.Contains(c!.Timing, StringComparer.Ordinal));
        foreach (var card in p.AllCards)
        {
            if (Hit(card.Condition)) return true;
            if (card.Effects.Any(e => Hit(e.Condition))) return true;
        }
        foreach (var r in p.Relics)
        {
            if (Hit(r.Condition)) return true;
            if (RelicEffects(r).Any(e => Hit(e.Condition))) return true;
        }
        foreach (var s in p.Potions)
            if (s.Effects.Any(e => Hit(e.Condition))) return true;
        foreach (var t in p.CustomPowers)
            foreach (var tr in t.Triggers)
                if (tr.Effects.Any(e => Hit(e.Condition))) return true;
        return false;
    }

    /// <summary>「被给予自定义关键词」这个时机的卡类名（生成转发器用；顺序 = 卡牌列表顺序）。</summary>
    public static IReadOnlyList<string> GivenKeywordTimingCardClasses(CharacterProfile p)
    {
        var n = Naming.From(p);
        return p.AllCards.Where(card => !card.IsVanillaCard
                && card.Effects.Any(e => IsCardTiming(e.Condition) && e.Condition!.Timing == "GivenKeyword"))
            .Select(card => n.CardClassName(p, card))
            .Distinct(StringComparer.Ordinal)
            .ToList();
    }

    /// <summary>
    /// 「卡牌时机」的效果里**不能用**「打出的目标」（本体那些钩子里没有 cardPlay.Target）。判据对着
    /// <see cref="EmitCardEffectOnce"/> 抄 —— 它里面碰 cardPlay.Target 的地方就是下面这几种：
    ///   · 一律用 cardPlay.Target 的：Stun（击晕）、TimesUp（大限已至）、PetSacrifice 的伤害收益；
    ///   · 只有「作用对象 = 敌人」那一档才用：Damage / Block / Heal / HpLoss / MaxHp / ApplyPower / TempPower /
    ///     DoublePower / ForbidBlock / ForbidHeal / Expose / ClearPowerOne / ClearPowerDebuffs
    ///     （Self / AllEnemies / RandomEnemies 这几档走 base.Owner 或 HittableEnemies，用不到它）；
    ///   · 「下回合生效」的那几档走的是另一个 Power（打给自己），也用不到。
    /// </summary>
    internal static bool TimingUsesPlayedTarget(EffectSpec e)
    {
        if (e.Kind == "Stun" || e.Kind == "TimesUp") return true;
        if (e.Kind == "PetSacrifice") return e.PetSacrificeGain == "Damage";
        // 「下回合生效」会改成打给自己的另一个状态（BlockNextTurnPower / 延迟 Power），用不到打出目标 ——
        // 只有这两种效果有这一档（别的效果的 NextTurn 不改变它打谁，所以不能一起放过）。
        if (e.NextTurn && e.Kind is "Block" or "ApplyPower") return false;
        if (e.Kind is not ("Damage" or "Block" or "Heal" or "HpLoss" or "MaxHp" or "ApplyPower" or "TempPower"
            or "DoublePower" or "ForbidBlock" or "ForbidHeal" or "Expose" or "ClearPowerOne" or "ClearPowerDebuffs"))
            return false;
        return e.TargetSide is "" or "Enemy";
    }

    /// <summary>
    /// 这张牌的 <c>TargetType</c>（AnyEnemy / AllEnemies / RandomEnemy / Self）。
    /// 校验器要用它判断「这张牌打出时到底有没有『选中的那个敌人』」——
    /// 「数值公式」里引用「指定敌人」的参数只有在 <c>AnyEnemy</c> 的牌上才有值（见 ProfileValidator）。
    /// </summary>
    public static string TargetTypeOf(CardSpec c) => ResolveTargetType(c);

    private static string ResolveTargetType(CardSpec c)
    {        // 能打敌人的效果（伤害 / 状态 / 格挡 / 回血 / 掉血 / 最大生命）决定这张牌的 TargetType
        // 「伙伴攻击」同理：打的是敌人（attacker 是宠物），卡牌也要变成需要选目标的那种。
        // 「牺牲伙伴」收益是伤害时同理（生成的是 .Targeting(cardPlay.Target)），收益是格挡时不算。
        static bool HitsEnemy(EffectSpec e) =>
            e.Kind is "Damage" or "ApplyPower" or "TempPower" or "Stun" or "Block" or "Heal" or "HpLoss" or "MaxHp"
            // 「大限已至」是本体 Time's Up 那种「指定敌人」的攻击牌（伤害 = 目标的灾厄层数），
            // 必须让这张牌变成要选目标的，否则打出去时 cardPlay.Target 是空的。
            or "TimesUp"
            // 翻倍 / 暴露 / 清除状态：都是「对目标身上的状态动手」，同样要让这张牌变成「要选目标」的
            or "DoublePower" or "Expose" or "ClearPowerOne" or "ClearPowerDebuffs" or "ForbidBlock"
            or "ForbidHeal"
            || PetAttackKind(e.Kind)
            || (e.Kind == "PetSacrifice" && e.PetSacrificeGain == "Damage");

        // 「数值 0 且升级也不加数值」的效果整条不生成（用户要求），所以它也不该让这张牌变成「要选目标」的
        bool effectChosenEnemy = c.Effects.Any(e => HitsEnemy(e) && !IsInertZero(e) && e.TargetSide == "Enemy");
        bool effectAllEnemies = c.Effects.Any(e => HitsEnemy(e) && !IsInertZero(e) && e.TargetSide == "AllEnemies");
        bool effectRandomEnemy = c.Effects.Any(e => HitsEnemy(e) && !IsInertZero(e) && e.TargetSide == "RandomEnemies");
        // 队友（用户要求）：「指定队友」= 本体 TargetType.AnyAlly（会弹目标选择，选中的队友进 cardPlay.Target），
        // 「全部队友」= AllAllies（不弹选择，遍历同一边的玩家单位、排除自己）。
        bool effectChosenAlly = c.Effects.Any(e => HitsEnemy(e) && !IsInertZero(e) && e.TargetSide == "Ally");
        bool effectAllAllies = c.Effects.Any(e => HitsEnemy(e) && !IsInertZero(e) && e.TargetSide == "AllAllies");

        // 锻造卡：图里那个【指向对象】模块**声明**了「这张牌在游戏里选中谁」（用户要求）——
        // 它比「从效果推」优先：因为这个模块存在的意义就是让「指定单体敌人」这类用法真的拿到 cardPlay.Target
        //（以前锻造卡永远推成 Self → cardPlay.Target 是 null → 图里写「指定单体敌人」全都拿到空目标）。
        // 「要选一个敌人」这一档还得和效果里推出来的取**并集**：效果自己要求选目标时不能不选。
        string? declared = ForgeGraphGen.DeclaredTargetType(c);
        if (declared is not null)
        {
            if (effectChosenEnemy || declared == "AnyEnemy") return "AnyEnemy";
            if (effectChosenAlly || declared == "AnyAlly") return "AnyAlly";
            if (declared == "AllEnemies" || effectAllEnemies) return "AllEnemies";
            if (declared == "AllAllies" || effectAllAllies) return "AllAllies";
            if (declared == "RandomEnemy" || effectRandomEnemy) return "RandomEnemy";
            return "Self";
        }

        // 「指定敌人」优先于「指定队友」：一张牌只有一个 TargetType，两者混用时按敌人处理，
        // 校验器会把这件事报出来（让用户自己决定留哪个）。
        if (effectChosenEnemy) return "AnyEnemy";
        if (effectChosenAlly) return "AnyAlly";
        if (effectAllEnemies) return "AllEnemies";
        if (effectAllAllies) return "AllAllies";
        if (effectRandomEnemy) return "RandomEnemy";
        return "Self";
    }

    /// <summary>
    /// 「生成 / 变化卡牌」的范围限定 + 「生成出来的卡怎么处理」的标记（回读靠它，见 ProjectRecovery）。
    ///
    /// 为什么不从代码里反推：这几个设置生成出来的都是**本体 API 的零散语句**
    /// （CardCmd.Upgrade / SetToFreeThisTurn / 一个临时的 ForgeTempUpgradePower…），
    /// 而「免费 / 仅本回合」这种差别只差一个方法名，反推很容易认错（而且老存档没有这些设置）。
    /// 标记一行写全，回读就一行读完。
    /// </summary>
    internal static string SpawnMarker(EffectSpec e, bool withKind = false) =>
        $"// CET:SpawnPick={e.SpawnPick} CET:SpawnFilter={(string.IsNullOrWhiteSpace(e.SpawnFilter) ? "-" : e.SpawnFilter)}"
        + $" CET:SpawnChoice={(int)Math.Max(1m, e.SpawnChoice)}"
        + $" CET:SpawnUp={(e.SpawnUpgraded ? 1 : 0)} CET:SpawnFree={(e.SpawnFree ? 1 : 0)}"
        + $" CET:SpawnFreeTurn={(e.SpawnFreeThisTurn ? 1 : 0)} CET:SpawnUpTurn={(e.SpawnUpgradedThisTurn ? 1 : 0)}"
        // 「范围界定」（需求 ③）的标记行只多带一个种类：这种标记是给选牌类效果写的，
        // 万一那条效果的代码没被回读认出来，也不会把范围配到**别的种类**的效果身上（见 ProjectRecovery 的 pendingSpawn）。
        + (withKind ? $" CET:Kind={e.Kind}" : "")
        // 需求 ⑦：「生成 / 变化出来的卡带上关键词」。**只在选了关键词时追加** —— 默认档（没选）
        // 的标记行必须与旧版逐字一致（老存档回读 / 生成代码一个字都不能变）。
        // 值原样写用户选的那个引用（本体枚举名或自定义关键词的键），回读时原样还原。
        + (e.HasSpawnKeyword ? $" CET:SpawnKeyword={e.SpawnKeyword.Trim()}" : "")
        // 「从范围里自己挑一张」（用户要求）：只在勾了的时候追加（默认档标记行逐字不变）。
        + (e.SpawnChosen ? " CET:Chosen=1" : "");

    /// <summary>
    /// 「生成卡牌」。
    ///
    /// 三种取卡方式：
    ///   · 「指定卡」（默认，老存档）→ <c>AddToCombatAndPreview&lt;卡类&gt;</c>（本体官方做法）；
    ///   · 「按范围随机」→ 从卡池里按范围（攻击 / 技能 / 能力 / 诅咒 / 状态 / 自定义关键词那一组）随机抽 N 张
    ///     （本体「发现 Discovery / 攻击药水 AttackPotion」用的就是 CardFactory.GetDistinctForCombat）；
    ///   · 「按范围随机 + 多选1（候选 M 张，M &gt; 1）」→ 先随机抽 M 张当候选，玩家**选一张**生成
    ///     （本体「发现 Discovery」就是这条路的原型：3 张里选 1 张）。
    /// 生成出来的卡还能带几个附加处理（升级 / 免费 / 仅本回合升级 / 仅本回合免费）—— 见 EmitSpawnModifiers。
    ///
    /// <paramref name="playerExpr"/> = **玩家那一侧**的表达式。卡牌 / 遗物 / 药水这三条链里
    /// <c>base.Owner</c> 本身就是 Player，所以默认值就是它（生成出来的文本与旧版逐字一致）；
    /// 需求 ⑥ 的自定义状态触发器链上 <c>base.Owner</c> 是 <c>Creature</c>，调用方传 <c>base.Owner.Player</c>。
    /// 这里**不复制第二份判据**：范围限定（<see cref="SpawnPoolExpr"/>）、附加处理（<see cref="EmitSpawnModifiers"/>）、
    /// 范围界定（<see cref="ScopeCondForFilter"/>）全都是同一批函数，只是「上下文表达式」不同。
    /// 需求 ⑥ 把它开成 internal 就是为了让 <c>CustomPowerGen</c> 那条链直接复用（而不是抄一份）。
    ///
    /// <paramref name="withMarker"/> / <paramref name="withComment"/> 只服务一件事：让**默认档逐字一致**。
    /// 「自定义状态的触发器」那条链原本是手写的一行 <c>AddToCombatAndPreview</c>，既没有 <c>CET:SpawnPick=…</c>
    /// 标记行、也没有「生成 N 张…」那句注释；现在换成复用这个函数，就必须把这两处压回原样
    /// （否则用户一个选项都不改、重新生成，代码文本也会变）。那条链上标记里读出来的 <c>SpawnPick</c> 默认就是
    /// <c>Fixed</c>、其余字段默认就是 0/空 —— 不写不影响回读，所以只在真的用上「按范围随机 / 附加处理 /
    /// 范围界定」时才写标记（那几样没有标记就回读不出来）。
    /// 卡牌 / 遗物 / 药水三条链一律用默认值（true / true），文本与旧版逐字一致。
    ///
    /// <paramref name="playerArg"/> = 只在那一条 <c>AddToCombatAndPreview</c> 里传的「玩家」实参。
    /// 卡牌 / 遗物 / 药水那三条链原来写的是 <c>base.Owner</c>；自定义状态那条链原来写的是 <c>base.Owner.Player</c>
    /// （两种写法指向同一个 Player，只是文本不同）—— 为了默认档逐字一致才留这个参数。
    /// 「仅本回合升级」那个 Power 的 Apply 实参 = <paramref name="tempUpSource"/>：
    /// 卡牌那几条链旧写法是 <c>this</c>、遗物 / 药水 / 自定义状态是 <c>null</c>（那几个 context 里没有「这张牌」）。
    /// 为了默认档逐字一致，这个实参由调用方按链给。
    /// </summary>
    internal static void EmitGenerateCard(CodeWriter w, CharacterProfile p, EffectSpec e, bool useX = false, string? countExpr = null,
        string tempUpSource = "this", string playerExpr = "base.Owner", bool withMarker = true,
        string? creatureExpr = null, bool withComment = true, string playerArg = "base.Owner")
    {
        // 玩家那个 Creature 的表达式：卡牌 / 遗物 / 药水那三条链里 base.Owner 就是 Player，所以是 owner.Creature。
        // 自定义状态那条链的默认档传的 playerExpr 直接就是 Creature（base.Owner），这时调用方会显式给 creatureExpr。
        creatureExpr ??= playerExpr + ".Creature";
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        string pile = e.SpawnToPile;
        string? tempUp = e.SpawnUpgradedThisTurn ? "__tempUp" : null;
        if (withMarker) w.Line(SpawnMarker(e));
        if (!e.IsSpawnRandom)
        {
            string card = string.IsNullOrWhiteSpace(e.SpawnCardId) ? "Shiv" : e.SpawnCardId!.Trim();
            if (withComment) w.Line($"// 生成 {nC} 张 {card} 放进{PileZh(pile)}");
            if (!e.HasSpawnModifier)
            {
                w.Line($"await CardPileCmd.AddToCombatAndPreview<{card}>({creatureExpr}, PileType.{pile}, {n}, {playerArg});");
                return;
            }
            // 要改「生成出来的卡」就得自己 CreateCard：AddToCombatAndPreview 内部拿不到那些实例
            EmitTempUpgradePowerApply(w, tempUp, tempUpSource, creatureExpr);
            w.Open($"for (int __genIdx = 0; __genIdx < {n}; __genIdx++)");
            w.Line($"CardModel __gen = {creatureExpr}.CombatState.CreateCard(ModelDb.Card<{card}>(), {playerExpr});");
            EmitSpawnModifiers(w, e, "__gen", tempUp, p, playerExpr, creatureExpr);
            w.Line($"await CardPileCmd.AddGeneratedCardToCombat(__gen, PileType.{pile}, {playerExpr});");
            w.Close();
            return;
        }

        string pool = SpawnPoolExpr(e, p, playerExpr);
        // 「从范围里**自己挑**一张」（用户要求：范围组里的卡以前只能随机抽候选，不能自己选）：
        // 候选 = 这一组范围里的**全部卡**（不随机抽），玩家想拿哪张就拿哪张。
        // 本体 `CardSelectCmd.FromChooseACardScreen` 候选 > 3 会直接抛 ArgumentException，所以 > 3 走「简单网格」。
        if (e.SpawnChosen)
        {
            // 整段写成「自己搞定一整段」：标记行带全信息（种类 / 数值 / 范围），回读时整段跳过 ——
            // 不然候选表 / 那两句选牌调用会被当成没认出来的语句（探针实测过）。
            // 候选表变量名用 `__chosenCand`（**不要**和「多选1」那套 `__candidates` 重名：
            // 回读的跳过规则是按变量名认的，重名会把「多选1」那一段也一起跳过 / 互相干扰）。
            w.Line(SelfContainedMarker(e));
            w.Line($"// 从「{EffectCatalog.SpawnFilterZh(e.SpawnFilter)}」里自己挑一张生成（候选 = 这一组里的全部卡）");
            w.Line($"var __genPool = {pool};");
            w.Line("List<CardModel> __chosenCand = __genPool.Take(60).ToList();   // 上限 60：再多选牌界面摆不下");
            w.Open("if (__chosenCand.Count > 0)");
            EmitTempUpgradePowerApply(w, tempUp, tempUpSource, creatureExpr);
            // 一句写完（不要换行）：回读的跳过名单是按「CardModel? __picked = 」这一行前缀认的。
            w.Line($"CardModel? __picked = __chosenCand.Count <= 3 ? await CardSelectCmd.FromChooseACardScreen(choiceContext, __chosenCand, {playerExpr}, canSkip: false) : (await CardSelectCmd.FromSimpleGrid(choiceContext, __chosenCand, {playerExpr}, new CardSelectorPrefs(base.SelectionScreenPrompt, 1))).FirstOrDefault();");
            w.Open("if (__picked is not null)");
            EmitSpawnModifiers(w, e, "__picked", tempUp, p, playerExpr, creatureExpr);
            w.Line($"await CardPileCmd.AddGeneratedCardToCombat(__picked, PileType.{pile}, {playerExpr});");
            w.Close();
            w.Close();
            return;
        }
        // 多选1：先随机抽 M 张候选，玩家选 1 张（生成 1 张 —— 「数值」这时是候选张数，不是生成张数）
        if (e.SpawnChoice > 1m)
        {
            int m = Math.Max(2, Math.Min(60, (int)e.SpawnChoice));
            w.Line($"// 按范围随机：先从「{EffectCatalog.SpawnFilterZh(e.SpawnFilter)}」里抽 {m} 张当候选，玩家选 1 张放进{PileZh(pile)}");
            w.Line($"var __genPool = {pool};");
            w.Line($"List<CardModel> __candidates = MegaCrit.Sts2.Core.Factories.CardFactory.GetDistinctForCombat({playerExpr}, __genPool, {m}, {playerExpr}.RunState.Rng.CombatCardGeneration).ToList();");
            // 池子比 M 小的时候会少给几张：本体「发现」在这一步是直接 ReportSoftlock 的，
            // 这里改成「有就选、一张都没有就整条跳过」（下面那个 if 就是干这个的），免得把牌卡死。
            w.Open("if (__candidates.Count > 0)");
            EmitTempUpgradePowerApply(w, tempUp, tempUpSource, creatureExpr);
            // 本体 CardSelectCmd.FromChooseACardScreen 在候选 > 3 时**直接抛 ArgumentException**，
            // 所以 > 3 走「简单网格」选牌界面（本体的「抉择悖论 ChoicesParadox」用的就是它，正好是「N 张里选 1 张」）。
            w.Line(m <= 3
                ? $"CardModel? __picked = await CardSelectCmd.FromChooseACardScreen(choiceContext, __candidates, {playerExpr}, canSkip: false);"
                : $"CardModel? __picked = (await CardSelectCmd.FromSimpleGrid(choiceContext, __candidates, {playerExpr}, new CardSelectorPrefs(base.SelectionScreenPrompt, 1))).FirstOrDefault();");
            w.Open("if (__picked is not null)");
            EmitSpawnModifiers(w, e, "__picked", tempUp, p, playerExpr, creatureExpr);
            w.Line($"await CardPileCmd.AddGeneratedCardToCombat(__picked, PileType.{pile}, {playerExpr});");
            w.Close();
            w.Close();
            return;
        }

        // 按范围随机：从卡池里抽 N 张（不重复）
        w.Line($"// 按范围随机生成 {nC} 张「{EffectCatalog.SpawnFilterZh(e.SpawnFilter)}」放进{PileZh(pile)}");
        w.Line($"var __genPool = {pool};");
        EmitTempUpgradePowerApply(w, tempUp, tempUpSource, creatureExpr);
        w.Line($"foreach (CardModel __gen in MegaCrit.Sts2.Core.Factories.CardFactory.GetDistinctForCombat({playerExpr}, __genPool, {n}, {playerExpr}.RunState.Rng.CombatCardGeneration))");
        w.Open("");
        EmitSpawnModifiers(w, e, "__gen", tempUp, p, playerExpr, creatureExpr);
        w.Line($"await CardPileCmd.AddGeneratedCardToCombat(__gen, PileType.{pile}, {playerExpr});");
        w.Close();
    }

    /// <summary>
    /// 「获得药水」（需求 ⑨）。两档：
    ///   · <b>指定药水</b>（默认档）→ <c>PotionCmd.TryToProcure&lt;本体药水类名&gt;(玩家)</c>。
    ///     为什么用泛型版：本体源码里它就是 <c>ModelDb.Potion&lt;T&gt;().ToMutable()</c> 再走带实例的那条重载，
    ///     而带实例的重载会 <c>potion.AssertMutable()</c> —— 直接把池子里的规范模型传进去会抛
    ///     <c>CanonicalModelException</c>。泛型版把「取规范模型 + 变可变副本」一步做掉，最不容易写错。
    ///     <c>PotionCmd</c> 在 <c>MegaCrit.Sts2.Core.Commands</c>（已有 global using），
    ///     药水类名在 <c>MegaCrit.Sts2.Core.Models.Potions</c>（**没有** global using，所以这里写全名，
    ///     和仓库里 <c>MegaCrit.Sts2.Core.Factories.CardFactory</c> 的写法一致 —— 也避免动全局 using 影响所有工程）。
    ///   · <b>随机药水</b> → 本体卡「炼制药水 Alchemize」的原样写法：
    ///     <c>PotionFactory.CreateRandomPotionInCombat(player, player.RunState.Rng.CombatPotionGeneration).ToMutable()</c>
    ///     + <c>TryToProcure(...)</c>；不在战斗里（遗物「获得时」那种）换成 <c>CreateRandomPotionOutOfCombat</c>，
    ///     否则会被 <c>CanBeGeneratedInCombat</c> 把治疗类药水全挡掉（随机范围白白变小）。
    ///
    /// <b>药水栏满</b>：本体 <c>TryToProcure</c> 会返回 <c>success = false</c>（源码注释：*Can fail if the
    /// potions bar is full*），这里**什么都不做** —— 不丢弃、不替换已有药水、不弹提示（用户要求的行为），
    /// 但卡面描述里写明了「（药水栏满时不会发生任何事）」，不静默。
    ///
    /// 数值 = 瓶数（写死在代码里，不声明动态变量，和「生成卡牌」同一套规矩）。
    /// <paramref name="playerExpr"/> = 玩家那一侧：卡牌 / 遗物 / 药水三条链是 <c>base.Owner</c>，
    /// 自定义状态触发器里是 <c>base.Owner.Player</c>（那里 base.Owner 是 Creature）。
    /// </summary>
    internal static void EmitGainPotion(CodeWriter w, EffectSpec e, bool useX = false, string playerExpr = "base.Owner",
        string? countExpr = null)
    {
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        string nText = countExpr is null ? $" {n} 瓶" : "（瓶数 = 本状态的层数）";
        string? potion = string.IsNullOrWhiteSpace(e.PotionId) ? null : e.PotionId!.Trim();
        // 数值 1 时不套循环（生成出来的代码干净些）；> 1 / = X / = 层数时套一层 for。
        bool loop = n != "1";
        w.Line(PotionMarker(e));
        if (!e.IsPotionRandom)
        {
            if (potion is null)
            {
                // 没选药水：不生成任何语句（参数面板上会显示「（未选）」，校验器另有错误拦住）。
                // 只写注释 —— 回读靠上面那行标记，注释不会被当成别的效果。
                w.Line("// ⚠ 没选「目标药水」：这条「获得药水」不会做任何事（请在效果面板上选一瓶，"
                    + "或者把「取药方式」改成「随机药水」）。");
                return;
            }
            w.Line($"// 获得{nText}「{EffectCatalog.FindPotionZh(potion)}」：本体 PotionCmd.TryToProcure<T>"
                + "（内部就是 ModelDb.Potion<T>().ToMutable()）。");
            w.Line("// 药水栏满时本体返回 success=false —— 这里什么都不发生（不会丢掉 / 替换你已经有的药水）。");
            if (loop) w.Open($"for (int __potionIdx = 0; __potionIdx < {n}; __potionIdx++)");
            w.Line($"await PotionCmd.TryToProcure<MegaCrit.Sts2.Core.Models.Potions.{potion}>({playerExpr});");
            if (loop) w.Close();
            return;
        }
        w.Line($"// 获得{nText}随机药水：本体卡「炼制药水」的原样写法（PotionFactory + ToMutable + TryToProcure）。");
        w.Line("// 战斗外的触发时机（遗物「获得时」那种）走 OutOfCombat 版，否则治疗类药水会被排除在随机范围外。");
        w.Line("// 药水栏满时本体返回 success=false —— 这里什么都不发生（不会丢掉 / 替换你已经有的药水）。");
        if (loop) w.Open($"for (int __potionIdx = 0; __potionIdx < {n}; __potionIdx++)");
        w.Line($"PotionModel __randPotion = {playerExpr}.Creature.CombatState is null");
        w.Line($"    ? MegaCrit.Sts2.Core.Factories.PotionFactory.CreateRandomPotionOutOfCombat({playerExpr}, {playerExpr}.RunState.Rng.CombatPotionGeneration)");
        w.Line($"    : MegaCrit.Sts2.Core.Factories.PotionFactory.CreateRandomPotionInCombat({playerExpr}, {playerExpr}.RunState.Rng.CombatPotionGeneration);");
        w.Line($"await PotionCmd.TryToProcure(__randPotion.ToMutable(), {playerExpr});");
        if (loop) w.Close();
    }

    /// <summary>
    /// 「获得药水」的标记行（回读用，见 ProjectRecovery 的 <c>CET:Effect=</c> 分支）。
    ///
    /// 为什么要标记：这一档的实现就是一句 <c>TryToProcure</c>（随机档那句里还套着 PotionFactory），
    /// 「指定还是随机 / 指定的是哪一瓶」都没法从语句里可靠反推 —— 随机档连药水名都没有。
    /// <c>CET:PotionPick</c> 只在**不是默认档（Fixed）**时才追加、<c>CET:Potion</c> 只在真的选了药水时才写：
    /// 缺项回读时按默认值补，老工程（没有这个种类）本来就不会有这一行。
    /// </summary>
    internal static string PotionMarker(EffectSpec e) =>
        SelfContainedMarker(e)
        + (e.IsPotionRandom ? " CET:PotionPick=Random" : "")
        + (string.IsNullOrWhiteSpace(e.PotionId) ? "" : $" CET:Potion={e.PotionId!.Trim()}");

    /// <summary>
    /// 勾了「仅在此回合升级」时，先挂上生成的那个「回合结束降回来」的状态（只挂一次，生成出来的卡都交给它）。
    /// </summary>
    private static void EmitTempUpgradePowerApply(CodeWriter w, string? tempUpVar, string cardSource,
        string creatureExpr = "base.Owner.Creature")
    {
        if (tempUpVar is null) return;
        // 最后那个实参（source）卡牌那几条链是 this、遗物 / 药水 / 自定义状态是 null，
        // 所以由调用方给（见 EmitGenerateCard 的 tempUpSource 说明）。
        w.Line("// 仅本回合升级：挂一个「回合结束时把它们降回来」的状态（下面的 Track 负责升级并记住是哪几张）");
        w.Line($"var {tempUpVar} = await PowerCmd.Apply<{Naming.AmbientTempUpgradePowerClass}>(choiceContext, {creatureExpr}, 1m, {creatureExpr}, {cardSource});");
    }

    /// <summary>
    /// 「生成 / 变化出来的卡」的附加处理：升级 / 免费打出 / 仅本回合免费 / 仅本回合升级。
    ///
    /// 本体 API（都在 <c>CardModel</c> / <c>CardEnergyCost</c> 上）：
    ///   · 升级 → <c>CardCmd.Upgrade(card)</c>（本体 Apotheosis / Armaments / Whetstone 都这么升）；
    ///   · 免费（本场战斗）→ <c>card.SetToFreeThisCombat()</c>（本体 Metamorphosis 那种）；
    ///   · 仅本回合免费 → <c>card.SetToFreeThisTurn()</c>（本体 InfernalBlade / AttackPotion 生成牌就是它）；
    ///   · 仅本回合升级 → 本体**没有**这种 API（只有视觉预览 CardUpgradePreviewType），
    ///     所以升级之后把这张牌交给生成的 <c>&lt;角色&gt;ForgeTempUpgradePower</c>，
    ///     它在回合结束时把「这次真的升上去的那几张」降回来（本来就是升级过的牌不碰）。
    ///
    /// <paramref name="playerExpr"/> / <paramref name="creatureExpr"/>：见 <see cref="EmitSpawnKeyword"/>。
    /// </summary>
    internal static void EmitSpawnModifiers(CodeWriter w, EffectSpec e, string cardVar, string? tempUpVar = null,
        CharacterProfile? p = null, string playerExpr = "base.Owner", string creatureExpr = "base.Owner.Creature")
    {
        if (e.SpawnUpgradedThisTurn)
        {
            // Track 里做「本来就是升级过的就不动」的判断 + 升级 + 记住它
            if (tempUpVar is not null)
                w.Line($"if ({tempUpVar} is not null) {tempUpVar}.Track({cardVar}); else CardCmd.Upgrade({cardVar});");
        }
        else if (e.SpawnUpgraded)
        {
            w.Line($"CardCmd.Upgrade({cardVar});");
        }
        if (e.SpawnFree) w.Line($"{cardVar}.SetToFreeThisCombat();");
        if (e.SpawnFreeThisTurn) w.Line($"{cardVar}.SetToFreeThisTurn();");
        // 需求 ⑦：给生成 / 变化出来的这张卡加上关键词（没选就一行都不写）
        EmitSpawnKeyword(w, e, cardVar, p, playerExpr, creatureExpr);
    }

    /// <summary>
    /// 需求 ⑦：「生成 / 变化出来的卡：加上关键词」的生成代码。
    ///
    /// 复用「给予卡牌关键词」那份实现（<see cref="EmitGiveKeywordTo"/>）—— 本体关键词走
    /// <c>AddKeyword(CardKeyword.X)</c>，自定义关键词走 <c>AddGivenCustomKeyword</c>
    /// + 本地化词条 + 悬停说明那一套，这里不另写一份。
    /// 和「给予」只有两点不同：
    ///   · 作用对象就是刚生成出来的那张卡（调用方把变量名传进来）；
    ///   · **没有「临时」档** —— 生成出来的本来就是新卡，回合结束再摘掉没有意义，所以固定按永久关键词生成。
    ///
    /// <paramref name="playerExpr"/> / <paramref name="creatureExpr"/> = 玩家 / 玩家那个 Creature 的表达式：
    /// 卡牌 / 遗物 / 药水那三条链里 <c>base.Owner</c> 就是 Player，默认值即它们（逐字不变）；
    /// 需求 ⑥ 的自定义状态触发器链上 <c>base.Owner</c> 是 Creature，调用方传 <c>base.Owner.Player</c> + <c>base.Owner</c>。
    /// （这两个表达式只在「临时关键词」那条分支里真的用到，而需求 ⑦ 固定永久，所以那边用不上。）
    /// </summary>
    internal static void EmitSpawnKeyword(CodeWriter w, EffectSpec e, string cardVar, CharacterProfile? p = null,
        string playerExpr = "base.Owner", string creatureExpr = "base.Owner.Creature")
    {
        string raw = (e.SpawnKeyword ?? "").Trim();
        if (raw.Length == 0) return;   // 默认档：一个字符都不写（生成代码与旧版逐字一致）
        var kw = ResolveKeyword(raw, p);
        if (kw.Custom && kw.Key.Length == 0)
        {
            // 只有「遗物上的变化卡牌」那条链会走到这里（那里拿不到角色配置）：
            // 界面上选的自定义关键词存的就是键，所以正常配置不会落空；手改存档写成中文名才会。
            w.Line($"// 生成出来的卡要带的关键词「{raw}」在这里认不出来（这条链上没有角色配置），这一项已忽略");
            return;
        }
        w.Line($"// 生成出来的卡带上关键词：{(kw.Custom ? "自定义关键词 " + kw.Key : kw.Enum)}");
        EmitGiveKeywordTo(w, e, cardVar, creatureExpr, "this", kw.Custom, kw.Enum, kw.Key, tempOverride: false);
    }

    /// <summary>
    /// 关键词引用 → 「是不是自定义关键词 / 本体枚举名 / 自定义关键词的键」。
    /// 「给予卡牌关键词」和需求 ⑦ 的「生成出来的卡带关键词」共用这一份解析，避免两处写法漂移。
    /// </summary>
    private static (bool Custom, string Enum, string Key) ResolveKeyword(string raw, CharacterProfile? p)
    {
        bool customKw = !EffectCatalog.IsVanillaKeywordName(raw);
        string kwEnum = EffectCatalog.NormalizeVanillaKeyword(raw) ?? "Retain";
        // 拿不到 profile 的地方（遗物那条变化链 / 自定义状态的钩子链）：用户在下拉里选的**已经是键**，规范化一下就够
        string customKey = !customKw ? "" : (p is null ? KeywordGen.NormalizeKeyText(raw) : KeywordGen.KeyOfReference(p, raw));
        return (customKw, kwEnum, customKey);
    }

    /// <summary>
    /// 「按范围随机」时的候选卡池表达式：
    ///   · 攻击 / 技能 / 能力 / 不限 → 角色卡池（+ 不限时也带上无色卡池？不加：本体的「发现」只用自己的角色卡池）；
    ///   · 诅咒 → 本体的诅咒卡池 + 你自己的卡池里的诅咒（你自己的诅咒也在这里面）；
    ///   · 状态 → 本体的状态卡池（伤口 / 灼伤 / 眩晕那种）+ 你自己的卡池里的状态牌；
    ///   · <c>Keyword:XXX</c> → **自定义关键词那一组牌**（把关键词当成「卡的组」用）：
    ///     生成期就能查出哪些牌带这个关键词（CardSpec.CustomKeywordList），所以直接列成显式牌表
    ///     （不走卡池过滤 —— 这样诅咒 / 先古卡只要标了关键词也照样进这一组）。
    /// 分数卡池一律按 <c>GetUnlockedCards</c> 走（和本体一致，会过滤掉没解锁 / 多人限制的牌）。
    /// </summary>
    private static string SpawnPoolExpr(EffectSpec e, CharacterProfile? p = null, string owner = "base.Owner")
    {
        // 自定义关键词 / 组：直接列出那一组牌的类
        if (EffectCatalog.IsKeywordFilter(e.SpawnFilter) || EffectCatalog.IsCardGroupFilter(e.SpawnFilter))
        {
            var group = EffectCatalog.IsCardGroupFilter(e.SpawnFilter)
                ? EffectCatalog.CardGroupCards(p, e.SpawnFilter)
                : EffectCatalog.KeywordGroupCards(p, e.SpawnFilter);
            if (group.Count == 0)
                return "new List<CardModel>()";
            var kn = Naming.From(p!);
            return "new List<CardModel> { " + string.Join(", ", group.Select(c => $"ModelDb.Card<{kn.CardClassName(p!, c)}>()")) + " }";
        }
        string charPool = $"{owner}.Character.CardPool.GetUnlockedCards({owner}.UnlockState, {owner}.RunState.CardMultiplayerConstraint)";
        string filter = e.SpawnFilter switch
        {
            "Attack" => "c => c.Type == CardType.Attack",
            "Skill" => "c => c.Type == CardType.Skill",
            "Power" => "c => c.Type == CardType.Power",
            // 诅咒 / 状态：本体的那两个卡池里的 + 你自己卡池里的（你做的诅咒 / 状态牌也在自己卡池里）
            "Curse" => "c => c.Rarity == CardRarity.Curse",
            "Status" => "c => c.Type == CardType.Status || c.Rarity == CardRarity.Status",
            _ => "c => true",
        };
        string extra = e.SpawnFilter switch
        {
            "Curse" => $"{charPool}.Concat(ModelDb.CardPool<CurseCardPool>().GetUnlockedCards({owner}.UnlockState, {owner}.RunState.CardMultiplayerConstraint))",
            "Status" => $"{charPool}.Concat(ModelDb.CardPool<StatusCardPool>().GetUnlockedCards({owner}.UnlockState, {owner}.RunState.CardMultiplayerConstraint))",
            _ => charPool,
        };
        return $"{extra}.Where({filter}).Distinct().ToList()";
    }

    /// <summary>
    /// 放置卡牌（用户要求的新效果）：
    ///   · **数值 0 = 这张牌自己**（<paramref name="selfExpr"/> 非空才有意义 —— 只有卡牌链有「这张牌」）：
    ///     <c>await CardPileCmd.Add(this, PileType.X, position)</c>；
    ///   · **数值 ≥ 1** = 从「从哪里选牌」那一摞挑 N 张（自己选 / 随机 / 牌顶），
    ///     再放到「放到哪一摞」（含**牌顶** = <c>CardPilePosition.Top</c>）。
    ///
    /// 本体 API：<c>CardPileCmd.Add(card|cards, PileType, CardPilePosition)</c>
    /// （默认位置是 <c>Bottom</c>，「牌顶」就传 <c>Top</c>）。
    /// </summary>
    private static void EmitPlaceCard(CodeWriter w, CharacterProfile? p, EffectSpec e, bool useX = false,
        string? countExpr = null, string? selfExpr = null, string playerExpr = "base.Owner", string? cardSource = null)
    {
        string toPile = e.PlaceTo switch
        {
            "Draw" or "Top" => "PileType.Draw",
            "Discard" => "PileType.Discard",
            "Exhaust" => "PileType.Exhaust",
            _ => "PileType.Hand",
        };
        string pos = e.PlaceTo == "Top" ? "CardPilePosition.Top" : "CardPilePosition.Bottom";
        string toZh = EffectCatalog.PlacePileZh(e.PlaceTo);
        // 「自己搞定一整段」的标记行：这条效果的实现有好几行（选牌 / 循环 / Add），
        // 回读时逐行猜会认错（`CardPileCmd.Add` 到处都是）—— 标记行把数值 / 放到哪一摞 / 从哪拿 / 选牌方式全带上。
        // ⚠ 「取几张」的非默认档标记（CET:CountMode）必须写在它**前面**：回读是「先攒着、等这条效果的
        //   标记出现时配上去」，写在后面就配不到这条效果上了（踩过：PlaceCard 的「全部」回读后档位丢了）。
        CountModeMarker(w, e);
        w.Line(SelfContainedMarker(e));

        // 数值 0 = 这张牌自己
        if (!(useX && e.AmountIsXEffective) && e.Amount <= 0m)
        {
            if (selfExpr is null)
            {
                Warn(w, e, "（数值 0 = 这张牌自己：只有卡牌上有「这张牌」—— 遗物 / 药水请把数值填 ≥ 1）");
                return;
            }
            w.Line($"// 把这张牌自己放到{toZh}");
            w.Line($"await CardPileCmd.Add({selfExpr}, {toPile}, {pos});");
            return;
        }

        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);
        string pileZh = EffectCatalog.SelectPileZh(e.SelectPile);
        string pileExpr = PileExpr(e, playerExpr);
        string? pred = CardScopePredicate(e, p);
        if (e.CountIsAll)
        {
            // 「全部」：把那一摞里符合条件的牌一次全放到目标那一摞（不弹选牌界面）。
            w.Line($"// 全部：把{pileZh}里符合条件的牌**全部**放到{toZh}{ScopeZhSuffix(e)}（不弹选牌界面）");
            w.Line($"var __place = {CardScopeFiltered(e, p, $"{pileExpr}.Cards")}.ToList();");
            w.Line($"if (__place.Count > 0) await CardPileCmd.Add(__place, {toPile}, {pos});");
        }
        else if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            w.Line($"// 自己从{pileZh}选 {nC} 张放到{toZh}{ScopeZhSuffix(e)}");
            string prefs = SelectPrefsExpr(e, "base.SelectionScreenPrompt", n);
            if (e.SelectPile == "Hand")
                w.Line($"var __place = (await CardSelectCmd.FromHand(context: choiceContext, player: {playerExpr}, prefs: {prefs}, filter: {pred ?? "null"}, source: {cardSource ?? "this"})).ToList();");
            else
                w.Line($"var __place = (await CardSelectCmd.FromCombatPile(choiceContext, {pileExpr}, {playerExpr}, {prefs}{(pred is null ? "" : ", " + pred)})).ToList();");
            w.Line($"if (__place.Count > 0) await CardPileCmd.Add(__place, {toPile}, {pos});");
        }
        else
        {
            string scope = CardScopeFiltered(e, p, $"{pileExpr}.Cards");
            w.Line(IsPileTop(e)
                ? $"// 从牌顶（抽牌堆最上面那张）拿 {nC} 张放到{toZh}（不用挑）{ScopeZhSuffix(e)}"
                : $"// 随机从{pileZh}拿 {nC} 张放到{toZh}{ScopeZhSuffix(e)}");
            w.Open($"for (int __placeIdx = 0; __placeIdx < {n}; __placeIdx++)");
            w.Line($"CardModel? __placeCard = {PickOne(e, $"{playerExpr}.RunState.Rng.CombatCardSelection.NextItem({scope})", $"{scope}.FirstOrDefault()")};");
            w.Line("if (__placeCard is null) break;");
            w.Line($"await CardPileCmd.Add(__placeCard, {toPile}, {pos});");
            w.Close();
        }
    }

    /// <summary>选牌用的那一摞牌（本体写法：PileType.X.GetPile(player)）。四摞都是战斗牌堆。</summary>
    private static string PileExpr(EffectSpec e, string player = "base.Owner") =>
        e.SelectPile switch
        {
            "Draw" or "Top" => $"PileType.Draw.GetPile({player})",
            "Discard" => $"PileType.Discard.GetPile({player})",
            "Exhaust" => $"PileType.Exhaust.GetPile({player})",
            _ => $"PileType.Hand.GetPile({player})",
        };

    /// <summary>
    /// 「牌顶」（用户要求：选牌 / 取牌方式里多一个「牌顶」）：抽牌堆**最上面那张** —— 直接拿走，
    /// **不问玩家、也不随机**（要 N 张就从上往下依次拿）。
    /// 本体抽牌堆的 <c>Cards</c> 是「顶在前」（本体的「预见 Scry」取的就是前 N 个），所以
    /// <c>PileExpr</c> 在 Top 这一档给的就是抽牌堆，取法只要把「随机抓一张」换成「拿最上面那张」。
    /// </summary>
    public static bool IsPileTop(EffectSpec e) => string.Equals(e.SelectPile, "Top", StringComparison.Ordinal);

    /// <summary>按「是不是牌顶那一档」在两种取法之间选一个（随机抓一张 / 拿最上面那张）。</summary>
    private static string PickOne(EffectSpec e, string randomExpr, string topExpr) =>
        IsPileTop(e) ? topExpr : randomExpr;

    // ==================== 「范围界定」（需求 ③：选牌类效果只对某一类牌 / 某一组牌动手）====================
    // 和「生成 / 变化卡牌」那套**共用同一个 SpawnFilter 字段与同一份选项表**，只是用在「候选池」上：
    //   不限（空）/ Attack / Skill / Power / Curse / Status / Keyword:XXX（自定义关键词那一组）。
    // 关键约定：**范围为空时一律返回 null / 原样表达式** —— 生成出来的文本和以前逐字一致（回归要求）。

    /// <summary>
    /// 范围界定的**条件部分**（不含 <c>c =&gt; </c>，方便和「只能升级的牌」这类已有条件用 &amp;&amp; 拼）。
    /// 返回 null = 没设范围（调用处原样输出，行为与旧版完全一致）。
    /// </summary>
    internal static string? CardScopeCond(EffectSpec e, CharacterProfile? p) =>
        e.HasCardScope ? ScopeCondForFilter(e.SpawnFilter, p) : null;

    /// <summary>
    /// 把「一个范围 Id」翻成生成期的显式条件（不含 <c>c =&gt; </c>）。
    /// 抽出来是因为**刮削的条件那一栏用的就是同一份选项表**（攻击 / 技能 / 能力 / 诅咒 / 状态 /
    /// 自定义关键词那一组 / 组），那边不是「范围界定」（字段是 ScrapeCond），但判据必须一模一样 ——
    /// 与其复制一份，不如两边都走这一个函数（见 <see cref="ScrapeCondExpr"/>）。
    /// 返回 null = 不限（空 Id）。
    /// </summary>
    internal static string? ScopeCondForFilter(string? filterId, CharacterProfile? p)
    {
        string f = (filterId ?? "").Trim();
        if (f.Length == 0) return null;
        // 自定义关键词 / 组那一组：这两样都是我们自己的标注（游戏里没有对应枚举），运行时过滤不出来，
        // 只能在生成期把「这一组有哪些牌」查成显式条件。牌的身份用 ModelId（本体就是按类名算的，
        // 战斗里的牌是规范模型的 MemberwiseClone，Id 一样）。
        if (EffectCatalog.IsKeywordFilter(f) || EffectCatalog.IsCardGroupFilter(f))
        {
            var group = EffectCatalog.IsCardGroupFilter(f)
                ? EffectCatalog.CardGroupCards(p, f)
                : EffectCatalog.KeywordGroupCards(p, f);
            if (p is null || group.Count == 0) return "false";      // 空组 / 拿不到配置：谁也不匹配（校验器已经报过错）
            var kn = Naming.From(p);
            return string.Join(" || ", group.Select(c => $"c.Id == ModelDb.Card<{kn.CardClassName(p, c)}>().Id"));
        }
        return f switch
        {
            "Attack" => "c.Type == CardType.Attack",
            "Skill" => "c.Type == CardType.Skill",
            "Power" => "c.Type == CardType.Power",
            "Curse" => "c.Rarity == CardRarity.Curse",
            "Status" => "c.Type == CardType.Status || c.Rarity == CardRarity.Status",
            _ => null,
        };
    }

    /// <summary>范围界定的谓词（<c>c =&gt; …</c>）；没设范围返回 null（给 CardSelectCmd 的 filter 参数用）。</summary>
    internal static string? CardScopePredicate(EffectSpec e, CharacterProfile? p)
    {
        string? cond = CardScopeCond(e, p);
        return cond is null ? null : $"c => {cond}";
    }

    /// <summary>把范围界定套在「候选牌」表达式上（没设范围 → 原样返回，生成的文本与旧版逐字一致）。</summary>
    internal static string CardScopeFiltered(EffectSpec e, CharacterProfile? p, string cardsExpr)
    {
        string? pred = CardScopePredicate(e, p);
        return pred is null ? cardsExpr : $"{cardsExpr}.Where({pred})";
    }

    /// <summary>和已有条件（例如「只能升级的牌」）拼成一个谓词：两个都有就 &amp;&amp; 起来。</summary>
    private static string CombineCond(string existingCond, string? scopeCond) =>
        scopeCond is null ? existingCond : $"({existingCond}) && ({scopeCond})";

    /// <summary>
    /// 要不要为这条效果写「范围界定」的标记行。
    /// 只有**真的设了范围**才写：这样「范围为空」的老配置生成出来的文本与旧版逐字一致（回归由自检钉死）。
    /// 「生成 / 变化 / 全局加牌」那几种本来就有标记行（<see cref="EffectSpec.UsesSpawnOptions"/>），不重复写。
    /// </summary>
    private static bool NeedsCardScopeMarker(EffectSpec e) => e.HasCardScope && !e.UsesSpawnOptions;

    /// <summary>范围界定的标记行（只有 <see cref="NeedsCardScopeMarker"/> 为真时才写）。</summary>
    private static string? CardScopeMarker(EffectSpec e) =>
        NeedsCardScopeMarker(e) ? SpawnMarker(e, withKind: true) : null;

    /// <summary>「范围界定」在注释 / 描述用的中文后缀（没设范围就空）。</summary>
    private static string ScopeZhSuffix(EffectSpec e) => e.HasCardScope ? $"（范围界定：{EffectCatalog.SpawnFilterZh(e.SpawnFilter)}）" : "";

    /// <summary>
    /// 消耗卡牌（参考铁甲战士的「坚毅」TrueGrit）：自选用 CardSelectCmd，随机用 Rng 抓牌。
    /// 「从哪里选牌」支持手牌 / 抽牌堆 / 弃牌堆：
    ///   手牌走本体 CardSelectCmd.FromHand；抽牌堆 / 弃牌堆走 CardSelectCmd.FromCombatPile
    ///   （本体「充能 / 净化」选抽牌堆、「全息影像 / 头槌」选弃牌堆都是这么写的）。
    ///
    /// 「范围界定」（需求 ③）：候选池套一层 <see cref="CardScopeFiltered"/> ——
    /// 自己选的那条路把谓词当 CardSelectCmd 的 filter 传（本体自己会在候选为空 / 不够时直接返回，
    /// 不会弹一个空选牌界面），随机那条路直接在 .Cards 后面 .Where。
    /// </summary>
    private static void EmitExhaustCard(CodeWriter w, CharacterProfile? p, EffectSpec e, bool useX = false, string? countExpr = null)
    {
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        string pileZh = EffectCatalog.SelectPileZh(e.SelectPile);
        string? scope = CardScopeMarker(e);
        if (scope is not null) w.Line(scope);
        CountModeMarker(w, e);
        string? pred = CardScopePredicate(e, p);
        if (e.CountIsAll)
        {
            // 「全部」（V0.2.163，需求「选择所有手牌」）：**不弹选牌界面**，直接把那一摞里符合条件的
            // 每一张消耗掉 —— 本体「恶魔之焰 FiendFire」就是这么写的（先把那摞 `.ToList()` 拍下来，
            // 再逐张 CardCmd.Exhaust：不拍快照会在遍历中改集合）。
            // 自包含标记：这一档没有选牌语句可认，回读只能靠它（别的档位不写，生成文本逐字不变）。
            w.Line(SelfContainedMarker(e));
            w.Line($"// 全部：把{pileZh}里符合条件的牌**全部**消耗{ScopeZhSuffix(e)}（不弹选牌界面，本体「恶魔之焰」那种）");
            w.Line($"foreach (CardModel c in {CardScopeFiltered(e, p, $"{PileExpr(e)}.Cards")}.ToList()) await CardCmd.Exhaust(choiceContext, c);");
        }
        else if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            w.Line($"// 自己从{pileZh}选 {CountZh(e, nC)} 张消耗{ScopeZhSuffix(e)}");
            if (e.SelectPile == "Hand")
            {
                // 「恰好 N 张」那条路**逐字不变**（老存档的回归红线）；只有 UpTo / Any 才多带两个实参
                string handPrefs = e.CountMode == CountModes.Exact
                    ? $"new CardSelectorPrefs(CardSelectorPrefs.ExhaustSelectionPrompt, {n})"
                    : $"new CardSelectorPrefs(CardSelectorPrefs.ExhaustSelectionPrompt, minCount: 0, maxCount: {RangeN(e, n)})";
                w.Line($"var toExhaust = (await CardSelectCmd.FromHand(context: choiceContext, player: base.Owner, prefs: {handPrefs}, filter: {pred ?? "null"}, source: this)).ToList();");
            }
            else
                w.Line($"var toExhaust = (await CardSelectCmd.FromCombatPile(choiceContext, {PileExpr(e)}, base.Owner, {SelectPrefsExpr(e, "CardSelectorPrefs.ExhaustSelectionPrompt", n)}{(pred is null ? "" : ", " + pred)})).ToList();");
            w.Line("foreach (CardModel c in toExhaust) await CardCmd.Exhaust(choiceContext, c);");
        }
        else
        {
            string scopeExpr = CardScopeFiltered(e, p, $"{PileExpr(e)}.Cards");
            w.Line(IsPileTop(e)
                ? $"// 从牌顶（抽牌堆最上面那张）拿 {nC} 张消耗{ScopeZhSuffix(e)}（不用挑）"
                : $"// 随机从{pileZh}消耗 {nC} 张{ScopeZhSuffix(e)}");
            w.Open($"for (int __pickIdx = 0; __pickIdx < {n}; __pickIdx++)");
            w.Line($"CardModel? pick = {PickOne(e, $"base.Owner.RunState.Rng.CombatCardSelection.NextItem({scopeExpr})", $"{scopeExpr}.FirstOrDefault()")};");
            w.Line("if (pick is null) break;");
            w.Line("await CardCmd.Exhaust(choiceContext, pick);");
            w.Close();
        }
    }

    /// <summary>
    /// 丢弃卡牌：把手牌 / 抽牌堆里的 N 张牌丢进弃牌堆（用户要求的新效果）。
    ///
    /// 走本体的 <c>CardCmd.Discard</c> —— 它内部是 <c>CardPileCmd.Add(card, 弃牌堆)</c> +
    /// <c>Hook.AfterCardDiscarded</c>（本体「杂技 Acrobatics / 早有准备 Prepared / 幸存者 Survivor /
    /// 计算赌博 CalculatedGamble」都是这么丢的），所以「奇巧」这类跟弃牌有关的钩子照常触发。
    /// 它在**任何一摞**上都能用（Add 会把牌从原来那摞挪过去），所以「从抽牌堆丢」也是同一个调用。
    ///
    /// 自己选：手牌走 <c>CardSelectCmd.FromHandForDiscard</c>（本体丢手牌专用的那个：奇巧牌会描金），
    ///         抽牌堆走 <c>CardSelectCmd.FromCombatPile</c>；随机：Rng.CombatCardSelection 抓。
    /// </summary>
    private static void EmitDiscardCard(CodeWriter w, CharacterProfile? p, EffectSpec e, bool useX = false, string? countExpr = null)
    {
        // 数值 0 = 这张牌自己（用户要求）：把手牌里**这张牌本身**丢进弃牌堆。
        // 走本体的 CardCmd.Discard（和丢别的牌同一个 API：内部派发 AfterCardDiscarded，「奇巧」照常触发）。
        // 一条标记行写全（回读靠它还原，见 ProjectRecovery 的 CET:Effect 分支）—— 这一档没有张数变量。
        if (AmountZeroIsSelf(e))
        {
            w.Line(SelfContainedMarker(e));
            w.Line("// 数值 0 = 这张牌自己：把这张牌本身丢进弃牌堆");
            w.Line("await CardCmd.Discard(choiceContext, this);");
            return;
        }
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        string pileZh = EffectCatalog.SelectPileZh(e.SelectPile);
        string? scope = CardScopeMarker(e);
        if (scope is not null) w.Line(scope);
        CountModeMarker(w, e);
        string? pred = CardScopePredicate(e, p);
        if (e.CountIsAll)
        {
            // 「全部」：不弹选牌界面，把那一摞里符合条件的牌一次全丢进弃牌堆
            //（本体「计算下注 CalculatedGamble」丢掉整只手牌就是这种；CardCmd.Discard 收整批）。
            w.Line(SelfContainedMarker(e));   // 这一档没有选牌语句可认，回读靠它
            w.Line($"// 全部：把{pileZh}里符合条件的牌**全部**丢弃{ScopeZhSuffix(e)}（不弹选牌界面）");
            // ⚠ 变量名和「自己选」那支**故意不一样**（__fgAllDiscard 而不是 toDiscard）：
            //   回读是按 `var toDiscard` 这行认「丢弃卡牌」的，同名会让「全部」档多回读一条。
            w.Line($"var __fgAllDiscard = {CardScopeFiltered(e, p, $"{PileExpr(e)}.Cards")}.ToList();");
            w.Line("await CardCmd.Discard(choiceContext, __fgAllDiscard);");
        }
        else if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            w.Line($"// 自己从{pileZh}选 {CountZh(e, nC)} 张丢弃{ScopeZhSuffix(e)}");
            if (e.SelectPile == "Hand")
            {
                // 「恰好 N 张」那条路**逐字不变**；只有 UpTo / Any 才多带两个实参
                string handPrefs = e.CountMode == CountModes.Exact
                    ? $"new CardSelectorPrefs(CardSelectorPrefs.DiscardSelectionPrompt, {n})"
                    : $"new CardSelectorPrefs(CardSelectorPrefs.DiscardSelectionPrompt, minCount: 0, maxCount: {RangeN(e, n)})";
                w.Line($"var toDiscard = (await CardSelectCmd.FromHandForDiscard(choiceContext, base.Owner, {handPrefs}, {pred ?? "null"}, this)).ToList();");
            }
            else
                w.Line($"var toDiscard = (await CardSelectCmd.FromCombatPile(choiceContext, {PileExpr(e)}, base.Owner, {SelectPrefsExpr(e, "CardSelectorPrefs.DiscardSelectionPrompt", n)}{(pred is null ? "" : ", " + pred)})).ToList();");
            w.Line("await CardCmd.Discard(choiceContext, toDiscard);");
        }
        else
        {
            string scopeExpr = CardScopeFiltered(e, p, $"{PileExpr(e)}.Cards");
            w.Line(IsPileTop(e)
                ? $"// 从牌顶（抽牌堆最上面那张）拿 {nC} 张丢弃{ScopeZhSuffix(e)}（不用挑）"
                : $"// 随机从{pileZh}丢弃 {nC} 张{ScopeZhSuffix(e)}");
            w.Open($"for (int __pickIdx = 0; __pickIdx < {n}; __pickIdx++)");
            w.Line($"CardModel? pick = {PickOne(e, $"base.Owner.RunState.Rng.CombatCardSelection.NextItem({scopeExpr})", $"{scopeExpr}.FirstOrDefault()")};");
            w.Line("if (pick is null) break;");
            w.Line("await CardCmd.Discard(choiceContext, pick);");
            w.Close();
        }
    }

    /// <summary>
    /// 重放卡牌（用户要求的新效果）：给选中的牌加上「重放 N 次」。
    ///
    /// 本体机制：<c>CardModel.BaseReplayCount</c> —— 打出这张牌时
    /// <c>GeneratePlayCount = GetEnchantedReplayCount() + 1</c>（CardModel.cs:2031），
    /// 所以「重放 1」= 这张牌打出去时连着打 2 次、「重放 2」= 3 次。
    /// 本体「转化 Transfigure / 隐藏宝石 HiddenGem / 剑圣 SwordSagePower / 士兵炖菜 SoldiersStew」
    /// 做的都是同一句 <c>card.BaseReplayCount += N</c>（HiddenGem 还会 CardCmd.Preview 一下）。
    ///
    /// 注意：只能给**别的**牌加 —— 自己这张牌的重放次数是在 OnPlay 之前就算好的
    /// （GeneratePlayCount 在 OnPlayWrapper 里、进 OnPlay 循环之前调用），
    /// 所以在自己的 OnPlay 里改 BaseReplayCount 对这一次打出没有作用（校验器会提示）。
    /// </summary>
    private static void EmitReplayCard(CodeWriter w, CharacterProfile? p, EffectSpec e, bool useX = false, string? countExpr = null)
    {
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        // 「重放次数」写了公式（用户要求⑦）：现算，夹到 1~20（和固定值那条同一个上限）
        int times = Math.Max(1, Math.Min(20, e.ReplayTimes));
        string timesExpr = times.ToString();
        if (CountFormulaExpr(_formulaOwner, e, "Replay", out _) is { } rf)
            timesExpr = $"(int)System.Math.Clamp({rf}, 1m, 20m)";
        int timesForMarker = times;
        bool timesIsFormula = timesExpr != timesForMarker.ToString();
        string pileZh = EffectCatalog.SelectPileZh(e.SelectPile);
        string? scope = CardScopeMarker(e);
        if (scope is not null) w.Line(scope);
        CountModeMarker(w, e);
        w.Line(SelfContainedMarker(e) + (timesIsFormula ? "" : $" CET:Replay={timesForMarker}"));
        // 选牌前先算「候选池」，并且**先筛掉不能重放的牌**（照本体「隐藏宝石 HiddenGem」的过滤条件）：
        //   · 打不出去的牌（Unplayable / 状态 / 诅咒）给它重放没有意义；
        //   · 已经有重放的牌不再叠加（本体也是 `c.GetEnchantedReplayCount() < 1`）——
        //     不然「重放 N 次」会一次次累乘，玩起来像卡死。
        // 为什么要先算池子：池子空了就整条跳过（本体 HiddenGem 就是 `if (list.Count == 0) return;`），
        // 不要拿着一张空界面的选牌请求去等玩家（那才是「打出后卡死」）。
        string pool = "__replayPool";
        string? scopeCond = CardScopeCond(e, p);
        string replayCond = CombineCond("!c.Keywords.Contains(CardKeyword.Unplayable) && c.GetEnchantedReplayCount() < 1", scopeCond);
        w.Line($"// 候选：{pileZh}里还能重放的牌（打不出去的、已经有重放的都排除）{ScopeZhSuffix(e)}");
        w.Line($"List<CardModel> {pool} = {PileExpr(e)}.Cards"
            + $".Where(c => {replayCond})"
            + ".ToList();");
        w.Open($"if ({pool}.Count > 0)");
        if (e.CountIsAll)
        {
            // 「全部」：候选池里（已经筛掉不能重放的）**全部**都给重放，不弹选牌界面。
            w.Line($"// 全部：{pileZh}里还能重放的牌**全部**给上（不弹选牌界面）{ScopeZhSuffix(e)}");
            w.Line($"var __replayPicked = {pool};");
            w.Open("foreach (CardModel __replayCard in __replayPicked)");
            w.Line($"__replayCard.BaseReplayCount += {timesExpr};");
            w.Close();
            w.Line("if (__replayPicked.Count > 0) CardCmd.Preview(__replayPicked);");
            w.Close();
            return;
        }
        w.Line($"int __replayWant = Math.Min({n}, {pool}.Count);   // 池子不够就少拿几张，绝不多要");
        if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            w.Line($"// 自己从{pileZh}选（最多 {nC} 张），让它们本场战斗内额外打出 {timesExpr} 次");
            string want = "__replayWant";
            string filterArg = $"c => {replayCond}";
            if (e.SelectPile == "Hand")
                w.Line($"var __replayFrom = (await CardSelectCmd.FromHand(context: choiceContext, player: base.Owner, prefs: new CardSelectorPrefs(base.SelectionScreenPrompt, {want}), filter: {filterArg}, source: this)).ToList();");
            else
                w.Line($"var __replayFrom = (await CardSelectCmd.FromCombatPile(choiceContext, {PileExpr(e)}, base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, {want}), {filterArg})).ToList();");
            w.Open("foreach (CardModel __replayCard in __replayFrom)");
            w.Line($"__replayCard.BaseReplayCount += {timesExpr};   // 本体：重放 N 次 = 打出去时连着打 N+1 次");
            w.Close();
            w.Line("if (__replayFrom.Count > 0) CardCmd.Preview(__replayFrom);   // 一次给整批（本体自己也有这个重载），别一张一张弹");
        }
        else
        {
            w.Line(IsPileTop(e)
                ? $"// 从牌顶（抽牌堆最上面那张）拿（最多 {nC} 张），让它们本场战斗内额外打出 {timesExpr} 次（不用挑）"
                : $"// 随机从{pileZh}拿（最多 {nC} 张），让它们本场战斗内额外打出 {timesExpr} 次");
            w.Line($"var __replayPicked = {PickOne(e, $"MegaCrit.Sts2.Core.Extensions.IEnumerableExtensions.TakeRandom({pool}, __replayWant, base.Owner.RunState.Rng.CombatCardSelection).ToList()", $"{pool}.Take(__replayWant).ToList()")};");
            w.Open("foreach (CardModel __replayCard in __replayPicked)");
            w.Line($"__replayCard.BaseReplayCount += {timesExpr};");
            w.Close();
            w.Line("if (__replayPicked.Count > 0) CardCmd.Preview(__replayPicked);");
        }
        w.Close();
    }

    /// <summary>
    /// 回合结束时自动打出（用户要求的新效果）：
    ///   · <paramref name="selfExpr"/> 非空（卡牌）= 数值 0 时自动打出**这张牌自己**；
    ///   · 数值 ≥ 1 = 现在（打出这条效果时）就选/随机出 N 张，本回合结束时自动打出它们。
    ///
    /// 为什么「选牌」放在现在、而不是回合结束时：
    /// 回合结束那个钩子里弹选牌界面体验很差（本体的回合结束流程正在跑，还要处理手牌进退），
    /// 而且 <c>PowerModel.SelectionScreenPrompt</c> 在本地化键缺失时**直接抛异常**。
    /// 选好之后交给生成的 <c>ForgeTurnEndPlayPower</c>（不可见），它在 BeforeSideTurnEnd 里
    /// 逐张 <c>CardCmd.AutoPlay</c> —— 那个时机跑在本体「手牌结算」之前，自动打出的牌会正常离开手牌。
    /// </summary>
    private static void EmitTurnEndPlay(CodeWriter w, EffectSpec e, CharacterProfile p, bool useX = false,
        string? selfExpr = null, string cardSource = "this")
    {
        string cls = Naming.From(p).TurnEndPlayPowerClass;
        string? scope = CardScopeMarker(e);
        if (scope is not null) w.Line(scope);
        CountModeMarker(w, e);
        w.Line(SelfContainedMarker(e));
        if (e.Amount <= 0m && !e.AmountIsXEffective)
        {
            if (selfExpr is null)
            {
                Warn(w, e, "（数值 0 = 这张牌自己，只有卡牌才有「自己」；这里请填 1 以上）");
                return;
            }
            w.Line("// 数值 0 = 这张牌自己：本回合结束时再自动打出它一次");
            w.Line($"await PowerCmd.Apply(choiceContext, {cls}.Create(new CardModel[] {{ {selfExpr} }}), base.Owner.Creature, 1m, base.Owner.Creature, {cardSource});");
            return;
        }

        string n = (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string pileZh = EffectCatalog.SelectPileZh(e.SelectPile);
        string? pred = CardScopePredicate(e, p);
        if (e.CountIsAll)
        {
            // 「全部」：那一摞里符合条件的牌**全部**在回合结束时自动打出（不弹选牌界面）。
            w.Line($"// 全部：{pileZh}里符合条件的牌**全部**在回合结束时自动打出{ScopeZhSuffix(e)}（现在不弹选牌界面）");
            w.Line($"var __tePicks = {CardScopeFiltered(e, p, $"{PileExpr(e)}.Cards")}.ToList();");
            w.Line($"if (__tePicks.Count > 0) await PowerCmd.Apply(choiceContext, {cls}.Create(__tePicks), base.Owner.Creature, 1m, base.Owner.Creature, {cardSource});");
            return;
        }
        w.Line($"// 现在先选好 {n} 张{pileZh}里的牌，本回合结束时自动打出它们{ScopeZhSuffix(e)}");
        if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            if (e.SelectPile == "Hand")
                w.Line($"var __tePicks = (await CardSelectCmd.FromHand(context: choiceContext, player: base.Owner, prefs: new CardSelectorPrefs(base.SelectionScreenPrompt, {n}), filter: {pred ?? "null"}, source: this)).ToList();");
            else
                w.Line($"var __tePicks = (await CardSelectCmd.FromCombatPile(choiceContext, {PileExpr(e)}, base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, {n}){(pred is null ? "" : ", " + pred)})).ToList();");
        }
        else
        {
            string tePool = CardScopeFiltered(e, p, $"{PileExpr(e)}.Cards");
            w.Line(IsPileTop(e)
                ? $"var __tePicks = {tePool}.Take({n}).ToList();   // 牌顶：抽牌堆最上面那 {n} 张（不用挑）"
                : $"var __tePicks = MegaCrit.Sts2.Core.Extensions.IEnumerableExtensions.TakeRandom({tePool}, {n}, base.Owner.RunState.Rng.CombatCardSelection).ToList();");
        }
        w.Line($"if (__tePicks.Count > 0) await PowerCmd.Apply(choiceContext, {cls}.Create(__tePicks), base.Owner.Creature, 1m, base.Owner.Creature, {cardSource});");
    }

    /// <summary>
    /// 「自己搞定一整段」的新效果在生成代码前写一行标记（毒性爆发 / 预见 / 升级卡牌 / 复制卡牌 / 重放 /
    /// 回合结束时自动打出 / 大限已至）。
    ///
    /// 为什么要标记：这几种效果的实现都是好几行（循环 + 施加 + 触发 / 选牌 + 丢掉 / 攻击链），
    /// 回读时逐行猜很容易认错 —— 例如预见的 `CardCmd.Discard(choiceContext, __scryDiscard)` 会被当成
    /// 「丢弃卡牌」、毒性爆发的 `PowerCmd.Apply&lt;PoisonPower&gt;` 会被当成「施加中毒」。
    /// 所以标记那一行就把效果收尾（数值 / 选牌方式 / 哪一摞都写在标记里），后面那几行整段跳过。
    /// 回读见 ProjectRecovery 的 `CET:Effect=` 分支。
    /// </summary>
    internal static string SelfContainedMarker(EffectSpec e) =>
        $"// CET:Effect={e.Kind} CET:Amount={Lit.Dec(e.Amount)} CET:Pick={e.CardPick} CET:Pile={e.SelectPile}"
        + (e.UsesCountFormula("Copies") ? "" : $" CET:Stack={(e.AmountIsStack ? 1 : 0)} CET:X={(e.AmountIsXEffective ? 1 : 0)} CET:Copies={Math.Max(1, e.Copies)}")
        // 自包含效果里「翻倍状态层数」要用到「哪一个状态 / 打谁」——顺手带上，回读时按它还原
        + $" CET:Power={Lit.Str(e.PowerId ?? "")} CET:Side={e.TargetSide}"
        // 「用目标卡填满手牌」要把选的那张卡带上（代码里只剩 CreateCard<那张卡>）；
        // 没填就不写这一项，别的种类回读时不受影响。
        + (string.IsNullOrWhiteSpace(e.SpawnCardId) ? "" : $" CET:Card={e.SpawnCardId!.Trim()}")
        // 「放置卡牌」放到哪一摞（V0.2.116）：**只有这个种类**才写这一项，别的种类的标记行一个字符都不动。
        + (e.Kind == "PlaceCard" ? $" CET:PlaceTo={e.PlaceTo}" : "")
        // 「刮削」的条件 / 操作：**只有这个种类**才有这两项（别的种类的标记行一个字符都不动）。
        // 而且只有**不是默认值**（非 0 费 + 丢弃）时才写：默认那一档的标记行与改动前逐字一致
        //（老存档的生成文本不能变，用户要求）；回读时缺项就按默认值补（见 ProjectRecovery）。
        + (e.Kind == "ScrapeDraw" && !EffectCatalog.IsDefaultScrape(e.ScrapeCond, e.ScrapeOp)
            ? $" CET:ScrapeCond={(e.ScrapeCond ?? "").Trim()} CET:ScrapeOp={(e.ScrapeOp ?? "").Trim()}"
            : "");

    /// <summary>
    /// 复制卡牌（用户要求的新效果）：从手牌 / 抽牌堆 / 弃牌堆里选 N 张（或随机拿 N 张），
    /// 每一张复制「复制的份数」份，复制出来的放进手牌。
    ///
    /// 参照本体「二刀流 DualWield」（它就是这个效果的官方做法）：
    ///   <c>CardSelectCmd.FromHand(prefs: new CardSelectorPrefs(base.SelectionScreenPrompt, 1), …)</c>
    ///   → <c>selection.CreateClone()</c> → <c>CardPileCmd.AddGeneratedCardToCombat(clone, PileType.Hand, base.Owner)</c>。
    /// 注意 <c>CreateClone</c> 只允许**战斗牌堆**里的牌（本体源码里非战斗牌堆会直接抛
    /// InvalidOperationException），所以这里的三摞都是战斗牌堆；复制出来的牌是克隆，
    /// 升级状态 / 附魔都跟着原牌走（本体 CloneCard 的行为）。
    /// </summary>
    /// <param name="playerExpr">玩家表达式：卡牌 / 遗物 / 药水三条链里就是 <c>base.Owner</c>（Player）；
    /// 放进**延迟状态**（`base.Owner` 是 Creature）时必须传 <c>base.Owner.Player</c>。
    /// <param name="creatureExpr">玩家那个 Creature 的表达式（同理：延迟状态里就是 <c>base.Owner</c>）。
    /// <param name="sourceExpr">「选牌来源」那个实参：卡牌链传 <c>this</c>（CardModel），
    /// 延迟状态 / 遗物 / 药水传 <c>null</c>（那里没有「这张牌」）。</param>
    private static void EmitCopyCard(CodeWriter w, CharacterProfile? p, EffectSpec e, bool useX = false, string? countExpr = null,
        string playerExpr = "base.Owner", string creatureExpr = "base.Owner.Creature", string sourceExpr = "this")
    {
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        // 「复制的份数」写了公式（用户要求⑦）：现算，夹到 1~20（和固定值那条同一个上限）
        int copies = Math.Max(1, Math.Min(20, e.Copies));
        string copiesExpr = CountFormulaExpr(_formulaOwner, e, "Copies", out _) is { } cf
            ? $"(int)System.Math.Clamp({cf}, 1m, 20m)"
            : copies.ToString();
        string pileZh = EffectCatalog.SelectPileZh(e.SelectPile);
        // 标记行：范围界定（需求 ③）和「复制出来的卡怎么处理」（用户要求：也能免费打出 / 升级）
        // 都靠它回读。默认档（没范围界定、没有附加处理）**一个字符都不写** —— 生成代码与旧版逐字一致。
        // 为什么放在 SelfContainedMarker 之前：回读时它先把 pendingSpawn 存下来，
        // 下一行的 CET:Effect=CopyCard 造出那条效果时才会把这几个设置配上（见 ProjectRecovery 的 Done）。
        if (e.HasCardScope || e.HasSpawnModifier) w.Line(SpawnMarker(e, withKind: true));
        CountModeMarker(w, e);
        w.Line(SelfContainedMarker(e));
        // 「仅本回合升级」要先把那个「回合结束降回来」的状态挂上（和生成卡牌同一套，只挂一次）
        string? tempUp = e.SpawnUpgradedThisTurn ? "__tempUp" : null;
        if (tempUp is not null) EmitTempUpgradePowerApply(w, tempUp, sourceExpr, creatureExpr);
        string? pred = CardScopePredicate(e, p);
        if (e.CountIsAll)
        {
            // 「全部」：那一摞里符合条件的牌**每一张**都复制「复制的份数」份（不弹选牌界面）。
            w.Line($"// 全部：把{pileZh}里符合条件的牌**每一张**都复制 {copiesExpr} 份，复制出来的放进手牌{ScopeZhSuffix(e)}（不弹选牌界面）");
            w.Open($"foreach (CardModel __src in {CardScopeFiltered(e, p, $"{PileExpr(e, playerExpr)}.Cards")}.ToList())");
            w.Open($"for (int __copyIdx = 0; __copyIdx < {copiesExpr}; __copyIdx++)");
            w.Line("CardModel __clone = __src.CreateClone();");
            EmitSpawnModifiers(w, e, "__clone", tempUp, p, playerExpr, creatureExpr);
            w.Line($"await CardPileCmd.AddGeneratedCardToCombat(__clone, PileType.Hand, {playerExpr});");
            w.Close();
            w.Close();
            return;
        }
        if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            w.Line($"// 自己从{pileZh}选 {nC} 张复制，每张 {copiesExpr} 份，复制出来的放进手牌{ScopeZhSuffix(e)}");
            if (e.SelectPile == "Hand")
                w.Line($"var __copyFrom = (await CardSelectCmd.FromHand(context: choiceContext, player: {playerExpr}, prefs: new CardSelectorPrefs(base.SelectionScreenPrompt, {n}), filter: {pred ?? "null"}, source: {sourceExpr})).ToList();");
            else
                w.Line($"var __copyFrom = (await CardSelectCmd.FromCombatPile(choiceContext, {PileExpr(e, playerExpr)}, {playerExpr}, new CardSelectorPrefs(base.SelectionScreenPrompt, {n}){(pred is null ? "" : ", " + pred)})).ToList();");
            w.Open("foreach (CardModel __src in __copyFrom)");
            w.Open($"for (int __copyIdx = 0; __copyIdx < {copiesExpr}; __copyIdx++)");
            w.Line("CardModel __clone = __src.CreateClone();");
            EmitSpawnModifiers(w, e, "__clone", tempUp, p, playerExpr, creatureExpr);
            w.Line($"await CardPileCmd.AddGeneratedCardToCombat(__clone, PileType.Hand, {playerExpr});");
            w.Close();
            w.Close();
        }
        else
        {
            string copyScope = CardScopeFiltered(e, p, $"{PileExpr(e, playerExpr)}.Cards");
            w.Line(IsPileTop(e)
                ? $"// 从牌顶（抽牌堆最上面那张）拿 {nC} 张复制，每张 {copiesExpr} 份（不用挑）{ScopeZhSuffix(e)}"
                : $"// 随机从{pileZh}拿 {nC} 张复制，每张 {copiesExpr} 份，复制出来的放进手牌{ScopeZhSuffix(e)}");
            w.Open($"for (int __copyPickIdx = 0; __copyPickIdx < {n}; __copyPickIdx++)");
            w.Line($"CardModel? __src = {PickOne(e, $"{playerExpr}.RunState.Rng.CombatCardSelection.NextItem({copyScope})", $"{copyScope}.FirstOrDefault()")};");
            w.Line("if (__src is null) break;");
            w.Open($"for (int __copyIdx = 0; __copyIdx < {copiesExpr}; __copyIdx++)");
            w.Line("CardModel __clone = __src.CreateClone();");
            EmitSpawnModifiers(w, e, "__clone", tempUp, p, playerExpr, creatureExpr);
            w.Line($"await CardPileCmd.AddGeneratedCardToCombat(__clone, PileType.Hand, {playerExpr});");
            w.Close();
            w.Close();
        }
    }

    /// <summary>
    /// 升级卡牌（用户要求的新效果）：从手牌 / 抽牌堆 / 弃牌堆里挑 N 张升级。
    ///
    /// 升级用本体的 <c>CardCmd.Upgrade</c>（本体自己也是这么升级的：Apotheosis / Armaments / Whetstone）；
    /// 它内部会跳过「不能升级」的卡（<c>IsUpgradable</c>），并做 FinalizeUpgradeInternal（费用 / 变量收尾）。
    /// 选牌时也带上 <c>c =&gt; c.IsUpgradable</c> 过滤，免得玩家选到升不了的牌（选了也是白选）。
    /// 战斗里的卡是牌组卡的**克隆**，所以这里升级只影响本场战斗（本体机制，不用我们处理）。
    /// </summary>
    private static void EmitUpgradeCard(CodeWriter w, CharacterProfile? p, EffectSpec e, bool useX = false, string? countExpr = null)
    {
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        string pileZh = EffectCatalog.SelectPileZh(e.SelectPile);
        string? scope = CardScopeMarker(e);
        if (scope is not null) w.Line(scope);
        CountModeMarker(w, e);
        w.Line(SelfContainedMarker(e));
        // 「只能升级的牌」是这条效果本来就有的过滤条件；范围界定有的话和它 && 起来（见 CombineCond）。
        string upgradableCond = CombineCond("c.IsUpgradable", CardScopeCond(e, p));
        if (e.CountIsAll)
        {
            // 「全部」：那一摞里**所有能升级的**牌一次全升级（不弹选牌界面）。
            w.Line($"// 全部：把{pileZh}里所有还能升级的牌**全部**升级{ScopeZhSuffix(e)}（不弹选牌界面）");
            w.Line($"foreach (CardModel c in {PileExpr(e)}.Cards.Where(c => {upgradableCond}).ToList()) CardCmd.Upgrade(c);");
        }
        else if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            w.Line($"// 自己从{pileZh}选 {CountZh(e, nC)} 张升级（只列能升级的牌）{ScopeZhSuffix(e)}");
            if (e.SelectPile == "Hand")
            {
                // 「恰好 N 张」那条路**逐字不变**；只有 UpTo / Any 才多带两个实参
                string handPrefs = e.CountMode == CountModes.Exact
                    ? $"new CardSelectorPrefs(CardSelectorPrefs.UpgradeSelectionPrompt, {n})"
                    : $"new CardSelectorPrefs(CardSelectorPrefs.UpgradeSelectionPrompt, minCount: 0, maxCount: {RangeN(e, n)})";
                w.Line($"var toUpgrade = (await CardSelectCmd.FromHand(choiceContext, base.Owner, {handPrefs}, c => {upgradableCond}, this)).ToList();");
            }
            else
                w.Line($"var toUpgrade = (await CardSelectCmd.FromCombatPile(choiceContext, {PileExpr(e)}, base.Owner, {SelectPrefsExpr(e, "CardSelectorPrefs.UpgradeSelectionPrompt", n)}, c => {upgradableCond})).ToList();");
            w.Line("foreach (CardModel c in toUpgrade) CardCmd.Upgrade(c);");
        }
        else
        {
            w.Line(IsPileTop(e)
                ? $"// 从牌顶（抽牌堆最上面那张）拿 {nC} 张升级（只挑能升级的、不用自己选）{ScopeZhSuffix(e)}"
                : $"// 随机升级{pileZh}里的 {nC} 张（只挑能升级的）{ScopeZhSuffix(e)}");
            w.Open($"for (int __pickIdx = 0; __pickIdx < {n}; __pickIdx++)");
            w.Line($"CardModel? pick = {PickOne(e, $"base.Owner.RunState.Rng.CombatCardSelection.NextItem({PileExpr(e)}.Cards.Where(c => {upgradableCond}))", $"{PileExpr(e)}.Cards.Where(c => {upgradableCond}).FirstOrDefault()")};");
            w.Line("if (pick is null) break;");
            w.Line("CardCmd.Upgrade(pick);");
            w.Close();
        }
    }

    /// <summary>
    /// 预见（一代观者的 Scry）：看抽牌堆顶的 N 张，把其中**任意张**丢进弃牌堆。
    ///
    /// 本体（StS2）**没有**这个机制（只有水晶球事件里同名的美术资源），所以自己拼：
    ///   · 抽牌堆顶 = <c>PileType.Draw.GetPile(player).Cards</c> 的**前 N 个**
    ///     （本体 CardPile 的索引 0 就是顶：抽牌时取 <c>Cards.FirstOrDefault()</c>，MoveToTop 也是 Insert(0)）；
    ///   · 从「显式牌表」里选牌只有 <c>CardSelectCmd.FromSimpleGrid</c>
    ///     （FromChooseACardScreen 超过 3 张会直接抛异常），min 0 / max N = 可以一张都不丢；
    ///   · 丢牌走 <c>CardCmd.Discard</c>（派发 AfterCardDiscarded，奇巧照常触发）。
    /// </summary>
    private static void EmitScry(CodeWriter w, CharacterProfile? p, EffectSpec e, bool useX = false, string? countExpr = null)
    {
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        string? scope = CardScopeMarker(e);
        if (scope is not null) w.Line(scope);
        w.Line(SelfContainedMarker(e));
        w.Line($"// 预见 {nC}：看抽牌堆顶的 {nC} 张，想丢的丢进弃牌堆（可以一张都不丢）{ScopeZhSuffix(e)}");
        // 范围界定：先取「抽牌堆顶 N 张」，再在这一小撮里按范围过滤（只丢符合范围的牌；都不符合就相当于没丢）
        w.Line($"var __scryTop = {CardScopeFiltered(e, p, $"PileType.Draw.GetPile(base.Owner).Cards.Take({n})")}.ToList();");
        w.Open("if (__scryTop.Count > 0)");
        w.Line("var __scryDiscard = (await CardSelectCmd.FromSimpleGrid(choiceContext, __scryTop, base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, 0, __scryTop.Count))).ToList();");
        w.Open("if (__scryDiscard.Count > 0)");
        w.Line("await CardCmd.Discard(choiceContext, __scryDiscard);");
        w.Close();
        w.Close();
    }

    /// <summary>
    /// 刮削的条件（不含 <c>c =&gt; </c>）。返回 null = 不限（不筛，抽到的每一张都动手）。
    /// 「非 0 费」是本体「刮削 Scrape」的判据，照原样写：
    /// <c>c.EnergyCost.GetWithModifiers(CostModifiers.All) != 0 || c.EnergyCost.CostsX</c>
    /// （CostsX 也留着：X 费牌的花费是 0，但它是「要花能量」的牌）。
    /// 其余（攻击 / 技能 / 能力 / 诅咒 / 状态 / 自定义关键词那一组）复用范围界定那份判据，
    /// 不复制粘贴第二份（见 <see cref="ScopeCondForFilter"/>）。
    /// </summary>
    private static string? ScrapeCondExpr(EffectSpec e, CharacterProfile? p)
    {
        string id = (e.ScrapeCond ?? "").Trim();
        if (id.Length == 0 || string.Equals(id, EffectCatalog.ScrapeCondAny, StringComparison.Ordinal)) return null;
        if (string.Equals(id, EffectCatalog.ScrapeCondNonZeroCost, StringComparison.Ordinal))
            return "c.EnergyCost.GetWithModifiers(CostModifiers.All) != 0 || c.EnergyCost.CostsX";
        return ScopeCondForFilter(id, p) ?? "false";   // 认不出来的 Id：谁也不匹配（校验器已经报过错）
    }

    /// <summary>
    /// 刮削（本体卡「刮削 Scrape」）：抽 N 张牌，然后对其中**符合条件的牌**执行**选定的操作**。
    ///
    /// 条件是 <see cref="EffectSpec.ScrapeCond"/>（默认「非 0 费」= 本体那张牌的判据；不限 / 按类型 /
    /// 按稀有度 / 自定义关键词那一组都行），操作是 <see cref="EffectSpec.ScrapeOp"/>
    /// （默认丢弃 = <c>CardCmd.Discard</c>；消耗 = <c>CardCmd.Exhaust</c>；升级 = <c>CardCmd.Upgrade</c>）。
    ///
    /// **默认那一档生成出来的文本与改动前逐字一致**（用户要求：老存档不能变）：
    /// 注释、抽牌那一句（含 <c>.Where(...)</c>）和 <c>CardCmd.Discard</c> 都原样保留 ——
    /// 所以默认那两行是**特意**写死的分支，不是忘了统一。由 --uicheck 钉死。
    ///
    /// 整段写在一个变量上（__scraped），回读时按 <c>CET:Effect=ScrapeDraw</c> 标记收尾、这几行整段跳过
    /// （见 ProjectRecovery 的 skipSelfContainedBody 名单）。
    /// </summary>
    private static void EmitScrapeDraw(CodeWriter w, CharacterProfile? p, EffectSpec e, string amount)
    {
        string? cond = ScrapeCondExpr(e, p);
        string condZh = EffectCatalog.ScrapeCondZhFor(p, e.ScrapeCond);
        string opZh = EffectCatalog.ScrapeOpZh(e.ScrapeOp);
        string draw = $"(await CardPileCmd.Draw(choiceContext, {amount}, base.Owner))";
        w.Line(SelfContainedMarker(e));
        // 默认（非 0 费 + 丢弃）用旧版那句注释，一个字符都不动
        if (EffectCatalog.IsDefaultScrape(e.ScrapeCond, e.ScrapeOp))
            w.Line($"// 抽 {amount} 张牌，丢弃其中所有「非 0 费」的牌（本体「刮削 Scrape」的写法）");
        else
            w.Line($"// 抽 {amount} 张牌，对其中「{condZh}」的牌{opZh}"
                + (e.ScrapeOp == EffectCatalog.ScrapeOpExhaust ? "（参考「消耗卡牌」的写法）"
                    : e.ScrapeOp == EffectCatalog.ScrapeOpUpgrade ? "（本体自己也是这么升级卡牌的）" : ""));
        w.Line(cond is null
            ? $"IEnumerable<CardModel> __scraped = await CardPileCmd.Draw(choiceContext, {amount}, base.Owner);"
            : $"IEnumerable<CardModel> __scraped = {draw}.Where(c => {cond});");
        // 操作那几行：丢弃 = CardCmd.Discard（一次传整批，和旧版一致）；消耗 / 升级按 EmitExhaustCard /
        // EmitUpgradeCard 的写法逐张来（CardCmd.Exhaust 只接受单张牌）。
        w.Line(e.ScrapeOp switch
        {
            EffectCatalog.ScrapeOpExhaust => "foreach (CardModel c in __scraped) await CardCmd.Exhaust(choiceContext, c);",
            EffectCatalog.ScrapeOpUpgrade => "foreach (CardModel c in __scraped) CardCmd.Upgrade(c);",
            _ => "await CardCmd.Discard(choiceContext, __scraped);",
        });
    }

    /// <summary>
    /// 用「目标卡」填满手牌（本体卡「迫降 CrashLanding」的做法）：
    /// 先算手牌还差几张（<c>CardPile.MaxCardsInHand - 手牌数</c>），再逐张 <c>CreateCard</c> 一次性加进手牌。
    /// 卡由「目标卡」那一栏选（没填时退成小刀 Shiv，和「生成卡牌」一致），张数完全由手牌上限决定。
    /// 整段写在一个变量上（__filled），回读时按 <c>CET:Effect=FillHand</c> 标记收尾、这几行整段跳过。
    /// </summary>
    private static void EmitFillHand(CodeWriter w, EffectSpec e)
    {
        string card = string.IsNullOrWhiteSpace(e.SpawnCardId) ? "Shiv" : e.SpawnCardId!.Trim();
        w.Line(SelfContainedMarker(e));
        w.Line($"// 用「{card}」把手牌填满（本体「迫降 CrashLanding」的写法：张数 = 手牌上限 - 当前手牌数）");
        w.Line("int __fillTo = CardPile.MaxCardsInHand - CardPile.GetCards(base.Owner, PileType.Hand).Count();");
        w.Open("if (__fillTo > 0)");
        w.Line("List<CardModel> __filled = new List<CardModel>();");
        w.Line($"for (int i = 0; i < __fillTo; i++) __filled.Add(base.CombatState.CreateCard<{card}>(base.Owner));");
        w.Line("await CardPileCmd.AddGeneratedCardsToCombat(__filled, PileType.Hand, base.Owner);");
        w.Close();
    }

    private static void EmitOutbreak(CodeWriter w, EffectSpec e, string amt, string cardSource)
        => EmitOutbreak(w, e, amt,
            enemies: "base.Owner.Creature.CombatState.HittableEnemies",
            applier: "base.Owner.Creature", cardSource: cardSource);

    /// <summary>
    /// 毒性爆发（本体 Outbreak，静默猎手稀有技能）：给**所有敌人**上 N 层中毒，然后把中毒立刻触发一次。
    /// 本体的写法就是 <c>PowerCmd.Apply&lt;PoisonPower&gt;</c> 一轮 + <c>PoisonPower.Trigger()</c> 一轮；
    /// 那一下伤害在 PoisonPower 内部是 <c>dealer: null</c>，所以不算「你造成的伤害」、也不吃力量（本体机制）。
    ///
    /// 参数化的原因：卡牌 / 遗物 / 药水里 <c>base.Owner</c> 是 Player（要 .Creature），
    /// 而自定义状态触发器里 <c>base.Owner</c> 本身就是 Creature（见 CustomPowerGen 的上下文）。
    /// </summary>
    internal static void EmitOutbreak(CodeWriter w, EffectSpec e, string amt, string enemies, string applier, string cardSource)
    {
        w.Line(SelfContainedMarker(e));
        w.Line($"// 毒性爆发：给所有敌人上 {amt} 层中毒，并立刻触发一次中毒伤害");
        w.Open($"foreach (Creature foe in {enemies})")
         .Line($"await PowerCmd.Apply<PoisonPower>(choiceContext, foe, {amt}, {applier}, {cardSource});")
         .Close();
        w.Open($"foreach (Creature foe in {enemies})")
         .Line("PoisonPower? poison = foe.GetPower<PoisonPower>();")
         .Line("if (poison is not null) await poison.Trigger();")
         .Close();
    }

    /// <summary>
    /// 大限已至（本体 Time's Up）：造成等于**目标身上灾厄层数**的伤害。
    /// 本体用的是计算变量三件套 + 普通攻击链（<c>DamageCmd.Attack(CalculatedDamage).FromCard(...).Targeting(cardPlay.Target)</c>），
    /// 所以这是一次正常攻击（能被格挡、吃力量/易伤），而伤害数字由目标的 DoomPower 层数决定。
    /// 只能打在**单个指定敌人**上（本体也是 TargetType.AnyEnemy），目标为空时本体直接抛异常。
    /// </summary>
    private static void EmitTimesUp(CodeWriter w, EffectSpec e)
    {
        w.Line(SelfContainedMarker(e));
        w.Line("// 大限已至：造成等于目标身上灾厄层数的伤害（本体 Time's Up 的写法）");
        w.Line("ArgumentNullException.ThrowIfNull(cardPlay.Target, \"cardPlay.Target\");   // 指定目标才生效（本体这张牌也是 AnyEnemy）");
        w.Line("await DamageCmd.Attack(base.DynamicVars.CalculatedDamage)")
         .Indent().Line(".FromCard(this, cardPlay)").Line(".Targeting(cardPlay.Target)")
         .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
    }

    /// <summary>
    /// 变化卡牌（参考储君的「下去」Begone）：
    /// 指定了目标卡 → CardCmd.Transform(原卡, 新卡)；没指定 → CardCmd.TransformToRandom（随机变化）；
    /// 「按范围随机」→ 先按范围抽一张出来再 Transform（这样范围限定才有意义）。
    /// 「从哪里选牌」同消耗卡牌：手牌 / 抽牌堆 / 弃牌堆（本体「降灵 Seance / 充能 Charge」就是选抽牌堆变化）。
    /// 变出来的新卡还能带「升级 / 免费 / 仅本回合升级 / 仅本回合免费」这几个附加处理。
    /// </summary>
    /// <param name="playerExpr">玩家表达式（卡牌 / 遗物链是 <c>base.Owner</c>；延迟状态里必须传 <c>base.Owner.Player</c>）。
    /// <param name="creatureExpr">玩家那个 Creature 的表达式（延迟状态里就是 <c>base.Owner</c>）。
    /// <param name="sourceExpr">「选牌来源」实参：卡牌链传 <c>this</c>，延迟状态 / 遗物 / 药水传 <c>null</c>。</param>
    private static void EmitTransformCard(CodeWriter w, EffectSpec e, bool useX = false, CharacterProfile? p = null, string cardSource = "this", string? countExpr = null,
        string playerExpr = "base.Owner", string creatureExpr = "base.Owner.Creature", string sourceExpr = "this",
        string combatStateExpr = "base.CombatState")
    {
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        string? target = string.IsNullOrWhiteSpace(e.SpawnCardId) ? null : e.SpawnCardId!.Trim();
        string pileZh = EffectCatalog.SelectPileZh(e.SelectPile);
        w.Line(SpawnMarker(e));
        bool randomSpawn = e.IsSpawnRandom;
        if (randomSpawn) w.Line($"var __transformPool = {SpawnPoolExpr(e, p, playerExpr)};   // 变化范围：{EffectCatalog.SpawnFilterZh(e.SpawnFilter)}");
        string? tempUp = e.SpawnUpgradedThisTurn ? "__tempUp" : null;
        // 「仅本回合升级」要挂一个生成的 Power，最后一个实参是 cardSource（CardModel?）——
        // 卡牌传 this 没问题，**遗物/药水不是 CardModel，必须传 null**（否则编译器选到
        // Apply<T>(ctx, IEnumerable<Creature>?, …) 那个重载，报「参数 2/参数 5」两条错，整个模组编译不过）。
        // 与 EmitGenerateCard 的 tempUpSource 是同一个约定。
        if (e.HasSpawnModifier) EmitTempUpgradePowerApply(w, tempUp, cardSource, creatureExpr);
        CountModeMarker(w, e);

        if (e.CountIsAll)
        {
            // 「全部」：那一摞里符合条件的牌**每一张**都变化（不弹选牌界面）。
            w.Line(SelfContainedMarker(e));   // 这一档没有选牌语句可认，回读靠它
            w.Line($"// 全部：把{pileZh}里符合条件的牌**全部**变化（不弹选牌界面）");
            w.Open($"foreach (CardModel c in {CardScopeFiltered(e, p, $"{PileExpr(e, playerExpr)}.Cards")}.ToList())");
            EmitTransformBody(w, e, "c", target, randomSpawn, tempUp, p, playerExpr, creatureExpr, combatStateExpr);
            w.Close();
        }
        else if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            w.Line($"// 自己从{pileZh}选 {nC} 张变化");
            if (e.SelectPile == "Hand")
                w.Line($"var toTransform = (await CardSelectCmd.FromHand(context: choiceContext, player: {playerExpr}, prefs: new CardSelectorPrefs(CardSelectorPrefs.TransformSelectionPrompt, {n}), filter: null, source: {sourceExpr})).ToList();");
            else
                w.Line($"var toTransform = (await CardSelectCmd.FromCombatPile(choiceContext, {PileExpr(e, playerExpr)}, {playerExpr}, new CardSelectorPrefs(CardSelectorPrefs.TransformSelectionPrompt, {n}))).ToList();");
            w.Line("foreach (CardModel c in toTransform)");
            w.Open("");
            EmitTransformBody(w, e, "c", target, randomSpawn, tempUp, p, playerExpr, creatureExpr, combatStateExpr);
            w.Close();
        }
        else
        {
            w.Line(IsPileTop(e)
                ? $"// 从牌顶（抽牌堆最上面那张）拿 {nC} 张变化（不用挑）"
                : $"// 随机从{pileZh}变化 {nC} 张");
            w.Open($"for (int __pickIdx = 0; __pickIdx < {n}; __pickIdx++)");
            w.Line($"CardModel? pick = {PickOne(e, $"{playerExpr}.RunState.Rng.CombatCardSelection.NextItem({PileExpr(e, playerExpr)}.Cards)", $"{PileExpr(e, playerExpr)}.Cards.FirstOrDefault()")};");
            w.Line("if (pick is null) break;");
            EmitTransformBody(w, e, "pick", target, randomSpawn, tempUp, p, playerExpr, creatureExpr, combatStateExpr);
            w.Close();
        }
    }

    /// <summary>把一张牌变成什么：按范围随机抽一张 / 指定的那张 / 本体的随机变化。</summary>
    private static void EmitTransformBody(CodeWriter w, EffectSpec e, string cardVar, string? target, bool randomSpawn, string? tempUpVar,
        CharacterProfile? p = null, string playerExpr = "base.Owner", string creatureExpr = "base.Owner.Creature",
        string combatStateExpr = "base.CombatState")
    {
        if (randomSpawn)
        {
            // 按范围随机：先抽一张（CardFactory 会用本体那套「变化候选」规则），变完再套附加处理
            w.Line($"CardModel? __newCard = {playerExpr}.RunState.Rng.CombatCardSelection.NextItem(__transformPool);");
            w.Line($"if (__newCard is not null)");
            w.Open("");
            w.Line($"CardModel __made = {combatStateExpr}.CreateCard(__newCard, {playerExpr});");
            w.Line($"await CardCmd.Transform({cardVar}, __made);");
            EmitSpawnModifiers(w, e, "__made", tempUpVar, p, playerExpr, creatureExpr);
            w.Close();
            return;
        }
        // 需求 ⑦：要往「变化出来的卡」上加关键词时，必须接住本体返回的那张新卡 ——
        // 本体 CardCmd.Transform / TransformToRandom 都是**新建一张再把原卡移掉**，
        // 只有返回值里的 cardAdded 才是变出来的那张（原来的写法把返回值丢掉了，拿不到它）。
        // 这一段只在**选了关键词**时才生成，所以默认档的代码与旧版逐字一致。
        if (e.HasSpawnKeyword)
        {
            bool randomVanilla = target is null;
            w.Line("// 变化出来的卡要带关键词：先接住本体返回的 cardAdded（新卡是它新建的）");
            w.Line($"var __tr = await {(randomVanilla
                ? $"CardCmd.TransformToRandom({cardVar}, {playerExpr}.RunState.Rng.CombatCardSelection)"
                : $"CardCmd.Transform({cardVar}, {combatStateExpr}.CreateCard<{target}>({playerExpr}))")};");
            // 两边的返回值类型不一样：TransformToRandom 是 CardPileAddResult（不可空结构体，用 `?.` 会 CS0023），
            // Transform 是 CardPileAddResult?（可空）—— 所以取值写法必须分开写。
            EmitSpawnKeyword(w, e, randomVanilla ? "__tr.cardAdded?" : "__tr?.cardAdded?", p, playerExpr, creatureExpr);
            return;
        }
        w.Line(target is null
            ? $"await CardCmd.TransformToRandom({cardVar}, {playerExpr}.RunState.Rng.CombatCardSelection);"
            : $"await CardCmd.Transform({cardVar}, {combatStateExpr}.CreateCard<{target}>({playerExpr}));");
    }

    /// <summary>
    /// 从抽牌堆 / 弃牌堆挑牌拿到手牌（本体「搜寻 SecretWeapon / 全息影像 Hologram / 挖掘 Dredge」那种）：
    /// <c>CardSelectCmd.FromCombatPile(...)</c> + <c>CardPileCmd.Add(选中, PileType.Hand)</c>。
    /// 选牌界面的提示语用 <c>base.SelectionScreenPrompt</c>（本体每条卡牌 / 遗物 / 药水自己的那条，
    /// 本地化键是 &lt;ENTRY&gt;.selectionScreenPrompt，生成时会一起写出来）。
    /// </summary>
    private static void EmitTakeFromPile(CodeWriter w, CharacterProfile? p, EffectSpec e, string pile, bool useX = false, string? countExpr = null)
    {
        string n = countExpr ?? (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        string nC = CountComment(e, n);   // 注释里写人类可读的张数（升级后带上「升级后 N 张」）
        string pileZh = PileZh(pile);
        string expr = $"PileType.{pile}.GetPile(base.Owner)";
        string? scope = CardScopeMarker(e);
        if (scope is not null) w.Line(scope);
        CountModeMarker(w, e);
        string? pred = CardScopePredicate(e, p);
        if (e.CountIsAll)
        {
            // 「全部」：把那一摞里符合条件的牌一次全拿到手牌（不弹选牌界面）。
            w.Line(SelfContainedMarker(e));   // 这一档没有选牌语句可认，回读靠它
            w.Line($"// 全部：把{pileZh}里符合条件的牌**全部**拿到手牌{ScopeZhSuffix(e)}（不弹选牌界面）");
            // ⚠ 变量名和「自己选」那支**故意不一样**（__fgAllTaken 而不是 __taken）：回读是按 `var __taken`
            //   认「从牌堆拿牌到手牌」的，同名会让「全部」档多回读一条。
            w.Line($"var __fgAllTaken = {CardScopeFiltered(e, p, $"{expr}.Cards")}.ToList();");
            w.Line("if (__fgAllTaken.Count > 0) await CardPileCmd.Add(__fgAllTaken, PileType.Hand);");
            return;
        }
        w.Line($"// 从{pileZh}里自己选 {CountZh(e, nC)} 张拿到手牌{ScopeZhSuffix(e)}");
        w.Line($"var __taken = (await CardSelectCmd.FromCombatPile(choiceContext, {expr}, base.Owner, {SelectPrefsExpr(e, "base.SelectionScreenPrompt", n)}{(pred is null ? "" : ", " + pred)})).ToList();");
        w.Line("if (__taken.Count > 0) await CardPileCmd.Add(__taken, PileType.Hand);");
    }

    private static string PileZh(string pile) => pile switch
    {
        "Draw" => "抽牌堆",
        "Discard" => "弃牌堆",
        "Exhaust" => "消耗牌堆",
        _ => "手牌",
    };

    /// <summary>奖励至少要有这么些「可用卡」，否则本体三选一抽不出来会崩。</summary>
    public const int MinRewardPool = 3;

    /// <summary>
    /// 奖励可用的卡：进了卡池、且稀有度是奖励会抽的那三档。
    /// （Basic 不参与奖励；本体抽稀有度时只在 Common/Uncommon/Rare 之间循环，
    ///   所以卡池里全是 Basic 的话同样会崩。）
    /// </summary>
    public static List<CardSpec> RewardEligibleCards(CharacterProfile p) =>
        p.Cards.Where(c => !c.IsVanillaCard && c.InCardPool && c.Rarity is "Common" or "Uncommon" or "Rare").ToList();

    /// <summary>
    /// 卡池是否小到本体发奖励时会崩。
    /// 本体 CardFactory.CreateForReward 会「互不重复地抽 N 张」（普通战斗三选一 N=3），
    /// 抽到第 N 张时可用卡被拉黑完了 → 抛 InvalidOperationException → 奖励界面不弹 → 死档。
    /// 注意：**不再**用「本体卡兜底」，而是让生成前的校验直接拦住（用户要求奖励里不能出现铁甲卡）。
    /// </summary>
    public static bool RewardPoolTooSmall(CharacterProfile p) =>
        RewardEligibleCards(p).Count < MinRewardPool;

    /// <summary>还差几张奖励可用的卡（给校验提示用）。</summary>
    public static string RewardPoolStatus(CharacterProfile p)
    {
        var pool = RewardEligibleCards(p);
        int byRarity(string r) => pool.Count(c => c.Rarity == r);
        return $"{pool.Count} 张可用（Common {byRarity("Common")} / Uncommon {byRarity("Uncommon")} / Rare {byRarity("Rare")}）";
    }

    /// <summary>
    /// 卡池里哪些牌型**一张都上不了商店**。
    ///
    /// 只查本体**真的会摆货架**的那三种牌型（<c>MerchantInventory._coloredCardTypes</c> =
    /// Attack ×2 / Skill ×2 / Power）—— 状态 / 诅咒 / 任务这几种类型本体根本不建货架，
    /// 拿它们去要求「稀有度改成 Common」是**误报**（而且状态卡的稀有度只能是 Status，改不了）。
    ///
    /// 为什么必须查：本体 <c>MerchantInventory.PopulateCharacterCardEntries()</c> 会为
    /// <c>Player.Character.CardPool</c> **每一种牌型**（Attack / Skill / Power）各建一个货架，
    /// 而 <c>CardFactory.CreateForMerchant</c> 先把 <c>CardRarity.Basic</c> 全部滤掉，
    /// 再从掷出的稀有度开始 <c>GetNextAllowedRarity</c> 绕圈找一个「这个牌型真的存在的稀有度」；
    /// 一圈绕完（含 Basic / Ancient / Curse / Event / Token 这些**不参与**商店的档）都找不到 →
    /// <c>CardRarity.None</c> → 抛 <c>InvalidOperationException</c>（"Can't generate valid rarity for
    /// merchant card type Attack with card options: …"）。
    ///
    /// 这个异常抛在 <c>MerchantRoom.EnterInternal</c> 里（进商店**之前**就炸），
    /// 商店界面根本建不起来 → 表现就是**进商店黑屏**。而战斗奖励只抽「任意牌型」，
    /// 所以卡池只要 ≥3 张 Common/Uncommon/Rare 奖励就正常 —— 这解释了「奖励没事、商店黑」。
    /// </summary>
    public static List<string> MerchantMissingTypes(CharacterProfile p) =>
        MerchantShelvedCardTypes
            .Where(t => p.Cards.Any(c => !c.IsVanillaCard && c.InCardPool && c.CardType == t)
                        && !p.Cards.Any(c => !c.IsVanillaCard && c.InCardPool && c.CardType == t
                                             && c.Rarity is "Common" or "Uncommon" or "Rare"))
            .ToList();

    /// <summary>
    /// 本体会在商店里摆货架的牌型（<c>MerchantInventory._coloredCardTypes</c> 里去重后的三种）。
    /// 其它类型（状态 / 诅咒 / 任务）不进商店，所以不参与「上不了商店」那条检查。
    /// </summary>
    public static readonly IReadOnlyList<string> MerchantShelvedCardTypes = new[] { "Attack", "Skill", "Power" };

    /// <summary>卡牌配色的十六进制值（非法就退回默认）。</summary>
    private static string Hex(string? value, string fallback)
    {
        string ok = Profile.CardColorSpec.NormalizeHex(value);
        return ok.Length > 0 ? ok : fallback;
    }

    /// <summary>
    /// 「数值就是这条效果的强度」的效果种类（数值填 0 = 这条效果什么都没做）。
    ///
    /// 用户要求：这些效果填 0 时，在游戏里**不显示、也不执行** ——
    /// 因为本体的伤害 / 格挡会被力量 / 敏捷加成（0 点伤害 + 3 点力量 = 3 点伤害，
    /// 0 点格挡 + 2 点敏捷 = 2 点格挡），所以不能只是「写个 0 摆着」；
    /// 只有升级增量给了数值（升级后 > 0）时，这条效果才真的存在。
    ///
    /// 不在名单里的要小心：召唤伙伴（0 = 用「召唤物」页配置的血量）、大限已至（伤害 = 目标灾厄层数）、
    /// 三个「按生命值算」的伙伴攻击 / 牺牲伙伴（0 只是 CalculationBase 的固定加值）——
    /// 这些的 0 都是有意义的，不能当「没填」处理。
    /// </summary>
    /// <summary>
    /// 数值 = 「力度」的那些效果（0 就是「不生效」）。
    ///
    /// **用户要求**：所有效果种类都允许填 0，填 0 只是**不生效**（不显示、也不执行）。
    /// 所以除了「0 有别的含义」的那几种，其余全部列在这里 —— 配上 <see cref="IsInertZero"/> 就是
    /// 「0 值整条丢掉」，界面上的数值范围（EffectKindOption.Min）也一起放宽到 0。
    ///
    /// **0 有别的含义、绝不能列进来**的几种：
    ///   · SummonPet —— 0 = 用「召唤物」页配置的血量；
    ///   · GiveKeyword —— 0 = 这张牌自己；
    ///   · TurnEndPlay —— 0 = 这张牌自己；
    ///   · 宠物那几条（PetDamageByMaxHp / PetSacrifice…）—— 数值 = **额外加多少**（0 是常态，
    ///     真正的力度来自「按最大生命 / 当前生命算」那个公式），填 0 照样要生效。
    /// </summary>
    private static bool AmountIsStrength(EffectSpec e) =>
        e.Kind is "Damage" or "Block" or "Heal" or "HpLoss" or "MaxHp" or "Draw" or "Gold" or "Energy"
            or "OverdraftEnergy" or "ExtraResource" or "ApplyPower" or "TempPower" or "Outbreak"
            or "BoostCard" or "UpgradeCard" or "Scry" or "CopyCard" or "ReplayCard" or "ScrapeDraw"
            // 增加额外资源量上限值：数值 = 抬多少（0 = 这一条不生效，和别的「数值 = 力度」一致）
            or "RaiseResourceCap"
            // 抽到就减费：数值 = 回合数，0 = 这一条不生效（和「禁止获得格挡」同一套规矩）
            or "CheapenDraw"
            // 抽到这张牌时它自己本场战斗费用 -N：开关型（0 = 不生效）
            or "CheapenSelfOnDraw"
            // 禁止生命回复：数值 = 回合数，0 = 这一条不生效
            or "ForbidHeal"
            or "GenerateCard" or "ExhaustCard" or "TransformCard" or "DiscardCard"
            // 需求 ⑨：获得药水 —— 数值 = 瓶数，0 = 这一条不生效（和「生成卡牌」同一套规矩）
            or "GainPotion"
            or "TakeFromDraw" or "TakeFromDiscard" or "TakeFromExhaust"
            // 将此牌放回手牌：纯开关型（1 = 生效），0 一定不生效 —— 见 IsInertZero 的特判
            or "ReturnSelfToHand"
            or "AddCardGlobal" or "TransformCardGlobal" or "RemoveCardGlobal" or "UpgradeCardGlobal" or "CardReward"
        && !e.AmountIsXEffective && !e.AmountIsStack
        // 「数值公式」（需求：「另加一栏『数值公式』」）：数值栏只是**占位**（真正的数字打出时才算），
        // 所以就算它填 0，这条效果也照样存在 —— 不然后面 IsInertZero 会把整条效果丢掉，
        // 用户会看到「公式填了却什么都没发生」。和「数值 = X」同一个道理。
        && !e.UsesAmountFormula;

    /// <summary>
    /// 「数值 0 = 这张牌自己」的那几档（用户要求：丢弃卡牌填 0 = 丢弃这张牌自己）。
    ///
    /// 和 <see cref="IsToggleKind"/> 的区别：这些种类的 0 **不是**「不生效」，而是一个**有意义的档位**，
    /// 所以 <see cref="IsInertZero"/> 必须放行、<see cref="HasNoDynamicVar"/> 必须认（它们没有「张数」变量）。
    /// 目前只有「丢弃卡牌」（本体「计算赌博 / 幸存者」丢的都是别的牌，丢自己这一档本工具自己拼）。
    /// 判断里带上 `!AmountIsX`：勾了「数值 = X」时 0 只是占位，X 打出时才定。
    /// </summary>
    internal static bool AmountZeroIsSelf(EffectSpec? e) =>
        e is not null && e.Kind == "DiscardCard" && e.Amount <= 0m && !e.AmountIsXEffective;

    /// <summary>数值 0、升级也不加数值 → 整条效果丢掉：描述不写、代码也不生成。</summary>
    public static bool IsInertZero(EffectSpec e) =>
        // 「数值 0 = 这张牌自己」的那几档：0 是有意义的档位，绝不能丢
        !AmountZeroIsSelf(e)
        && ((IsToggleKind(e) && e.Amount == 0m)
            // 「纯开关型」的效果（放回手牌 / 抽到就减费自己）：值 0 = 关，而且升级增量对它没有任何意义
            //（它们没有可升级的数值，校验器会提醒）—— 所以这里不看 UpgradeAmount，一律当「不生效」。
            || (e.Amount == 0m && e.UpgradeAmount == 0m && AmountIsStrength(e)));

    /// <summary>
    /// 「纯开关型」的效果：数值只有「开 / 关」两种含义，0 = 不生效（升级增量对它没意义）。
    /// 它们的代码不写在 OnPlay 里，而是挂在卡自己的钩子上（见 EmitSelfReturnHook / EmitSelfDrawHook）。
    /// </summary>
    internal static bool IsToggleKind(EffectSpec? e) =>
        e is not null && e.Kind is "ReturnSelfToHand" or "CheapenSelfOnDraw";

    /// <summary>
    /// 数值 0、只有升级增量才给得出数值 → 没升级时整条不执行（<c>if (base.IsUpgraded)</c>）、
    /// 描述里也用本体的 <c>{IfUpgraded:show:…}</c> 藏起来（用户要求：只有升级后才有这个效果）。
    /// 要求它有动态变量（升级增量写在那个变量上）—— 没有变量的种类（额外资源量 0）不走这条。
    /// </summary>
    public static bool IsUpgradeOnlyZero(EffectSpec e) =>
        e.Amount == 0m && e.UpgradeAmount != 0m && AmountIsStrength(e) && !HasNoDynamicVar(e);

    /// <summary>「升级之后才有的效果」的运行时守卫（只对卡牌有意义：遗物 / 药水 / 状态没有升级这回事）。</summary>
    private static string? UpgradeOnlyGuard(EffectSpec e, bool isCard) =>
        isCard && IsUpgradeOnlyZero(e) ? "if (base.IsUpgraded)" : null;

    /// <summary>
    /// V0.2.141：「数值公式 + 升级增量」算出来**升级后正好是 0**（升级增量把常数公式抵平了）
    /// —— 升级过的那张牌打出去不会有任何效果。
    ///
    /// <para><b>为什么要有这条判据</b>：用户实测报「在生成器填负值的力量不生效」，查下来是两个原因叠在一起 ——
    /// ① 回读把同一个升级增量算了两遍（<c>-2</c> 的卡回读成 <c>UpgradeAmount=2</c>，
    /// 再生成出来升级后就是 <c>0</c> 层）；② 就算增量是对的（用户手填 <c>升级增量 2</c> 配公式 <c>-2</c>），
    /// 升级后那一档也确实是 0 层、而**界面上一个字都不说**。①已在 <c>ProjectRecovery</c> 修掉；
    /// ②在这里变成看得见的警告（见 <c>ProfileValidator</c>）。</para>
    ///
    /// <para>判据分两支，覆盖两处配置面：① 写了**纯常数公式**（那 5 种效果）→ 常数 + 增量 == 0；
    /// ② 没写公式、用**固定数值**（遗物 / 药水 / 状态，以及卡牌上不支持公式的种类）→ 数值 + 增量 == 0
    /// —— 后者是「老存档里残留的升级增量」那一档，同一个道理、同一句话提醒。</para>
    ///
    /// <para>⚠ 结果为零本身**不是错误**：老存档 / 用户自己就想这么配都得能继续生成，所以它只出「警告」。</para>
    /// </summary>
    internal static bool UpgradeCancelsToZero(CharacterProfile? p, EffectSpec e) =>
        e.UpgradeAmount != 0m
        && (ForgeNumbers.TryEffectFormulaConst(p, e, out decimal formulaValue) ? formulaValue : e.Amount) + e.UpgradeAmount == 0m;

    /// <summary>
    /// 效果列表那一行（<c>EffectSpec.Display</c>）要写的「升级后最终值」：纯常数公式 + 非零升级增量时给出
    /// 「升级后的档位是多少」（<c>UpgradeAmount</c>），其它情形返回 null（不写这个尾巴）。
    ///
    /// <para>为什么只对**常数公式**写：公式占位值（<c>Amount</c>）对「那 5 种」效果只是个占位，
    /// 真正打出去的是公式；给真·现算公式写「升级后 X」会写一个假数字（打出时才现算），
    /// 所以那些照旧只写「升级 +N」。判据和生成端 / 校验器同一份（<c>TryEffectFormulaConst</c>）。</para>
    /// </summary>
    public static decimal? ConstantFormulaUpgradeValue(CharacterProfile? p, EffectSpec e)
    {
        if (e.UpgradeAmount == 0m) return null;
        return ForgeNumbers.TryEffectFormulaConst(p, e, out decimal formulaValue) ? formulaValue + e.UpgradeAmount : null;
    }

    /// <summary>
    /// 这个种类**天生**就不声明动态变量（数值直接写在代码里）。
    /// 额外资源量 ≤ 0、召唤伙伴 0 层、数值 = X、全部召唤物内联计算这四种是**看数值**才决定的，
    /// 所以放在 <see cref="HasNoDynamicVar"/> 里 —— 两件事分开写（混在一起时踩过坑，见那边的注释）。
    /// </summary>
    /// <summary>
    /// 「播放音效」（V0.2.154）：本体所有声音都走 FMOD，一句 <c>SfxCmd.Play(事件路径, 音量)</c> 就行
    /// （本体自己也是这么放的：<c>CreatureCmd</c> 里的 block_gain / heal / PlayDamage…）。
    ///
    /// <para>音量 = 「数值」那一栏的百分比（留空 / 0 = 100%）→ 写成 <c>1f</c> / <c>1.5f</c>。</para>
    ///
    /// <para>⚠ 三条链（卡牌 / 遗物 / 药水）和自定义状态的触发时机**共用这一份**：
    /// <c>SfxCmd</c> 是静态的、不需要 choiceContext / 目标，所以哪里有「效果」哪里就能放。</para>
    /// </summary>
    internal static void EmitPlaySfx(CodeWriter w, EffectSpec e)
    {
        string path = (e.Sfx ?? "").Trim();
        if (path.Length == 0)
        {
            w.Line("// ⚠「播放音效」没选音效（「音效」那一栏是空的）：这条效果什么都不做（校验器也会提示）。");
            return;
        }
        decimal pct = e.SfxVolumePercent;
        string vol = (pct / 100m).ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) + "f";
        // 回读标记：路径和音量都认不出来（SfxCmd.Play 那一句虽然也能正则，但标记最稳）
        w.Line($"// CET:Sfx={path} CET:SfxVolume={Lit.Dec(pct)}");
        w.Line($"SfxCmd.Play({Lit.Str(path)}, {vol});   // 播放本体音效：{EffectCatalog.SfxDisplay(path)}"
            + (pct == 100m ? "（默认音量）" : $"（音量 {pct:0.##}%）"));
    }

    /// <summary>
    /// 「播放音频文件（我上传的）」（V0.2.155）：本体自己的声音全是 FMOD 事件，而模组**注册不了新的
    /// FMOD 事件**（bank 里只有事件 GUID）。所以这条路绕开 FMOD，用 Godot 自己的播放器：
    ///
    /// <code>
    /// {
    ///     var __sfx = new AudioStreamPlayer();
    ///     __sfx.Stream = GD.Load&lt;AudioStream&gt;("res://audio/xxx.ogg");
    ///     __sfx.VolumeDb = Mathf.LinearToDb(1f);
    ///     ((SceneTree)Engine.GetMainLoop()).Root.AddChild(__sfx);   // 模型不是 Node，挂到场景根上最稳
    ///     __sfx.Finished += __sfx.QueueFree;                        // 放完自己回收，不会越攒越多
    ///     __sfx.Play();
    /// }
    /// </code>
    ///
    /// <para>几点说明：① 整段包在 <c>{ }</c> 里 —— 同一条效果在一个方法里出现两次时局部变量名不会撞；
    /// ② 音量 = 「数值」那一栏的百分比 → <c>Mathf.LinearToDb(pct/100)</c>（Godot 的分贝）；
    /// ③ 文件是生成时复制进工程 <c>audio/</c> 的（<see cref="ArtGenerator"/> 负责复制），
    /// 导出预设是 <c>all_resources</c>，所以会一起打进 PCK。</para>
    /// </summary>
    internal static void EmitPlaySoundFile(CodeWriter w, EffectSpec e)
    {
        string key = (e.Sfx ?? "").Trim().Replace('\\', '/');
        if (key.Length == 0)
        {
            w.Line("// ⚠「播放音频文件」没选音频（「音频文件」那一栏是空的）：这条效果什么都不做"
                + "（到「美术资源」页上传一个 .ogg / .mp3 / .wav，校验器也会提示）。");
            return;
        }
        decimal pct = e.SfxVolumePercent;
        string vol = (pct / 100m).ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) + "f";
        w.Line($"// CET:SfxFile={key} CET:SfxVolume={Lit.Dec(pct)}");
        w.Line($"// 播放上传的音频：{key}（音量 {pct:0.##}%）—— Godot AudioStreamPlayer，不走 FMOD");
        w.Open("{");
        w.Line($"var {SfxPlayerVar} = new AudioStreamPlayer();");
        w.Line($"{SfxPlayerVar}.Stream = GD.Load<AudioStream>({Lit.Str("res://audio/" + key)});");
        w.Line($"{SfxPlayerVar}.VolumeDb = Mathf.LinearToDb({vol});");
        w.Line($"((SceneTree)Engine.GetMainLoop()).Root.AddChild({SfxPlayerVar});   // 模型不是 Node，挂场景根上");
        w.Line($"{SfxPlayerVar}.Finished += {SfxPlayerVar}.QueueFree;   // 放完自己回收");
        w.Line($"{SfxPlayerVar}.Play();");
        w.Close("}");
    }

    /// <summary>播放自定义音频那个局部变量名（固定一个就行：整段包在 <c>{ }</c> 作用域里）。</summary>
    private const string SfxPlayerVar = "__sfx";

    /// <summary>
    /// 这个种类**没有可以升级的数值**吗（<c>OnUpgrade</c> 里不会给它写 <c>UpgradeValueBy</c>）？
    /// 校验器用它来提醒「升级增量填了但不会生效」（以前是静默忽略的 —— 用户问过
    /// 「升级卡牌的升级增量没用吗」：战斗内的「升级卡牌」有用，但带「（全局）」的那些没有）。
    /// </summary>
    internal static bool KindIgnoresUpgradeIncrement(EffectSpec e) => NoDynamicVarKind(e) || AmountZeroIsSelf(e);

    private static bool NoDynamicVarKind(EffectSpec e) =>
        // 生成卡牌 / 变化卡牌：**现在声明 CardsVar 了**（见 VarDeclarationCore / VarNameOf）——
        // 用户报过「生成 / 变化卡牌的数值填了升级增量还是不变」：以前这两条在这里，
        // 于是既不声明变量、卡面也写死数字，升级增量无处可落（OnUpgrade 里根本没有那一行）。
        // 消耗 / 丢弃卡牌同理（同一条根因，见下）。
        e.Kind is "EndTurn" or "ExtraTurn" 
        // 需求 ⑨：获得药水 —— 瓶数是循环次数（写死在代码里），不声明动态变量。
        // **必须列在这里**：漏掉的话 VarDeclaration 的兜底会生成 new DynamicVar("Value", …)，
        // 和别的「没有数值的效果」撞名 → 本体 DynamicVarSet 抛 duplicate key（开新局就崩）。
        or "GainPotion"
        // 全局（牌组）类：获得 / 变化 / 删除牌组里的牌 —— 张数是循环次数，也不是动态变量。
        // **必须列在这里**：漏掉的话 VarDeclaration 的兜底会生成两个 new DynamicVar("Value", …)，
        // 本体的 DynamicVarSet 会直接抛 DynamicVarSet contains duplicate key 'Value'
        //（发生在构造卡牌时 → 开新局就崩、黑屏，实测踩过）。
        or "AddCardGlobal" or "TransformCardGlobal" or "RemoveCardGlobal" or "CardReward"
        // 「给予卡牌关键词」：数值 = 选几张牌（0 = 这张牌自己），不给这张牌加成任何动态变量
        or "GiveKeyword"
        // 「回合结束时自动打出」：数值 0 = 这张牌自己（**不能**被当成「0 = 不生效」丢掉），
        // 数值写死在代码里，不声明动态变量（0 那一档描述里也不用占位符）
        or "TurnEndPlay"
        // 用「目标卡」填满手牌：张数由手牌上限决定（代码里算），数值永远是 0，不声明动态变量
        or "FillHand"
        // 抽到就减费：数值 = 持续回合数（生成期字面量写进 PowerCmd.Apply），不声明动态变量
        or "CheapenDraw"
        // 禁止生命回复：数值 = 持续回合数（同样写死），不声明动态变量
        or "ForbidHeal"
    // 「翻倍状态层数」：数值 = 倍数（写死在代码里），不声明动态变量
    or "DoublePower" or "Expose" or "ClearPowerOne" or "ClearPowerDebuffs" or "ForbidBlock"
        // 击晕：没有数值，也不用声明动态变量
        or "Stun"
        // 播放音效（V0.2.154）：音量写在 SfxCmd.Play 那一句里，不声明动态变量
        //（**必须列在这里**，否则 VarDeclaration 的兜底会多写一个 new DynamicVar("Value", 0m)，
        //  和别的「没有数值的效果」撞名 → 本体 DynamicVarSet 抛 duplicate key）
        or "PlaySfx"
        // 播放上传的音频文件（V0.2.155）：同理，音量写死在 AudioStreamPlayer 那个块里
        or "PlaySoundFile"
        // 「伙伴替主人承伤」开 / 关：只挂 / 摘一个状态，没有数值 —— **必须列在这里**，
        // 否则 VarDeclaration 的兜底会多写一个 new DynamicVar("Value", 0m)（两条就撞名 → 开新局崩）
        or "PetGuardOn" or "PetGuardOff"
        // 「从某一摞拿牌到手牌」：**现在声明** CardsVar 了（见 VarDeclarationCore）——
        // 用户报过「卡面写着 {Value:diff()} 结果原样印出来」：以前这里把它当成「没有变量」，
        // 于是自定义描述里根本取不到「拿几张」这个数。现在给它一个正常的 CardsVar
        //（同一张牌拿两次时第二个自动起别名 Cards2），卡面写 {Cards:diff()} / {Cards2:diff()} 就能显示。
        // 「升级牌组里的牌（全局）」：张数同样是循环次数，不声明动态变量
        or "UpgradeCardGlobal"
        // 「将此牌放回手牌」：纯开关（数值 0/1），数值写死在生成代码里，不声明动态变量 ——
        // **必须列在这里**，否则 VarDeclaration 的兜底会生成 new DynamicVar("Value", …)，
        // 和别的「没有数值的效果」撞名 → 本体 DynamicVarSet 抛 duplicate key（开新局就崩）。
        or "ReturnSelfToHand"
        // 「抽到这张牌时它本场战斗费用 -N」：同样写死在卡自己的 AfterCardDrawn 里，不声明动态变量
        or "CheapenSelfOnDraw";

    /// <summary>
    /// 这一条效果到底有没有动态变量（CanonicalVars 会不会给它声明一个）。分成两部分：
    ///   ①「种类天生没有变量」→ <see cref="NoDynamicVarKind"/>；
    ///   ②「看数值才知道」：额外资源量 ≤ 0、召唤伙伴 0 层、数值 = X、全部召唤物内联计算。
    ///
    /// ⚠️ 早先这里把 ② 的「数值 = X」写成挂在 <see cref="AmountIsStrength"/> 名单末尾的
    /// <c>&amp;&amp; !e.AmountIsXEffective</c>，把两件事混成了一件：
    ///   · 【数值 = X】的「从抽牌堆拿牌」被当成**有**动态变量 → 卡牌自定义描述的「填入参数…」菜单里
    ///     跑出一个 <c>{Value:diff()}</c>，可生成代码里根本没声明过它（卡面上显示不出来）——
    ///     用户报「自定义描述的参数怎么缺失」时查到的就是这一类；
    ///   · 顺带让 IsInertZero 对「数值 = X」的种类失效（它们本来就不该按「0 = 不生效」处理）。
    /// </summary>
    internal static bool HasNoDynamicVar(EffectSpec e) =>
        NoDynamicVarKind(e)
        // 额外资源量：只有「正数获得」才声明变量（花费走 CanonicalStarCost，不占变量）
        || (e.Kind == "ExtraResource" && e.Amount <= 0)
        // 召唤伙伴：数值填 0 = 用「召唤物」页配置的血量（生成时直接读那只的常量，不声明变量）。
        // 注意：这条要和 ProjectRecovery 的 HasVar / SummonPet 回读保持一致 —— 声明了却没有变量可以取，
        // 或者没声明却被回读当成有变量，都会让「生成 → 回读 → 再生成」两边对不上。
        || (e.Kind == "SummonPet" && e.Amount <= 0)
        // 「数值 = X」时数值不存在 DynamicVar 里（直接取 X），所以不声明变量、也不要 OnUpgrade
        || e.AmountIsXEffective
        // 「全部召唤物」+「按生命值算收益」：改用内联计算（每只各自算），没有动态变量可声明，
        // 升级增量也直接写在表达式里（见 IsAllPetsInlineCalc）。
        || IsAllPetsInlineCalc(e)
        // 「取任意张 / 全部」：没有张数这个数字可显示（卡面写「任意张」「所有」），所以不声明变量。
        // **必须列在这里**：否则 OnUpgrade 会去写一个没声明的 Cards → 本体抛 KeyNotFoundException。
        || e.CountHasNoNumber
        // 「数值 0 = 这张牌自己」（丢弃卡牌）：这一档没有「张数」，不声明 Cards 变量 ——
        // 否则 OnUpgrade / 卡面占位符会去找一个不存在的数字（和「取任意张」同一个坑）。
        || AmountZeroIsSelf(e);

    /// <summary>
    /// 额外资源量花费：把负数「获得额外资源量」效果（按生效次数放大）累加成这张牌需要消耗的额外资源量。
    /// 0 表示这张牌不花额外资源量。
    ///
    /// <para>⚠ V0.2.131：卡牌页新增了「额外资源量费用」框（用户可以显式写数字 / <c>Y</c>）。
    /// 写了个式子时**以那个框为准**，不再从负数效果推算（避免「框里写了 3、效果里还留着 -2」两边打架）。</para>
    /// </summary>
    public static int StarCostOf(CardSpec c) => StarCostOf(null, c);

    /// <summary>带配置的版本（「额外资源量费用」框里的式子要拿自定义参数表才能折叠成常数）。</summary>
    public static int StarCostOf(CharacterProfile? p, CardSpec c)
    {
        // 「额外资源量费用」框写了东西 → 以它为准
        if (!string.IsNullOrWhiteSpace(c.StarCostFormula))
        {
            var r = ForgeNumbers.ResolveCost(p, c.StarCostFormula, "Y", allowPlus: false, "额外资源量费用");
            return r.IsConstant ? r.Value : 0;   // 写了 Y（全部资源量）时走 HasStarCostX，不声明固定费用
        }
        decimal need = 0m;
        foreach (var e in c.Effects)
        {
            if (e.Kind != "ExtraResource" || e.Amount >= 0) continue;
            need += (-e.Amount) * Math.Max(1, e.Times);
        }
        // 锻造卡（用户报的坑）：布上【能量】模块填的额外资源量消耗也是**这张牌的费用** ——
        // 声明成本体的星星费用，本体就会在打出前扣、不够时禁止打出、卡面数字变红。
        if (c.IsForged) need += ForgeGraphGen.ResourceCostOf(c.ForgeGraph);
        return need <= 0m ? 0 : (int)decimal.Ceiling(need);
    }

    /// <summary>
    /// 这张牌的**能量费用**是不是 X：
    /// 老勾选框 <c>CostIsX</c>，或者费用框里写了一个光秃秃的 <c>X</c>（V0.2.131 的等价写法）。
    /// </summary>
    public static bool IsCostX(CardSpec c) => c.CostIsX || ForgeNumbers.IsBareX(c.CostFormula);

    /// <summary>这张牌的**额外资源量费用**是不是 X/Y（老勾选框，或额外资源量费用框里写了 <c>Y</c>）。</summary>
    public static bool IsStarCostX(CardSpec c) => c.StarCostIsX || ForgeNumbers.IsBareY(c.StarCostFormula);

    /// <summary>
    /// 升级后 X 要加几（0 = 不加）：老勾选框「升级后 X +1」→ 1；
    /// 「升级后费用」框里写 <c>X</c> / <c>X+1</c> / <c>X+2</c> → 0 / 1 / 2。
    /// </summary>
    public static int CostXPlus(CardSpec c)
    {
        if (c.XPlusOnUpgrade) return 1;
        if (string.IsNullOrWhiteSpace(c.UpgradeCostFormula)) return 0;
        var r = ForgeNumbers.ResolveCost(null, c.UpgradeCostFormula, "X", allowPlus: true, "升级后费用");
        return r.IsX ? r.Plus : 0;
    }

    /// <summary>
    /// 一张牌的**能量费用**：普通卡就是卡牌页那个「费用」；**锻造卡**的费用由布左上角【能量】模块定
    /// （用户报的坑：以前那块填了也只在打出时偷偷扣一次，卡面 / 游戏里一直显示 0 费）。
    ///
    /// <para>⚠ V0.2.131：真正的实现挂在带配置的那个重载上（费用框里的 <c>A+3</c> 要拿参数表才能折叠）。
    /// 这里保留单参数版本给「拿不到配置」的老调用点（自检 / 界面列表显示）。</para>
    /// </summary>
    public static int CardCostOf(CardSpec c) => CardCostOf(null, c);

    /// <summary>带配置的版本（费用框里的 <c>A+3</c> 要拿自定义参数表才能折叠成常数）。</summary>
    public static int CardCostOf(CharacterProfile? p, CardSpec c)
    {
        // X 费：本体要求构造函数写 0（真正的消耗由本体按 HasEnergyCostX + ResolveEnergyXValue 结算）
        if (IsCostX(c)) return 0;
        if (c.IsForged) return ForgeGraphGen.EnergyCostOf(c.ForgeGraph);
        var r = ForgeNumbers.ResolveCost(p, c.CostFormula, "X", allowPlus: true, "费用");
        return r.IsConstant ? r.Value : c.Cost;
    }

    /// <summary>
    /// 按「生效次数」包一层循环：整条效果重复生效 N 次。
    ///
    /// 注意：body 外面**永远再包一层作用域 {}**：
    /// 同一条效果里可能内嵌自己的循环（随机目标 / 随机消耗 / 全局加牌…），
    /// 这些循环变量和临时变量（foes / hits / pick / other）如果和外面重名，C# 会直接 CS0136 编译不过
    /// （用户实测：一张「生效次数 = 3」的随机打敌人牌，生成出两层 for (int i…) 就炸了）。
    /// 注意 C# 不允许内层作用域重复声明外层的同名局部变量，所以内层的循环变量也全部用了 __ 前缀的名字。
    /// </summary>
    private static void EmitRepeated(CodeWriter w, EffectSpec e, Action<CodeWriter> body, bool useX = false)
    {
        // 「生效次数」写了公式（用户要求⑦）：上界现算 —— 夹到 1~20 次（和固定值那条同样的上限，
        // 免得公式算出 999 直接把一局卡死）。
        if (CountFormulaExpr(_formulaOwner, e, "Times", out _) is { } timesExpr)
        {
            w.Open($"for (int i = 0; i < (int)System.Math.Clamp({timesExpr}, 1m, 20m); i++)");
            w.Open("");
            body(w);
            w.Close();
            w.Close();
            return;
        }
        if (useX && e.TimesIsX)
        {
            w.Open($"for (int i = 0; i < {XVar}; i++)");
            w.Open("");
            body(w);
            w.Close();
            w.Close();
            return;
        }
        int times = Math.Max(1, e.Times);
        if (times > 1) w.Open($"for (int i = 0; i < {times}; i++)");
        w.Open("");
        body(w);
        w.Close();
        if (times > 1) w.Close();
    }

    private static void EmitCardEffect(CodeWriter w, CharacterProfile p, EffectSpec e, bool useX = false,
        Dictionary<EffectSpec, string>? varMap = null, string? petVar = null, PetGen.PetDef? petDef = null,
        string? effectComment = null, IReadOnlyDictionary<string, string>? petLookup = null, bool captureFatal = false)
    {
        // 数值 0 且升级也不加数值：整条丢掉（用户要求：不显示、也不执行）
        if (IsInertZero(e)) return;
        // 「数值公式」（需求：「另加一栏『数值公式』」）：公式本身写在效果那一行（打出时才求值），
        // 生成的代码里只剩算完的表达式，反推不回来 —— 所以在这里单独写一行标记，
        // 「从工程恢复存档」按它把公式原样认回去（见 ProjectRecovery 的 CET:AmountFormula）。
        if (e.UsesAmountFormula) w.Line($"// CET:AmountFormula={EscapeMarker(e.AmountFormula)}");
        // 次数类公式（用户要求⑦）：同样一行标记带走全部（键=公式，用 | 分隔；公式里不会出现 |，
        // 因为解析器只认字母 / 数字 / 运算符 / 括号）。
        if (e.UsesAnyCountFormula)
            w.Line("// CET:CountFormulas=" + EscapeMarker(string.Join("|",
                EffectSpec.CountFormulaKeys.Where(k => !string.IsNullOrWhiteSpace(e.CountFormula(k)))
                    .Select(k => k + "=" + ForgeFormula.DisplayText(e.CountFormula(k))))));
        // 「不同效果的概率之间是否独立」（V0.2.132）：**只在显式勾了「独立」时**写这一行 ——
        // 默认档（同组共用一次掷骰、各占区间）一个字都不写，老存档的生成文本因此逐字节不变。
        // 为什么要把百分比也带上：这一档的守卫是 `NextDouble() * 100.0 < N`，而回读**从来**
        // 不回读概率（老缺口，见 ProjectRecovery 里没有 ChanceEnabled 的分支）—— 不写就还原不出 N。
        if (e.ChanceEnabled && e.ChanceIndependent)
            w.Line("// CET:ChanceIndependent=1 CET:ChancePct="
                + e.ChancePercent.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture));
        // 条件数值的公式（用户要求⑦）：条件守卫那一行里已经变成算完的表达式，反推不回来 —— 所以整条条件
        // （种类 + 固定数值 + 状态 + 指向对象 + 两个公式）都写进一行标记，回读直接按它重建。
        // （标记写在条件守卫的**块内**：回读时由这一块里那条效果认领，见 ProjectRecovery 的 Done。）
        if (e.Condition is { } condWithFormula && condWithFormula.UsesAnyFormula)
            w.Line("// CET:CondFull=" + EscapeMarker(ConditionMarker(condWithFormula)));
        // 数值 0、靠升级才有数值：没升级时整条跳过（不然 0 点伤害会被力量加成、0 点格挡会被敏捷加成）
        string? zeroGuard = UpgradeOnlyGuard(e, isCard: true);
        if (zeroGuard is not null) w.Open(zeroGuard);
        // 次数公式要 __fgPlayer / __fgSelf ⇒ 告诉深处的发射器「现在生成的是这张卡」（见 _formulaOwner）
        CharacterProfile? prevFormulaOwner = _formulaOwner;
        _formulaOwner = p;
        try
        {
            EmitRepeated(w, e, x =>
            {
                // 宠物类效果：在这条效果的**第一行**写一行标记（单行，回读按它认种类与公式，见 MarkerText）
                if (IsPetKindForMarker(e.Kind))
                    x.Line($"// CET:PetEffect={MarkerText(e)}");
                EmitCardEffectOnce(x, p, e, useX, varMap, petVar, petDef, effectComment, petLookup, captureFatal);
            }, useX);
        }
        finally
        {
            _formulaOwner = prevFormulaOwner;
        }
        if (zeroGuard is not null) w.Close();
    }

    /// <summary>
    /// 「全部召唤物」+「按生命值算收益」的宠物效果：改用**内联计算**（<c>(decimal)pet.MaxHp</c> 这种）。
    ///
    /// 为什么不能继续用本体那套计算变量：<c>CalculatedDamage / CalculatedBlock / CalculationBase</c>
    /// 名字是固定的（本体按名字取），一张牌只有一套 —— 而「全部召唤物」是每只各算一次，
    /// 各自的倍率来源都不同，一套变量装不下。所以这一档既不声明动态变量，卡面也不显示具体数字
    /// （见 LocalizationGen：描述里写明「各自按自己的生命值算」）。
    /// 升级增量也直接写成 <c>(base.IsUpgraded ? N : 0m)</c>（和 CalculationBase 的加值等价）。
    /// </summary>
    internal static bool IsAllPetsInlineCalc(EffectSpec e) =>
        PetGen.IsAll(e.PetSummon) && PetFormula(e) is not null and not "fixed";

    /// <summary>
    /// 卡面描述里该用的动态变量名 —— 必须是 <c>CanonicalVars</c> 里**真实声明**的那个键。
    ///
    /// 为什么不能直接用 <see cref="VarNameOf"/>：三个「按生命值算的伙伴攻击」和「牺牲伙伴（按生命值算）」
    /// 声明的是本体那套**固定名字**的计算变量（<c>CalculatedDamage</c> / <c>CalculatedBlock</c>，
    /// 见 <see cref="CalcDamageVars"/> / <see cref="PetSacrificeVarDecl"/>），
    /// 而 <see cref="VarNameOf"/> 给它们起的名字（PetMaxHpDamage 这种）只是**我们自己内部**用来去重的。
    /// 用错名字的后果：卡面上直接原样印出 <c>{PetMissingHpDamage:diff()}</c>
    /// （用户实测截图报过：已损失生命值 / 最大生命值那两种、以及牺牲伙伴的收益都是这样）——
    /// 因为本地化文本里的 <c>{名字:diff()}</c> 在本体的 DynamicVars 里找不到同名变量。
    /// </summary>
    public static string DisplayVarNameOf(EffectSpec e, Dictionary<EffectSpec, string>? map = null) =>
        PetFormula(e) is not null and not "fixed"
            ? (e.Kind == "PetSacrifice" && e.PetSacrificeGain != "Damage" ? "CalculatedBlock" : "CalculatedDamage")
            : VarNameOf(e, map);

    /// <summary>
    /// 生成后自检：这份源码里有没有「引用了、但 CanonicalVars 里没声明」的动态变量。
    /// 返回缺失的变量名（空列表 = 没问题；**认不出来的变量类型会跳过整张卡的自检**，宁可漏报不误报）。
    ///
    /// 为什么必须查：本体的 <c>DynamicVars</c> 是**按名字取**的，取不到就抛 <c>KeyNotFoundException</c>。
    /// 这个异常发生在「卡牌被升级 / 牌组界面预览升级（『查看升级』）/ 卡面渲染」时，
    /// 表现是**牌组界面整个打不开、一片空白**（用户实测报过：牺牲伙伴选「固定 N」又填了升级增量，
    /// 升级增量被写到没声明的 CalculationBase 上，一开牌组就看不到牌）。
    /// 只有游戏里才会暴露，所以生成完就自己查一遍，把它当成生成错误拦住。
    /// </summary>
    public static IReadOnlyList<string> MissingDynamicVars(string source)
    {
        var m = System.Text.RegularExpressions.Regex.Match(source, @"CanonicalVars\s*=>\s*\[(.*?)\];",
            System.Text.RegularExpressions.RegexOptions.Singleline);
        var declared = new HashSet<string>(StringComparer.Ordinal);
        if (m.Success)
        {
            foreach (string item in SplitTopLevel(m.Groups[1].Value))
            {
                string s = item.Trim();
                if (s.Length == 0) continue;
                // 1) 起了名字的（new DynamicVar("PetHp", 0m) / new BlockVar("PetSacrificeBlock", 6m, …)）
                //    ⚠ 只认「构造函数**第一个参数**就是字符串」的写法。以前是「这一项里随便哪个字符串都算」，
                //    而「数值公式」的 lambda 里会写状态的类名（例：`ForgeFormulaRuntime.PowerAmount(…, "StellePower4")`）
                //    → 自检把变量名认成了状态的类名，于是误报「Damage / Block 没有声明」把生成整个拦住
                //    （用户实测：公式里引用了自定义状态层数的那几张卡全中招）。
                var named = System.Text.RegularExpressions.Regex.Match(s, @"^new\s+[A-Za-z0-9_<>,\.\s]+\(\s*""([^""]+)""");
                if (named.Success) { declared.Add(named.Groups[1].Value); continue; }
                // 2) 没起名字的：按变量类型的默认键名（和本体一致）
                var ty = System.Text.RegularExpressions.Regex.Match(s, @"new\s+([A-Za-z0-9_]+)");
                if (!ty.Success) continue;
                string tn = ty.Groups[1].Value;
                if (tn == "PowerVar" || tn == "ForgeFormulaPowerVar")
                {
                    // 没起名字的 PowerVar<T>：键就是 T 的名字 —— 必须**认出来**，
                    // 否则整张卡的自检会放弃（见下面 def is null 那条），真正的漏声明就漏报了。
                    // ForgeFormulaPowerVar<T> 是「数值公式」用的现算版本（V0.2.111），键同样是状态的类名。
                    var pw = System.Text.RegularExpressions.Regex.Match(s, @"(?:ForgeFormula)?PowerVar<(\w+)>");
                    if (!pw.Success) continue;                          // 认不出来这一项 → 跳过这一项即可
                    declared.Add(pw.Groups[1].Value);
                    continue;
                }
                string? def = tn switch
                {
                    "DamageVar" => "Damage",
                    "BlockVar" => "Block",
                    // 「数值公式」用的现算版本（V0.2.111）：键和本体那几个一模一样（卡面占位符不变）
                    "ForgeFormulaDamageVar" => "Damage",
                    "ForgeFormulaBlockVar" => "Block",
                    "ForgeFormulaHpLossVar" => "HpLoss",
                    "ForgeFormulaHealVar" => "Heal",
                    "CardsVar" => "Cards",
                    "EnergyVar" => "Energy",
                    "HealVar" => "Heal",
                    "HpLossVar" => "HpLoss",
                    "MaxHpVar" => "MaxHp",
                    "GoldVar" => "Gold",
                    "StarsVar" => "Stars",
                    "CalculationBaseVar" => "CalculationBase",
                    "CalculationExtraVar" => "CalculationExtra",
                    "ExtraDamageVar" => "ExtraDamage",
                    "CalculatedDamageVar" => "CalculatedDamage",
                    "CalculatedBlockVar" => "CalculatedBlock",
                    _ => null,
                };
                if (def is null)
                {
                    // 认不出来的**这一项**只跳过自己，不要放弃整张卡的检查 ——
                    // 以前是 return Array.Empty<string>()，等于「有一项看不懂，就把这张卡的漏声明全放过」，
                    // 那正是漏报的来源（本次就是被匿名 PowerVar 触发的）。宁可漏报一项，不能漏整张卡。
                    continue;
                }
                declared.Add(def);
            }
        }

        var refs = new HashSet<string>(StringComparer.Ordinal);
        foreach (System.Text.RegularExpressions.Match r in System.Text.RegularExpressions.Regex.Matches(
                     source, @"base\.DynamicVars\.([A-Za-z0-9_]+)"))
            refs.Add(r.Groups[1].Value);
        foreach (System.Text.RegularExpressions.Match r in System.Text.RegularExpressions.Regex.Matches(
                     source, @"base\.DynamicVars\[""([^""]+)""\]"))
            refs.Add(r.Groups[1].Value);
        return refs.Where(x => !declared.Contains(x)).OrderBy(x => x, StringComparer.Ordinal).ToList();
    }

    /// <summary>按**顶层**逗号切分（跳过括号 / 方括号里的逗号）—— 用来拆 CanonicalVars 的每一项。</summary>
    private static IEnumerable<string> SplitTopLevel(string s)
    {
        int depth = 0, start = 0;
        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            if (c is '(' or '[' or '<') depth++;
            else if (c is ')' or ']' or '>') depth--;
            else if (c == ',' && depth <= 0)
            {
                yield return s.Substring(start, i - start);
                start = i + 1;
            }
        }
        if (start < s.Length) yield return s.Substring(start);
    }

    /// <summary>要不要写 <c>// CET:PetEffect=…</c> 标记（新增的那批宠物效果都要，SummonPet / PetAttack 保持原样）。</summary>
    internal static bool IsPetKindForMarker(string kind) =>
        kind is "PetDamageByMaxHp" or "PetDamageByCurHp" or "PetDamageByMissingHp"
            or "PetHeal" or "PetLoseHp" or "PetGainMaxHp" or "PetSacrifice" or "PetApplyPower"
            or "PetGuardOn" or "PetGuardOff";

    /// <summary>
    /// 「这条召唤伙伴」对应的**查询变量名**（那张牌在 OnPlay 开头声明的 <c>Creature? __&lt;宠物&gt;</c>）。
    ///
    /// 为什么召唤也要这个：同一张牌里如果还有别的宠物效果（替主人承伤 / 伙伴攻击 / 给伙伴加血…），
    /// 它们用的都是那个变量；而它是在**召唤之前**查的、这时必然是 null ——
    /// 不把 <c>Summon</c> 返回的那只写回去，后半段就全被 <c>if (__pet is not null)</c> 跳过了，
    /// 玩家会看到「卡打出去了、但伙伴没承伤 / 没攻击」（用户实测的正是「召唤小八替你挨打」这张）。
    /// 变量的声明规则和 CardSource 里的 petLookup 一致：只有这张牌真的有「需要已召唤宠物」的效果时才有这个变量，
    /// 所以这里查不到就返回 null（纯召唤牌不写回，免得引用一个没声明的变量 → CS0103）。
    /// </summary>
    private static string? PetSummonVarOf(CharacterProfile p, EffectSpec e, PetGen.PetDef? petDef, IReadOnlyDictionary<string, string>? petLookup)
    {
        if (petLookup is null) return null;
        string? cls = (petDef ?? PetGen.Resolve(p, e.PetSummon))?.ClassName;
        return cls is not null && petLookup.TryGetValue(cls, out string? v) ? v : null;
    }

    private static void EmitCardEffectOnce(CodeWriter w, CharacterProfile p, EffectSpec e, bool useX = false,
        Dictionary<EffectSpec, string>? varMap = null, string? petVar = null, PetGen.PetDef? petDef = null,
        string? effectComment = null, IReadOnlyDictionary<string, string>? petLookup = null, bool captureFatal = false,
        bool inDelayedBody = false, IReadOnlyDictionary<string, string>? literalAmounts = null)
    {
        // 「延迟状态」里没有卡牌的动态变量（CanonicalVars）也没有序号公式上下文 ——
        // 数值一律用生成期折好的字面量（键 = 变量名，见 DelayedVarMap）。
        if (inDelayedBody)
        {
            string lit = LiteralAmountOf(e, literalAmounts);
            EmitCardEffectSwitch(w, p, e, lit, useX: false, petVar: petVar, petDef: petDef,
                effectComment: effectComment, petLookup: petLookup, blockAmtOverride: lit);
            return;
        }
        // 「数值公式」（需求：「另加一栏『数值公式』」）：写了公式就用公式算出来的那个值，
        // 动态变量（CanonicalVars 里那个）只是占位、没人再去读它。
        // 求值用的局部变量（__pM / __X / __Y…）由 OnPlay（或卡牌时机钩子）开头的
        // ForgeGraphGen.EmitCardFormulaPrologue 先声明好 —— 这里只管用。
        string? formula = ForgeGraphGen.CardFormulaExpr(p, e, out _);
        string amt = formula ?? AmountExpr(e, useX, varMap);
        // ===== 升级增量（用户实测：「升级增量怎么没效果了」）=====
        // 打了「数值公式」的卡，打出时用的是**公式算出来的那个值**（不读 CanonicalVars 里的变量），
        // 而本体的升级增量是 `OnUpgrade` 里 `base.DynamicVars["Damage"].UpgradeValueBy(3m)` —— 改的是变量，
        // 两边不搭界，于是升级前后打出来一样多。这里把增量直接并进「打出时」的表达式
        // （写法沿用本体习惯的「升级前后两个数」，见 <see cref="UpgradeAwareAmount"/>）。
        // 变量那边也同步带上增量（见 VarDeclarationCore / FormulaVarsSource），卡面数字才和打出来的一致。
        if (formula is not null && e.UpgradeAmount != 0m) amt = UpgradeAwareAmount(e, formula);
        // 作用对象是「队友」时写一行标记：生成出来的语句和「指定敌人」**长得一模一样**
        //（都是 `cardPlay.Target`），回读分不出这两档，只能靠标记还原（见 ProjectRecovery 的 pendingTargetSide）。
        // V0.2.132：「全体单位」的循环体（CombatState.Creatures）也认不出来，一起写标记；
        // 「全部友方不包括召唤物」的过滤条件补在标记里（` CET:AllyNoPets=1`）—— 老存档两样都不会写，
        // 生成文本一个字节不变。
        if (e.TargetSide is "Ally" or "AllAllies" or "AllUnits")
            w.Line($"// CET:TargetSide={e.TargetSide}" + (e.AllAlliesExcludePets ? " CET:AllyNoPets=1" : ""));
        // 「下回合生效」的**新支持种类**（V0.2.133）：现在只挂延迟状态，下回合开始时由它
        // 跑同一套发射器（见 EmitDelayedEffectBody / DelayedPowersSource）。
        // ⚠ 这一段在老存档上**永远不会**走到「多生成」：这些种类在 V0.2.132 及以前界面上
        //    根本没有「下回合生效」勾选框（SupportsNextTurn=false），所以老存档里它们必然 NextTurn=false。
        // ⚠ inDelayedBody = true 时**不能**再走这里 —— 那是在延迟状态类里「重放」这条效果，
        //    再挂一次延迟状态就成了无限套娃（实测：生成出来的类里挂它自己）。
        if (!inDelayedBody && UsesDelayedEffectBranch(e))
        {
            EmitDelayedPowerApply(w, p, e, "base.Owner.Creature", "base.Owner.Creature");
            return;
        }
        // 「下回合生效」的**生成类**效果（用户要求：生成卡牌之类也要能下回合）：现在不生成，
        // 改成给自己挂一个延迟状态（层数 = 张数），下回合开始时由它调用同一套发射器（见 DelayedPowersSource）。
        // 标记行要写在这里 —— 回读是**按用它的那张牌**认效果的（延迟状态类里那几个标识别写重复）。
        if (e.NextTurn && IsDelayedSpawnKind(e.Kind))
        {
            // 张数：有动态变量的（生成卡牌 → Cards）走变量，没有的那些（全局类）用字面量 ——
            // 用字面量是因为它们本来就不声明变量（`HasNoDynamicVar`），写 `base.DynamicVars["Value"]` 会取不到。
            string n = HasNoDynamicVar(e)
                ? Math.Max(1, (int)Math.Round(e.Amount, MidpointRounding.AwayFromZero)).ToString() + "m"
                : (formula ?? AmountExpr(e, useX, varMap));
            // 两行标记：`SpawnMarker`（范围 / 张数模式 / 附加处理）+ `SelfContainedMarker`（种类 / 数值 /
            // 复制份数 / 选牌方式 / 哪一摞）+ `CET:NextTurn=1`（回读时才知道这条是「下回合生效」）。
            // 回读按这两行造出效果，紧跟着的注释和 Apply 那行整段跳过（见 ProjectRecovery 的跳过名单）。
            w.Line(SpawnMarker(e, withKind: true));
            w.Line(SelfContainedMarker(e) + " CET:NextTurn=1");
            w.Line($"// 下回合生效：现在只挂延迟状态，下回合开始时再{EffectCatalog.FindKind(e.Kind).Display}");
            w.Line($"await PowerCmd.Apply<{DelayedPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {n}, base.Owner.Creature, this);");
            return;
        }
        // 「直接把缓慢设成 N%」：本体的做法就是只施加 1 层（层数对「缓慢」没有作用），
        // 而且 amount == 0 时 PowerCmd.Apply 会直接 return（状态根本不会挂上），所以必须给 1。
        if (IsSlowPercentEffect(e)) amt = "1m";
        // 格挡走的是另一条取数路径（BlockValueAccess），单独把公式接上去（升级增量同理）
        string blockAmt = formula is not null
            ? (e.UpgradeAmount != 0m ? UpgradeAwareAmount(e, formula) : formula)
            : BlockValueAccess(varMap, e);
        EmitCardEffectSwitch(w, p, e, amt, useX, varMap, petVar, petDef, effectComment, petLookup, captureFatal, blockAmt);
    }

    /// <summary>
    /// 一条效果「到底做什么」的那一大段 <c>switch</c>（V0.2.133 从 <see cref="EmitCardEffectOnce"/>
    /// 里原样搬出来的，一个字都没改 —— 搬出来只是为了让**延迟状态**那条路也能跑同一套发射器）。
    /// </summary>
    private static void EmitCardEffectSwitch(CodeWriter w, CharacterProfile p, EffectSpec e, string amt, bool useX = false,
        Dictionary<EffectSpec, string>? varMap = null, string? petVar = null, PetGen.PetDef? petDef = null,
        string? effectComment = null, IReadOnlyDictionary<string, string>? petLookup = null, bool captureFatal = false,
        string? blockAmtOverride = null)
    {
        // ⚠ 延迟状态那条路传进来的 blockAmt 是**已经折好的字面量**（那里没有 base.DynamicVars）。
        string blockAmt = blockAmtOverride ?? BlockValueAccess(varMap, e);
        switch (e.Kind)
        {
            case "EndTurn":
                w.Line("PlayerCmd.EndTurn(base.Owner, canBackOut: false);");
                break;

            case "ExtraTurn":
                w.Line($"await PowerCmd.Apply<{Naming.From(p).ExtraTurnPowerClass}>(choiceContext, base.Owner.Creature, 1m, base.Owner.Creature, this);");
                break;

            case "GenerateCard":
                EmitGenerateCard(w, p, e, useX, CountExprAt(e, varMap, useX));
                break;

            // 本回合这张牌自己费用变 0（用户要求）。用本体的 CardModel.SetToFreeThisTurn()：
            // 内部是 EnergyCost.SetThisTurnOrUntilPlayed(0) + SetStarCostThisTurn(0) ——
            // 即「本回合内费用变 0（打出之后恢复）」，能量费和额外资源量费一起管（本体「子弹时间」就是这套）。
            // 为什么用 SetThisTurnOrUntilPlayed 而不是 SetThisTurn：打出记录已经生成了，卡的
            // EnergyCost 是最后一次读；「或打出前」那一档对本回合没有任何区别，而且它跟本体
            // 绝大多数「本回合费用变 0」的写法一致（SetThisTurn 只留给「同一回合内多次打出也要免费」那几张）。
            case "CheapenSelf":
                w.Line("base.SetToFreeThisTurn();   // 本回合这张牌自己费用变 0（本体 CardModel.SetToFreeThisTurn：能量费 + 额外资源量费一起）");
                break;

            // 播放音效（V0.2.154）：一句 SfxCmd.Play 就完事（三条链共用同一个发射器）
            case "PlaySfx":
                EmitPlaySfx(w, e);
                break;

            // 播放上传的音频文件（V0.2.155）：Godot AudioStreamPlayer（不走 FMOD —— 模组注册不了 FMOD 事件）
            case "PlaySoundFile":
                EmitPlaySoundFile(w, e);
                break;

            // 增加额外资源量上限值（用户要求）：给那个隐藏状态加层数，上限 = 基础上限 + 层数。
            // 状态是「谁身上谁受益」，所以固定打给自己（base.Owner.Creature）。
            case "RaiseResourceCap":
                w.Line($"await PowerCmd.Apply<{StarCapPowerClass(p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, this);   // 额外资源量上限提高");
                break;

            // 获得药水（需求 ⑨）：不需要 choiceContext（本体 PotionCmd.TryToProcure 不收 context）
            case "GainPotion":
                EmitGainPotion(w, e, useX);
                break;

            case "ExhaustCard":
                EmitExhaustCard(w, p, e, useX, CountExprAt(e, varMap, useX));
                break;

            case "DiscardCard":
                EmitDiscardCard(w, p, e, useX, CountExprAt(e, varMap, useX));
                break;

            case "TransformCard":
                EmitTransformCard(w, e, useX, p, countExpr: CountExprAt(e, varMap, useX));
                break;

            case "UpgradeCard":
                EmitUpgradeCard(w, p, e, useX, CountExprAt(e, varMap, useX));
                break;

            case "Scry":
                EmitScry(w, p, e, useX, CountExprAt(e, varMap, useX));
                break;

            case "ScrapeDraw":
                EmitScrapeDraw(w, p, e, amt);
                break;

            case "FillHand":
                EmitFillHand(w, e);
                break;

            // 抽到就减费：给自己挂上生成的 <角色>ForgeDrawCostPower（层数 = 持续回合数）。
            // 负数 = 反向扣层数（ApplyPowerLine 的那条路）。
            case "CheapenDraw":
                w.Line(SelfContainedMarker(e));
                w.Line(ApplyPowerLine(e, useX, Naming.From(p).DrawCostPowerClass, "base.Owner.Creature",
                    Math.Abs((int)e.Amount).ToString(), "base.Owner.Creature") + "   // 抽到就减费");
                break;

            case "Outbreak":
                EmitOutbreak(w, e, amt, "this");
                break;

            case "TimesUp":
                EmitTimesUp(w, e);
                break;

            case "TakeFromDraw":
                EmitTakeFromPile(w, p, e, "Draw", useX, CountExprAt(e, varMap, useX));
                break;

            case "TakeFromDiscard":
                EmitTakeFromPile(w, p, e, "Discard", useX, CountExprAt(e, varMap, useX));
                break;

            // 从消耗牌堆拿牌到手牌（消耗牌堆同样是战斗牌堆，走同一个本体 API）
            case "TakeFromExhaust":
                EmitTakeFromPile(w, p, e, "Exhaust", useX, CountExprAt(e, varMap, useX));
                break;

            // 复制卡牌：选/随机拿 N 张，每张复制「复制的份数」份（本体「二刀流」的官方做法）
            case "CopyCard":
                EmitCopyCard(w, p, e, useX, CountExprAt(e, varMap, useX));
                break;

            // 重放卡牌：给选中的牌加上「重放 N 次」（本体 CardModel.BaseReplayCount）
            case "ReplayCard":
                EmitReplayCard(w, p, e, useX, CountExprAt(e, varMap, useX));
                break;

            // 放置卡牌（用户要求）：数值 0 = 这张牌自己；≥ 1 = 从某一摞挑 N 张放到「放到哪一摞」
            case "PlaceCard":
                EmitPlaceCard(w, p, e, useX, CountExprAt(e, varMap, useX), selfExpr: "this");
                break;

            // 回合结束时自动打出：数值 0 = 这张牌自己；≥ 1 = 先选好 N 张，回合结束时打出去
            case "TurnEndPlay":
                EmitTurnEndPlay(w, e, p, useX, selfExpr: "this");
                break;

            case "AddCardGlobal":
            case "TransformCardGlobal":
            case "RemoveCardGlobal":
            case "UpgradeCardGlobal":
                EmitGlobalCardEffect(w, e, "base.Owner", useX, p);
                break;

                case "CardReward":
                    EmitCardReward(w, e, "base.Owner", useX);
                    break;

            case "Damage":
                EmitAttack(w, e, amt, useX, captureFatal);
                break;

            // ===== 召唤伙伴（本体的通用宠物 API，不需要补丁）=====
            case "SummonPet":
                // 把「这只宠物在这张牌里的查询变量」（如果声明了）传进去：召唤命令返回的那只要写回它，
                // 否则同一张牌后面那些宠物效果（承伤 / 攻击 / 加血…）第一次会被 `if (__pet is not null)` 整条跳过
                EmitSummonPet(w, e, p, amt, useX, effectComment, petDef, PetSummonVarOf(p, e, petDef, petLookup));
                break;

            case "PetAttack":
                EmitPetAttack(w, e, p, petVar ?? "__pet", amt, useX, petDef);
                break;

            // ===== 新增的那批宠物效果（都要「已经召唤出来的那只」，外面已经包了 if (pet != null)）=====
            // 三个按生命值算的伙伴攻击：用本体攻击链 + 计算变量三件套；attacker 换成宠物。
            case "PetDamageByMaxHp":
            case "PetDamageByCurHp":
            case "PetDamageByMissingHp":
                EmitPetCalculatedAttack(w, e, p, petVar ?? "__pet", useX, petDef);
                break;

            case "PetHeal":
                EmitPetHeal(w, e, petVar ?? "__pet", amt);
                break;

            case "PetLoseHp":
                EmitPetLoseHp(w, e, petVar ?? "__pet", amt);
                break;

            case "PetGainMaxHp":
                EmitPetGainMaxHp(w, e, petVar ?? "__pet", amt);
                break;

            case "PetSacrifice":
                EmitPetSacrifice(w, e, p, petVar ?? "__pet", varMap, useX, petDef);
                break;

            case "PetApplyPower":
                EmitPetApplyPower(w, p, e, petVar ?? "__pet", amt, varMap);
                break;

            case "PetGuardOn":
                EmitPetGuard(w, p, petVar ?? "__pet", on: true);
                break;

            case "PetGuardOff":
                EmitPetGuard(w, p, petVar ?? "__pet", on: false);
                break;

            // ===== 透支能量：现在拿 N 点，下回合少 N 点（走生成的负债 Power）=====
            case "OverdraftEnergy":
                w.Line($"await PowerCmd.Apply<{Naming.From(p).EnergyDebtPowerClass}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, this);"
                    + "   // 透支：施加时立刻给能量，下回合能量重置后再扣掉（本体 GainEnergy 忽略负数，所以必须自己扣）");
                break;

            // ===== 给予卡牌关键词 =====
            // 数值 = 选几张牌（**0 = 这张牌自己**），从「选牌方式 / 从哪里选牌」挑，
            // 给它们加上「给予关键词」里选的那个关键词（本体枚举名 或 自定义关键词的键）。
            // 勾了「是否为临时关键词」= 只本回合有效：
            //   · 保留 / 奇巧 → 本体的单回合标记（GiveSingleTurnRetain / GiveSingleTurnSly，回合末自动复位）；
            //   · 其它本体关键词 → 现在就 AddKeyword，再挂一个我们生成的临时 Power，回合结束时 RemoveKeyword；
            //   · 自定义关键词 → 走生成的「关键词补丁」注册表（卡面文字 + 悬停说明都是它加的），临时时由临时 Power 摘掉。
            case "GiveKeyword":
                EmitGiveKeyword(w, p, e, useX, "base.Owner", "base.Owner.Creature", "this", selfAllowed: true);
                break;

            // ===== 击晕 =====
            // 本体的「击晕」不是状态（Power），而是**怪物意图**：CreatureCmd.Stun(creature)
            // （本体卡「口哨 Whistle」就是这么写的）。被打晕的敌人这一回合什么都不做。
            case "Stun":
                EmitStun(w, e, useX, "cardPlay.Target", "base.CombatState.HittableEnemies", "base.Owner");
                break;

            // ===== 强化指定卡牌（像本体「精准」对「小刀」）=====
            // 给自己挂一张生成的「强化」Power：它在状态栏里显示，只给**你指定的那一张卡**的
            // 伤害 / 格挡加「层数」那么多（本场战斗内一直有效）。
            // 写法照抄本体 AccuracyPower（伤害）/ DexterityPower（格挡），只把判定从「小刀」换成指定的卡。
            case "BoostCard":
                w.Line(BoostMarker(e));
                w.Line($"await PowerCmd.Apply<{BoostPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, this);"
                    + $"   // 强化「{(string.IsNullOrWhiteSpace(e.SpawnCardId) ? "?" : e.SpawnCardId!.Trim())}」的{(e.BoostStat == "Block" ? "格挡" : "伤害")}：层数 = 加多少");
                break;

            case "Block":
                // 「生成调试日志」（V0.2.142，默认关）：把目标 + 实际用的格挡值写进日志
                DebugLogGen.Target(w, e, ChainTargetExpr(e, "cardPlay.Target", "base.Owner.Creature"),
                    IsNegativeAmount(e, useX) ? AbsExpr(amt) : blockAmt, inLoop: IsMultiTargetSide(e));
                if (IsNegativeAmount(e, useX))
                    // 负数 = 失去 N 点格挡（本体 GainBlock 对非正数什么都不做，得走 LoseBlock；
                    // remover 传我们这边，本体用它记「谁削掉的」）
                    EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.LoseBlock(choiceContext, {c}, {AbsExpr(amt)}, base.Owner.Creature);   // 负数 = 失去格挡");
                else if (e.NextTurn)
                {
                    w.Line($"await PowerCmd.Apply<BlockNextTurnPower>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, this);");
                }
                else if (useX && e.AmountIsXEffective)
                    // 格挡 = X：BlockVar 那条重载只能吃固定值，X 要走 decimal 重载
                    EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.GainBlock({c}, x, ValueProp.Move, cardPlay);");
                else
                    EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.GainBlock({c}, {blockAmt}, ValueProp.Move, cardPlay);");
                break;

            case "Draw":
                if (e.NextTurn)
                    w.Line($"await PowerCmd.Apply<DrawCardsNextTurnPower>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, this);");
                else
                    w.Line($"await CardPileCmd.Draw(choiceContext, {amt}, base.Owner);");
                break;

            case "Energy":
                if (e.NextTurn)
                    // 下回合生效：正数用本体的 EnergyNextTurnPower；负数（下回合少 N 点）它做不到
                    // （AfterEnergyReset 走的还是 GainEnergy，负数被忽略）→ 用我们生成的负债 Power。
                    w.Line(IsNegativeAmount(e, useX)
                        ? $"await PowerCmd.Apply<{Naming.From(p).EnergyNextTurnDebtPowerClass}>(choiceContext, base.Owner.Creature, {AbsExpr(amt)}, base.Owner.Creature, this);   // 下回合少 N 点能量"
                        : $"await PowerCmd.Apply<EnergyNextTurnPower>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, this);");
                else
                    w.Line(GainEnergyLine(e, amt, useX, "base.Owner"));
                break;

            case "Heal":
                DebugLogGen.Target(w, e, ChainTargetExpr(e, "cardPlay.Target", "base.Owner.Creature"),
                    IsNegativeAmount(e, useX) ? (-e.Amount).ToString("0.##", System.Globalization.CultureInfo.InvariantCulture) + "m" : amt,
                    inLoop: IsMultiTargetSide(e));
                if (IsNegativeAmount(e, useX))
                    EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.Damage(choiceContext, {c}, {-e.Amount}, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move, this, null);");
                else
                    EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.Heal({c}, {amt});");
                break;

            case "HpLoss":
                DebugLogGen.Target(w, e, ChainTargetExpr(e, "cardPlay.Target", "base.Owner.Creature"), amt, inLoop: IsMultiTargetSide(e));
                EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                    c => $"await CreatureCmd.Damage(choiceContext, {c}, {amt}, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move, this, null);");
                break;

            case "MaxHp":
                DebugLogGen.Target(w, e, ChainTargetExpr(e, "cardPlay.Target", "base.Owner.Creature"),
                    IsNegativeAmount(e, useX) ? (-e.Amount).ToString("0.##", System.Globalization.CultureInfo.InvariantCulture) + "m" : amt,
                    inLoop: IsMultiTargetSide(e));
                if (IsNegativeAmount(e, useX))
                    EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.LoseMaxHp(choiceContext, {c}, {-e.Amount}, isFromCard: true);");
                else
                    EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.GainMaxHp({c}, {amt});");
                break;

            case "Gold":
                w.Line(GainGoldLine(e, amt, useX, "base.Owner"));
                break;
            case "ExtraResource":
                // 额外资源量 = 本体的星星资源。
                // 正数：声明一个 StarsVar（canonical 变量），打出时按它的 BaseValue 立即获得，
                //       升级增量写在 OnUpgrade 里（UpgradeValueBy），卡面描述用 {Stars:diff()} 跟着变。
                // 负数（花费）：不在这里扣，而是通过 CanonicalStarCost 声明成卡牌费用，
                //       本体自带的判定会让「资源不够就打不出去」，并且卡面会显示红色的费用数字。
                if (e.NextTurn && (e.Amount > 0 || e.AmountIsXEffective))
                {
                    // 下回合生效：本体的 StarNextTurnPower（AfterEnergyReset 里 GainStars 再自毁）。
                    // 注意它的 GainStars 拒绝负数（本体直接抛 ArgumentException），所以只有「获得」走这条；
                    // 「需要 N 点」是卡牌费用，跟下回合无关（校验器会提醒）。
                    string gainNext = useX && e.AmountIsXEffective ? XVar : VarAccess(e, varMap);
                    w.Line($"await PowerCmd.Apply<StarNextTurnPower>(choiceContext, base.Owner.Creature, {gainNext}, base.Owner.Creature, this);   // 下回合开始时获得 {gainNext} 点额外资源量");
                    break;
                }
                if (e.Amount > 0)
                {
                    // 有 StarsVar 就用它（升级增量由 OnUpgrade 的 UpgradeValueBy 处理），
                    // 卡面描述里的 {Stars:diff()} 也会跟着变 —— 以前用「IsUpgraded 三目」写死，描述永远显示原值。
                    string gain = useX && e.AmountIsXEffective
                        ? XVar
                        : VarAccess(e, varMap);
                    w.Line($"await PlayerCmd.GainStars({gain}, base.Owner);");
                }
                break;

            // 翻倍当前特定状态（用户要求的新效果）：数值 = 倍数（2 = 翻倍），状态从「增益/减益」栏选。
            // 先取目标身上那份实例再 ModifyAmount(+现有层数 ×(倍数-1)) —— 本体没有「翻倍」API，
            // 加「(倍数-1) 倍现有层数」就是同一个意思，而且走的是本体自己的层数变更（会触发状态钩子）。
            case "DoublePower":
                w.Line(SelfContainedMarker(e));
                int __dblTimes = Math.Clamp((int)e.Amount, 2, 5);   // 2 = 翻倍；生成期就定下来（不声明动态变量）
                EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                    c => $"{{ PowerModel? __dblPower = {c}.GetPower<{e.PowerId}>(); if (__dblPower is not null && __dblPower.Amount != 0) await PowerCmd.ModifyAmount(choiceContext, __dblPower, __dblPower.Amount * {__dblTimes - 1}, base.Owner.Creature, this); }}   // 翻 {__dblTimes} 倍");
                break;

            // 禁止持有护盾：施加本体现成的 NoBlockPower（数值 = 层数）。复用 ApplyPowerLine，
            // 所以负数也自动是反向（负数 = 把这个状态扣掉）。
            case "ForbidBlock":
                w.Line(SelfContainedMarker(e));
                EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                    c => ApplyPowerLine(e, useX, "NoBlockPower", c, Math.Abs((int)e.Amount).ToString(), "base.Owner.Creature") + "   // 禁止获得格挡");
                break;

            // 禁止生命回复：给目标挂上本模组自己生成的状态（它配一条 Harmony 前缀把治疗量改成 0）
            case "ForbidHeal":
                w.Line(SelfContainedMarker(e));
                EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                    c => ApplyPowerLine(e, useX, Naming.From(p).NoHealPowerClass, c, Math.Abs((int)e.Amount).ToString(), "base.Owner.Creature") + "   // 禁止生命回复");
                break;

            // 暴露（照本体卡「暴露 Expose」写）：清空目标的格挡 + 移除人工制品，再施加 N 层状态。
            case "Expose":
                w.Line(SelfContainedMarker(e));
                EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                    c => $"{{ Creature __expTarget = {c}!; await CreatureCmd.LoseBlock(choiceContext, __expTarget, __expTarget.Block, base.Owner.Creature); if (__expTarget.HasPower<ArtifactPower>()) await PowerCmd.Remove<ArtifactPower>(__expTarget); await PowerCmd.Apply<{e.PowerId}>(choiceContext, __expTarget, {Math.Clamp((int)e.Amount, 0, 99)}, base.Owner.Creature, this); }}   // 暴露：清格挡 + 去人工制品 + 施加状态");
                break;

            // 清除目标身上的指定状态（本体 PowerCmd.Remove）。
            case "ClearPowerOne":
                w.Line(SelfContainedMarker(e));
                EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                    c => $"{{ PowerModel? __clrPower = {c}.GetPower<{e.PowerId}>(); if (__clrPower is not null) await PowerCmd.Remove(__clrPower); }}   // 清除指定状态");
                break;

            // 清除目标身上的所有减益状态（先 ToList 再遍历，免得边遍历边改集合）。
            case "ClearPowerDebuffs":
                w.Line(SelfContainedMarker(e));
                EmitPerCreature(w, e, useX, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                    c => $"{{ foreach (PowerModel __clrP in {c}.Powers.ToList()) {{ if (__clrP.TypeForCurrentAmount == PowerType.Debuff) await PowerCmd.Remove(__clrP); }} }}   // 清除所有减益");
                break;

            case "ApplyPower":
                if (e.NextTurn)
                {
                    w.Line($"await PowerCmd.Apply<{DelayedPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, this);");
                    break;
                }
                switch (e.TargetSide)
                {
                    case "Self":
                        w.Line(ApplyPowerInstr(e, useX, e.PowerId, "base.Owner.Creature", amt, "base.Owner.Creature"));
                        EmitSlowPercentFix(w, e, "base.Owner.Creature");
                        break;
                    case "AllEnemies":
                        w.Open("foreach (Creature foe in base.CombatState.HittableEnemies)")
                         .Line(ApplyPowerInstr(e, useX, e.PowerId, "foe", amt, "base.Owner.Creature"));
                        EmitSlowPercentFix(w, e, "foe");
                        w.Close();
                        break;
                    case "RandomEnemies":
                        w.Line("List<Creature> foes = base.CombatState.HittableEnemies.ToList();")
                         .Open($"for (int __foeIdx = 0; __foeIdx < {RepeatExpr(e, useX)} && foes.Count > 0; __foeIdx++)")
                         .Line("Creature foe = base.Owner.RunState.Rng.CombatTargets.NextItem(foes);");
                        if (!e.AllowDuplicates) w.Line("foes.Remove(foe);");
                        w.Line(ApplyPowerInstr(e, useX, e.PowerId, "foe", amt, "base.Owner.Creature"));
                        EmitSlowPercentFix(w, e, "foe");
                        w.Close();
                        break;
                    default:
                        w.Line(ApplyPowerInstr(e, useX, e.PowerId, "cardPlay.Target", amt, "base.Owner.Creature"));
                        EmitSlowPercentFix(w, e, "cardPlay.Target");
                        break;

                    // 全部队友（用户要求）：遍历同一边的玩家单位、排除自己（本体 BladeSymphony 那种「全体友方」）
                    case "AllAllies":
                        w.Open("if (base.Owner.Creature.CombatState is not null)");
                        w.Open("foreach (Creature ally in base.Owner.Creature.CombatState.PlayerCreatures"
                             + ".Where(c => c.IsAlive && c != base.Owner.Creature" + AllyFilterSuffix(e) + ").ToList())");
                        w.Line(ApplyPowerInstr(e, useX, e.PowerId, "ally", amt, "base.Owner.Creature"));
                        EmitSlowPercentFix(w, e, "ally");
                        w.Close();
                        w.Close();
                        break;

                    // 全体单位（V0.2.132）：场上两边所有存活单位（含自己 / 队友 / 召唤物 / 敌人）
                    case "AllUnits":
                        w.Open(AllUnitsGuardLine);
                        w.Open(AllUnitsForeachLine);
                        w.Line(ApplyPowerInstr(e, useX, e.PowerId, "unit", amt, "base.Owner.Creature"));
                        EmitSlowPercentFix(w, e, "unit");
                        w.Close();
                        w.Close();
                        break;
                }
                break;

            // 临时增益：不打真正的状态，而是打我们生成的「临时 Power」——
            // 它在施加时把 X 层加进真正的状态、回合结束时再把 X 层撤掉、自己消失
            // （本体 FlexPotion 的 TemporaryStrengthPower 就是这套，照它写）。
            case "TempPower":
                // 「生成调试日志」（V0.2.142，默认关）：目标 + 实际施加的层数。
                // （真正的层数变化发生在生成的「临时 Power」里，这里至少能看出打的是谁、打了几层。）
                DebugLogGen.Target(w, e, ChainTargetExpr(e, "cardPlay.Target", "base.Owner.Creature"), amt,
                    inLoop: e.TargetSide is "AllAllies" or "AllUnits");
                switch (e.TargetSide)
                {
                    case "Self":
                        w.Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, this);"
                            + "   // 临时增益：本回合 +X，回合结束撤掉");
                        break;
                    case "AllEnemies":
                        w.Open("foreach (Creature foe in base.CombatState.HittableEnemies)")
                         .Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, foe, {amt}, base.Owner.Creature, this);")
                         .Close();
                        break;
                    case "RandomEnemies":
                        w.Line("List<Creature> foes = base.CombatState.HittableEnemies.ToList();")
                         .Open($"for (int __foeIdx = 0; __foeIdx < {RepeatExpr(e, useX)} && foes.Count > 0; __foeIdx++)")
                         .Line("Creature foe = base.Owner.RunState.Rng.CombatTargets.NextItem(foes);");
                        if (!e.AllowDuplicates) w.Line("foes.Remove(foe);");
                        w.Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, foe, {amt}, base.Owner.Creature, this);")
                         .Close();
                        break;
                    default:
                        w.Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, cardPlay.Target, {amt}, base.Owner.Creature, this);");
                        break;

                    // 全部队友（用户要求）：同一边的玩家单位、排除自己
                    case "AllAllies":
                        w.Open("if (base.Owner.Creature.CombatState is not null)")
                         .Open("foreach (Creature ally in base.Owner.Creature.CombatState.PlayerCreatures"
                             + ".Where(c => c.IsAlive && c != base.Owner.Creature" + AllyFilterSuffix(e) + ").ToList())")
                         .Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, ally, {amt}, base.Owner.Creature, this);")
                         .Close()
                         .Close();
                        break;

                    // 全体单位（V0.2.132）：两边所有存活单位，各打一份临时状态
                    case "AllUnits":
                        w.Open(AllUnitsGuardLine)
                         .Open(AllUnitsForeachLine)
                         .Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, unit, {amt}, base.Owner.Creature, this);")
                         .Close()
                         .Close();
                        break;
                }
                break;
        }
    }

    private static void EmitAttack(CodeWriter w, EffectSpec e, string amt, bool useX = false, bool captureFatal = false)
    {        // 斩杀条件要用「上一条攻击的结果」：把 AttackCommand 记到 __lastAttack，
        // 并在打之前记下「目标的 Power 允许触发斩杀」（本体 Feed / HandOfGreed / TheHunt 都是这个顺序：
        // 打之前算 shouldTriggerFatal，打完再看 Results 里有没有 WasTargetKilled）。
        string pre = captureFatal ? "__lastAttack = " : "";
        if (captureFatal)
        {
            w.Line("// 斩杀：打之前先记下「目标允许触发斩杀」（小怪 / 会复活的目标返回 false）");
            w.Line("__fatalOk = cardPlay.Target is null || cardPlay.Target.Powers.All(pm => pm.ShouldOwnerDeathTriggerFatal());");
        }
        // 「生成调试日志」（V0.2.142，默认关）：打出前把「打的是谁、打多少」写进游戏日志。
        // targetSide 与下面各分支的 .Targeting(…) 一一对应（见 AttackTargetExpr）。
        DebugLogGen.Target(w, e, AttackTargetExpr(e), amt, inLoop: IsMultiTargetSide(e));
        switch (e.TargetSide)
        {
            case "Self":
                // 【造成伤害】+ 作用对象「自己」= 本体 DamageProps.cardUnpowered（Unpowered | Move）：
                //   · **格挡能挡**（卡面写的是「受到 N 点伤害」，不是「失去 N 点生命」）；
                //     本体就是这样：`Creature.LoseHpInternal` 之外，格挡的扣减只看 props 里有没有 Unblockable
                //     （Creature.cs：`props.HasFlag(Unblockable) ? 0 : Math.Min(Block, amount)`）。
                //   · 不被力量 / 易伤放大 —— 卡面上印的是 5 就掉 5，不会变成 5+力量（这点和「本体诅咒牌
                //     对自己造成伤害」用的是同一个常量）。
                // ⚠ 以前这里写的是 Unblockable | Unpowered | Move（= 本体 DamageProps.cardHpLoss，
                //   和「失去生命」生成的一模一样），于是护盾一点都吃不到 —— 用户报的
                //   「为什么对自己造成伤害不会被护盾格挡」就是这个。想「无视格挡」请用效果种类「失去生命」。
                w.Line($"await CreatureCmd.Damage(choiceContext, base.Owner.Creature, {amt}, ValueProp.Unpowered | ValueProp.Move, this, cardPlay);");
                break;
            case "AllEnemies":
                // 命中次数：**一次打全体**（TargetingAllOpponents）之后「命中 N 次」靠 WithHitCount 表达
                //（和锻造图那条路一致）。以前这里把「对群数/命中次数」整个忽略了 —— 用户实测：
                // 「对所有敌人造成伤害」填了命中次数 4，生成出来只打 1 下（他要的是每个敌人各挨 4 下）。
                // 命中 1 次时仍然不写 WithHitCount（老存档生成的代码一个字都不变）。
                if (RepeatIsMulti(e, useX))
                {
                    w.Line($"{pre}await DamageCmd.Attack({amt})")
                     .Indent().Line(".FromCard(this, cardPlay)").Line(".TargetingAllOpponents(base.CombatState)")
                     .Line($".WithHitCount({RepeatExpr(e, useX)})")
                     .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                }
                else
                {
                    w.Line($"{pre}await DamageCmd.Attack({amt})")
                     .Indent().Line(".FromCard(this, cardPlay)").Line(".TargetingAllOpponents(base.CombatState)")
                     .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                }
                break;
            case "RandomEnemies":
                if (e.AllowDuplicates)
                {
                    // 允许重复命中同一个敌人：次数照填（本体回旋镖就是默认允许重复）
                    w.Line($"{pre}await DamageCmd.Attack({amt})")
                     .Indent().Line(".FromCard(this, cardPlay)")
                     .Line(".TargetingRandomOpponents(base.CombatState, allowDuplicates: true)")
                     .Line($".WithHitCount({RepeatExpr(e, useX)})")
                     .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                }
                else
                {
                    // 不允许重复选中：命中次数要收敛到「当前可打的敌人数」，
                    // 否则本体找不到足够多互不相同的目标会一直等 → 卡牌卡住
                    w.Line($"int hits = {RepeatExpr(e, useX)};")
                     .Line("if (hits > base.CombatState.HittableEnemies.Count) hits = base.CombatState.HittableEnemies.Count;")
                     .Open("if (hits > 0)")
                     .Line($"{pre}await DamageCmd.Attack({amt})")
                     .Indent().Line(".FromCard(this, cardPlay)")
                     .Line(".TargetingRandomOpponents(base.CombatState, allowDuplicates: false)")
                     .Line(".WithHitCount(hits)")
                     .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent()
                     .Close();
                }
                break;
            // 全部队友（用户要求）：同一边的玩家单位、排除自己 —— 逐个各打一次（本体 BladeSymphony 那种「全体友方」）
            case "AllAllies":
                w.Open("if (base.Owner.Creature.CombatState is not null)");
                w.Open("foreach (Creature ally in base.Owner.Creature.CombatState.PlayerCreatures"
                     + ".Where(c => c.IsAlive && c != base.Owner.Creature" + AllyFilterSuffix(e) + ").ToList())");
                w.Line($"{pre}await DamageCmd.Attack({amt})")
                 .Indent().Line(".FromCard(this, cardPlay)").Line(".Targeting(ally)")
                 .Line(RepeatExpr(e, useX) == "1" ? "" : $".WithHitCount({RepeatExpr(e, useX)})")
                 .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                w.Close();
                w.Close();
                break;

            // 全体单位（V0.2.132）：场上两边所有存活单位，逐个各打一次（含自己 / 队友 / 召唤物 / 敌人）
            case "AllUnits":
                w.Open(AllUnitsGuardLine);
                w.Open(AllUnitsForeachLine);
                w.Line($"{pre}await DamageCmd.Attack({amt})")
                 .Indent().Line(".FromCard(this, cardPlay)").Line(".Targeting(unit)")
                 .Line(RepeatExpr(e, useX) == "1" ? "" : $".WithHitCount({RepeatExpr(e, useX)})")
                 .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                w.Close();
                w.Close();
                break;

            default:
                // 本体「旋风斩 / 天际钻头」就是 .WithHitCount(...) 打同一个目标。
                string singleHits = RepeatExpr(e, useX);
                bool multi = RepeatIsMulti(e, useX);
                if (multi)
                {
                    w.Line($"{pre}await DamageCmd.Attack({amt})")
                     .Indent().Line(".FromCard(this, cardPlay)").Line(".Targeting(cardPlay.Target)")
                     .Line($".WithHitCount({singleHits})")
                     .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                }
                else
                {
                    w.Line($"{pre}await DamageCmd.Attack({amt})")
                     .Indent().Line(".FromCard(this, cardPlay)").Line(".Targeting(cardPlay.Target)")
                     .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                }
                break;
        }
    }

    /// <summary>
    /// 「造成伤害」那条链里，日志该写哪个目标表达式（V0.2.142，见 <see cref="DebugLogGen"/>）。
    /// 必须和 <see cref="EmitAttack"/> 里各分支的 <c>.Targeting(…)</c> 一一对应，日志才不会指错人。
    /// 非卡牌来源（遗物 / 药水 / 自定义状态）里没有 <c>cardPlay</c>，那条链不会走到这里。
    /// </summary>
    internal static string AttackTargetExpr(EffectSpec e) => e.TargetSide switch
    {
        "Self" => "base.Owner.Creature",
        "AllAllies" => "ally",
        "AllUnits" => "unit",
        "AllEnemies" or "RandomEnemies" => "base.CombatState.HittableEnemies.FirstOrDefault()",
        _ => "cardPlay.Target",
    };

    /// <summary>这个作用对象是「一群」吗（日志里目标名字要运行时取，见 <see cref="DebugLogGen.Target"/>）。</summary>
    private static bool IsMultiTargetSide(EffectSpec e) => e.TargetSide is "AllAllies" or "AllUnits";

    /// <summary>
    /// 各条链里「造成伤害 / 格挡 / 治疗 / 失去生命 / 最大生命」该写哪个目标表达式。
    ///
    /// 卡牌链有 <c>cardPlay.Target</c>（玩家选中的目标）；遗物 / 药水**没有** ——
    /// 那两条链里「指定敌人」那一档会退回自己（见 <c>EmitPerCreature</c>：<c>Enemy</c> + 没有
    /// <c>cardTargetExpr</c> 时取「可打的第一个敌人」只对**需要敌人**的效果有意义），
    /// 而「获得格挡 / 回复生命」这类本来就没有敌人可指定 —— 所以 <paramref name="selfExpr"/> 才是它们的默认目标。
    /// 判据：这个效果种类**要不要敌人**（和 <c>EmitPerCreature</c> / 遗物链各分支的口径一致）。
    /// </summary>
    private static string ChainTargetExpr(EffectSpec e, string cardTargetExpr, string selfExpr) => e.TargetSide switch
    {
        "AllAllies" => "ally",
        "AllUnits" => "unit",
        "AllEnemies" or "RandomEnemies" => selfExpr + ".CombatState.HittableEnemies.FirstOrDefault()",
        "Enemy" when NeedsEnemyTarget(e.Kind) => cardTargetExpr,
        "Enemy" => selfExpr,     // 这条链没有「玩家选中的目标」→ 退回自己（和 EmitPerCreature 的 Enemy 分支同口径）
        _ => selfExpr,
    };

    /// <summary>这个效果种类在「指定敌人」那一档真的需要一个敌人吗（不需要的退回自己 / 第一个敌人）。</summary>
    private static bool NeedsEnemyTarget(string kind) => kind is "Damage" or "HpLoss" or "ApplyPower" or "TempPower";

    /// <summary>遗物链的「造成伤害 / 格挡 …」日志目标（没有 <c>cardPlay</c> → 第一个可打的敌人）。</summary>
    private static string RelicAttackTargetExpr(EffectSpec e) =>
        ChainTargetExpr(e, "base.Owner.Creature.CombatState.HittableEnemies.FirstOrDefault()", "base.Owner.Creature");

    /// <summary>
    /// 药水链的「造成伤害 / 格挡 …」日志目标 —— 由**药水自己的作用目标**（<c>PotionSpec.TargetType</c>）决定：
    /// 全体敌人时给一个代表性目标（可打的第一个），不是药水的 <c>EffectSpec.TargetSide</c>
    /// （药水那条栏只影响卡面描述，真正打谁看这一栏，见 EmitPotionEffectOnce 的注释）。
    /// </summary>
    private static string PotionAttackTargetExpr(string potionTarget, string allEnemies) => potionTarget switch
    {
        "AllEnemies" => allEnemies + ".FirstOrDefault()",
        "AnyEnemy" => "target",
        _ => "base.Owner.Creature",
    };

    // ==================== 召唤伙伴（无需补丁） ====================    //
    // 为什么不走 OstyCmd.Summon：那个是奥斯提专用包装，内部硬编码 Osty 类型，非 Osty 会抛异常。
    // 本体真正通用的是 PlayerCmd.AddPet<T>(player)（Byrdpip / Pael's Legion 用的就是它），
    // 所以生成的是「每只召唤物一个宠物类 + 一个命令助手」，召唤 = 助手.Summon(choiceContext, owner, hp)。
    // 也**不要**用 MinionPower（那是给敌方小怪打的标记）。

    /// <summary>
    /// 「伙伴攻击」在 OnPlay 里那个局部变量名（按宠物类名取，一张牌指向多只宠物时互不覆盖）。
    /// 用 <c>__</c> 前缀：和生成代码里其它临时变量（<c>__foeIdx</c> / <c>__pickIdx</c>…）保持一致的风格。
    /// </summary>
    internal static string PetAttackVarName(string petClassName) =>
        petClassName.Length == 0 ? "__pet" : "__" + char.ToLowerInvariant(petClassName[0]) + petClassName.Substring(1);

    /// <summary>
    /// 召唤伙伴的两种语义用**注释标记**区分，方便「从工程恢复存档」原样认回来：
    ///   · 数值 0（用「召唤物」页配置的血量）→ <c>// CET:PetHp=configured</c>
    ///   · 按这条效果填的数值 → <c>// CET:PetHp=var</c>
    /// 为什么要标记：两种情况生成出来的调用一模一样（配置血量是多少就写多少 m），
    /// 不标记的话「填了 9」和「留空用配置的 9」恢复出来无法区分。
    /// </summary>
    private static string PetHpComment(bool configured) => configured ? " // CET:PetHp=configured" : " // CET:PetHp=var";

    /// <summary>「这只召唤物还没选 / 选的那只不存在」时生成的兜底说明（校验器会先把这种配置拦住）。</summary>
    private static string PetMissingHint(string? id) =>
        (string.IsNullOrWhiteSpace(id) ? "（还没选召唤物）" : $"（找不到召唤物「{id!.Trim()}」）");

    /// <summary>
    /// 「召唤伙伴」。数值 &gt; 0 = 按填的生命召唤；数值 = 0 = 用「召唤物」页里配置的血量。
    /// 助手内部的 Summon 已经处理了「已经在场就加最大生命、不重复召唤」，所以这里直接调一次就行。
    ///
    /// 哪一只由 <see cref="EffectSpec.PetSummon"/>（稳定标识 = 宠物类名）决定；留空（老存档）时
    /// <see cref="PetGen.Resolve"/> 会退回第一只启用的召唤物 —— 和上一版单只召唤物的行为一致。
    /// </summary>
    private static void EmitSummonPet(CodeWriter w, EffectSpec e, CharacterProfile p, string amt, bool useX,
        string? extraComment = null, PetGen.PetDef? petDef = null, string? petVar = null)
    {
        // 「全部召唤物」：展开时逐只传进来（那时 e.PetSummon 是 "*"，Resolve 认不出来）
        var def = petDef ?? PetGen.Resolve(p, e.PetSummon);
        if (def is null)
        {
            // 校验器会拦住这种配置（生成会被中止），这里只保证万一跑到了也不生成编译不过的代码
            w.Line($"// ⚠ 这条「召唤伙伴」没有可用的召唤物{PetMissingHint(e.PetSummon)}：到「召唤物」页添加一只并勾上「启用」");
            return;
        }

        bool useConfigured = !useX && e.Amount <= 0;
        string hp = useConfigured ? $"{def.Hp}m" : amt;
        string cmd = def.ClassName + "Cmd";
        w.Line(useConfigured
            ? $"// 数值 0 = 用「召唤物」页里配置的血量（{def.DisplayName} {def.Hp} 点生命）"
            : $"// 按这条效果填的生命召唤{def.DisplayName}（已经在场就加最大生命，本体 OstyCmd 的做法）");
        // 把 Summon 返回的那只**写回局部变量**：那个变量是在 OnPlay 开头查一次的，之后所有宠物效果都用它。
        // 召唤前它必然还是 null（不然就不用召了），不复写的话「同一张牌先召唤、再让它承伤 / 攻击 / 加血」
        // 第一次打出时后半段会被整条跳过（`if (__pet is not null)` 判空）—— 玩家会以为效果没生效。
        string assign = petVar is null ? "" : petVar + " = ";
        w.Line($"{assign}await {cmd}.Summon(choiceContext, base.Owner, {hp});"
            + PetHpComment(useConfigured) + (extraComment is null ? "" : " " + extraComment));
    }

    /// <summary>
    /// 「伙伴攻击」：attacker 是**宠物**（不是玩家）。
    ///
    /// 为什么不能写 <c>FromMonster(pet.Monster)</c>（上一版就是这么写的，用户实测「攻击不生效」）：
    ///   · <c>FromMonster</c>（本体 AttackCommand.cs:257-267）把来源标成 <c>SourceType.Monster</c>，而
    ///     <c>GetPossibleTargets()</c>（:163-182）在 <c>_sourceType == Monster</c> 时硬编码返回
    ///     <c>_combatState.PlayerCreatures</c> —— 玩家侧的宠物会去打玩家自己人；
    ///   · 它还顺手 <c>TargetingAllOpponents</c>（:266）把 <c>_combatState</c> 设上，
    ///     于是 <c>Targeting</c>（:273-286）抛 "Already set to target opponents of attacker"；
    ///     反过来先 <c>Targeting</c> 再 <c>FromMonster</c>，<c>TargetingAllOpponents</c> 又抛 "Targets already set."。
    /// 正确形状 = 本体 <c>FromOsty</c>（:238-251）那套：攻击者换成宠物，但来源仍标成 Card —— 于是
    /// <c>GetPossibleTargets()</c> 走 <c>:179 GetOpponentsOf(Attacker)</c>（宠物是玩家侧 → 拿到敌人），
    /// <c>Execute</c> 里 <c>dealer: Attacker</c> / <c>cardSource: ModelSource as CardModel</c>（:669）也对。
    /// <c>FromOsty</c> 硬校验 <c>osty.Monster is Osty</c>，用不了；所以先走 <c>FromCard</c>，
    /// 再用我们自己的扩展方法 <c>FromPetAttacker</c> 反射把 <c>Attacker</c> 换成宠物（**不需要补丁**）。
    ///
    /// 注意：宠物必须活着（血量 &gt; 0）才打得出伤害 —— <c>Execute</c> 开头 <c>if (Attacker.IsDead) return this;</c>
    /// 会静默早退，所以调用处要先判「这只宠物在不在场」，血量也由召唤命令保证 &gt; 0。
    /// </summary>
    private static void EmitPetAttack(CodeWriter w, EffectSpec e, CharacterProfile p, string petVar, string amt,
        bool useX, PetGen.PetDef? petDef = null)
    {
        var def = petDef ?? PetGen.Resolve(p, e.PetSummon);
        if (def is null)
        {
            w.Line($"// ⚠ 这条「伙伴攻击」没有可用的召唤物{PetMissingHint(e.PetSummon)}：到「召唤物」页添加一只并勾上「启用」");
            return;
        }

        string hits = RepeatExpr(e, useX);
        bool multi = RepeatIsMulti(e, useX);

        switch (e.TargetSide)
        {
            case "AllEnemies":
                w.Line($"await DamageCmd.Attack({amt})")
                 .Indent().Line(".FromCard(this, cardPlay)          // 来源 = 这张牌（攻击历史与 hook 都正常）")
                 .Line(".TargetingAllOpponents(base.CombatState)")
                 .Line($".FromPetAttacker({petVar})          // 攻击者换成{def.DisplayName}")
                 .Line(".WithAttackerAnim(\"Attack\", 0.3f)   // 宠物自己的攻击动画（没有就退化成不动，无副作用）");
                if (multi) w.Line($".WithHitCount({hits})");
                w.Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                break;

            case "RandomEnemies":
                w.Line($"await DamageCmd.Attack({amt})")
                 .Indent().Line(".FromCard(this, cardPlay)")
                 .Line($".TargetingRandomOpponents(base.CombatState, allowDuplicates: {(e.AllowDuplicates ? "true" : "false")})")
                 .Line($".FromPetAttacker({petVar})")
                 .Line(".WithAttackerAnim(\"Attack\", 0.3f)")
                 .Line($".WithHitCount({hits})")
                 .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                break;

            default:
                w.Line($"await DamageCmd.Attack({amt})")
                 .Indent().Line(".FromCard(this, cardPlay)")
                 .Line(".Targeting(cardPlay.Target)")
                 .Line($".FromPetAttacker({petVar})");
                if (multi) w.Line($".WithHitCount({hits})");
                w.Line(".WithAttackerAnim(\"Attack\", 0.3f)")
                 .Line(".WithHitFx(\"vfx/vfx_attack_slash\")").Line(".Execute(choiceContext);").Dedent().Line();
                break;
        }
    }

    // ==================== 新增的那批宠物效果（不需要任何补丁） ====================
    //
    // 共同点：都要求「宠物已经召唤出来且活着」—— 调用处外面已经包了 if (pet != null)，
    // 所以这里不再重复判空（也**不能**再写一行 `Creature? pet = …`：那会和外面的同名变量冲突 → CS0136）。
    // 「需要已召唤宠物」的整张牌还会生成 IsPlayable / ShouldGlowRedInternal（见 CardSource）。

    /// <summary>
    /// 三个「按生命值算的伙伴攻击」：<c>DamageCmd.Attack(base.DynamicVars.CalculatedDamage)</c>。
    ///
    /// 为什么传 CalculatedDamageVar 而不是先算出数字：走这条路本体的 ModifyDamage / 力量 / 虚弱 /
    /// 附魔都会照常作用在**宠物**身上（Attacker 已经被 FromPetAttacker 换成宠物）。
    /// 为什么不用 <c>.FromCard(this, cardPlay)</c> 之后直接 Attacker？—— FromCard 会把 Attacker 设成玩家，
    /// 必须再用 FromPetAttacker 盖掉，次序不能反（本体 AttackCommand.cs:216-223 校验 Attacker 已设置就抛）。
    /// </summary>
    private static void EmitPetCalculatedAttack(CodeWriter w, EffectSpec e, CharacterProfile p, string petVar,
        bool useX, PetGen.PetDef? petDef = null)
    {
        var def = petDef ?? PetGen.Resolve(p, e.PetSummon);
        if (def is null)
        {
            w.Line($"// ⚠ 这条「{EffectCatalog.FindKind(e.Kind).Display}」没有可用的召唤物{PetMissingHint(e.PetSummon)}"
                + "：到「召唤物」页添加一只并勾上「启用」");
            return;
        }

        // 「全部召唤物」展开出来的那一份：没有计算变量可用（一张牌只有一套固定名字的计算变量），
        // 直接按**这只自己的**生命值算 —— 见 IsAllPetsInlineCalc 的说明。
        bool inline = IsAllPetsInlineCalc(e);
        string damage = inline ? InlinePetDamageExpr(e, petVar) : "base.DynamicVars.CalculatedDamage";

        string formulaZh = e.Kind switch
        {
            "PetDamageByCurHp" => "当前生命值",
            "PetDamageByMissingHp" => "已损失的生命值",
            _ => "最大生命值",
        };
        string hits = RepeatExpr(e, useX);
        bool multi = RepeatIsMulti(e, useX);
        w.Line(inline
            ? $"// 伤害 = 伙伴{def.DisplayName}自己的{formulaZh}（「全部召唤物」：每只各自算，卡面不显示具体数字）"
            : $"// 伤害 = 伙伴{def.DisplayName}的{formulaZh}（由 CalculatedDamage 这个计算变量在本体里算）");

        switch (e.TargetSide)
        {
            case "AllEnemies":
                w.Line($"await DamageCmd.Attack({damage})")
                 .Indent().Line(".FromCard(this, cardPlay)          // 来源 = 这张牌（攻击历史与 hook 都正常）")
                 .Line(".TargetingAllOpponents(base.CombatState)")
                 .Line($".FromPetAttacker({petVar})          // 攻击者换成{def.DisplayName}")
                 .Line(".WithAttackerAnim(\"Attack\", 0.3f)");
                if (multi) w.Line($".WithHitCount({hits})");
                w.Line(".WithHitFx(\"vfx/vfx_attack_blunt\", null, \"blunt_attack.mp3\")")
                 .Line(".Execute(choiceContext);").Dedent().Line();
                break;

            case "RandomEnemies":
                w.Line($"await DamageCmd.Attack({damage})")
                 .Indent().Line(".FromCard(this, cardPlay)")
                 .Line($".TargetingRandomOpponents(base.CombatState, allowDuplicates: {(e.AllowDuplicates ? "true" : "false")})")
                 .Line($".FromPetAttacker({petVar})")
                 .Line(".WithAttackerAnim(\"Attack\", 0.3f)")
                 .Line($".WithHitCount({hits})")
                 .Line(".WithHitFx(\"vfx/vfx_attack_blunt\", null, \"blunt_attack.mp3\")")
                 .Line(".Execute(choiceContext);").Dedent().Line();
                break;

            default:
                w.Line($"await DamageCmd.Attack({damage})")
                 .Indent().Line(".FromCard(this, cardPlay)")
                 .Line(".Targeting(cardPlay.Target)")
                 .Line($".FromPetAttacker({petVar})");
                if (multi) w.Line($".WithHitCount({hits})");
                w.Line(".WithAttackerAnim(\"Attack\", 0.3f)")
                 .Line(".WithHitFx(\"vfx/vfx_attack_blunt\", null, \"blunt_attack.mp3\")")
                 .Line(".Execute(choiceContext);").Dedent().Line();
                break;
        }
    }

    /// <summary>
    /// 「全部召唤物」那一档的伤害表达式：直接用**这只宠物自己**的生命值算（内联，不走计算变量）。
    /// 三种倍率与本体 CalculatedDamageVar 的 lambda 完全一致（最大生命 / 当前生命 / 已损失），
    /// 升级增量按 <c>(base.IsUpgraded ? N : 0m)</c> 加在最后 —— 等价于原来抬 CalculationBase 的做法。
    /// </summary>
    private static string InlinePetDamageExpr(EffectSpec e, string petVar)
    {
        string v = e.Kind switch
        {
            "PetDamageByCurHp" => $"(decimal){petVar}.CurrentHp",
            "PetDamageByMissingHp" => $"(decimal)({petVar}.MaxHp - {petVar}.CurrentHp)",
            _ => $"(decimal){petVar}.MaxHp",
        };
        if (e.UpgradeAmount != 0m)
            v = $"({v} + (base.IsUpgraded ? {Lit.Dec(e.UpgradeAmount)} : 0m))";
        return v;
    }

    /// <summary>治疗伙伴：<c>CreatureCmd.Heal(pet, Heal.BaseValue)</c>（升级增量照常生效）。</summary>
    private static void EmitPetHeal(CodeWriter w, EffectSpec e, string petVar, string amt)
    {
        _ = e;
        w.Line($"await CreatureCmd.Heal({petVar}, base.DynamicVars.Heal.BaseValue);");
    }

    /// <summary>
    /// 伙伴失去生命：走 <c>CreatureCmd.Damage</c> + <c>ValueProp.Unblockable | Unpowered | Move</c>
    /// （本体 <c>DamageProps.cardHpLoss</c> 就是这个组合）—— 不吃格挡、不吃力量，dealer 是主人、来源是这张牌。
    /// </summary>
    private static void EmitPetLoseHp(CodeWriter w, EffectSpec e, string petVar, string amt)
    {
        _ = e;
        w.Line($"await CreatureCmd.Damage(choiceContext, {petVar}, base.DynamicVars.HpLoss.BaseValue,")
         .Indent().Line("ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move,   // 本体 DamageProps.cardHpLoss")
         .Line("base.Owner.Creature, this, cardPlay);").Dedent();
    }

    /// <summary>
    /// 伙伴最大生命 +N。注意本体 <c>GainMaxHp</c> 内部最后会 <c>Heal</c> 等量 ——
    /// 所以**当前生命也会跟着涨**（卡面描述里写明了，免得玩家以为只加上限）。
    /// </summary>
    private static void EmitPetGainMaxHp(CodeWriter w, EffectSpec e, string petVar, string amt)
    {
        _ = e;
        w.Line($"await CreatureCmd.GainMaxHp({petVar}, base.DynamicVars.MaxHp.BaseValue);"
            + "   // 本体内部最后会 Heal 等量：当前生命同时回复");
    }

    /// <summary>
    /// 牺牲伙伴：**先算收益、再杀宠物**（顺序绝不能反 —— 宠物死了就取不到它的生命值，
    /// 而且 CalculatedBlock/CalculatedDamage 是在宠物身上算的）。
    /// 收益是格挡：<c>CreatureCmd.GainBlock(主人, 收益, …)</c>；
    /// 收益是伤害：先把收益算成数字存下来，再 <c>CreatureCmd.Kill</c>，最后用 <c>DamageCmd.Attack(数字)</c> 打出去；
    /// 收益是「获得增益 / 减益」：同样先把层数算成数字存下来，再 Kill，最后
    /// <c>PowerCmd.Apply&lt;状态&gt;(choiceContext, base.Owner.Creature, 层数, …)</c> 挂在自己身上。
    /// </summary>
    private static void EmitPetSacrifice(CodeWriter w, EffectSpec e, CharacterProfile p, string petVar,
        Dictionary<EffectSpec, string>? varMap, bool useX, PetGen.PetDef? petDef = null,
        string? petVarOverride = null, bool inStatus = false)
    {
        // petVarOverride：自定义状态那条链自己查好了宠物（`XxxCmd.Get(base.Owner)` 写在 if 守卫外面），
        // 这里就不必再按类名拼一遍变量名 —— 保证两边用的是同一个局部变量。
        if (petVarOverride is not null) petVar = petVarOverride;
        var def = petDef ?? PetGen.Resolve(p, e.PetSummon);
        if (def is null)
        {
            w.Line($"// ⚠ 这条「牺牲伙伴」没有可用的召唤物{PetMissingHint(e.PetSummon)}"
                + "：到「召唤物」页添加一只并勾上「启用」");
            return;
        }

        bool block = e.PetSacrificeGain != "Damage";     // 「获得增益 / 减益」也走格挡那一套变量（见 PetSacrificeVarDecl）
        bool power = e.PetSacrificeGain == "Power";
        string what = e.PetSacrificeGain switch
        {
            "Damage" => "伤害",
            "Power" => "状态 " + e.PowerId,
            _ => "格挡",
        };
        string valZh = e.PetSacrificeFormula switch
        {
            "Fixed" => $"固定 {e.Amount:0.##} 点",
            "CurHp" => $"等于{def.DisplayName}的当前生命值",
            _ => $"等于{def.DisplayName}的最大生命 × {e.PetSacrificeMultiplier:0.##}",
        };
        // 「全部召唤物」展开出来的那一份：按生命值算的收益没有计算变量可用（一张牌只有一套固定名字的
        // 计算变量），改成**内联**读这只宠物自己的生命值；固定值那份仍然读共用的 Block/Damage 变量。
        bool inline = IsAllPetsInlineCalc(e);
        // 「为什么是这个顺序」写进生成出来的代码里：收益（层数）要按宠物**还活着时**的生命值算，
        // 所以必须「先算成一个局部变量 → 再杀宠物 → 最后才用它」。默认档那两种的措辞照旧不改。
        string orderZh = power
            ? "（先算层数、再杀宠物、最后才挂状态 —— 顺序反了就取不到生命值）"
            : "（先算收益、再杀宠物 —— 顺序反了就取不到生命值）";
        w.Line($"// 牺牲{def.DisplayName}换{what}：收益 {valZh}{orderZh}"
            + (inline ? "【全部召唤物：每只各自算，卡面不显示具体数字】" : ""));

        // 收益是固定值时不需要计算变量（普通 BlockVar / DamageVar），直接读变量值即可。
        bool fixedFormula = e.PetSacrificeFormula == "Fixed";
        string gainExpr = fixedFormula
            ? "base.DynamicVars[" + Lit.Str(VarNameOf(e, varMap)) + "].BaseValue"
            : inline
                ? (e.PetSacrificeFormula == "CurHp"
                    ? $"(decimal){petVar}.CurrentHp"
                    : $"(decimal){petVar}.MaxHp * {Lit.Dec(e.PetSacrificeMultiplier)}")
                : (block
                    ? "base.DynamicVars.CalculatedBlock.Calculate(cardPlay.Target)"
                    : "base.DynamicVars.CalculatedDamage.Calculate(cardPlay.Target)");

        if (power)
        {
            if (string.IsNullOrWhiteSpace(e.PowerId))
            {
                // 校验器本来就会拦住这种配置（没选状态）；这里兜底成「只牺牲、不给状态」的注释，
                // 绝不生成 PowerCmd.Apply<>（泛型参数是空的 → CS0305 编译不过）。
                w.Line("// ⚠ 收益选了「获得增益 / 减益」却没选状态（「增益 / 减益」那一栏是空的）："
                    + "这条只牺牲伙伴、不给任何状态 —— 到效果栏里补选一个状态");
                w.Line($"await CreatureCmd.Kill({petVar});");
                return;
            }
            // 三段各自的「为什么」：层数按伙伴的生命值算，宠物一死（CreatureCmd.Kill）就取不到生命值了，
            // 所以先算成一个局部变量再动手；状态挂在自己身上（不跟「作用对象」那一栏走）。
            w.Line($"decimal layers = {gainExpr};   // 先算层数：宠物还活着才取得到它的生命值");
            w.Line($"await CreatureCmd.Kill({petVar});   // 再杀宠物");
            if (inStatus)
            {
                // 状态钩子里 base.Owner **本身就是 Creature**（卡牌那条链里是 PlayerModel，才要 .Creature）；
                // cardSource 必须传 null：PowerCmd.Apply 最后一个形参是 CardModel?，状态里没有「这张牌」，
                // 传 this 会选错重载 → 整个模组编译不过（CS1503 Creature → Player / CS1061 Creature.Creature）。
                w.Line($"await PowerCmd.Apply<{e.PowerId}>(choiceContext, base.Owner, layers, base.Owner, null);"
                    + "   // 最后把状态挂到自己身上");
            }
            else
            {
                w.Line($"await PowerCmd.Apply<{e.PowerId}>(choiceContext, base.Owner.Creature, layers, base.Owner.Creature, this);"
                    + "   // 最后把状态挂到自己身上");
            }
        }
        else if (block)
        {
            w.Line($"decimal gain = {gainExpr};");
            w.Line($"await CreatureCmd.Kill({petVar});");
            string blockSource = (fixedFormula || inline) ? "ValueProp.Move" : "base.DynamicVars.CalculatedBlock.Props";
            if (inStatus)
            {
                // 状态钩子里 base.Owner **本身就是 Creature**（卡牌那条链里它是 PlayerModel，所以要 .Creature）；
                // 而且没有 cardPlay 可以当「来源」，格挡的来源传 null（本体状态里给格挡就是这么写的，
                // 例如 BlockPower / 各种「回合开始获得格挡」的状态）。
                w.Line($"await CreatureCmd.GainBlock(base.Owner, gain, {blockSource}, null);");
            }
            else
            {
                w.Line($"await CreatureCmd.GainBlock(base.Owner.Creature, gain, {blockSource}, cardPlay);");
            }
        }
        else
        {
            w.Line($"decimal dmg = {gainExpr};");
            w.Line($"await CreatureCmd.Kill({petVar});");
            if (inStatus)
            {
                // 状态里没有「这张牌」也没有「玩家选中的目标」：
                //   · **不能**写 `.FromCard(base.Owner, null)` —— 它的第一个形参是 CardModel，传 Creature 直接
                //     CS1503 编译不过（本体 AttackCommand.cs:214 `FromCard(CardModel card, CardPlay? cardPlay)`）；
                //   · 也不能用 `.FromMonster(pet.Monster)` —— 它内部顺手调 TargetingAllOpponents，之后再
                //     Targeting(foe) 会抛「Targets already set」（AttackCommand.cs:257-267 / 273-286）；
                //   · 所以只「选目标 + 用扩展方法把攻击者换成宠物」，跳过「来源」那一步
                //     （Attacker 是靠反射设的，不要求先调 FromCard；ModelSource / CardPlay 留空即可）。
                // 目标用状态那条链同一套解析（自己 / 全部敌人 / 随机敌人 / 可打的第一个敌人）。
                // 外层套一对大括号：EmitPerCreature 在 Self 分支是直接把 body 写成一行的，
                // 而攻击命令是多行语句 —— 包起来才不会让后面那条语句掉进 if / for 里。
                EmitPerCreature(w, e, useX: false, "base.Owner", null,
                    "base.Owner.CombatState.HittableEnemies",
                    foe => "{ await DamageCmd.Attack(dmg).Targeting(" + foe + ").FromPetAttacker(" + petVar + ")"
                        + ".WithAttackerAnim(\"Attack\", 0.3f)"
                        + ".WithHitFx(\"vfx/vfx_attack_blunt\", null, \"blunt_attack.mp3\").Execute(choiceContext); }");
            }
            else
            {
                w.Line("await DamageCmd.Attack(dmg)")
                 .Indent().Line(".FromCard(this, cardPlay)")
                 .Line(".Targeting(cardPlay.Target)")
                 .Line(".WithHitFx(\"vfx/vfx_attack_blunt\", null, \"blunt_attack.mp3\")")
                 .Line(".Execute(choiceContext);").Dedent();
            }
        }
    }

    /// <summary>
    /// 给伙伴施加状态：<c>PowerCmd.Apply&lt;{PowerId}&gt;(choiceContext, pet, 层数, base.Owner.Creature, this)</c>。
    /// 下回合生效时走现有的「延迟状态」类（<c>ForgeDelayed&lt;PowerId&gt;</c>）挂在宠物身上，
    /// 那个类自己的钩子里会把真正的状态施加到**它的主人**（也就是这只宠物）上 —— 和普通「下回合生效」一致。
    /// </summary>
    private static void EmitPetApplyPower(CodeWriter w, CharacterProfile p, EffectSpec e, string petVar, string amt,
        Dictionary<EffectSpec, string>? map = null)
    {
        _ = amt;
        // 数值**不**用外面传来的表达式：PetApplyPower 的变量名是 PetPower<PowerId>（不是本体的属性），
        // 这里按名字取 —— 回读也照这一行把数值配回去（升级增量同样生效）。
        // 注意必须用**带别名映射**的 VarNameOf(e, map)：同一张牌上两条同样的「给伙伴施加状态」时，
        // 第二条在 CanonicalVars 里声明成 PetPowerStrengthPower2（否则 DynamicVarSet 撞名会抛异常），
        // 以前这里固定读第一条的名字 → 第二条的变量取不到 → 牌组界面打不开（KeyNotFoundException）。
        string calc = $"base.DynamicVars[{Lit.Str(VarNameOf(e, map))}].BaseValue";
        if (e.NextTurn)
        {
            w.Line($"await PowerCmd.Apply<{DelayedPowerClassName(e, p)}>(choiceContext, {petVar}, {calc}, base.Owner.Creature, this);");
            return;
        }
        w.Line(ApplyPowerInstr(e, useX: false, e.PowerId, petVar, calc, "base.Owner.Creature"));
    }

    /// <summary>
    /// 伙伴替主人承伤 开 / 关：用我们**自己的共用守卫类** <c>ForgePetGuardianPower</c>
    /// （不是本体的 DieForYouPower —— 那个是 Osty 专用；多只宠物共用这一个类、由它自己仲裁谁承担）。
    ///
    /// 这里不再判 <c>HasPower&lt;T&gt;()</c>：宠物已经判活（外面那层 <c>if (pet != null)</c>），
    /// 一只活着的宠物要么已经挂着守卫（PowerStackType.Single 重复 Apply 不会多一个实例），
    /// 要么没挂 —— 直接 Apply / Remove 都是对的，而且生成的代码短一半。
    /// 关的时候用 <c>PowerCmd.Remove&lt;T&gt;(Creature)</c>（本体签名，核实过：<c>PowerCmd.cs:282</c>）。
    /// </summary>
    private static void EmitPetGuard(CodeWriter w, CharacterProfile p, string petVar, bool on)
    {
        string power = Naming.From(p).GuardianPowerClass;
        if (on)
            w.Line($"await PowerCmd.Apply<{power}>(choiceContext, {petVar}, 1m, null, null);"
                + "   // 共用守卫：多只都挂时由它自己仲裁（列表里第一只活着的承担）");
        else
            w.Line($"await PowerCmd.Remove<{power}>({petVar});"
                + "   // 取消替主人承伤：多只都挂着时只摘这一只，剩下那只（若有）继续承担");
    }

    // ==================== 下回合生效的延迟 Power ====================
    /// <summary>
    /// 哪些「生成类」效果支持「下回合生效」（用户要求：生成卡牌之类也要能下回合）。
    ///
    /// 现在支持：生成卡牌（指定卡 / 按范围随机 / 多选1）、获得卡牌（全局）、变化卡牌（全局）、
    /// 删除卡牌（全局）、升级牌组里的牌（全局）——
    /// 这几条的发射器都把「玩家 / 来源」当参数了（`EmitGenerateCard` / `EmitGlobalCardEffect` /
    /// `EmitCopyCard` / `EmitTransformCard`），放进延迟状态（`base.Owner` 是 Creature）只要传
    /// `base.Owner.Player` / `sourceExpr: null` / `combatStateExpr: base.Owner.CombatState` 就行。
    /// </summary>
    public static bool IsDelayedSpawnKind(string? kind) =>
        kind is "GenerateCard" or "CopyCard" or "TransformCard"
        or "AddCardGlobal" or "TransformCardGlobal" or "RemoveCardGlobal" or "UpgradeCardGlobal";

    internal static string DelayedPowerClassName(EffectSpec e, CharacterProfile? owner = null) =>
        owner is null ? Naming.AmbientDelayedPowerClass(e) : Naming.From(owner).DelayedPowerClass(e);

    /// <summary>
    /// 打出「下回合生效」的那条效果时，挂延迟状态那一句。
    ///
    /// <paramref name="ownerExpr"/> = 挂给谁（卡牌 / 遗物 / 药水链是 <c>base.Owner.Creature</c>，
    /// 自定义状态链是 <c>base.Owner</c>）；<paramref name="playerExpr"/> = 玩家（<c>base.Owner</c> 或
    /// <c>base.Owner.Player</c>）。
    ///
    /// 层数（<c>Amount</c>）就是这条效果的「数值」（张数 / 层数 / 点数的**字面量** —— 延迟状态下
    /// 没有卡牌的动态变量，所以一律在生成期折成常量，和生成类那套一致）。
    /// 挂的时候把「打谁」当 target 一起交给它：延迟状态在下回合用 <c>base.Target</c> 取回那个目标
    ///（目标已经不在了就退成第一个可打的敌人，不静默失效）。
    /// </summary>
    internal static void EmitDelayedPowerApply(CodeWriter w, CharacterProfile p, EffectSpec e,
        string ownerExpr, string playerExpr)
    {
        string n = Lit.Dec(e.Amount);
        // 回读用：`CET:Effect=` 那一行带着这条效果的全部信息（种类 / 数值 / 状态 / 目标卡 /
        // 作用对象 / 选牌方式…），`CET:NextTurn=1` 说明它是「下回合生效」——
        // 和生成类那套标记**完全同一份**（见 SelfContainedMarker），回读端只认一次。
        // 「给予关键词」那条还要额外带上关键词（SelfContainedMarker 里没有这一项，
        // 而延迟状态下 EmitGiveKeyword 的 CET:GiveKeyword= 标记写在**状态类体内**、卡这边看不到）；
        // 「获得药水」那条要带上「指定还是随机 / 指定的是哪一瓶」（同 PotionMarker 的约定：
        // 随机档才写 PotionPick、真的选了药水才写 Potion）。
        w.Line(SelfContainedMarker(e) + " CET:NextTurn=1"
            + (e.Kind == "GiveKeyword" ? $" CET:Given={Lit.Identifier(e.GivenKeyword ?? "", "")}" : "")
            + (e.Kind == "GainPotion" && e.IsPotionRandom ? " CET:PotionPick=Random" : "")
            + (e.Kind == "GainPotion" && !string.IsNullOrWhiteSpace(e.PotionId) ? $" CET:Potion={e.PotionId!.Trim()}" : ""));
        w.Line($"// 下回合生效：现在只挂延迟状态，下回合开始时再{EffectCatalog.FindKind(e.Kind).Display}"
            + (e.TargetSide is "Enemy" or "Ally" ? "（打到打出时选中的那个目标；目标不在了就退成第一个可打的敌人）" : ""));
        w.Line($"await PowerCmd.Apply<{DelayedPowerClassName(e, p)}>(choiceContext, {ownerExpr}, {n}, {playerExpr}, null);");
    }

    /// <summary>
    /// 「下回合生效」+ 新支持的种类时，把那条效果**原样**发射一遍（走
    /// <see cref="EmitCardEffectOnce"/> 同一套发射器），产出的语句就是延迟状态类的方法体。
    ///
    /// 表达式替换表（延迟状态 vs 卡牌链）：
    ///   · <c>base.CombatState</c>      → <c>__fgDelayedCombat</c>（PowerModel 上没有这个属性）；
    ///   · <c>cardPlay.Target</c>        → <c>__fgDelayedTarget</c>（延迟状态下没有 cardPlay）；
    ///   · <c>cardPlay</c>（`FromCard(this, cardPlay)` 那几处）→ <c>null</c>；
    ///   · <c>this</c>（当作 CardModel 用）→ <c>null</c>。
    /// ⚠ **不能**替换 <c>base.Owner</c>：延迟状态里 <c>base.Owner</c> 是 Creature，
    /// 而卡牌链里它是 Player —— 两边的类型不一样（替换会在 CreatureCmd.Heal 这种地方 CS1503）。
    /// 但**金额**来源本来就不一样：卡牌链读 <c>base.DynamicVars.X.BaseValue</c>，
    /// 延迟状态下没有那些变量，所以在 <paramref name="varMap"/> 里把每条效果映射成**字面量**
    ///（同一套 <see cref="VarNamesOf"/> 算法，只是取值改成常量）。
    ///
    /// 替换顺序有意义（先换长的），别调换。字符串字面量里不会出现这些记号（注释除外，注释换了也无妨）。
    /// </summary>
    private static void EmitDelayedEffectBody(CodeWriter w, CharacterProfile p, EffectSpec e,
        Dictionary<string, string>? literalAmounts)
    {
        // 先把上下文声明出来（只有在这条效果真的会用到时才声明，免得 CS0219 之类的噪声）。
        w.Line("Player __fgDelayedPlayer = base.Owner.Player;");
        // ⚠ 声明成 Creature 而不是 ICombatState：卡牌链上的发射器把「战斗状态」用在两处 ——
        //   `X.CombatState.HittableEnemies`（只用得到 HittableEnemies）和
        //   `X.CombatState.CreateCard<T>(player)`（那需要 Creature 上的版本）。
        //   声明成 Creature 时，把 `base.CombatState` 换成 `__fgDelayedSelf.CombatState` 两边都过。
        w.Line("Creature __fgDelayedSelf = base.Owner;");
        if (e.TargetSide is "Enemy" or "Ally")
        {
            w.Line("// 打出时选中的那个目标（PowerCmd.Apply 的 target 参数）；目标已经离场就退成第一个可打的敌人");
            w.Line("Creature __fgDelayedTarget = base.Target");
            w.Line("    ?? __fgDelayedSelf.CombatState.HittableEnemies.FirstOrDefault()");
            w.Line("    ?? base.Owner;");
        }

        // 宠物类效果要「已经召唤出来的那一只」—— 卡牌链上它是 OnPlay 开头查好的局部变量，
        // 延迟状态里没有它，只能按「这个玩家名下的召唤物」重新查一次（查不到就整条跳过，不静默做错人）。
        string? petVar = null;
        if (NeedsExistingPet(e) && PetGen.Resolve(p, e.PetSummon) is { } pd)
        {
            petVar = PetAttackVarName(pd.ClassName);
            // 召唤物查询的写法照抄 PetGen 自己生成的那句：本体把「玩家名下的召唤物」放在
            // PlayerCombatState.Pets 里（ICombatState 上没有 Pets —— 探针实测 CS1061）。
            w.Line($"Creature? {petVar} = __fgDelayedPlayer.PlayerCombatState?.Pets"
                + $".FirstOrDefault(p => p.Monster is {pd.ClassName} && p.IsAlive);   // 这只伙伴还在场吗");
            w.Open($"if ({petVar} is not null)");
        }

        var tmp = new CodeWriter();
        CharacterProfile? prevFormulaOwner = _formulaOwner;
        _formulaOwner = p;
        try
        {
            EmitCardEffectOnce(tmp, p, e, useX: false, varMap: null, petVar: petVar, petDef: null,
                effectComment: null, petLookup: null, captureFatal: false, inDelayedBody: true,
                literalAmounts: literalAmounts);
        }
        finally
        {
            _formulaOwner = prevFormulaOwner;
        }

        // ⚠ 用一个不可能出现在生成代码里的记号先替掉 `this`，最后再换成实参 ——
        // 否则 `this` 会被前面那些替换里恰好出现的字母序列影响。分两步最稳。
        const string thisToken = "\u0001THIS\u0001";
        string body = tmp.ToString();
        body = body.Replace("base.Owner.Creature", "__fgDelayedSelf")
                   .Replace("base.Owner", "__fgDelayedPlayer")
                   .Replace("base.CombatState", DelayedCombatExpr)
                   .Replace("cardPlay.Target", DelayedTargetExpr)
                   .Replace("cardPlay", "null")
                   .Replace("this", thisToken)
                   .Replace(thisToken, DelayedCardSourceExpr);
        foreach (string line in body.Replace("\r\n", "\n").Split('\n'))
        {
            if (line.Trim().Length == 0) { w.Line(); continue; }
            w.Line(line.TrimEnd());
        }
        if (petVar is not null) w.Close();
    }

    // ==================== 「下回合生效」的**通用**延迟分支（V0.2.133）====================
    //
    // V0.2.132 及以前只有 12 种（本体那五个 + 生成类七个）真的有延迟分支。本轮把它扩到
    // **除 `EffectCatalog.NextTurnMeaningless` 之外的每一种**（65 - 8 = 57 种），做法是：
    //   · 打出时只挂一个 `StringComparison.Ordinal` 的延迟状态（= `<角色>ForgeDelayed<...>`），
    //     挂之前把「这一条效果需要的上下文」一起交给它（见 EmitDelayedApply）；
    //   · 下回合开始时（`AfterPlayerTurnStart`）那个状态跑**同一套既有发射器**
    //     （`EmitCardEffectOnce`）—— 所以「打出时」与「下回合」两条路发出来的语句只有
    //     「上下文表达式」不同，行为不会慢慢长歪。
    //
    // 为什么用「替换占位表达式」而不是给 `EmitCardEffectOnce` 加十几个参数：
    // 那几个发射器里写死了 `base.Owner.Creature`（卡牌链里 base.Owner 是 Player）和
    // `cardPlay.Target`（只有「打出的那一瞬间」才有）；延迟状态里 base.Owner **本身就是 Creature**，
    // 也没有 cardPlay。与其把几十个调用点全改一遍（那是本项目最容易踩的回归面），
    // 不如在**写进延迟状态那一段**统一替换掉这几个表达式。

    /// <summary>延迟状态里「玩家」的表达式（`base.Owner` 是 Creature，所以要取 .Player）。</summary>
    internal const string DelayedPlayerExpr = "__fgDelayedPlayer";
    /// <summary>延迟状态里「战斗状态」的表达式。</summary>
    internal const string DelayedCombatExpr = "__fgDelayedSelf.CombatState";
    /// <summary>延迟状态里「这一条效果打谁」的表达式（见 <see cref="DelayedTargetExpr"/> 的说明）。</summary>
    internal const string DelayedTargetExpr = "__fgDelayedTarget";
    /// <summary>延迟状态里「这一条效果从哪来」的实参 —— 那边没有 CardModel，一律 null。</summary>
    internal const string DelayedCardSourceExpr = "null";

    /// <summary>
    /// 延迟状态里的**金额字面量表**：卡牌链读 <c>base.DynamicVars.X.BaseValue</c>（升级增量写在
    /// OnUpgrade 的 UpgradeValueBy 里），而延迟状态里**根本没有那些动态变量**
    ///（引用会 KeyNotFoundException / CS1061）—— 所以延迟状态里的数值一律在生成期折成常量。
    ///
    /// 取值口径：<c>Amount + UpgradeAmount</c>（升级后的值，把升级增量也保住；
    /// 延迟状态下没法知道这张牌升级了没有，取「升级后」是保守且可预期的）。
    /// 「数值 = X」用不了（延迟状态里没有 <c>x</c>）→ 退成基础数值。
    /// </summary>
    private static Dictionary<string, string> DelayedVarMap(CharacterProfile p)
    {
        // 键是**动态变量名**（`Damage` / `Block2` / …），不是 EffectSpec ——
        // 延迟状态里没有 `base.DynamicVars`，那些名字只是拿来查「该用哪个常量」。
        var effects = AllEffects(p).ToList();
        var names = VarNamesOf(effects);
        var map = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var e in effects)
        {
            string? name = VarNameOf(e, names);
            if (string.IsNullOrWhiteSpace(name)) continue;
            map[name!] = Lit.Dec(e.Amount + e.UpgradeAmount);
        }
        return map;
    }

    /// <summary>延迟状态里这条效果的数值：按变量名查 <see cref="DelayedVarMap"/> 折好的常量；
    /// 查不到（不声明变量的那几种）直接用 <c>Amount + UpgradeAmount</c>。</summary>
    private static string LiteralAmountOf(EffectSpec e, IReadOnlyDictionary<string, string>? literalAmounts)
    {
        string name = VarNameOf(e);
        if (literalAmounts is not null && literalAmounts.TryGetValue(name, out string? lit) && !string.IsNullOrWhiteSpace(lit))
            return lit!;
        return Lit.Dec(e.Amount + e.UpgradeAmount);
    }

    /// <summary>
    /// 这些种类有没有**通用**延迟分支（<see cref="EmitCardEffectOnce"/> 顶部那个分支）。
    ///
    /// 与 <see cref="EffectCatalog.HonorsNextTurn"/> 的关系：本方法为 true ⇒ 一定有延迟状态分支；
    /// 但「下回合生效」还有三条**老路**（不走这个分支）：
    ///   · 格挡 / 抽牌 / 能量 / 额外资源量 —— 走本体现成的 `BlockNextTurnPower` 那四个；
    ///   · 生成 / 复制 / 变化 / 全局加牌（`<see cref="IsDelayedSpawnKind"/>`）—— V0.2.88~90 的先例；
    ///   · 施加状态（`ApplyPower`）—— 走 `<角色>ForgeDelayed<状态>`（层数 = 层数）。
    /// 所以判据是「<see cref="EffectCatalog.HonorsNextTurn"/> 且不是上面那三类」。
    /// </summary>
    public static bool IsDelayedEffectKind(string? kind) =>
        kind is not null
        && EffectCatalog.HonorsNextTurn(kind)
        && !IsDelayedSpawnKind(kind)
        && kind is not ("Block" or "Draw" or "Energy" or "ExtraResource" or "ApplyPower");

    /// <summary>这条效果「下回合生效」时走不走新加的通用延迟分支。</summary>
    internal static bool UsesDelayedEffectBranch(EffectSpec e) => e.NextTurn && IsDelayedEffectKind(e.Kind);

    /// <summary>通用延迟状态的去重键（同一条效果在同一个存档里只生成一个类）。</summary>
    internal static string DelayedEffectKey(EffectSpec e) =>
        "D:" + e.Kind + "|" + (e.PowerId ?? "") + "|" + (e.SpawnCardId ?? "") + "|" + (e.TargetSide ?? "")
        + "|" + (e.SpawnFilter ?? "") + "|" + e.CardPick + "|" + e.SelectPile + "|" + e.PlaceTo
        + "|" + (e.GivenKeyword ?? "") + "|" + (e.BoostStat ?? "") + "|" + (e.ScrapeCond ?? "") + (e.ScrapeOp ?? "")
        + "|" + e.TempPowerReverse + "|" + e.PetSummon + "|" + (e.PetSacrificeGain ?? "");

    public static IEnumerable<EffectSpec> CollectDelayedEffects(CharacterProfile p)
    {
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var e in AllEffects(p))
        {
            if (!e.NextTurn) continue;
            if (e.Kind == "ApplyPower")
            {
                if (seen.Add("P:" + (e.PowerId ?? ""))) yield return e;
            }
            else if (IsDelayedSpawnKind(e.Kind))
            {
                // 生成类：类名里带「种类 + 那张卡 + 随机范围 + 张数变量」，去重键要跟着带上，
                // 否则两张「生成不同卡」的牌会合成一个类（后写的覆盖前写的）。
                string key = "S:" + e.Kind + "|" + (e.SpawnCardId ?? "") + "|" + (e.SpawnFilter ?? "") + "|"
                    + (e.IsSpawnRandom ? "r" : "f") + "|" + e.SpawnChoice + "|" + e.SpawnToPile + "|" + (e.HasSpawnModifier ? "m" : "")
                    + (e.AmountIsXEffective ? "|X" : "");
                if (seen.Add(key)) yield return e;
            }
            else if (IsDelayedEffectKind(e.Kind))
            {
                if (seen.Add(DelayedEffectKey(e))) yield return e;
            }
        }
    }

    /// <summary>
    /// 「临时增益」用到的全部效果（按「状态 + 什么时候撤 + 正负号」去重 —— 三样任一个不同都要各自的类）。
    /// 只做卡牌 / 药水 / 遗物 / 自定义状态触发里出现的；有才生成对应的临时 Power 类。
    ///
    /// ⚠ 去重键**必须带上正负号**：`+5 力量` 和 `-5 力量` 是两套完全不同的生成代码
    /// （一个 Apply 加层、一个 GetPower+ModifyAmount 扣层），合成一个类会变成
    /// 「后写的那份覆盖前一份」，于是两张牌里有一张的行为是错的（实测踩过）。
    /// </summary>
    public static IEnumerable<EffectSpec> CollectTempPowerEffects(CharacterProfile p)
    {
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var e in AllEffects(p))
        {
            if (e.Kind != "TempPower") continue;
            if (seen.Add(TempPowerKey(e))) yield return e;
        }
        // 「锻造页」节点图里的「临时增益 / 临时减益」模块：这些**不在** AllEffects 里（那是卡牌 / 遗物 /
        // 药水 / 状态各自的「效果」列表），所以以前图里的临时模块**没有生成对应的临时 Power** ——
        // 生成端把它当成「施加状态」，打出去就是**永久**加层（用户报的「临时增益不生效 / 不还原」）。
        // 现在把图里的也算进来；类名由 ForgeGraphGen.TempPowerEffectOf 统一算，调用点用的是同一份。
        foreach (var g in ForgeGraphGen.AllGraphsWithPowers(p))
        {
            if (g is null || g.IsEmpty) continue;
            foreach (var node in g.Nodes)
            {
                if (node is null || node.Kind != "Effect") continue;
                if (node.Get("Effect", "Damage") != "TempPower") continue;
                var e = ForgeGraphGen.TempPowerEffectOf(node);
                if (string.IsNullOrWhiteSpace(e.PowerId)) continue;   // 没选状态：校验器会拦住，这里不生成空类
                if (seen.Add(TempPowerKey(e))) yield return e;
            }
        }
    }

    /// <summary>
    /// 临时 Power 类的去重键：状态 + 撤销时机 + **正负号**。
    /// 正负号必须算进去（正数档「加层」和负数档「扣层」是两套代码，见上面那段注释）。
    /// </summary>
    internal static string TempPowerKey(EffectSpec e) =>
        (e.PowerId ?? "") + "|" + (e.TempPowerReverse ?? "") + "|" + (e.Amount < 0m ? "-" : "+");

    /// <summary>这个存档里有没有「临时增益」（有才生成 TempPowers.cs）。</summary>
    public static bool UsesTempPower(CharacterProfile p) => CollectTempPowerEffects(p).Any();

    /// <summary>临时增益 Power 的类名（兜底用当前角色，见 <see cref="Naming.CurrentCharClass"/>）。</summary>
    internal static string TempPowerClassName(EffectSpec e, CharacterProfile? owner = null) =>
        owner is null ? Naming.AmbientTempPowerClass(e) : Naming.From(owner).TempPowerClass(e);

    /// <summary>
    /// 「禁止目标回复生命」用的状态 **+ 那条 Harmony 前缀**（同一个文件里，PatchAll 会一起打上）。
    ///
    /// 为什么必须用补丁：本体没有任何「治疗量修改」的钩子（全库只有营地的 ModifyRestSiteHealAmount），
    /// 所以只能在 <c>CreatureCmd.Heal</c> 上做一个前缀，把 <c>ref amount</c> 改成 0。
    /// **不能**用「前缀返回 false 跳过原方法」：它是 <c>async Task</c>，跳过了调用方 await 到 null 会炸；
    /// 把治疗量改成 0 则是让原方法照常跑完（本体内部是 min(amount, 最大生命-当前生命) = 0），
    /// 动画 / 返回值都正常，只是血量不动。
    /// </summary>
    public static string NoHealPowerSource(CharacterProfile p)
    {
        if (!NeedsNoHealPower(p)) return "";
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 「禁止目标回复生命」用的状态 + 治疗量清零补丁 </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {n.NoHealPowerClass} : PowerModel")
         .Line("public override PowerType Type => PowerType.Debuff;")
         .Line()
         .Line("public override PowerStackType StackType => PowerStackType.Counter;")
         .Line()
         .Line("// 层数 = 还能持续几个回合：挂在自己身上就在玩家回合末掉、挂在敌人身上就在敌人回合末掉，掉光自毁")
         .Open("public override async Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)")
         .Line("bool mine = base.Owner.IsPlayer ? side == CombatSide.Player : side == CombatSide.Enemy;")
         .Line("if (!mine) return;")
         .Open("if (base.Amount <= 1)")
         .Line("await PowerCmd.Remove(this);")
         .Close()
         .Line("else")
         .Open("")
         .Line("SetAmount(base.Amount - 1);")
         .Close()
         .Close()
         .Close()
         .Line()
         .Line("/// <summary>把 CreatureCmd.Heal 的治疗量改成 0（身上挂着上面那个状态时）。</summary>")
         .Line("[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Commands.CreatureCmd), nameof(MegaCrit.Sts2.Core.Commands.CreatureCmd.Heal))]")
         .Open($"internal static class {n.NoHealPowerClass}Patch")
         .Line("// ref 改参数而不是跳过原方法：原方法是 async Task，跳过会让调用方 await 到 null")
         .Open("private static void Prefix(Creature creature, ref decimal amount)")
         .Line($"if (creature is not null && creature.HasPower<{n.NoHealPowerClass}>()) amount = 0m;")
         .Close()
         .Close();
        return w.ToString();
    }

    /// <summary>存档里有没有「禁止目标回复生命」的效果（没有就不生成那个状态 / 补丁）。</summary>
    public static bool NeedsNoHealPower(CharacterProfile p) =>
        AllEffects(p).Any(e => e.Kind == "ForbidHeal");

    /// <summary>
    /// 「抽到就减费」用的 Power：挂在自己身上，层数 = 还能持续几个回合。
    ///
    /// 本体没有现成的状态，所以自己写（用的都是本体公开 API，不需要 Harmony）：
    ///   · <c>AfterCardDrawn</c>：每次抽到自己的牌就把那张牌的 <c>EnergyCost</c> 用
    ///     <c>SetThisCombat(当前费用 - 1)</c> 降 1（本体 ConfusedPower 就是这么改费用的）；
    ///     X 费牌（CostsX）和不能打出的牌（Canonical &lt; 0）不动，已经是 0 费的也不再往下减；
    ///   · <c>BeforeSideTurnEnd</c>：玩家回合结束时掉 1 层，掉光自毁。
    /// </summary>
    public static string DrawCostPowerSource(CharacterProfile p)
    {
        if (!NeedsDrawCostPower(p)) return "";
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 「抽到就减费」用的 Power </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {n.DrawCostPowerClass} : PowerModel")
         .Line("public override PowerType Type => PowerType.Buff;")
         .Line()
         .Line("public override PowerStackType StackType => PowerStackType.Counter;")
         .Line()
         .Line("// 每次抽到牌：那张牌本场战斗的费用 -1（本体 ConfusedPower 就是用 SetThisCombat 改费用的）")
         .Open("public override async Task AfterCardDrawn(PlayerChoiceContext choiceContext, CardModel card, bool fromHandDraw)")
         .Line("if (card.Owner != base.Owner.Player) return;")
         .Line("if (card.EnergyCost.CostsX || card.EnergyCost.Canonical < 0) return;   // X 费 / 不能打出的牌不动")
         .Line("int __now = card.EnergyCost.GetWithModifiers(CostModifiers.All);")
         .Open("if (__now > 0)")
         .Line("card.EnergyCost.SetThisCombat(__now - 1);")
         .Close()
         .Line("await Task.CompletedTask;")
         .Close()
         .Line()
         .Line("// 层数 = 还能持续几个回合：每回合掉 1 层，掉光自毁")
         .Open("public override async Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)")
         .Line("if (side != CombatSide.Player) return;")
         .Open("if (base.Amount <= 1)")
         .Line("await PowerCmd.Remove(this);")
         .Close()
         .Line("else")
         .Open("")
         .Line("SetAmount(base.Amount - 1);")
         .Close()
         .Close()
         .Close();
        return w.ToString();
    }

    /// <summary>存档里有没有「抽到就减费」的效果（没有就不生成那个 Power 类）。</summary>
    public static bool NeedsDrawCostPower(CharacterProfile p) =>
        AllEffects(p).Any(e => e.Kind == "CheapenDraw");

    /// <summary>
    /// 「临时增益（本回合 +X）」的临时 Power：**照抄本体 TemporaryStrengthPower 那套**写。
    ///
    /// 为什么不能直接施加状态再自己减掉：本体的「临时力量 / 临时敏捷 / 临时专注」就是
    /// <c>TemporaryStrengthPower</c> 这一类类（FlexPotion 的 FlexPotionPower 继承它）——
    ///   · <c>BeforeApplied</c>：新挂上时，把 X 层加进**真正的状态**（silent，不额外闪特效）；
    ///   · <c>AfterPowerAmountChanged</c>：叠加时按**增量**补进真正的状态（同一套）；
    ///   · <c>AfterSideTurnEnd</c>：这一回合结束（拥有者在这一侧里）时，把这次加的 X 层撤掉、自己消失。
    /// 好处是：层数、叠加、显示、以及「这是临时加的」在状态栏上都和本体一模一样；
    /// 而且不需要 Harmony，也不依赖任何本体私有 API。
    ///
    /// 另外**必须实现本体那个 <c>ITemporaryPower</c> 接口**（本体的尖啸 PiercingWailPower / 灵活药剂
    /// FlexPotionPower 都实现了它）：本体好几处（「痛苦」Misery、「幻觉」、「扒手」、「不安之灯」、
    /// 以及「减益」成就徽章）都靠这个接口认出「这只是临时挂上去的，别当成真的状态」。
    /// 接口只有两个成员：<c>InternallyAppliedPower</c>（真正被加减的那个状态）和
    /// <c>OriginModel</c>（来源模型）—— 后者本体的临时状态基类只拿来取标题 / 说明 / 悬停提示，
    /// 我们这个类自己声明了标题和说明（见 LocalizationGen），所以给 <c>this</c> 就够了。
    /// </summary>
    public static string TempPowersSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 临时增益（本回合 +X）用的临时 Power：这一回合加上，到点（回合结束 / 下回合开始）撤掉 </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line();

        foreach (var e in CollectTempPowerEffects(p))
        {
            string power = e.PowerId ?? "StrengthPower";
            string cls = n.TempPowerClass(e);
            // 增益 / 减益跟着那个状态本身的分类走（查不到就按增益）
            bool isBuff = EffectCatalog.FindPower(e.PowerId)?.IsBuff ?? true;
            // 「什么时候撤」两档：回合结束时（默认）/ 下回合开始时（用户要求的那种「撑过这一回合」）
            bool nextTurn = e.TempPowerReverse == TempPowerReverses.NextTurnStart;
            // 负数 = **让目标先失去** |数值| 层，到点再还原（用户要的「让敌人失去 5 点临时力量」）。
            // 两种写法（看那个状态本体允不允许负层数，见 EffectCatalog.AllowsNegativeLayers）：
            //   · 允许（力量 / 敏捷 / 专注…本体 AllowNegative => true）→ **照尖啸那套**：直接把负数施加进去
            //     （Apply<状态>(target, -N)），目标身上本来 0 层也能扣成负层数；
            //   · 不允许（虚弱 / 易伤…）→ 先取实例再 ModifyAmount(-N) 扣已有层数（全项目「负数 = 扣层数」的约定），
            //     目标身上没有这个状态时什么都做不了（层数不能凭空变成负的）。
            bool negative = e.Amount < 0m;
            bool vanillaNegative = negative && EffectCatalog.AllowsNegativeLayers(e.PowerId);
            string layerZh = negative ? "失去" : "获得";

            w.Line(nextTurn
                ? $"/// <summary>临时 {power}：这一回合 {layerZh}层数，撑过敌人的回合，**下回合开始时**把这次变化还原。</summary>"
                : $"/// <summary>临时 {power}：本回合内 {layerZh}层数，回合结束时把这次变化还原。</summary>")
             .Open($"public sealed class {cls} : PowerModel, ITemporaryPower")
             .Line($"public override PowerType Type => PowerType.{(isBuff ? "Buff" : "Debuff")};")
             .Line()
             .Line("public override PowerStackType StackType => PowerStackType.Counter;")
             .Line()
             .Line("// 本体那套「临时状态」接口（尖啸 / 灵活药剂都实现了它）：「痛苦 / 幻觉 / 扒手 / 不安之灯」")
             .Line("// 以及「减益」成就徽章都靠它认出「这只是临时挂上去的，不是真的状态」。")
             .Line("// OriginModel = 来源模型：本体的临时状态基类只用它取标题 / 说明 / 悬停提示，")
             .Line("// 这个类自己声明了这些（localization/powers.json），所以给 this 就够，不会有人拿它去查卡牌。")
             .Line("public AbstractModel OriginModel => this;")
             .Line($"public PowerModel InternallyAppliedPower => ModelDb.Power<{power}>();")
             .Line()
             .Line("// 允许负层数（点数可以被扣到 0 以下）：本体「尖啸」扣敌人力量就是这么干的 ——")
             .Line("// 目标本来 0 层也要能扣成负数，所以临时状态自己必须允许负数（不然本体会把它当 0 层当场移除）。")
             .Line("public override bool AllowNegative => true;")
             .Line();
            if (negative && vanillaNegative)
            {
                w.Line($"// 刚挂上：**照本体「尖啸」那套**把负数层数施加进真正的状态（{power} 本体 AllowNegative => true，")
                 .Line("// 目标身上本来 0 层也能扣成负层数；用 ModifyAmount 的话「本来没有这个状态」就什么都做不了 ——")
                 .Line("// 那正是用户报的「临时减益不生效」）。到点还原时再 Apply(+N) 加回来。")
                 .Open("public override async Task BeforeApplied(Creature target, decimal amount, Creature? applier, CardModel? cardSource)")
                 .Line($"await PowerCmd.Apply<{power}>(new ThrowingPlayerChoiceContext(), target, amount, applier, cardSource, silent: true);")
                 .Close()
                 .Line()
                 .Line("// 叠加时按增量继续扣（amount 是这次变化的量，base.Amount 是变化后的总量）")
                 .Open("public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel powerModel, decimal amount, Creature? applier, CardModel? cardSource)")
                 .Open("if (!(amount == (decimal)base.Amount) && powerModel == this)")
                 .Line($"await PowerCmd.Apply<{power}>(choiceContext, base.Owner, amount, applier, cardSource, silent: true);")
                 .Close()
                 .Close()
                 .Line();
            }
            else if (negative)
            {
                w.Line($"// 刚挂上：从真正的状态里**扣掉** |层数|（本体「扣层数」就是这么写的：先取实例再 ModifyAmount(-N)）。")
                 .Line($"// 为什么不用「施加负数」（尖啸那套）：{power} 本体没有开 AllowNegative（层数不能为负），")
                 .Line("// 施加负数只会挂上一个层数为负、什么也不做的状态。扣到 0 时本体自己会把那个状态移除；")
                 .Line("// 目标身上本来就没有这个状态时这一扣没有意义（层数不能凭空变负），所以什么都不做。")
                 .Open("public override async Task BeforeApplied(Creature target, decimal amount, Creature? applier, CardModel? cardSource)")
                 .Line($"PowerModel? __real = target.GetPower<{power}>();")
                 .Line("if (__real is not null) await PowerCmd.ModifyAmount(new ThrowingPlayerChoiceContext(), __real, amount, applier, cardSource, silent: true);")
                 .Close()
                 .Line()
                 .Line("// 叠加时按增量继续扣（amount 是这次变化的量，base.Amount 是变化后的总量）")
                 .Open("public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel powerModel, decimal amount, Creature? applier, CardModel? cardSource)")
                 .Open("if (!(amount == (decimal)base.Amount) && powerModel == this)")
                 .Line($"PowerModel? __realNow = base.Owner.GetPower<{power}>();")
                 .Line("if (__realNow is not null) await PowerCmd.ModifyAmount(choiceContext, __realNow, amount, applier, cardSource, silent: true);")
                 .Close()
                 .Close()
                 .Line();
            }
            else
            {
                w.Line("// 刚挂上：把层数加进真正的状态（silent = 不额外闪一次，本体 FlexPotion 的做法）")
                 .Open("public override async Task BeforeApplied(Creature target, decimal amount, Creature? applier, CardModel? cardSource)")
                 .Line($"await PowerCmd.Apply<{power}>(new ThrowingPlayerChoiceContext(), target, amount, applier, cardSource, silent: true);")
                 .Close()
                 .Line()
                 .Line("// 叠加时按增量补进真正的状态（amount 是这次变化的量，base.Amount 是变化后的总量）")
                 .Open("public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)")
                 .Open("if (!(amount == (decimal)base.Amount) && power == this)")
                 .Line($"await PowerCmd.Apply<{power}>(choiceContext, base.Owner, amount, applier, cardSource, silent: true);")
                 .Close()
                 .Close()
                 .Line();
            }
            if (nextTurn)
            {
                w.Line("// 下回合开始时才撤：这一回合和敌人的回合都保留，到你的下一个回合开始时把这次临时变化还原、自己消失")
                 .Line("// ⚠ 还原一律写 -base.Amount：正数档（加层）撤成负数、负数档（扣层）撤成正数，两个方向都对")
                 .Open("public override async Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)")
                 .Line("if (player != base.Owner.Player) return;")
                 .Line("Flash();")
                 .Line("await PowerCmd.Remove(this);")
                 .Line($"await PowerCmd.Apply<{power}>(choiceContext, base.Owner, -base.Amount, base.Owner, null);")
                 .Close();
            }
            else
            {
                w.Line("// 这一回合结束：把这次临时变化还原，然后自己消失")
                 .Line("// ⚠ 还原一律写 -base.Amount：正数档（加层）撤成负数、负数档（扣层）撤成正数，两个方向都对")
                 .Open("public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)")
                 .Open("if (participants.Contains(base.Owner))")
                 .Line("Flash();")
                 .Line("await PowerCmd.Remove(this);")
                 .Line($"await PowerCmd.Apply<{power}>(choiceContext, base.Owner, -base.Amount, base.Owner, null);")
                 .Close()
                 .Close();
            }
            w.Close()
             .Line();
        }
        return w.ToString();
    }

    // ==================== 强化指定卡牌（像本体「精准」）====================

    /// <summary>「强化指定卡牌」用的 Power 类名（兜底用当前角色，见 <see cref="Naming.CurrentCharClass"/>）。</summary>
    internal static string BoostPowerClassName(EffectSpec e, CharacterProfile? owner = null) =>
        owner is null ? Naming.AmbientBoostPowerClass(e) : Naming.From(owner).BoostPowerClass(e);

    /// <summary>
    /// 存档里用到的全部「强化指定卡牌」效果（按「目标卡 + 强化什么」去重：
    /// 同一对只生成**一个** Power —— 两张牌都强化「打击」的伤害时共用一个）。
    /// </summary>
    public static IEnumerable<EffectSpec> CollectBoostEffects(CharacterProfile p)
    {
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var e in AllEffects(p))
        {
            if (e.Kind != "BoostCard") continue;
            if (seen.Add(Naming.BoostPowerSuffix(e))) yield return e;
        }
    }

    /// <summary>
    /// V0.2.136：把「升级后获得 / 失去的自定义关键词」写成回读标记（卡牌与诅咒两条路径共用）。
    ///
    /// <para>两个标记**各自一行**（为空的那一栏不写）—— 避免「同一行上两个标记、空值吃串」的歧义
    ///（实测：<c>Add= CET:UpgradeKeywordRemove=VOID</c> 会被贪婪匹配整段吃进 Add 的值里）。</para>
    ///
    /// <para>存的是**规范化后的本地化键**（和界面勾选、生成时用的同一套，见
    /// <see cref="KeywordGen.NormalizeReferences"/>）：用户填中文名也能原样回来。</para>
    /// </summary>
    private static void EmitUpgradeKeywordMarkers(CharacterProfile p, CardSpec c, CodeWriter w)
    {
        var add = KeywordGen.NormalizeReferences(p, c.UpgradeAddedCustomKeywords);
        var del = KeywordGen.NormalizeReferences(p, c.UpgradeRemovedCustomKeywords);
        if (add.Count > 0)
            w.Line("// CET:UpgradeKeywordAdd=" + EscapeMarker(string.Join("|", add)));
        if (del.Count > 0)
            w.Line("// CET:UpgradeKeywordRemove=" + EscapeMarker(string.Join("|", del)));
    }

    /// <summary>
    /// 把一段用户写的文本塞进**单行注释标记**里：换行一律转义成 <c>\n</c> 两个字面字符
    /// （不然标记会被截成好几行，回读时只剩第一行）。
    /// </summary>
    public static string EscapeMarker(string text) =>
        (text ?? "").Replace("\r\n", "\n").Replace('\r', '\n').Replace("\n", "\\n");

    /// <summary>回读标记里的文本（把 <c>\n</c> 还原成真正的换行）。</summary>
    public static string UnescapeMarker(string text) =>
        (text ?? "").Replace("\\n", "\n");

    /// <summary>这个存档里有没有「强化指定卡牌」（有才生成 BoostPowers.cs）。</summary>
    public static bool UsesBoostCard(CharacterProfile p) => CollectBoostEffects(p).Any();

    /// <summary>
    /// 「强化指定卡牌」的回读标记：**目标卡**和**强化什么（伤害 / 格挡）**在生成的代码里
    /// 只剩「一个 Apply 到某个 Power」这一句话，认不回来 —— 所以生成时额外写一行标记
    /// （<c>// CET:BoostCard=&lt;卡类名&gt; CET:BoostStat=Damage|Block</c>），回读时按它还原。
    /// 数值仍然是 CanonicalVars 里的 <c>Boost</c> 变量。
    /// </summary>
    internal static string BoostMarker(EffectSpec e) =>
        $"// CET:BoostCard={(string.IsNullOrWhiteSpace(e.SpawnCardId) ? "?" : e.SpawnCardId!.Trim())}"
        + $" CET:BoostStat={(e.BoostStat == "Block" ? "Block" : "Damage")}";

    /// <summary>
    /// 「强化指定卡牌」（像本体「精准」对「小刀」）用的 Power。
    ///
    /// 本体里「精准」就是这么写的：<c>AccuracyPower.ModifyDamageAdditive</c> 判断
    /// 「打出的这张牌是不是小刀」，是就把自己的层数加成上去；「敏捷」则是走
    /// <c>ModifyBlockAdditive</c>。这里把「小刀」换成**你在「目标卡」里选的那张牌**，
    /// 于是就有了「所有「打击」+3 伤害」这种效果。
    ///
    /// 为什么用「挂一张 Power」而不是直接改卡牌模型：Power 是**本场战斗内**的临时状态，
    /// 战斗结束自动消失，不会污染存档里的卡牌（和本体「精准」的行为一致）。
    /// 层数 = 加多少；允许负数（填负数就是削弱那张卡 —— 本体状态默认会被夹到 0，必须开 AllowNegative）。
    /// </summary>
    public static string BoostPowersSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 强化指定卡牌（像本体「精准」）用的 Power </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line();

        foreach (var e in CollectBoostEffects(p))
        {
            string cls = n.BoostPowerClass(e);
            // 「目标卡」下拉里存的就是**生成出来的类名**（自己的卡是 CardClassName 算出来的名字，
            // 初始打击 / 防御带角色前缀；本体卡则是本体类名），所以这里直接用，不要再加一次前缀。
            string? card = string.IsNullOrWhiteSpace(e.SpawnCardId) ? null : e.SpawnCardId!.Trim();
            bool block = e.BoostStat == "Block";
            string what = block ? "格挡" : "伤害";
            string cardZh = card ?? "（未选目标卡）";

            w.Line($"/// <summary>本场战斗内，你打出的「{cardZh}」的{what} +层数（层数就是加多少）。</summary>")
             .Open($"public sealed class {cls} : PowerModel")
             .Line("public override PowerType Type => PowerType.Buff;")
             .Line()
             .Line("public override PowerStackType StackType => PowerStackType.Counter;")
             .Line()
             .Line("// 填负数 = 削弱那张卡（本体状态默认把负数夹到 0，必须显式打开）")
             .Line("public override bool AllowNegative => true;")
             .Line();

            if (block)
            {
                w.Open("public override decimal ModifyBlockAdditive(Creature target, decimal block, ValueProp props, CardModel? cardSource, CardPlay? cardPlay)");
                if (card is not null) w.Line($"if (cardSource is not {card}) return 0m;        // 只管这一张卡");
                w.Line("if (base.Owner != target) return 0m;            // 只加在主人自己身上")
                 .Line("if (!props.IsPoweredCardOrMonsterMoveBlock()) return 0m;")
                 .Line("return base.Amount;                            // 层数 = 加多少格挡")
                 .Close();
            }
            else
            {
                w.Open("public override decimal ModifyDamageAdditive(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)");
                w.Line("if (base.Owner != dealer) return 0m;           // 只强化自己打出的牌")
                 .Line("if (!props.IsPoweredAttack()) return 0m;       // 只加强「攻击伤害」（本体「精准」的做法）");
                if (card is not null) w.Line($"if (cardSource is not {card}) return 0m;        // 只管这一张卡");
                w.Line("return base.Amount;                            // 层数 = 加多少伤害")
                 .Close();
            }

            w.Close().Line();
        }
        return w.ToString();
    }

    /// <summary>
    /// 「诅咒 / 先古卡」每一种的**外观池**源码。
    ///
    /// 为什么要单独一个池：本体的边框材质只能从池上取 —— <c>CardModel.FrameMaterial</c> 就是
    /// <c>VisualCardPool.FrameMaterial</c>（<c>CardPoolModel.FrameMaterialPath</c> →
    /// <c>res://materials/cards/frames/&lt;名字&gt;_mat.tres</c>），卡本身没有可覆写的口子。
    /// 本体自己也是这么干的：Clash / DualWield 覆写 <c>VisualCardPool</c> 借铁甲战士的卡框。
    ///
    /// 这个池**不装任何卡**（<c>GenerateAllCards</c> 返回空），只负责给出边框材质 / 能量图标前缀，
    /// 所以也**不进** <c>ModelDb.AllCardPools</c> —— 进去了反而会在卡牌图鉴里多出一个空分类
    /// （<c>ModelDb.CardPool&lt;T&gt;()</c> 是按类型查注册表，和 AllCardPools 无关）。
    ///
    /// 牌堆底色 / 能量图标描边只能跟角色配色：本体取的是**真实卡池**（<c>card.Pool.DeckEntryCardColor</c> /
    /// <c>NCard</c> 里的 <c>Model.Pool.EnergyOutlineColor</c>），而真实卡池必须装这张卡。
    /// 这里照抄角色的值，保证不会更差。
    /// </summary>
    public static string SpecialStylePoolSource(CharacterProfile p, SpecialCardStyleSpec style,
        string poolClass, string title, string frameMaterial)
    {
        var n = Naming.From(p);
        string deckHex = Hex(p.Colors.DeckEntryColor, "D62000");
        string outlineHex = Hex(p.Colors.EnergyOutlineColor, "802020");
        return new CodeWriter()
            .Line("// <auto-generated> 「诅咒 / 先古卡」的外观池（只换卡牌边框材质，不装卡） </auto-generated>")
            .Line($"namespace {n.Namespace};")
            .Line()
            .Line("/// <summary>")
            .Line($"/// {title} 专用的外观池：卡牌边框材质 = {frameMaterial}。")
            .Line("/// 池里**没有卡**（GenerateAllCards 返回空）—— 它只是让 FrameMaterial 有个地方取。")
            .Line("/// 牌堆底色 / 能量描边只能跟角色配色（本体取的是真实卡池，见生成器里的说明），这里照抄角色那份。")
            .Line("/// </summary>")
            .Open($"public sealed class {poolClass} : CardPoolModel")
            .Line($"public override string Title => {Lit.Str(n.CharSlug + "_style")};")
            .Line()
            .Line("// 能量图标仍然用角色自己的（CardModel.EnergyIconPath 也走 VisualCardPool）")
            .Line($"public override string EnergyColorName => {Lit.Str(n.EnergyColor)};")
            .Line()
            .Line($"public override string CardFrameMaterialPath => {Lit.Str(frameMaterial)};")
            .Line()
            .Line($"public override Color DeckEntryCardColor => new Color({Lit.Str(deckHex)});")
            .Line()
            .Line($"public override Color EnergyOutlineColor => new Color({Lit.Str(outlineHex)});")
            .Line()
            .Line("public override bool IsColorless => false;")
            .Line()
            .Line("protected override CardModel[] GenerateAllCards() => [];")
            .Close()
            .ToString();
    }

    /// <summary>
    /// 这一类牌最终用哪个卡框材质名（null = 不加外观池，按老样子）。
    /// 自定义颜色 → 生成出来的 <c>&lt;角色&gt;_&lt;类&gt;_frame</c> 材质；选了本体框色 → 直接用它的名字。
    /// </summary>
    public static string? SpecialFrameMaterialOf(CharacterProfile p, SpecialCardStyleSpec style, string stem) =>
        !style.Any ? null
        : style.IsCustomFrame ? Naming.From(p).SpecialFrameMaterial(stem)
        : style.Frame.Trim();

    public static string DelayedPowersSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 下回合生效用的延迟 Power </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line();

        foreach (var e in CollectDelayedEffects(p))
        {
            // 「下回合生效」的**通用**延迟状态（V0.2.133）：层数 = 这条效果的数值，
            // 下回合开始时跑**同一套发射器**（EmitDelayedEffectBody），跑完自毁。
            if (IsDelayedEffectKind(e.Kind))
            {
                string clsNew = n.DelayedPowerClass(e);
                w.Line($"/// <summary>下回合开始时执行「{EffectCatalog.FindKind(e.Kind).Display}」（层数 = 数值）。</summary>")
                 .Line($"// CET:DelayedEffect={e.Kind}")
                 .Open($"public sealed class {clsNew} : PowerModel")
                 .Line("public override PowerType Type => PowerType.Buff;")
                 .Line()
                 .Line("public override PowerStackType StackType => PowerStackType.Counter;")
                 .Line()
                 .Open("public override async Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)")
                 .Line("if (player != base.Owner.Player || base.Amount <= 0) return;")
                 .Line();
                EmitDelayedEffectBody(w, p, e, DelayedVarMap(p));
                w.Line()
                 .Line("await PowerCmd.Remove(this);")
                 .Close()
                 .Close()
                 .Line();
                continue;
            }

            // 生成类（用户要求：生成卡牌之类也能下回合生效）：层数 = 张数，下回合开始时调用同一套发射器。
            if (IsDelayedSpawnKind(e.Kind))
            {
                string cls2 = n.DelayedPowerClass(e);
                w.Line($"/// <summary>下回合开始时执行「{EffectCatalog.FindKind(e.Kind).Display}」（层数 = 张数）。</summary>")
                 .Line($"// CET:DelayedSpawn={e.Kind}")
                 .Open($"public sealed class {cls2} : PowerModel")
                 .Line("public override PowerType Type => PowerType.Buff;")
                 .Line()
                 .Line("public override PowerStackType StackType => PowerStackType.Counter;")
                 .Line()
                 .Open("public override async Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)")
                 .Line("if (player != base.Owner.Player || base.Amount <= 0) return;")
                 .Line();
                string amt = "base.Amount";
                if (e.Kind == "GenerateCard")
                {
                    // 生成卡牌：走卡牌那条链同一份发射器（玩家表达式换成 base.Owner.Player，Creature 就是 base.Owner）。
                    // withMarker: false —— 标记行要写在**用它的那张牌**上（回读按那张牌认），写在这里会被当成状态的语句。
                    EmitGenerateCard(w, p, e, useX: false, countExpr: amt, tempUpSource: "null",
                        playerExpr: "base.Owner.Player", withMarker: false, creatureExpr: "base.Owner",
                        playerArg: "base.Owner.Player");
                }
                else if (e.Kind == "CopyCard")
                {
                    // 复制卡牌：同样复用那份发射器 —— 延迟状态里没有「这张牌」（source 传 null）、
                    // 玩家是 base.Owner.Player、Creature 是 base.Owner。
                    EmitCopyCard(w, p, e, useX: false, countExpr: amt,
                        playerExpr: "base.Owner.Player", creatureExpr: "base.Owner", sourceExpr: "null");
                }
                else if (e.Kind == "TransformCard")
                {
                    // 变化卡牌（战斗内）：同一套参数化（V0.2.90 起 EmitTransformCard 也接受玩家表达式）。
                    // 注意 combatStateExpr：延迟状态里没有 CardModel 的 base.CombatState，得走 Creature 的。
                    EmitTransformCard(w, e, useX: false, p: p, cardSource: "null", countExpr: amt,
                        playerExpr: "base.Owner.Player", creatureExpr: "base.Owner", sourceExpr: "null",
                        combatStateExpr: "base.Owner.CombatState");
                }
                else
                {
                    EmitGlobalCardEffect(w, e, "base.Owner.Player", useX: false, p);
                }
                w.Line()
                 .Line("await PowerCmd.Remove(this);")
                 .Close()
                 .Close()
                 .Line();
                continue;
            }

            string power = e.PowerId ?? "WeakPower";
            string cls = n.DelayedPowerClass(e);
            bool toSelf = e.TargetSide == "Self";

            w.Line($"/// <summary>下回合开始时{(toSelf ? "给自己" : "给所有敌人")}施加 {power}。</summary>")
             .Open($"public sealed class {cls} : PowerModel")
             .Line("public override PowerType Type => PowerType.Buff;")
             .Line()
             .Line("public override PowerStackType StackType => PowerStackType.Counter;")
             .Line()
             .Open("public override async Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)")
             .Line("if (player != base.Owner.Player) return;")
             .Line();

            if (toSelf)
                w.Line($"await PowerCmd.Apply<{power}>(choiceContext, base.Owner, base.Amount, base.Owner, null);");
            else
                w.Open("foreach (Creature foe in base.Owner.CombatState.HittableEnemies)")
                 .Line($"await PowerCmd.Apply<{power}>(choiceContext, foe, base.Amount, base.Owner, null);")
                 .Close();

            w.Line()
             .Line("await PowerCmd.Remove(this);")
             .Close()
             .Close()
             .Line();
        }
        return w.ToString();
    }

    // ==================== 遗物 ====================

    /// <summary>
    /// 这只遗物的效果（V0.2.126 起是**整只遗物唯一的一份**：效果挂在遗物上，
    /// 触发时机只说明「什么时候触发」，见 <see cref="RelicSpec.Effects"/>）。
    ///
    /// 为什么留成方法：生成端有十几处「按整只遗物算」的判断（动态变量声明 / 悬停提示 / 概率掷骰 /
    /// 先古预览 / 条件 / 「用到才生成」的东西）都走它，改一处就全改到。空集合不是 null。
    /// </summary>
    private static IEnumerable<EffectSpec> RelicEffects(RelicSpec r) =>
        r.Effects is null ? Enumerable.Empty<EffectSpec>() : r.Effects.Where(e => e is not null);

    public static string RelicSource(CharacterProfile p, RelicSpec r, int index)
    {
        // 「生成调试日志」（V0.2.142）用的临时变量序号：每次生成一个源文件从头开始
        //（「同一份存档生成两次文本逐字节相同」是既有红线，见 DebugLogGen._seq）。
        DebugLogGen.Reset();
        // ===== V0.2.126：效果是**整只遗物那一份**，触发时机只决定「什么时候跑它」=====
        // 只有一条时机时**完全走下面那条老路径**（一个字符都不变 —— 单时机 Any 的回归红线，
        // 那种形状就是 V0.2.121 及更早的老存档）；两条以上才走 EmitRelicMultiTriggerHook
        // （按「钩子」分组，同一条钩子只生成一个 override）。
        if (r.Triggers.Count(t => t is not null) > 1)
            return EmitRelicMultiTriggerHook(p, r, index);

        var n = Naming.From(p);
        string cls = n.RelicClassName(r, index);
        var trigger = EffectCatalog.RelicTriggers.FirstOrDefault(t => t.Id == r.Trigger) ?? EffectCatalog.RelicTriggers[0];
        // 「获得时」的钩子没有 choiceContext，需要的时候生成端自己造一个（见 CanBootstrapContext）；
        // 「每消耗一个能量 / 每消耗一个额外资源量 / 生成卡牌时」同样没有，但那三条在战斗里 ——
        // 按本体 Hook.cs 的做法造 HookPlayerChoiceContext（见 BootstrapInCombat）。
        bool needCtx = (CanBootstrapContext(trigger.Id) || BootstrapInCombat(trigger.Id))
                       && r.Effects.Any(x => RelicNeedsChoiceContext(x));
        bool hasContext = HasContext(trigger.Id) || needCtx;
        // 「战斗胜利时」的钩子签名里带 CombatRoom：卡牌奖励走本体那套战斗奖励（AddExtraReward）
        string? roomVar = trigger.Id is "CombatVictory" or "CombatEnd" ? "room" : null;

        string signature = RelicTriggerSignature(trigger.Id);

        var w = new CodeWriter();
        w.Line("// <auto-generated> 自定义遗物 </auto-generated>");
        if (r.HasCustomDescription)
            w.Line($"// CET:CustomDescReplace={(r.CustomDescriptionReplaces ? 1 : 0)} CET:CustomDescription={EscapeMarker(r.CustomDescription)}");
        w.Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {cls} : RelicModel")
         .Line($"public override RelicRarity Rarity => RelicRarity.{r.Rarity};");
        // 「获得时」= 拾取时生效：按本体「好吃饼干 / 磨刀石」那样声明一句
        // （本体 HasUponPickupEffect 的效果之一就是这只遗物不能在商店里被换掉 —— 语义上正是「拿了就生效」）
        if (trigger.Id == "Obtained")
            w.Line("public override bool HasUponPickupEffect => true;");
        w.Line()
         .Line("protected override IEnumerable<DynamicVar> CanonicalVars =>")
         .Line("[");
        // 第 10 批：动态变量要覆盖**所有触发时机**的效果（只看 r.Effects = 第 1 条时机会漏掉后面的）
        var relicAllEffects = RelicEffects(r).ToList();
        var relicVars = VarNamesOf(relicAllEffects);
        foreach (var e in relicAllEffects.Where(x => !HasNoDynamicVar(x))) w.Line($"    {VarDeclaration(e, relicVars, p)},");
        w.Line("];");

        // 鼠标悬停遗物描述里的状态 → 弹出那条说明（自定义状态 / 被改写的本体状态都有）
        // V0.2.164：遗物上写了「数值公式」时，顺带把悬停数字的现算挂上去（见 FormulaPreviewRefreshMethod）
        bool relicFormulaPreview = relicAllEffects.Any(x => x is not null
            && x.UsesAmountFormula && FormulaVarClassOf(x.Kind) is not null);
        w.Raw(FormulaPreviewRefreshMethod(p, relicAllEffects, relicVars, "base.Owner", "base.Owner.Creature"));
        w.Raw(HoverTipsOverride(relicAllEffects, isPublic: false, owner: p, refreshFormulaPreview: relicFormulaPreview));

        // 条件选项：「每场战斗只触发一次」需要一个标记（本体「百年积木」的做法）
        bool hasCond = r.Condition is not null && !r.Condition.IsNone;
        var relicEffectConds = relicAllEffects.Where(x => x.Condition is not null && !x.Condition.IsNone).ToList();
        bool oncePerCombat = (hasCond && r.Condition.Kind == "OncePerCombat")
                             || relicEffectConds.Any(x => x.Condition.Kind == "OncePerCombat");
        string condExpr = hasCond ? ConditionExpr(r.Condition, CondCtx.Relic) : "true";
        if (oncePerCombat)
        {
            w.Line()
             .Line("// 条件：每场战斗只触发一次（本体「百年积木」的做法：用完打标记，战斗结束清零）")
             .Line("private bool _condUsedThisCombat;");
        }

        w.Line()
         .Line($"// 触发时机：{trigger.Display}")
         .Open(signature);

        // 「某个状态层数到达 N 层时」（用户要求）：盯哪个状态 / 到达多少层这两个参数从守卫语句里
        // 反推也行，但守卫一旦以后改写法就会丢配置 —— 所以照旧写一行标记（只在选了这个时机时写）。
        if (trigger.Id == "PowerReached")
            w.Line($"// CET:PowerWatch={Lit.Identifier(r.TriggerPowerId ?? "", "")} CET:PowerReach={Lit.Dec(Math.Max(0m, r.TriggerAmount))}");
        // 「某个状态被移除时」也盯着某一个状态（留空 = 任意状态）→ 同样写一行标记（回读用）
        if (trigger.Id == "PowerRemoved")
            w.Line($"// CET:PowerWatch={Lit.Identifier(r.TriggerPowerId ?? "", "")}");

        // 守卫那一大段 switch 抽成了 RelicTriggerGuardLines（下面那个方法）——**文本一个字都没动**：
        // 单条时机这条路径仍然把它们原样写进方法体（return 式守卫），红线（逐字不变）不受影响；
        // 多条时机那条路径用同一份行文本改写成 if 块（见 EmitRelicMultiTriggerHook）。
        foreach (string guardLine in RelicTriggerGuardLines(trigger.Id, r.TriggerPowerId, r.TriggerAmount, r.TriggerCardFilter, p))
            w.Line(guardLine);

        // 触发时机上的数值（用户要求：遗物 / 状态两边都要有）：
        //   计数族（打牌 / 消耗 / 弃掉 / 抽到 / 生成）→ 每累计 N 次触发一次（本回合 / 本场战斗）；
        //   阈值族（受到·造成伤害 / 失去生命 / 获得格挡）→ 数值 ≥ N 才触发。
        // 遗物只有一个触发时机，所以这里直接用「不满足就 return」的写法。
        foreach (string amountLine in TriggerAmountLines(trigger.Id, r.TriggerAmount, r.TriggerScope,
                     "base.Owner.Creature", "base.Owner.Creature.CombatState", "base.Owner", TriggerValueExpr(trigger.Id),
                     CombatCountersClass(p)))
            w.Line(amountLine);
        // 数值也写一行标记（回读用：守卫那几行的写法以后改了就丢配置）
        // ⚠ V0.2.152：`PowerReached`（到达 N 层）**故意不写这一行** —— 它的 N 由上面那行
        // `// CET:PowerWatch=… CET:PowerReach=N` 记着，回读也按它 + 守卫正则还原；
        // 多写一行 `CET:TriggerAmount` 会让「多时机（全部满足 / 任一满足）」那条路的段落切分
        // 多切出一条时机（自检实测：2 条变 3 条）。
        if (r.TriggerAmount > 0m && ((TriggerSupportsAmount(trigger.Id) && trigger.Id != "PowerReached") || PerPointTrigger(trigger.Id)))
            w.Line("// CET:TriggerAmount=" + TriggerAmountForMarker(r.TriggerAmount) + " CET:TriggerScope=" + r.TriggerScope);

        if (needCtx)
        {            w.Line();
            if (CanBootstrapContext(trigger.Id))
            {
                w.Line("// 这个钩子（AfterObtained）本体没给 choiceContext：按本体的做法自己造一个阻塞式的");
                w.Line("// （本体的 BlockingPlayerChoiceContext 注释里点名的第一个场景就是「遗物 AfterObtained 回调」）");
                w.Line("var choiceContext = new MegaCrit.Sts2.Core.GameActions.Multiplayer.BlockingPlayerChoiceContext();");
            }
            else
            {
                w.Line("// 这个钩子本体没给 choiceContext（战斗里那几条）：按本体 Hook.cs 的做法造一个 HookPlayerChoiceContext");
                w.Line("// —— 战斗里**不能**用 BlockingPlayerChoiceContext（那是局外的阻塞式上下文，会卡住）");
                w.Line("// 遗物的 Owner 就是 Player，所以用「(source, owner, netId, type)」这个重载（不用传 CombatState）。");
                w.Line("ulong __netId = MegaCrit.Sts2.Core.Context.LocalContext.NetId ?? 0UL;");
                w.Line("var choiceContext = new MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext(this, base.Owner, __netId, MegaCrit.Sts2.Core.Entities.Multiplayer.GameActionType.Combat);");
            }
        }

        if (hasCond)
        {
            w.Line();
            w.Line($"// 条件（整只遗物）：{ConditionText(r.Condition)}（不满足时不触发）");
            w.Line(ConditionGuard(r.Condition));
            if (r.Condition.Kind == "OncePerCombat") w.Line("_condUsedThisCombat = true;");
        }

        // 效果那一整段（按点数循环 / 概率掷骰 / 先古预览）抽成了 EmitRelicEffectBlock ——
        // 单条路径和多条路径共用同一份文本，免得两边慢慢长歪。这里的输出和以前**逐字一致**。
        // ⚠ 「关系 = 全部满足才触发、但只配了 1 条时机」也走这条路径（校验器会提示「不生效」）：
        //   单条时机下「全部满足」和「满足其中一个」是同一条，生成的代码一个字都一样。
        //   ⚠ 为了让这种情况回读得回来，只有这时候多写一行标记 —— **单条 + Any 不写**
        //   （红线：那种形状 = V0.2.121 及更早的老存档，生成文本必须逐字一致）。
        if (r.IsAllTriggers) w.Line(RelicTriggerModeMarker(r));
        int relicEffectIndex = 0;
        // 「生成调试日志」（V0.2.142，默认关）：这一段的效果都属于「这只遗物」
        using (DebugLogGen.Begin(p, "遗物", r.Name, cls, "base.Owner.Creature"))
            EmitRelicEffectBlock(w, p, r.First, r.Effects.ToList(), hasContext, relicVars, roomVar, ref relicEffectIndex);
        // 效果级「每场战斗只触发一次」：跑过一次就打标记（整只遗物级的已经在上面打过标记了）
        if (!hasCond || r.Condition.Kind != "OncePerCombat")
            if (relicEffectConds.Any(x => x.Condition.Kind == "OncePerCombat"))
                w.Line("_condUsedThisCombat = true;");
        // 「每场战斗只触发一次」+ 触发时机本身就是「战斗结束时」：清理钩子和触发钩子是**同一个方法**，
        // 另写一个 AfterCombatEnd 就是 CS0111（整个模组编译不过）—— 所以在触发体**末尾**把标记清掉
        // （效果已经跑完了，清掉等于「这场用过了」；下一次战斗开始又是 false）。
        if (oncePerCombat && trigger.Id == "CombatEnd")
            w.Line("_condUsedThisCombat = false;   // 触发时机就是「战斗结束时」→ 顺手把「每场战斗只触发一次」的标记清掉");

        // 锻造节点图里【触发时机】和这只遗物的触发时机**是同一个钩子**时，把节点图嵌进这个方法里
        // （不能另写一个同名 override —— 那是 CS0111）；不同的时机才在类末尾新加方法。
        if (ForgeGraphGen.UsesGraph(r) && ForgeGraphGen.RelicGraphNestsInTrigger(r, trigger.Id))
            w.Line($"await {ForgeRelicGraphMethod}({(trigger.Id is "CombatVictory" or "CombatEnd" ? "room" : "")});   // 锻造节点图：{trigger.Display}");

        w.Close();

        if (oncePerCombat && trigger.Id != "CombatEnd")
        {
            w.Line()
             .Line("/// <summary>战斗结束：把「每场战斗只触发一次」的标记清掉。</summary>")
             .Open("public override Task AfterCombatEnd(CombatRoom room)")
             .Line("_condUsedThisCombat = false;")
             .Line("return Task.CompletedTask;")
             .Close();
        }
        // 锻造节点图：图非空时把它的钩子附加在类末尾（空图 = 一个字符都不写）
        if (ForgeGraphGen.UsesGraph(r))
        {
            string fields = ForgeGraphGen.TimingFields(p, r);
            if (fields.Length > 0) w.Raw(fields);
            string hooks = ForgeGraphGen.RelicHooks(p, r);
            if (hooks.Length > 0) w.Raw(hooks);
        }
        w.Close();
        return w.ToString();
    }

    /// <summary>
    /// 「只认属于自己的那件事」的归属守卫行（**不带缩进**，调用方自己缩进）。
    ///
    /// 这是 <see cref="RelicSource"/> 里那个大 <c>switch (trigger.Id)</c> 的**等价副本** ——
    /// 为什么允许两份文本：遗物页那一份是逐字锁死的（红线：遗物页生成结果不许变），
    /// 而锻造页的节点图（<see cref="ForgeGraphGen.EmitHook"/>）需要同一套行为。
    /// 两份文本必须**行为一致**：改这里就要同步改那边（自检里有「时机 → 期望守卫片段」的对照表兜着）。
    ///
    /// 为什么锻造页原来一条守卫都没有：它在 8 空格缩进的方法体里直接跑效果，
    /// 结果敌人打我 / 敌人打牌 / 别人掉血也会触发你自己的锻造遗物。
    ///
    /// <paramref name="triggerPowerId"/> / <paramref name="triggerAmount"/> = 状态层数那三条
    /// （到达 N 层 / 层数变化 / 被移除）要的「盯哪个状态」「到达 N 层」（锻造页存在【触发时机】模块的这两栏上）。
    /// <paramref name="triggerAmountExpr"/>（V0.2.128）= 「到达 N 层」那一栏写了**运行时公式**时用它
    /// （非空就替掉那个常数；内联表达式，见 ForgeNumbers.Place.Inline）。null = 老行为（常数），逐字不变。
    ///
    /// 可见性 = public：自检（App 那一侧）要直接调这两份守卫做「三份完全一致」的对照，
    /// 而 App 是另一个程序集（Core 没有 InternalsVisibleTo）。生成逻辑本身一个字没动。
    /// </summary>
    public static IReadOnlyList<string> ForgeTriggerGuardLines(string triggerId, string? triggerPowerId, decimal triggerAmount,
        string? triggerAmountExpr = null)
    {
        var lines = new List<string>();
        switch (triggerId)
        {
            case "CombatStart":
                lines.Add("// 只在本次战斗自己的第一个回合开始前触发一次");
                lines.Add("if (!participants.Contains(base.Owner.Creature) || base.Owner.PlayerCombatState.TurnNumber > 1) return;");
                break;
            case "PlayerTurnStart":
                lines.Add("if (player != base.Owner) return;");
                break;
            case "PlayerTurnEnd":
                lines.Add("if (side != base.Owner.Creature.Side) return;");
                break;
            case "DamageReceived":
                lines.Add("if (target != base.Owner.Creature) return;");
                // 「失去生命」不算「受到伤害」：本体 DamageProps.cardHpLoss = Unblockable | Unpowered
                //（血祭 / 献祭 / 中毒这类穿盾且没有来源加成的掉血）—— 它由「自己失去生命时」那条时机负责，别两边都触发。
                // 注意别把它和「对自己造成伤害」搞混：那条生成的是 Unpowered | Move（**格挡能挡**），
                // 不含 Unblockable → 不会被这一句挡掉，照旧算「受到伤害」。
                lines.Add("if (props.HasFlag(ValueProp.Unblockable) && props.HasFlag(ValueProp.Unpowered)) return;");
                lines.Add("if (result.UnblockedDamage <= 0) return;   // 这一下全被格挡 / 0 伤害：不算受到伤害");
                // V0.2.139：**自己已经死了就别再跑**（钩子是 CreatureCmd.Damage 无条件广播的，致死那一下也进）。
                // 不挡的话「受到伤害时回复生命」会在自己死后把血拉回来 —— 多人模式下队友还活着 = 看起来复活。
                // 位置：在「只认自己」那句**之后**（= 挨打的确实是本人），且在效果之前。
                // 锻造链的 Owner 是 Player，所以必须写 base.Owner.Creature（不是 base.Owner）。
                lines.Add("if (base.Owner.Creature.IsDead) return;   // 自己已经死了：致死那一下不再跑（否则「回复生命」会把人拉回来）");
                break;
            case "Attacked":
                lines.Add("// 多次连击只算一次：本体的 AfterAttack 是所有命中跑完之后才调一次");
                lines.Add("decimal __takenThisAttack = command.Results.SelectMany(hits => hits).Where(r => r.Receiver == base.Owner.Creature).Sum(r => r.UnblockedDamage);");
                lines.Add("if (__takenThisAttack <= 0) return;   // 这一次攻击没真的打到我（全被格挡 / 打的是别人）");
                // V0.2.139：本体 AfterAttack 在**所有命中结束之后**才跑一次 ——「这一击把我打死了」也是
                // 在这个时点才调到这里（__takenThisAttack 照样 > 0）。不挡的话「受到攻击后回复生命」
                // 会把自己从 0 血拉回来（多人模式下 = 复活）。
                lines.Add("if (base.Owner.Creature.IsDead) return;   // 自己已经死了：致死那一下不再跑（否则「回复生命」会把人拉回来）");
                break;
            case "GoldGained":
                lines.Add("if (player != base.Owner) return;");
                break;
            case "DamageDealt":
                lines.Add("if (dealer != base.Owner.Creature) return;   // 只认自己造成的伤害");
                // 「失去生命」不算「受到伤害」，也就不算「自己造成伤害」（同上：本体 DamageProps.cardHpLoss =
                // Unblockable | Unpowered；「对自己造成伤害」是 Unpowered | Move，不含 Unblockable → 照旧算）。
                lines.Add("if (props.HasFlag(ValueProp.Unblockable) && props.HasFlag(ValueProp.Unpowered)) return;");
                break;
            case "EnergySpent":
                lines.Add("if (amount <= 0 || card?.Owner?.Creature != base.Owner.Creature) return;   // 只认「我方角色花的能量」（0 费不算）");
                break;
            case "StarsSpent":
                lines.Add("if (amount <= 0 || spender != base.Owner) return;   // 只认「我方角色花的额外资源量」");
                break;
            case "CardGenerated":
                lines.Add("if (creator is null || creator != base.Owner) return;   // 只认「我方角色主动生成」的牌");
                break;
            case "PowerReached":
                lines.Add("if (power.Owner is null || power.Owner != base.Owner.Creature) return;   // 只看自己身上的状态");
                if (!string.IsNullOrWhiteSpace(triggerPowerId))
                    lines.Add($"if (power is not {Lit.Identifier(triggerPowerId, "VulnerablePower")}) return;   // 只盯「{EffectCatalog.PowerName(triggerPowerId, triggerPowerId)}」");
                if (triggerAmountExpr is not null)
                {
                    // 运行时公式（V0.2.128）：算两遍（判据里两边都要那个数）——公式是纯表达式，没有副作用
                    lines.Add($"if (!(power.Amount >= ({triggerAmountExpr}) && power.Amount - amount < ({triggerAmountExpr}))) return;"
                        + "   // 只有「层数跨过公式算出来的那个数」那一下才触发");
                }
                else
                {
                    lines.Add($"if (!(power.Amount >= {Lit.Dec(Math.Max(0m, triggerAmount))} && power.Amount - amount < {Lit.Dec(Math.Max(0m, triggerAmount))})) return;"
                        + $"   // 只有「层数跨过 {Math.Max(0m, triggerAmount):0.##}」那一下才触发");
                }
                break;
            case "PowerChanged":
                lines.Add("if (power.Owner is null || power.Owner != base.Owner.Creature) return;   // 只看自己身上的状态");
                if (!string.IsNullOrWhiteSpace(triggerPowerId))
                    lines.Add($"if (power is not {Lit.Identifier(triggerPowerId, "VulnerablePower")}) return;   // 只盯「{EffectCatalog.PowerName(triggerPowerId, triggerPowerId)}」");
                break;
            case "PowerRemoved":
                lines.Add("if (power.Owner is null || power.Owner != base.Owner.Creature) return;   // 只看自己身上的状态");
                if (!string.IsNullOrWhiteSpace(triggerPowerId))
                    lines.Add($"if (power is not {Lit.Identifier(triggerPowerId, "VulnerablePower")}) return;   // 只盯「{EffectCatalog.PowerName(triggerPowerId, triggerPowerId)}」");
                break;
            case "CardPlayed":
            case "CardResolved":
                // 遗物页那份还多一层「只对哪类牌生效」（RelicSpec.TriggerCardFilter，第 9 批 ④ 前半段）——
                // 那是**遗物自己**的字段；锻造节点图上要筛牌请用【条件】模块，所以这里只有归属这一条。
                // V0.2.157：两条时机（结算前 / 结算完）共用同一条归属守卫。
                lines.Add("if (cardPlay.Player != base.Owner) return;   // 只认自己打出的牌");
                break;
            case "CardExhausted":
                lines.Add("if (card?.Owner?.Creature != base.Owner.Creature) return;   // 只认自己被消耗的牌");
                break;
            case "CardDrawn":
                lines.Add("if (card?.Owner?.Creature != base.Owner.Creature) return;   // 只认自己抽到的牌");
                break;
            case "CardDiscarded":
                lines.Add("if (card?.Owner?.Creature != base.Owner.Creature) return;   // 只认自己被弃掉的牌");
                break;
            case "HpLost":
                lines.Add("if (creature != base.Owner.Creature) return;   // 只认自己掉血");
                lines.Add("if (delta >= 0m) return;   // delta 为正是回血，不算「失去生命」");
                // V0.2.139：致死那一下这个钩子也会进来（delta 正好是负的），不挡的话
                //「失去生命时回复生命」会在自己死后把血拉回来（多人模式下队友还活着 = 复活）。
                // 锻造链的 base.Owner 是 Player → 必须写 base.Owner.Creature。
                lines.Add("if (base.Owner.Creature.IsDead) return;   // 自己已经死了：致死那一下不再跑（否则「回复生命」会把人拉回来）");
                break;
            case "BlockGained":
                lines.Add("if (creature != base.Owner.Creature) return;   // 只认自己拿到格挡");
                break;
            case "EnemyDeath":
                lines.Add("if (!creature.IsEnemy) return;   // 只认敌人死亡（自己人死了不算）");
                break;
            case "EnemyTurnStart":
                lines.Add("if (side != CombatSide.Enemy) return;   // 只认敌人那一侧");
                break;
            case "EnemyTurnEnd":
                lines.Add("if (side != CombatSide.Enemy) return;   // 只认敌人那一侧");
                break;
            case "EnemyDamaged":
                // ⚠ 这里**故意不**加「失去生命不算受到伤害」那句守卫：敌人侧没有「敌人失去生命」这条触发时机
                //   可以替代，排掉就等于「敌人被血祭 / 中毒扣血」再也收不到通知 —— 功能直接丢了（自己那两条才有替代）。
                lines.Add("if (target == base.Owner.Creature || !target.IsAlive) return;   // 受伤的是敌人（自己不算）");
                break;
            case "EnemyDealtDamage":
                // 同上：敌人造成的伤害也没有「敌人失去生命」这条时机兜底，守卫保持原样。
                lines.Add("if (dealer is null || dealer == base.Owner.Creature) return;   // 打人的是敌人（自己不算）");
                break;
            case "EnemyBlockGained":
                lines.Add("if (creature == base.Owner.Creature) return;   // 拿格挡的是敌人（自己不算）");
                break;
            case "Shuffle":
                lines.Add("if (shuffler != base.Owner) return;");
                break;
        }
        return lines;
    }

    // ==================== 遗物：多条触发时机（第 10 批） ====================
    //
    // 用户原话：「在哪选择多个触发时机，我怎么看不到，能不能在遗物页底下新增触发时机列表，
    // 并且可以添加多个触发时机」。设计（用户已确认）：
    //   · 每条触发时机**各自配自己的效果**（和「自定义状态」页一模一样）；
    //   · 也能勾「要和其他时机同时成立（都成立才触发）」，和状态页同一套语义。
    //
    // 关键约束（红线）：**只有一条时机、且没勾「同时成立」的遗物，生成文本必须和以前逐字一致**
    // —— 所以 RelicSource 在那种情况下压根不走这里（见它的开头），这里只处理 ≥ 2 条的遗物。
    //
    // 另一个必须解决的坑：同一个**本体钩子方法**只能生成一个 override（写两个同名同参数的 → CS0111，
    // 整个模组编译不过）。所以这里按「钩子」分组（不是按「配置里的时机」分组）：两条时机都落在
    // AfterDamageReceived 上时，只生成**一个** override，方法体里按顺序放各自的条件块 + 效果块。

    /// <summary>多条触发时机时，一条时机在某个钩子方法里的全部内容（守卫 / 数值门 / 效果）。</summary>
    private sealed class RelicTriggerPlan
    {
        public RelicSpec Relic = null!;
        public RelicTriggerSpec Trigger = null!;
        public string Id = "";
        public string Display = "";
        /// <summary>要写在方法体里的注释（`// 触发时机：X` / `// CET:PowerWatch=`）。</summary>
        public List<string> Comments = new();
        /// <summary>变量声明行（`decimal __takenThisAttack = …`）——不带 return，放在 if 块**外面**。</summary>
        public List<string> Decls = new();
        /// <summary>守卫行（`if (…) return;`）——多时机时改写成 `if (!(…)) { … }`。</summary>
        public List<string> Guards = new();
        /// <summary>「触发时机上的数值」那几行（`if (…) return;` / `int __deaths = …`）。</summary>
        public List<string> AmountLines = new();
        public bool NeedsCtx;
        /// <summary>效果里能不能直接用 <c>choiceContext</c>（本体钩子给的参数 + 生成端自己造的那两种）。</summary>
        public bool HasContext;
        public string? RoomVar;
        /// <summary>
        /// 这一段要不要跑**遗物那份共享效果**（V0.2.126）：Any 模式每条时机都跑；
        /// All 模式只有最后那条跑（前面几条只打 <c>__andHit</c> 标记）。
        /// </summary>
        public bool SharedEffects;
    }

    /// <summary>
    /// 遗物触发时机的**归属守卫行**（`if (…) return;`）。
    ///
    /// 这是原来 <see cref="RelicSource"/> 里那个大 <c>switch (trigger.Id)</c> 的**逐字搬家** ——
    /// 文本一个字都没改，所以只有一条时机的老存档生成结果完全不变（红线）；
    /// 多条时机那条路径拿同一份行文本改写成 if 块（见 <see cref="EmitRelicMultiTriggerHook"/>）。
    /// </summary>
    /// <param name="triggerCardFilter">「打出一张牌后」只对哪类牌生效（遗物页那一栏；`Any` = 不过滤）。</param>
    public static IReadOnlyList<string> RelicTriggerGuardLines(string triggerId, string? triggerPowerId,
        decimal triggerAmount, string? triggerCardFilter, CharacterProfile p)
    {
        var lines = new List<string>();
        switch (triggerId)
        {
            case "CombatStart":
                lines.Add("// 只在本次战斗自己的第一个回合开始前触发一次");
                lines.Add("if (!participants.Contains(base.Owner.Creature) || base.Owner.PlayerCombatState.TurnNumber > 1) return;");
                break;
            case "PlayerTurnStart":
                lines.Add("if (player != base.Owner) return;");
                break;
            case "PlayerTurnEnd":
                lines.Add("if (side != base.Owner.Creature.Side) return;");
                break;
            case "DamageReceived":
                lines.Add("if (target != base.Owner.Creature) return;");
                // 「失去生命」不算「受到伤害」：本体 DamageProps.cardHpLoss = Unblockable | Unpowered
                //（血祭 / 献祭 / 中毒这类穿盾且没有来源加成的掉血）—— 它由「自己失去生命时」那条时机负责，别两边都触发。
                // 注意别把它和「对自己造成伤害」搞混：那条生成的是 Unpowered | Move（**格挡能挡**），
                // 不含 Unblockable → 不会被这一句挡掉，照旧算「受到伤害」。
                lines.Add("if (props.HasFlag(ValueProp.Unblockable) && props.HasFlag(ValueProp.Unpowered)) return;");
                // 本体「原体黏土 SelfFormingClay / 残存之心 BeatingRemnant」都是这么判的：
                // 全被格挡（或 0 伤害）的那一下不算「受到伤害」。（每一下都会进这个钩子 —— 连击就是多次触发）
                lines.Add("if (result.UnblockedDamage <= 0) return;   // 这一下全被格挡 / 0 伤害：不算受到伤害");
                // V0.2.139：**自己已经死了就别再跑**。本体 Hook.AfterDamageReceived 在 CreatureCmd.Damage 里
                // **无条件**广播（扣血那一步之后才派发），所以「被敌人打死的那一下」照样会进到这里 ——
                // 效果里只要有「回复生命」，就会把 HP 从 0 拉回正数：多人模式下队友还活着 = 看起来「复活」。
                // 单人模式一样生效（致死那一下不再触发这只遗物）—— 这是预期语义。
                // 位置：在「只认自己」那句**之后**（= 挨打的确实是本人），且在效果之前。
                // ⚠ 遗物链的 base.Owner 是 **Player**，所以这里必须写 base.Owner.Creature。
                lines.Add("if (base.Owner.Creature.IsDead) return;   // 自己已经死了：致死那一下不再跑（否则「回复生命」会把人拉回来）");
                break;
            // 「受到攻击后」：本体 AfterAttack 在**一次攻击的所有命中都结束之后**才跑一次
            //（AbstractModel.AfterAttack 的注释就是这么写的）—— 所以连击只算一次。
            // 判据：这一次攻击的命中结果里，有没有真的打到「我」身上的伤害。
            case "Attacked":
                lines.Add("// 多次连击只算一次：本体的 AfterAttack 是所有命中跑完之后才调一次");
                lines.Add("decimal __takenThisAttack = command.Results.SelectMany(hits => hits).Where(r => r.Receiver == base.Owner.Creature).Sum(r => r.UnblockedDamage);");
                lines.Add("if (__takenThisAttack <= 0) return;   // 这一次攻击没真的打到我（全被格挡 / 打的是别人）");
                // V0.2.139：同上 ——「这一击把我打死了」也是在所有命中结束之后才调到这里
                //（__takenThisAttack 照样 > 0），不挡的话「受到攻击后回复生命」会把人从 0 血拉回来。
                lines.Add("if (base.Owner.Creature.IsDead) return;   // 自己已经死了：致死那一下不再跑（否则「回复生命」会把人拉回来）");
                break;
            case "GoldGained":
                lines.Add("if (player != base.Owner) return;");
                break;
            // 造成伤害时（每一下）：只认自己造成的伤害。**不判「有没有真的打穿格挡」**——
            // 和自定义状态那条「自己造成伤害后」口径一致（本体 AfterDamageGiven 是每一下命中都调）。
            case "DamageDealt":
                lines.Add("if (dealer != base.Owner.Creature) return;   // 只认自己造成的伤害");
                // 「失去生命」不算「受到伤害」，也就不算「自己造成伤害」（同上：本体 DamageProps.cardHpLoss =
                // Unblockable | Unpowered；「对自己造成伤害」是 Unpowered | Move，不含 Unblockable → 照旧算）。
                lines.Add("if (props.HasFlag(ValueProp.Unblockable) && props.HasFlag(ValueProp.Unpowered)) return;");
                break;
            // 每消耗一个能量：本体这条钩子**0 费也会调**（本体源码里 amount > 0 只包住历史记录 / 扣能量，
            // 钩子调用在外面），所以必须自己挡掉 amount <= 0；「是谁花的」只能从 card.Owner 认
            // （本体 EnvenomPower / OrbitPower 都是这么判的）—— 不判的话联机时别人打牌也会触发你的遗物。
            case "EnergySpent":
                lines.Add("if (amount <= 0 || card?.Owner?.Creature != base.Owner.Creature) return;   // 只认「我方角色花的能量」（0 费不算）");
                break;
            // 每消耗一个额外资源量：同上（本体这条钩子带 spender，直接比 Player）
            case "StarsSpent":
                lines.Add("if (amount <= 0 || spender != base.Owner) return;   // 只认「我方角色花的额外资源量」");
                break;
            // 生成卡牌时：本体注释写明「只算玩家自己生成的那几张」（敌人塞给你的状态牌不算），
            // 而且 creator 可能为 null（本体自己的写法就是判 null）。
            case "CardGenerated":
                lines.Add("if (creator is null || creator != base.Owner) return;   // 只认「我方角色主动生成」的牌");
                break;
            // 某个状态层数到达 N 层时（用户要求）：本体 AfterPowerAmountChanged 任何单位的状态层数一变就会调
            //（而且是**每层一次** —— 上 3 层会连着调 3 次），所以这里判三件事：
            //   ① 是自己身上的状态（遗物的 Owner 是 Player，所以比 base.Owner.Creature）；
            //   ② 是不是你盯的那个状态（留空 = 任何状态都算）；
            //   ③ 这一次变化**跨过**了 N 层（之前不到 N、变化后到了 N 或更多）——
            //      power.Amount 是变化后的层数，amount 是这一次的增量，所以「之前」= power.Amount - amount。
            case "PowerReached":
                lines.Add("if (power.Owner is null || power.Owner != base.Owner.Creature) return;   // 只看自己身上的状态");
                if (!string.IsNullOrWhiteSpace(triggerPowerId))
                    lines.Add($"if (power is not {Lit.Identifier(triggerPowerId, "VulnerablePower")}) return;   // 只盯「{EffectCatalog.PowerName(triggerPowerId, triggerPowerId)}」");
                lines.Add($"if (!(power.Amount >= {Lit.Dec(Math.Max(0m, triggerAmount))} && power.Amount - amount < {Lit.Dec(Math.Max(0m, triggerAmount))})) return;"
                     + $"   // 只有「层数跨过 {Math.Max(0m, triggerAmount):0.##}」那一下才触发");
                break;
            // 某个状态层数变化时（升或降都触发）：同一个钩子，只是不判「跨过 N」那一条
            //（用户要求「两边触发时机一致」，所以状态那边有的这一条遗物也有）
            case "PowerChanged":
                lines.Add("if (power.Owner is null || power.Owner != base.Owner.Creature) return;   // 只看自己身上的状态");
                if (!string.IsNullOrWhiteSpace(triggerPowerId))
                    lines.Add($"if (power is not {Lit.Identifier(triggerPowerId, "VulnerablePower")}) return;   // 只盯「{EffectCatalog.PowerName(triggerPowerId, triggerPowerId)}」");
                break;
            // 「某个状态被移除时」（用户要求）：走工具自己打的补丁（见 PowerRemovalSource）——
            // 补丁会把「谁身上哪个状态被移除了」传进来，这里只做归属 + 盯哪个状态的过滤。
            case "PowerRemoved":
                lines.Add("if (power.Owner is null || power.Owner != base.Owner.Creature) return;   // 只看自己身上的状态");
                if (!string.IsNullOrWhiteSpace(triggerPowerId))
                    lines.Add($"if (power is not {Lit.Identifier(triggerPowerId, "VulnerablePower")}) return;   // 只盯「{EffectCatalog.PowerName(triggerPowerId, triggerPowerId)}」");
                break;
            // ===== 用户要求「遗物 / 状态触发时机合并成同一套」后补上的这批 =====
            // 守卫都按**遗物**的归属判据写（状态那条链的 base.Owner 是 Creature，遗物这边是 Player →
            // 一律比 base.Owner.Creature），本体给的钩子签名两边完全一样。
            // V0.2.157：「打出一张牌时」与「一张牌结算完毕时」**共用这一段守卫**（区别只在钩子：
            // BeforeCardPlayed = 结算前 / AfterCardPlayedLate = 结算完）。本体这两个钩子都是
            // 「任意一方打出牌都会调」→ 先只认「自己打的」。
            case "CardPlayed":
            case "CardResolved":
                lines.Add("if (cardPlay.Player != base.Owner) return;   // 只认自己打出的牌");
                // 「只对哪类牌生效」（用户要求：遗物侧也要有范围，和状态侧同一套 —— 第 9 批 ④）：
                // 老四档（攻击 / 技能 / 能力）生成的判据和状态侧**逐字同款**；新增的
                // 诅咒 / 状态 / 关键词组 / 组 走卡牌那边同一套「范围界定」谓词（见 ScopeCondForFilter），
                // 并写一行 `// CET:CardFilter=` 供回读（守卫语句以后改写法也不丢配置）。
                string filter = string.IsNullOrWhiteSpace(triggerCardFilter) ? "Any" : triggerCardFilter;
                if (!string.Equals(filter, "Any", StringComparison.Ordinal))
                {
                    if (filter is "Attack" or "Skill" or "Power")
                    {
                        lines.Add($"if (cardPlay.Card.Type != CardType.{filter}) return;"
                             + $"   // 只对「{PowerTriggers.CardFilterZh(filter)}」牌生效");
                    }
                    else
                    {
                        lines.Add("// CET:CardFilter=" + filter);
                        string? relicFilterCond = ScopeCondForFilter(filter, p);
                        // 认不出来的筛选值：不乱猜、不筛（校验器会报错说清），但标记照旧写出来，回读不丢配置
                        if (relicFilterCond is not null)
                            lines.Add($"if (!({relicFilterCond.Replace("c.", "cardPlay.Card.")})) return;"
                                 + $"   // 只对「{PowerTriggers.CardFilterZh(filter)}」生效");
                    }
                }
                break;
            case "CardExhausted":
                lines.Add("if (card?.Owner?.Creature != base.Owner.Creature) return;   // 只认自己被消耗的牌");
                break;
            case "CardDrawn":
                lines.Add("if (card?.Owner?.Creature != base.Owner.Creature) return;   // 只认自己抽到的牌");
                break;
            case "CardDiscarded":
                lines.Add("if (card?.Owner?.Creature != base.Owner.Creature) return;   // 只认自己被弃掉的牌");
                break;
            case "HpLost":
                // 本体 AfterCurrentHpChanged：delta 为正是回血，只有 delta < 0 才算「失去生命」
                lines.Add("if (creature != base.Owner.Creature) return;   // 只认自己掉血");
                lines.Add("if (delta >= 0m) return;   // delta 为正是回血，不算「失去生命」");
                // V0.2.139：致死那一下这个钩子也会进来（delta 正好是负的）—— 不挡的话
                //「失去生命时回复生命」会在自己死后把血拉回来（多人模式下队友还活着 = 复活）。
                // ⚠ 遗物链的 base.Owner 是 Player → 必须写 base.Owner.Creature。
                lines.Add("if (base.Owner.Creature.IsDead) return;   // 自己已经死了：致死那一下不再跑（否则「回复生命」会把人拉回来）");
                break;
            case "BlockGained":
                lines.Add("if (creature != base.Owner.Creature) return;   // 只认自己拿到格挡");
                break;
            case "EnemyDeath":
                lines.Add("if (!creature.IsEnemy) return;   // 只认敌人死亡（自己人死了不算）");
                break;
            case "EnemyTurnStart":
                lines.Add("if (side != CombatSide.Enemy) return;   // 只认敌人那一侧");
                break;
            case "EnemyTurnEnd":
                lines.Add("if (side != CombatSide.Enemy) return;   // 只认敌人那一侧");
                break;
            case "EnemyDamaged":
                // ⚠ 这里**故意不**加「失去生命不算受到伤害」那句守卫：敌人侧没有「敌人失去生命」这条触发时机
                //   可以替代，排掉就等于「敌人被血祭 / 中毒扣血」再也收不到通知 —— 功能直接丢了（自己那两条才有替代）。
                lines.Add("if (target == base.Owner.Creature || !target.IsAlive) return;   // 受伤的是敌人（自己不算）");
                break;
            case "EnemyDealtDamage":
                // 同上：敌人造成的伤害也没有「敌人失去生命」这条时机兜底，守卫保持原样。
                lines.Add("if (dealer is null || dealer == base.Owner.Creature) return;   // 打人的是敌人（自己不算）");
                break;
            case "EnemyBlockGained":
                lines.Add("if (creature == base.Owner.Creature) return;   // 拿格挡的是敌人（自己不算）");
                break;
            // 洗牌：只看**自己**的抽牌堆被洗（本体 BiiigHug / TheAbacus 都是这个判法）。
            // 条件「本回合 / 本场战斗洗过牌」不靠这里记 —— 那是 ShuffleTracker 的补丁负责的（用到才生成）。
            case "Shuffle":
                lines.Add("if (shuffler != base.Owner) return;");
                break;
        }
        return lines;
    }

    /// <summary>前置行里用来分隔「守卫」与「触发时机数值」的哨兵注释（只在生成期用，不会写进结果）。</summary>
    private const string RelicAmountSentinel = "//__CET_AMOUNT__";

    /// <summary>
    /// 一条触发时机的**前置行**（守卫 / 注释 / 变量声明）：从写好的方法体开头往前扫连续的
    /// 注释行 + 声明行 + 守卫行 —— 这样「`// CET:PowerWatch=` / `// 触发时机：` 这类标记」
    /// 不用再抄第二份（抄两份必然有一天不同步）。
    ///
    /// 中间插一行**哨兵**（<see cref="RelicAmountSentinel"/>）：它后面才是「触发时机上的数值」那几行 ——
    /// 为什么需要：数值行和守卫行长得一样（都是 `if (…) return;`），不按位置切分不出来；
    /// 而回读标记 `// CET:TriggerAmount=` 是**单独写在数值行后面**的、不在这些行里，
    /// 以前拿它去 IndexOf 永远找不到 → 数值行整段丢失（实测：两条时机的遗物生成出来
    /// 「每累计花掉 N 次」那一条**根本没写**，触发时机数值静默失效）。
    /// </summary>
    private static List<string> RelicTriggerPreludeLines(string triggerId, string? powerId, decimal amount,
        string scope, string? cardFilter, CharacterProfile p)
    {
        var w2 = new CodeWriter();
        if (triggerId == "PowerReached")
            w2.Line($"// CET:PowerWatch={Lit.Identifier(powerId ?? "", "")} CET:PowerReach={Lit.Dec(Math.Max(0m, amount))}");
        else if (triggerId == "PowerRemoved")
            w2.Line($"// CET:PowerWatch={Lit.Identifier(powerId ?? "", "")}");
        foreach (string g in RelicTriggerGuardLines(triggerId, powerId, amount, cardFilter, p)) w2.Line(g);
        w2.Line(RelicAmountSentinel);
        // ⚠ 这里必须传这条时机自己的 Scope（以前写死 "Turn" —— 数值那行注释里的范围会错，回读就认错）
        foreach (string a in TriggerAmountLines(triggerId, amount, scope,
                     "base.Owner.Creature", "base.Owner.Creature.CombatState", "base.Owner", TriggerValueExpr(triggerId),
                     CombatCountersClass(p)))
            w2.Line(a);
        return w2.ToString().Replace("\r\n", "\n").Split('\n').Where(l => l.Length > 0).ToList();
    }

    /// <summary>
    /// 关系模式的**回读标记行**（V0.2.126）：<c>// CET:TriggerMode=Any|All CET:AndScope=Turn|Combat</c>。
    ///
    /// 为什么要有它：生成端两种模式写出来的代码形状相近（都是一堆守卫 + 一段效果），
    /// 光看代码反推不出「这几条时机是任意一条就触发，还是全都要满足」；而「重置范围」只在
    /// All 模式下存在，没有标记就丢了。位置照其他 <c>CET:</c> 标记的风格写在效果段之前。
    /// </summary>
    internal static string RelicTriggerModeMarker(RelicSpec r) =>
        $"// CET:TriggerMode={(r.IsAllTriggers ? "All" : "Any")} CET:AndScope={r.AndScope}"
        + (r.IsAllTriggers ? "   // 整只遗物：全部触发时机都满足才跑一次效果" : "   // 整只遗物：任意一条触发时机满足就跑一次效果");

    /// <summary>
    /// 多条触发时机时的钩子方法：**按钩子分组**，一组只生成一个 override。
    ///
    /// 两条时机落在同一个钩子上时（例：都是 AfterDamageReceived），方法体里按顺序放：
    /// <code>
    /// // 触发时机：自己受到伤害后（每一下）
    /// if (!(target == base.Owner.Creature)) { …效果… }
    /// // 触发时机：敌人受到伤害后
    /// if (!(target == base.Owner.Creature) || !(result.UnblockedDamage > 0)) { …效果… }
    /// </code>
    /// 为什么不是「第一条用 return 式守卫、后面几条用 if」：那样同一个钩子里的第一条一旦不成立就
    /// <c>return</c>，把后面几条时机一起跳过了。全部包成 if 块才是「各自独立判断」。
    /// </summary>
    private static string EmitRelicMultiTriggerHook(CharacterProfile p, RelicSpec r, int index)
    {
        var n = Naming.From(p);
        string cls = n.RelicClassName(r, index);
        var triggers = r.Triggers.Where(t => t is not null).ToList();
        // V0.2.126：效果是**整只遗物唯一那一份**（不再按时机各配一份）
        var allEffects = RelicEffects(r).ToList();

        // 「全部满足才触发」（用户要求）＝ V0.2.122 那套「同时成立」的语义推广到整只遗物：
        // 每条时机各自照常判断自己那件事，谁成立了就打个标记；**最后凑齐的那一条**才跑
        // 遗物那份共享效果，然后把这一轮的标记清掉（一个窗口只触发一次）。
        // 实现口径和「自定义状态」页完全一样（见 CustomPowerGen.TryWrapRequireAll）。
        bool andOn = r.IsAllTriggers;
        // 谁负责跑那份共享效果：All 模式 = **最后一条时机**（前面各条只打标记，凑齐了才轮到它）；
        // Any 模式 = 每条时机各自跑（见下面 plan.SharedEffects 的赋值）。
        var lastTrigger = triggers[triggers.Count - 1];
        var firstTrigger = triggers[0];
        var plans = new List<RelicTriggerPlan>();
        foreach (var t in triggers)
        {
            var plan = new RelicTriggerPlan
            {
                Relic = r,
                Trigger = t,
                Id = t.Kind,
                Display = EffectCatalog.RelicTriggers.FirstOrDefault(x => x.Id == t.Kind)?.Display ?? t.Kind,
                RoomVar = t.Kind is "CombatVictory" or "CombatEnd" ? "room" : null,
                HasContext = HasContext(t.Kind),
            };
            var prelude = RelicTriggerPreludeLines(t.Kind, t.PowerId, t.Amount, t.Scope, t.CardFilter, p);
            // 哨兵前 = 注释 / 声明 / 守卫；哨兵后 = 「触发时机上的数值」那几行（见 RelicTriggerPreludeLines）
            int amountStart = prelude.IndexOf(RelicAmountSentinel);
            if (amountStart < 0) amountStart = prelude.Count;
            else
            {
                // 数值那一行标记要跟着数值行走（回读全靠它）——见 ctor 里 RelicTriggerPlan 的说明
                prelude.RemoveAt(amountStart);
                // ⚠ V0.2.152：`PowerReached` 同上面那处（多写一行会让多时机那条路多切出一条时机）
                if (t.Amount > 0m && ((TriggerSupportsAmount(t.Kind) && t.Kind != "PowerReached") || PerPointTrigger(t.Kind)))
                    prelude.Insert(amountStart,
                        "// CET:TriggerAmount=" + TriggerAmountForMarker(t.Amount) + " CET:TriggerScope=" + t.Scope);
            }
            plan.AmountLines.AddRange(prelude.Skip(amountStart));
            foreach (string line in prelude.Take(amountStart))
            {
                if (line.StartsWith("//", StringComparison.Ordinal)) plan.Comments.Add(line);
                else if (IsRelicGuardLine(line)) plan.Guards.Add(line);
                else plan.Decls.Add(line);
            }
            // 上下文：这个钩子本体没给 choiceContext、而遗物那份效果里有用得到它的 → 生成端自己造一个
            plan.NeedsCtx = (CanBootstrapContext(t.Kind) || BootstrapInCombat(t.Kind))
                            && allEffects.Any(x => RelicNeedsChoiceContext(x));
            // Any 模式：每条时机各自跑共享效果；All 模式：只有最后那条跑（前面几条只打标记）
            plan.SharedEffects = !andOn || ReferenceEquals(lastTrigger, t);
            plans.Add(plan);
        }

        // 同一个钩子里**重复**的变量名要各加后缀（例：两条「受到攻击后」各声明一个 __takenThisAttack
        // → 同一个方法体里两次声明 = CS0128）。只有真重复时才加后缀，别的声明文本一个字不动。
        var perHook = new Dictionary<string, List<RelicTriggerPlan>>(StringComparer.Ordinal);
        var hookOrder = new List<string>();
        foreach (var plan in plans)
        {
            string sig = RelicTriggerSignature(plan.Id);
            if (!perHook.TryGetValue(sig, out var list)) { list = new List<RelicTriggerPlan>(); perHook[sig] = list; hookOrder.Add(sig); }
            list.Add(plan);
        }

        var w = new CodeWriter();
        w.Line("// <auto-generated> 自定义遗物 </auto-generated>");
        if (r.HasCustomDescription)
            w.Line($"// CET:CustomDescReplace={(r.CustomDescriptionReplaces ? 1 : 0)} CET:CustomDescription={EscapeMarker(r.CustomDescription)}");
        w.Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {cls} : RelicModel")
         .Line($"public override RelicRarity Rarity => RelicRarity.{r.Rarity};");
        // 「获得时」= 拾取时生效：只要有一条时机是「获得时」就声明（和单条路径同一句）
        if (triggers.Any(t => t.Kind == "Obtained"))
            w.Line("public override bool HasUponPickupEffect => true;");
        w.Line()
         .Line("protected override IEnumerable<DynamicVar> CanonicalVars =>")
         .Line("[");
        var relicVars = VarNamesOf(allEffects);
        foreach (var e in allEffects.Where(x => !HasNoDynamicVar(x))) w.Line($"    {VarDeclaration(e, relicVars, p)},");
        w.Line("];");

        // V0.2.164：遗物上写了「数值公式」时，悬停数字要在取说明那一步现算（见 FormulaPreviewRefreshMethod）
        bool multiFormulaPreview = allEffects.Any(x => x is not null
            && x.UsesAmountFormula && FormulaVarClassOf(x.Kind) is not null);
        w.Raw(FormulaPreviewRefreshMethod(p, allEffects, relicVars, "base.Owner", "base.Owner.Creature"));
        w.Raw(HoverTipsOverride(allEffects, isPublic: false, owner: p, refreshFormulaPreview: multiFormulaPreview));

        bool hasCond = r.Condition is not null && !r.Condition.IsNone;
        var relicEffectConds = allEffects.Where(x => x.Condition is not null && !x.Condition.IsNone).ToList();
        bool oncePerCombat = (hasCond && r.Condition.Kind == "OncePerCombat")
                             || relicEffectConds.Any(x => x.Condition.Kind == "OncePerCombat");
        string condExpr = hasCond ? ConditionExpr(r.Condition, CondCtx.Relic) : "true";
        if (oncePerCombat)
        {
            w.Line()
             .Line("// 条件：每场战斗只触发一次（本体「百年积木」的做法：用完打标记，战斗结束清零）")
             .Line("private bool _condUsedThisCombat;");
        }
        if (andOn)
        {
            w.Line()
             .Line("/// <summary>")
             .Line("/// 【全部满足才触发】这几条触发时机各自照常判断自己那件事，谁成立了就打个标记；")
             .Line("/// **最后凑齐的那一条**才会跑遗物那份效果，然后把这一轮的标记清掉（一个窗口只触发一次）。")
             .Line("/// 窗口 = " + (r.AndScope == "Combat" ? "本场战斗（整场凑齐一次就行）" : "本回合（换回合按回合号自动清零）") + "。")
             .Line("/// </summary>")
             .Line("private bool " + string.Join(", ", triggers.Select((_, i) => $"__andHit{i}")) + ";");
            if (r.AndScope != "Combat")
                w.Line("private int __andTurn;   // 上一次记下的回合数（变了就清标记 = 本回合窗口）");
        }

        int relicEffectIndex = 0;   // 「转化为先古卡」的预览序号：跨触发时机连续编号（和单条路径同一套）

        foreach (string sig in hookOrder)
        {
            var group = perHook[sig];
            // 同一组里重复的**生成期临时变量** → 各加一个后缀（`__takenThisAttack` → `__takenThisAttack1`），
            // 否则同一个方法体里声明两次 = CS0128。只碰 `__` 开头的名字，而且只碰真的重复的那些。
            var dupes = group.SelectMany(pl => pl.Decls.Concat(pl.AmountLines))
                .SelectMany(RelicTempVars)
                .GroupBy(x => x, StringComparer.Ordinal)
                .Where(g => g.Count() > 1)
                .Select(g => g.Key)
                .ToHashSet(StringComparer.Ordinal);

            w.Line()
             .Line($"// 触发时机：{group[0].Display}" + (group.Count > 1 ? $"（这个方法里合并了 {group.Count} 条时机）" : ""))
             .Open(sig);
            for (int gi = 0; gi < group.Count; gi++)
            {
                var plan = group[gi];
                // 重命名要和「名字判据」对得上：只改 `__` 开头的临时变量（`__deaths` 在守卫行里也要一起改）
                for (int i = 0; i < plan.Decls.Count; i++)
                    plan.Decls[i] = RenameRelicTempVars(plan.Decls[i], dupes, gi);
                for (int i = 0; i < plan.AmountLines.Count; i++)
                    plan.AmountLines[i] = RenameRelicTempVars(plan.AmountLines[i], dupes, gi);
                for (int i = 0; i < plan.Guards.Count; i++)
                    plan.Guards[i] = RenameRelicTempVars(plan.Guards[i], dupes, gi);
            }
            for (int gi = 0; gi < group.Count; gi++)
            {
                var plan = group[gi];
                foreach (string c in plan.Comments) w.Line(c);
                // 「全部满足才触发」（用户要求）：这条时机成立时打自己的标记；
                // **最后凑齐的那一条**（= 最后一条时机）才跑遗物那份共享效果，然后清标记。
                string flags = string.Join(" && ", triggers.Select((_, i) => $"__andHit{i}"));
                int myIdx = 0;
                for (int i = 0; i < triggers.Count; i++) if (ReferenceEquals(triggers[i], plan.Trigger)) { myIdx = i; break; }
                if (andOn && r.AndScope != "Combat")
                {
                    // 本回合窗口：换回合先把标记清掉（按回合号认，不需要额外的重置钩子）。
                    // ⚠ 每个分支里都写一遍（不是只写第一段）：前面那些分支的守卫一旦不成立，
                    //   写在它们后面的代码就永远不会跑到，标记会一直留着。
                    // ⚠ 遗物的 base.Owner **就是 Player**，所以直接取 PlayerCombatState；
                    //   不能照抄状态页那版（状态那边 base.Owner 是 Creature，才要多一层 `.Player?`）——
                    //   抄错会生成 `base.Owner.Player?.PlayerCombatState` → CS1061（真 build 抓到的）。
                    w.Open("if (base.Owner.PlayerCombatState is { } __andPcs && __andPcs.TurnNumber != __andTurn)");
                    w.Line("__andTurn = __andPcs.TurnNumber;   // 新的一回合：把「全部满足」的标记清掉");
                    w.Line(string.Join(" ", triggers.Select((_, i) => $"__andHit{i} = false;")));
                    w.Close();
                }
                // 关系模式 + 「这条时机跑共享效果」的标记。⚠ 必须写在 `if` **外面**（缩进 0）：
                // 回读靠这一行认「关系 + 重置范围」和「共享效果在哪一段」（见 ProjectRecovery 的
                // RelicTriggerModeFromText / SplitRelicTriggerSegments）；缩进进 if 块里就切不出这一段了。
                // 只写在**真正跑共享效果的那一段**（All = 最后一条时机；Any = 第一条）——
                // 每一段都写的话回读会拿第一段去解析效果，而 All 模式的第一段里根本没有效果。
                if (ReferenceEquals(andOn ? lastTrigger : firstTrigger, plan.Trigger)) w.Line(RelicTriggerModeMarker(r));
                // 守卫 / 数值门 / 上下文 / 条件一行行地收集成「这个分支里要写的东西」——
                // 守卫是**合并**的（多个 `return` 守卫 = 多个条件与起来；本分支不成立就整段跳过）。
                // 为什么不用 `return`：同一个钩子方法里还有别的触发时机，`return` 会把它们一起跳过。
                var conds = new List<string>();
                foreach (string d in plan.Decls) w.Line(d);
                if (plan.NeedsCtx && !plan.HasContext)
                {
                    w.Line();
                    if (CanBootstrapContext(plan.Id))
                    {
                        w.Line("// 这个钩子（AfterObtained）本体没给 choiceContext：按本体的做法自己造一个阻塞式的");
                        w.Line("// （本体的 BlockingPlayerChoiceContext 注释里点名的第一个场景就是「遗物 AfterObtained 回调」）");
                        w.Line("var choiceContext = new MegaCrit.Sts2.Core.GameActions.Multiplayer.BlockingPlayerChoiceContext();");
                    }
                    else
                    {
                        w.Line("// 这个钩子本体没给 choiceContext（战斗里那几条）：按本体 Hook.cs 的做法造一个 HookPlayerChoiceContext");
                        w.Line("// —— 战斗里**不能**用 BlockingPlayerChoiceContext（那是局外的阻塞式上下文，会卡住）");
                        w.Line("// 遗物的 Owner 就是 Player，所以用「(source, owner, netId, type)」这个重载（不用传 CombatState）。");
                        w.Line("ulong __netId = MegaCrit.Sts2.Core.Context.LocalContext.NetId ?? 0UL;");
                        w.Line("var choiceContext = new MegaCrit.Sts2.Core.Hooks.HookPlayerChoiceContext(this, base.Owner, __netId, MegaCrit.Sts2.Core.Entities.Multiplayer.GameActionType.Combat);");
                    }
                }
                foreach (string a in plan.AmountLines)
                {
                    if (IsRelicGuardLine(a)) conds.Add(NegateRelicGuard(a));
                    else w.Line(a);
                }
                foreach (string g in plan.Guards) conds.Add(NegateRelicGuard(g));
                bool condBites = false;
                if (hasCond)
                {
                    w.Line();
                    w.Line($"// 条件（整只遗物）：{ConditionText(r.Condition)}（不满足时不触发）");
                    conds.Add(NegateRelicGuard(ConditionGuard(r.Condition)));
                    condBites = true;
                }
                // 一个分支里的条件合并成一句（多个 `return` 守卫 = 多个条件与起来）
                if (conds.Count > 0) w.Open("if (" + string.Join(" && ", conds) + ")");
                if (andOn)
                {
                    w.Line($"__andHit{myIdx} = true;   // 这条成立（第 {myIdx + 1}/{triggers.Count} 条）");
                    w.Line("// 所有参与的那几条时机在同一个窗口里都成立过了");
                    w.Open($"if ({flags})");
                }
                if (condBites && r.Condition.Kind == "OncePerCombat") w.Line("_condUsedThisCombat = true;");
                int before = w.Length;
                if (plan.SharedEffects)
                {
                    // 「生成调试日志」（V0.2.142，默认关）：这一段的效果都属于「这只遗物」
                    using (DebugLogGen.Begin(p, "遗物", r.Name, Naming.From(p).RelicClassName(r, index), "base.Owner.Creature"))
                        EmitRelicEffectBlock(w, p, plan.Trigger, allEffects, plan.HasContext,
                            relicVars, plan.RoomVar, ref relicEffectIndex);
                }
                if (andOn)
                {
                    w.Line(string.Join(" ", triggers.Select((_, i) => $"__andHit{i} = false;")) + "   // 这一轮用掉了，下个窗口重新凑");
                    w.Close();
                }
                if (conds.Count > 0) w.Close();
                // 这条时机一个字符都没写（没效果 / 没上下文 / 没条件）：async 的方法体不能空着
                if (w.Length == before && conds.Count == 0 && !andOn)
                    w.Line("await Task.CompletedTask;   // 这条时机什么都没配：保持 async 方法的签名一致");
                // 锻造节点图里【触发时机】和这条时机是同一个钩子时，把节点图嵌进这个方法里（不能另写同名 override）
                if (ForgeGraphGen.UsesGraph(r) && ForgeGraphGen.RelicGraphNestsInTrigger(r, plan.Id))
                    w.Line($"await {ForgeRelicGraphMethod}({(plan.Id is "CombatVictory" or "CombatEnd" ? "room" : "")});   // 锻造节点图：{plan.Display}");
            }
            // 效果级「每场战斗只触发一次」：跑过一次就打标记（整只遗物级的已经在上面打过标记了）
            if (!hasCond || r.Condition.Kind != "OncePerCombat")
                if (relicEffectConds.Any(x => x.Condition.Kind == "OncePerCombat"))
                    w.Line("_condUsedThisCombat = true;");
            // 清理钩子和触发钩子是同一个方法时（触发时机就是「战斗结束时」）在末尾清标记（另写一个 = CS0111）
            if (oncePerCombat && group.Any(pl => pl.Id == "CombatEnd"))
                w.Line("_condUsedThisCombat = false;   // 触发时机就是「战斗结束时」→ 顺手把「每场战斗只触发一次」的标记清掉");
            w.Close();
        }

        if (oncePerCombat && !triggers.Any(t => t.Kind == "CombatEnd"))
        {
            w.Line()
             .Line("/// <summary>战斗结束：把「每场战斗只触发一次」的标记清掉。</summary>")
             .Open("public override Task AfterCombatEnd(CombatRoom room)")
             .Line("_condUsedThisCombat = false;")
             .Line("return Task.CompletedTask;")
             .Close();
        }
        // 锻造节点图：图非空时把它的钩子附加在类末尾（空图 = 一个字符都不写）
        if (ForgeGraphGen.UsesGraph(r))
        {
            string fields = ForgeGraphGen.TimingFields(p, r);
            if (fields.Length > 0) w.Raw(fields);
            string hooks = ForgeGraphGen.RelicHooks(p, r);
            if (hooks.Length > 0) w.Raw(hooks);
        }
        w.Close();
        return w.ToString();
    }

    /// <summary>
    /// 这个遗物钩子里「一条触发时机自己的那份效果」——单条路径和多条路径共用同一份文本，
    /// 免得两边慢慢长歪（单条路径调它时输出和以前逐字一致）。
    ///
    /// <paramref name="relicEffectIndex"/> 是**跨触发时机连续**的序号（「转化为先古卡」的预览收集要用它）。
    /// </summary>
    private static void EmitRelicEffectBlock(CodeWriter w, CharacterProfile p, RelicTriggerSpec t,
        List<EffectSpec> effects, bool hasContext, Dictionary<EffectSpec, string> relicVars, string? roomVar,
        ref int relicEffectIndex)
    {
        if (effects.Count > 0) w.Line();
        // 「每消耗一个能量 / 每消耗一个额外资源量」：本体那个 amount 是**这一张牌一共花的**点数，
        // 所以整段效果按点数各跑一次（本体 OrbitPower 也是按点数累加的）。掷骰留在循环外面 ——
        // 一次触发只掷一次，和「同一只遗物这一次触发共用一次掷骰」那条规矩一致。
        bool perPoint = PerPointTrigger(t.Kind);
        // 「花掉 N 点」的数值（用户要求）：填了 N 就按「每累计花掉 N 点触发一次」筛，范围 = 本回合 / 本场战斗
        bool spendThreshold = perPoint && t.Amount > 0m;
        if (perPoint)
        {
            if (spendThreshold)
            {
                w.Line($"// 数值：每累计花掉 {t.Amount:0.##} 点触发一次（范围：{(t.Scope == "Combat" ? "本场战斗" : "本回合")}）");
                w.Line(SpendBeforeLine(t.Kind, t.Scope, "base.Owner.Creature", "base.Owner.Creature.CombatState"));
            }
            w.Line($"// 这个钩子的 amount 是「这一张牌一共花的」点数 → 下面的效果按点数各触发一次（{t.Display}）");
            w.Open($"for (int __{t.Kind}Idx = 0; __{t.Kind}Idx < amount; __{t.Kind}Idx++)");
            if (spendThreshold)
                w.Line(SpendTickLine(t.Amount, $"__{t.Kind}Idx", "__spentBefore"));
        }
        // 概率生效：这只遗物这一次触发里，所有勾了概率的效果共用一次掷骰
        var relicChanceSlices = ChanceSlices(effects);
        if (relicChanceSlices.Count > 0) w.Line(ChanceRollLine());
        int petAllSeq = 0;
        // 「转化为先古卡」的预览收集：所有配对行的结果汇总到这一个 List，方法末尾一次性弹本体那个预览界面
        bool hasAncientTranscend = effects.Any(x => x.Kind == "AncientTranscend");
        if (hasAncientTranscend)
        {
            w.Line();
            w.Line("// 「转化为先古卡」变出来的牌先收在这里，最后一次性弹预览（本体潘多拉魔盒的 NSimpleCardsViewScreen）");
            w.Line("var __fgAncientPreview = new List<CardPileAddResult>();");
        }
        foreach (var e in effects)
        {
            // 每条效果自己的条件：不满足时只跳过这一条
            string? cond = EffectConditionGuard(e, CondCtx.Relic, chanceSlices: relicChanceSlices);
            if (cond is not null)
            {
                w.Line($"// 条件（只对「{EffectCatalog.FindKind(e.Kind).Display}」这条效果）：{ConditionText(e.Condition)}（不满足时这条效果不触发）");
                w.Open(cond);
            }
            // 「全部召唤物」的「召唤伙伴」：给这一组一个组号，回读时把展开的多份合并回一条
            string? petAllGroup = PetGen.IsAll(e.PetSummon) && e.Kind == "SummonPet" ? "r" + petAllSeq++ : null;
            // V0.2.132：新档位在**遗物链**上也要能回读 —— 卡牌链的标记写在 EmitCardEffect 里，
            // 遗物这条链没有；只在**新档位**（全体单位 / 全部友方不含召唤物）出现时才补一行，
            // 老存档（6 档 + 含召唤物）一个字符都不多（红线①）。
            if (string.Equals(e.TargetSide, "AllUnits", StringComparison.Ordinal))
                w.Line("// CET:TargetSide=AllUnits");
            else if (string.Equals(e.TargetSide, "AllAllies", StringComparison.Ordinal) && e.AllAlliesExcludePets)
                w.Line("// CET:TargetSide=AllAllies CET:AllyNoPets=1");
            EmitRelicEffect(w, p, e, hasContext, relicVars, roomVar, petAllGroup, relicEffectIndex++);
            if (cond is not null) w.Close();
        }
        // 按点数循环到此为止：下面这些是「一次触发只做一次」的东西（预览界面 / 标记 / 节点图）
        if (perPoint) w.Close();
        // 预览：本体那个界面是 public static，模组里能直接调（潘多拉魔盒就是它）；
        // TestMode 下本体自己会 return null，所以自检不会被弹窗卡住。
        if (hasAncientTranscend)
        {
            w.Line();
            w.Open("if (__fgAncientPreview.Count > 0)");
            w.Line($"MegaCrit.Sts2.Core.Nodes.Screens.NSimpleCardsViewScreen.ShowScreen(__fgAncientPreview, new MegaCrit.Sts2.Core.Localization.LocString(\"relics\", \"{AncientPreviewLocKey}\"));");
            w.Close();
        }
    }

    /// <summary>生成出来的那一行是不是「不满足就退出本钩子」的守卫（`return;` 结尾）。</summary>
    /// <remarks>
    /// V0.2.139：判断前先**去掉行尾的行注释**（`… return;   // 说明`）。以前这里只看整行里有没有
    /// <c>return;</c>，而这条判据（<see cref="EmitRelicMultiTriggerHook"/> 里用它把前置行分成
    /// 「守卫 / 声明」两拨）是**按语义分类**的 —— 一行声明里只要出现字符串 <c>"return;"</c>
    /// （或者以后有人写别的花样）就会被**静默挪进守卫**那一拨，再被 <see cref="NegateRelicGuard"/>
    /// 取反、塞进 <c>if (…)</c> 条件里。注释是生成器自己加的说明文字，不该影响这个分类。
    /// </remarks>
    private static bool IsRelicGuardLine(string line)
    {
        string code = line;
        int comment = code.IndexOf("//", StringComparison.Ordinal);
        if (comment >= 0) code = code[..comment];
        return code.Contains("return;", StringComparison.Ordinal);
    }

    /// <summary>
    /// 把守卫行 <c>if (条件) return;</c> 取反成条件表达式（多条时机合并时用 —— 同一个钩子方法里
    /// 不能再用 <c>return</c>，否则第一条不成立就把后面的时机全跳过了）。
    ///
    /// 取反规则（必须**按运算符归类**做 De Morgan，不能只换 <c>!=</c> —— 那些 <c>&amp;&amp;</c> /
    /// <c>||</c> 连起来的复合条件只换一部分会**静默改掉语义**）：
    /// <code>
    /// !(A &amp;&amp; B) = !A || !B        !(A || B) = !A &amp;&amp; !B
    /// a != b  → a == b          a &lt;= b → a &gt; b
    /// a == b  → a != b          a &gt;= b → a &lt; b
    /// a &lt; b   → a &gt;= b          a &gt; b  → a &lt;= b
    /// x is Y  → x is not Y      x is not Y → x is Y
    /// x is null → x is not null （反过来同理）
    /// !x      → x（其余情况整个括起来取反）
    /// </code>
    /// 例子：<c>if (!participants.Contains(X) || TurnNumber &gt; 1) return;</c> →
    /// <c>participants.Contains(X) &amp;&amp; TurnNumber &lt;= 1</c>。
    /// </summary>
    internal static string NegateRelicGuard(string line)
    {
        string body = line;
        int at = body.IndexOf("return;", StringComparison.Ordinal);
        if (at > 0) body = body[..at];
        body = body.Trim();
        if (body.StartsWith("if (", StringComparison.Ordinal) && body.EndsWith(")", StringComparison.Ordinal))
            body = body[4..^1].Trim();
        return NegateConditionExpr(body);
    }

    /// <summary>
    /// 条件表达式取反（见 <see cref="NegateRelicGuard"/> 的规则表）。
    ///
    /// ⚠ 为什么比较运算符那一层要做「插在中间就整个括起来」：<c>x == y</c> 取反时把 <c>==</c> 换成
    /// <c>!=</c> 是对的，但 <c>a == !(b)</c> 这种（说明右侧本身已经是取反过的表达式）再换就成了
    /// <c>a != !(b)</c> —— 语法还合法但**语义完全错**（实测：`player == !(base.Owner)`）。
    /// 所以只有「两边都不是以 <c>!</c> 开头的原子表达式」才换运算符，其余一律整个括起来取反。
    /// </summary>
    internal static string NegateConditionExpr(string expr)
    {
        string s = expr.Trim();
        if (s.Length == 0) return "true";
        if (s.StartsWith("!(", StringComparison.Ordinal) && s.EndsWith(")", StringComparison.Ordinal)) return s[2..^1];
        if (s.StartsWith("!", StringComparison.Ordinal)) return s[1..].Trim();
        // 顶层 ||：!(A || B) = !A && !B
        var orParts = SplitTopLevel(s, "||");
        if (orParts.Count > 1)
            return string.Join(" && ", orParts.Select(NegateConditionExpr));
        // 顶层 &&：!(A && B) = !A || !B
        var andParts = SplitTopLevel(s, "&&");
        if (andParts.Count > 1)
            return string.Join(" || ", andParts.Select(NegateConditionExpr));
        // 比较：只有两边都不是 `!` 开头的表达式才换运算符
        foreach (var (op, not) in new[] { (" != ", " == "), (" == ", " != "), (" <= ", " > "), (" >= ", " < "),
                                         (" < ", " >= "), (" > ", " <= ") })
        {
            int i = s.IndexOf(op, StringComparison.Ordinal);
            if (i < 0) continue;
            string left = s[..i].Trim();
            string right = s[(i + op.Length)..].Trim();
            if (left.StartsWith("!", StringComparison.Ordinal) || right.StartsWith("!", StringComparison.Ordinal))
                return "!(" + s + ")";
            return left + not + right;
        }
        // is 模式
        if (s.EndsWith(" is null", StringComparison.Ordinal)) return s[..^" is null".Length] + " is not null";
        if (s.EndsWith(" is not null", StringComparison.Ordinal)) return s[..^" is not null".Length] + " is null";
        if (s.Contains(" is not ", StringComparison.Ordinal)) return s.Replace(" is not ", " is ", StringComparison.Ordinal);
        if (s.Contains(" is ", StringComparison.Ordinal)) return s.Replace(" is ", " is not ", StringComparison.Ordinal);
        return "!(" + s + ")";
    }

    /// <summary>
    /// 按**顶层**运算符切分（括号里的不算）：<c>a &amp;&amp; foo(b || c)</c> 按 <c>&amp;&amp;</c> 切 = 2 段。
    /// 自己数括号深度、找不到就返回单元素列表（调用方按「不是复合条件」处理）。
    /// </summary>
    private static List<string> SplitTopLevel(string expr, string op)
    {
        var parts = new List<string>();
        int depth = 0, start = 0;
        for (int i = 0; i < expr.Length; i++)
        {
            char c = expr[i];
            if (c == '(' || c == '[') depth++;
            else if (c == ')' || c == ']') depth--;
            else if (depth == 0 && i + op.Length <= expr.Length
                     && string.CompareOrdinal(expr, i, op, 0, op.Length) == 0)
            {
                parts.Add(expr[start..i]);
                i += op.Length - 1;
                start = i + 1;
            }
        }
        if (parts.Count == 0) return new List<string> { expr };
        parts.Add(expr[start..]);
        return parts;
    }

    /// <summary>给同一条钩子里重复出现的临时变量加后缀（`__takenThisAttack` → `__takenThisAttack1`）。</summary>
    private static string RenameRelicTempVars(string line, HashSet<string> names, int suffix)
    {
        if (names.Count == 0) return line;
        foreach (string name in names)
            line = Regex.Replace(line, $@"\b{Regex.Escape(name)}(?!\d)\b",
                name + suffix.ToString(System.Globalization.CultureInfo.InvariantCulture), RegexOptions.None);
        return line;
    }

    /// <summary>这一行里的「生成期临时变量」名字（`__` 开头，句点在名字里也算 —— `__takenThisAttack.s` 那种）。</summary>
    private static IEnumerable<string> RelicTempVars(string line) =>
        Regex.Matches(line, @"__[A-Za-z0-9_.]+").Select(m => m.Value.TrimEnd('.'));

    /// <summary>
    /// 遗物触发时机对应的**钩子方法名**（从 <see cref="RelicTriggerSignature"/> 的签名里取）。
    ///
    /// 用途：锻造遗物图上「图的【触发时机】和遗物自己的触发时机是同一个钩子」时要嵌进同一个方法
    /// （<see cref="ForgeGraphGen.RelicGraphNestsInTrigger"/>），否则一个类里会出现两个签名一样的
    /// override → CS0111，整个模组编译不过。签名文本是**唯一事实来源**，所以这里也从它推。
    /// </summary>
    internal static string RelicHookNameOf(string? triggerId)
    {
        string sig = RelicTriggerSignature(triggerId ?? "");
        int at = sig.IndexOf("Task ", StringComparison.Ordinal);
        if (at < 0) return "";
        int start = at + "Task ".Length;
        int paren = sig.IndexOf('(', start);
        return paren > start ? sig[start..paren] : "";
    }

    /// <summary>
    /// 遗物触发时机对应的钩子签名（**只有这一份**：RelicSource 和锻造节点图都用它，
    /// 免得两边写重了变成同一个类里两个同名方法 —— 那是 CS0111，整个模组编译不过）。
    /// </summary>
    public static string RelicTriggerSignature(string triggerId) => triggerId switch
    {
        // 获得时：本体「拾取时生效」的遗物钩子（YummyCookie / Claws / Whetstone…）
        "Obtained" => "public override async Task AfterObtained()",
        // 战斗开始时用 BeforeSideTurnStart（本体 BagOfMarbles 的做法：这个钩子带 choiceContext）
        "CombatStart" => "public override async Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)",
        "PlayerTurnStart" => "public override async Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)",
        "PlayerTurnEnd" => "public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)",
        "CombatVictory" => "public override async Task AfterCombatVictory(CombatRoom room)",
        // 战斗结束时（房间结算之前）：本体 AfterCombatEnd —— 比 AfterCombatVictory 早，
        // 跑在 room.OnCombatEnded() / 发奖励 / 存档 **之前**（见 CombatManager.EndCombatInternal 的顺序）。
        "CombatEnd" => "public override async Task AfterCombatEnd(CombatRoom room)",
        "DamageReceived" => "public override async Task AfterDamageReceived(PlayerChoiceContext choiceContext, Creature target, DamageResult result, ValueProp props, Creature? dealer, CardModel? cardSource)",
        // 受到攻击后：本体 AfterAttack（multi-attack 时它在所有命中结束后只跑一次 —— 见 AbstractModel 注释）。
        // AttackCommand 在 MegaCrit.Sts2.Core.Commands.Builders，而生成的 GlobalUsings 里没有那个命名空间
        //（卡牌代码只用到 DamageCmd），所以这里必须写全名，不然生成的工程 CS0246。
        "Attacked" => "public override async Task AfterAttack(PlayerChoiceContext choiceContext, MegaCrit.Sts2.Core.Commands.Builders.AttackCommand command)",
        "GoldGained" => "public override async Task AfterGoldGained(Player player)",
        // ===== 用户要求新增的五条 =====
        // 造成伤害时（每一下）：本体 AfterDamageGiven（和 DamageReceived 是同一对钩子，方向相反）
        "DamageDealt" => "public override async Task AfterDamageGiven(PlayerChoiceContext choiceContext, Creature? dealer, DamageResult result, ValueProp props, Creature target, CardModel? cardSource)",
        // 每消耗一个能量 / 每消耗一个额外资源量：这两个钩子**没有 choiceContext**
        //（本体签名就是 `AfterEnergySpent(CardModel card, int amount)` / `AfterStarsSpent(int amount, Player spender)`），
        // 需要 context 的效果由生成端自己造一个（见 BootstrapInCombat）。
        "EnergySpent" => "public override async Task AfterEnergySpent(CardModel card, int amount)",
        "StarsSpent" => "public override async Task AfterStarsSpent(int amount, Player spender)",
        // 生成卡牌时：本体 AfterCardGeneratedForCombat（玩家自己生成的牌才算，敌人塞的不算），同样没有 choiceContext
        "CardGenerated" => "public override async Task AfterCardGeneratedForCombat(CardModel card, Player? creator)",
        // 某个状态层数到达 N 层时（用户要求）：本体 AfterPowerAmountChanged —— 带 choiceContext
        "PowerReached" => "public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)",
        // ===== 用户要求「遗物 / 状态触发时机合并成同一套」：补齐状态那边有、遗物缺的那些 =====
        // V0.2.157：「打出一张牌时」= BeforeCardPlayed（**这张牌还没结算**，所以「打出它才施加的状态」
        // 不会被它自己触发）；「一张牌结算完毕时」= AfterCardPlayedLate（旧版的打出一张牌后）。
        "CardPlayed" => "public override async Task BeforeCardPlayed(CardPlay cardPlay)",
        "CardResolved" => "public override async Task AfterCardPlayedLate(PlayerChoiceContext choiceContext, CardPlay cardPlay)",
        "CardExhausted" => "public override async Task AfterCardExhausted(PlayerChoiceContext choiceContext, CardModel card, bool causedByEthereal)",
        "CardDrawn" => "public override async Task AfterCardDrawn(PlayerChoiceContext choiceContext, CardModel card, bool fromHandDraw)",
        "CardDiscarded" => "public override async Task AfterCardDiscarded(PlayerChoiceContext choiceContext, CardModel card)",
        "HpLost" => "public override async Task AfterCurrentHpChanged(Creature creature, decimal delta)",
        "BlockGained" => "public override async Task AfterBlockGained(Creature creature, decimal amount, ValueProp props, CardModel? cardSource)",
        "EnemyDeath" => "public override async Task AfterDeath(PlayerChoiceContext choiceContext, Creature creature, bool wasRemovalPrevented, float deathAnimLength)",
        "EnemyTurnStart" => "public override async Task AfterSideTurnStart(CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)",
        "EnemyTurnEnd" => "public override async Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)",
        "EnemyDamaged" => "public override async Task AfterDamageReceived(PlayerChoiceContext choiceContext, Creature target, DamageResult result, ValueProp props, Creature? dealer, CardModel? cardSource)",
        "EnemyDealtDamage" => "public override async Task AfterDamageGiven(PlayerChoiceContext choiceContext, Creature? dealer, DamageResult result, ValueProp props, Creature target, CardModel? cardSource)",
        "EnemyBlockGained" => "public override async Task AfterBlockGained(Creature creature, decimal amount, ValueProp props, CardModel? cardSource)",
        "PowerChanged" => "public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)",
        // 某个状态被移除时（用户要求）：本体**没有**任何全局的「状态被移除」钩子
        //（`PowerModel.AfterRemoved` 是那个状态自己的实例钩子，遗物收不到；`PowerCmd.Remove` 也不走层数变化那条路），
        // 所以这条不是 override，而是工具自己打补丁后调过来的一个普通方法（见 PowerRemovalSource）。
        "PowerRemoved" => $"public async Task {PowerRemovedMethod}(PowerModel power)",
        // 抽牌堆打乱洗牌时（本体先古遗物「大～抱抱 BiiigHug」就是这条）：参数名必须是 shuffler，
        // 生成的效果体会先判 `if (shuffler != base.Owner) return;`（只看自己洗的牌）。
        "Shuffle" => "public override async Task AfterShuffle(PlayerChoiceContext choiceContext, Player shuffler)",
        _ => "public override async Task BeforeCombatStart()",
    };

    /// <summary>遗物图要嵌进那个触发钩子时，用的方法名（和 <see cref="RelicTriggerSignature"/> 配套）。</summary>
    public const string ForgeRelicGraphMethod = "ForgeGraphOnTrigger";

    /// <summary>
    /// 「某个状态被移除时」在遗物 / 状态类里那个方法名（工具补丁补丁通知过来调用它，见 <see cref="PowerRemovalSource"/>）。
    /// 遗物侧写 <c>public async Task OnForgePowerRemovedAsync(PowerModel power)</c>；状态侧一样（但 base.Owner 是 Creature）。
    /// </summary>
    public const string PowerRemovedMethod = "OnForgePowerRemovedAsync";

    /// <summary>该触发时机的钩子是否带 choiceContext。</summary>
    public static bool HasContext(string triggerId) =>        triggerId is "CombatStart" or "PlayerTurnStart" or "PlayerTurnEnd" or "DamageReceived" or "Shuffle" or "Attacked" or "DamageDealt" or "PowerReached"
        // 用户要求合并触发时机后补上的这批（带 choiceContext 的那些）
        or "CardExhausted" or "CardDrawn" or "CardDiscarded" or "EnemyDeath"
        or "EnemyTurnEnd" or "EnemyDamaged" or "EnemyDealtDamage" or "PowerChanged"
        // V0.2.157：「打出一张牌时」的钩子 BeforeCardPlayed **不带** choiceContext，所以要造一个；
        // 「一张牌结算完毕时」（AfterCardPlayedLate）带 ✓
        or "CardResolved";

    /// <summary>
    /// 这一条触发时机的钩子**在战斗里但没有 choiceContext**，需要时生成端按本体 <c>Hook.cs</c> 的做法
    /// 自己造一个 <c>HookPlayerChoiceContext</c>（不能照「获得时」那样用 <c>BlockingPlayerChoiceContext</c> ——
    /// 那是局外的阻塞式上下文，战斗里用它会卡住）。本体派发钩子时造的就是前者：
    /// <c>new HookPlayerChoiceContext(model, netId, combatState, GameActionType.Combat)</c>。
    /// </summary>
    public static bool BootstrapInCombat(string triggerId) =>
        triggerId is "EnergySpent" or "StarsSpent" or "CardGenerated"
        // 合并触发时机后补上的这批（本体同样没给 choiceContext）
        or "HpLost" or "BlockGained" or "EnemyTurnStart" or "EnemyBlockGained"
        // V0.2.157：「打出一张牌时」= BeforeCardPlayed(CardPlay)，本体签名里没有 choiceContext
        or "CardPlayed"
        // 「某个状态被移除时」是工具补丁调过来的，也没有 choiceContext（战斗里 → HookPlayerChoiceContext）
        or "PowerRemoved";

    /// <summary>
    /// 「每消耗一个能量 / 每消耗一个额外资源量」的钩子参数 <c>amount</c> 是**这一张牌一共花的点数**，
    /// 所以「每消耗一个」要按点数各触发一次（本体 OrbitPower 也是按点数累加的）。
    /// </summary>
    public static bool PerPointTrigger(string triggerId) => triggerId is "EnergySpent" or "StarsSpent";

    /// <summary>
    /// 「获得时」（<c>AfterObtained()</c>）的签名里**没有** choiceContext，但本体允许在遗物获得时做需要它的操作
    /// （本体「好吃饼干 YummyCookie」在获得时让玩家升级牌、「爪子 Claws」在获得时让玩家选牌变化）。
    /// 生成端会自己造一个阻塞式 context —— 本体的 <c>BlockingPlayerChoiceContext</c> 注释里点名的第一个场景
    /// 就是 "Relic AfterObtained callbacks"。所以这条触发时机不算「没有 context」。
    /// </summary>
    public static bool CanBootstrapContext(string triggerId) => triggerId == "Obtained";

    /// <summary>
    /// 这条效果在**遗物**上会不会用到 choiceContext（决定「获得时」要不要自己造一个）。
    /// 拿不准就返回 true：多造一个没用上的局部变量最多是个编译警告，少造一个是编译错误（CS0103）。
    /// </summary>
    public static bool RelicNeedsChoiceContext(EffectSpec e) => e.Kind switch
    {
        "Block" or "Energy" or "ExtraResource" => e.NextTurn,
        "Heal" or "MaxHp" => e.Amount < 0,
        "Draw" or "Damage" or "HpLoss" or "EndTurn" or "ExtraTurn" or "GenerateCard" or "ExhaustCard"
            or "DiscardCard" or "UpgradeCard" or "Scry" or "TransformCard" or "TakeFromDraw" or "TakeFromDiscard"
            or "ApplyPower" or "TempPower" or "SummonPet" or "CardReward" or "GiveKeyword" or "BoostCard" => true,
        // 转化为先古卡：改牌组 + 弹预览界面，按「拿不准就 true」的规矩算需要（漏了会让「获得时」不造
        // 阻塞式 context → 生成出来只有一行「已忽略」，用户实测踩过这条）。
        "AncientTranscend" => true,
        _ => false,
    };

    private static void EmitRelicEffect(CodeWriter w, CharacterProfile p, EffectSpec e, bool hasContext,
        Dictionary<EffectSpec, string>? varMap = null, string? roomVar = null, string? petAllGroup = null,
        int relicEffectIndex = 0)
    {
        if (IsInertZero(e)) return;   // 数值 0：整条丢掉（用户要求：不显示、也不执行）
        // V0.2.164：遗物上也能写「数值公式」了 —— 同样写一行标记，「从工程恢复存档」按它认回来
        if (e.UsesAmountFormula) w.Line($"// CET:AmountFormula={EscapeMarker(e.AmountFormula)}");
        EmitRepeated(w, e, x => EmitRelicEffectOnce(x, p, e, hasContext, varMap, roomVar, petAllGroup, relicEffectIndex));
    }

    private static void EmitRelicEffectOnce(CodeWriter w, CharacterProfile p, EffectSpec e, bool hasContext,
        Dictionary<EffectSpec, string>? varMap = null, string? roomVar = null, string? petAllGroup = null,
        int relicEffectIndex = 0)
    {
        // 「下回合生效」的新支持种类（V0.2.133）：遗物链也接上（老存档里这些种类勾不上，见别处说明）。
        if (UsesDelayedEffectBranch(e))
        {
            EmitDelayedPowerApply(w, p, e, "base.Owner.Creature", "base.Owner.Creature");
            return;
        }
        // V0.2.164：「数值公式」在这条链上是**全内联**求值（遗物的 Owner 是 Player，
        // 「自己」= base.Owner.Creature；没有「玩家选中的目标」→「指定敌人」取可打的第一个敌人）
        string amt = InlineAmountFormula(p, e, "base.Owner", "base.Owner.Creature", FirstEnemyOf("base.Owner"))
                     ?? VarAccess(e, varMap);
        string blockAmt = InlineAmountFormula(p, e, "base.Owner", "base.Owner.Creature", FirstEnemyOf("base.Owner"))
                          ?? BlockValueAccess(varMap, e);
        // 「直接把缓慢设成 N%」：本体做法是只施加 1 层（层数对「缓慢」没有作用），amount 为 0 时本体直接不挂状态
        if (IsSlowPercentEffect(e)) amt = "1m";
        switch (e.Kind)
        {
            case "EndTurn":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，结束回合无法实现）"); break; }
                w.Line("PlayerCmd.EndTurn(base.Owner, canBackOut: false);");
                break;

            case "ExtraTurn":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，额外回合无法实现）"); break; }
                w.Line($"await PowerCmd.Apply<{Naming.From(p).ExtraTurnPowerClass}>(choiceContext, base.Owner.Creature, 1m, base.Owner.Creature, null);");
                break;

            // 播放音效（V0.2.154）：SfxCmd 是静态的，不需要 choiceContext / 目标，遗物上直接放
            case "PlaySfx":
                EmitPlaySfx(w, e);
                break;

            // 播放上传的音频文件（V0.2.155）：Godot AudioStreamPlayer，同样不需要 choiceContext / 目标
            case "PlaySoundFile":
                EmitPlaySoundFile(w, e);
                break;

            case "GenerateCard":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，生成卡牌无法实现）"); break; }
                EmitGenerateCard(w, p, e, tempUpSource: "null");
                break;

            // 获得药水（需求 ⑨）：本体 TryToProcure 不收 choiceContext，所以没有 choiceContext 的
            // 触发时机（遗物「获得时 / 战斗胜利时」）照样能用 —— 这里**不加** hasContext 的判断。
            case "GainPotion":
                EmitGainPotion(w, e);
                break;

            case "ExhaustCard":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，消耗卡牌无法实现）"); break; }
                EmitExhaustCard(w, p, e);
                break;

            case "DiscardCard":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，丢弃卡牌无法实现）"); break; }
                EmitDiscardCard(w, p, e);
                break;

            case "UpgradeCard":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，升级卡牌无法实现）"); break; }
                EmitUpgradeCard(w, p, e);
                break;

            case "Scry":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，预见无法实现）"); break; }
                EmitScry(w, p, e);
                break;

            case "ScrapeDraw":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，刮削抽不了牌）"); break; }
                EmitScrapeDraw(w, p, e, Lit.Dec(e.Amount));
                break;

            case "FillHand":
                if (!hasContext) { Warn(w, e, "（该触发时机不在战斗里，填满手牌无法实现）"); break; }
                EmitFillHand(w, e);
                break;

            case "CheapenDraw":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，施加不了「抽到就减费」状态）"); break; }
                w.Line(SelfContainedMarker(e));
                w.Line(ApplyPowerLine(e, useX: false, Naming.From(p).DrawCostPowerClass, "base.Owner.Creature",
                    Math.Abs((int)e.Amount).ToString(), "base.Owner.Creature", cardSourceExpr: "null") + "   // 抽到就减费");
                break;

            // 毒性爆发：只要拿到玩家和敌人列表就行（本体 PoisonPower 那一下伤害 dealer 是 null）
            case "Outbreak":
                EmitOutbreak(w, e, Lit.Dec(e.Amount), "null");
                break;

            case "TransformCard":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，变化卡牌无法实现）"); break; }
                // 这里**故意不传 profile**：传了会顺带改掉「按范围随机变化 + 范围限定 = 自定义关键词那一组」
                // 的候选池表达式（p 为 null 时那一组查不出来、现在生成的是空表），
                // 而需求 ⑦ 的硬要求是「没选关键词时生成代码逐字不变」。需求 ⑦ 要用的自定义关键词
                // 解析在这条链上退回 KeywordGen.NormalizeKeyText（界面下拉存的**就是键**，所以够用；
                // 手改存档写成中文名的话这一项会打印一行「没认出来」的说明）。
                EmitTransformCard(w, e, cardSource: "null");
                break;

            case "TakeFromDraw":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，从抽牌堆拿牌无法实现）"); break; }
                EmitTakeFromPile(w, p, e, "Draw");
                break;

            case "TakeFromDiscard":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，从弃牌堆拿牌无法实现）"); break; }
                EmitTakeFromPile(w, p, e, "Discard");
                break;

            // 从消耗牌堆拿牌到手牌：消耗牌堆同样是战斗牌堆（PileType.IsCombatPile() 认它），
            // 和另外两摞走同一个本体 API —— 卡牌 / 药水上早就有，「遗物触发」这一档也补上（需求 ③：三个上下文都要接）
            case "TakeFromExhaust":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，从消耗牌堆拿牌无法实现）"); break; }
                EmitTakeFromPile(w, p, e, "Exhaust");
                break;

            // 放置卡牌：遗物上没有「这张牌自己」这一说 → 数值 0 由生成端说清（数值 ≥ 1 挑牌照常）
            case "PlaceCard":
                if (!hasContext)
                {
                    Warn(w, e, "（该触发时机没有 choiceContext，放置卡牌里「自己选」那一路用不了 —— 请改成「随机」/「牌顶」或用卡牌 / 药水）");
                    break;
                }
                EmitPlaceCard(w, p, e, selfExpr: null, cardSource: null);
                break;

            // 复制卡牌：**只能用在卡牌 / 药水上**。遗物没有「战斗里选牌」的时机
            // （本体 CreateClone 要求原牌在战斗牌堆里，遗物获得时多半不在战斗里），所以不静默丢掉。
            case "CopyCard":
                Warn(w, e, "（「复制卡牌」需要在战斗里从手牌 / 抽牌堆 / 弃牌堆 / 消耗牌堆选牌，遗物上用不了 —— 请改用卡牌或药水）");
                break;

            // 重放卡牌：遗物可以（「每回合让手里的一张牌重放一次」这类很常见），选牌走本体接口
            case "ReplayCard":
                EmitReplayCard(w, p, e);
                break;

            // 回合结束时自动打出：遗物上只能填 1 以上（数值 0 = 这张牌自己，遗物没有「自己这张牌」）
            case "TurnEndPlay":
                EmitTurnEndPlay(w, e, p, selfExpr: null, cardSource: "null");
                break;

            // 全局（牌组）类效果不需要 choiceContext，只要拿到 Player 就行（遗物的 base.Owner 就是 Player）
            case "AddCardGlobal":
            case "TransformCardGlobal":
            case "RemoveCardGlobal":
            case "UpgradeCardGlobal":
                EmitGlobalCardEffect(w, e, "base.Owner", p: p);
                break;

                case "CardReward":
                    EmitCardReward(w, e, "base.Owner", roomVar: roomVar);
                    break;

            case "Damage":
                if (!hasContext) { Warn(w, e); break; }
                // 「生成调试日志」（V0.2.142，默认关）：目标 + 实际数值
                DebugLogGen.Target(w, e, RelicAttackTargetExpr(e), amt, inLoop: IsMultiTargetSide(e));
                if (e.TargetSide == "Self")
                    // 「对自己造成伤害」= **格挡能挡**、不被力量/易伤放大。
                    // 遗物/自定义状态这类**非卡牌来源**用本体 DamageProps.nonCardUnpowered（Unpowered），
                    // 卡牌那条用 cardUnpowered（Unpowered | Move）—— 两个常量都**没有** Unblockable。
                    // （以前这里写的是 Unblockable|Unpowered|Move = DamageProps.cardHpLoss，
                    //   和「失去生命」一模一样，于是护盾一格都吃不到 —— 用户报的就是这个。）
                    w.Line($"await CreatureCmd.Damage(choiceContext, base.Owner.Creature, {amt}, ValueProp.Unpowered, null, null);");
                else if (e.TargetSide == "AllUnits")
                    // 全体单位（V0.2.132）：两边所有存活单位（含自己 / 队友 / 召唤物 / 敌人）
                    w.Open(AllUnitsGuardLine)
                     .Line($"await CreatureCmd.Damage(choiceContext, base.Owner.Creature.CombatState.Creatures.Where(c => c.IsAlive).ToList(), {amt}, ValueProp.Move, base.Owner.Creature);")
                     .Close();
                else
                    w.Line($"await CreatureCmd.Damage(choiceContext, base.Owner.Creature.CombatState.HittableEnemies, {amt}, ValueProp.Move, base.Owner.Creature);");
                break;

            // 「战斗开始时召唤伙伴」= 本体 Byrdpip 那个遗物的写法（遗物里召唤宠物是官方支持的路子）。
            // 不过本体的钩子只有「战斗开始 / 每回合开始 / 每回合结束 / 受到伤害」这四个带 choiceContext，
            // 「战斗胜利 / 获得金币」那两个钩子拿不到 context（宠物召唤要它），所以那两种时机上只能忽略。
            case "SummonPet":
                if (!hasContext)
                {
                    Warn(w, e, "（该触发时机没有 choiceContext，召唤伙伴无法实现；"
                        + "想要「战斗开始时召唤伙伴」请把遗物的触发时机改成「战斗开始时」）");
                    break;
                }
                // 「全部召唤物」：逐只展开（和卡牌一样），回读靠 CET:PetAll 标记合并回一条
                if (PetGen.IsAll(e.PetSummon))
                {
                    var sumDefs = PetGen.ResolveMany(p, e.PetSummon);
                    if (sumDefs.Count == 0) { EmitSummonPet(w, e, p, amt, useX: false); break; }
                    w.Line($"// 【全部召唤物】这一条对 {sumDefs.Count} 只各来一遍："
                        + string.Join("、", sumDefs.Select(d => d.DisplayName)));
                    foreach (var d in sumDefs)
                        EmitSummonPet(w, e, p, amt, useX: false,
                            extraComment: petAllGroup is null ? null : "// CET:PetAll=" + petAllGroup, petDef: d);
                    break;
                }
                EmitSummonPet(w, e, p, amt, useX: false);
                break;

            // 「伙伴攻击」只能用在卡牌上：遗物没有「玩家选中的目标」，宠物该打谁说不清，所以不静默丢掉。
            // 新增的那批宠物效果（治疗/失去生命/最大生命/牺牲/施加状态/守卫开关）技术上只要拿到 Player
            // 就能做，但**本档只支持卡牌**（用户要求宠物类效果这一档只做卡牌）—— 一并给一句说明，不静默丢。
            case "PetAttack":
            case "PetDamageByMaxHp":
            case "PetDamageByCurHp":
            case "PetDamageByMissingHp":
            case "PetHeal":
            case "PetLoseHp":
            case "PetGainMaxHp":
            case "PetSacrifice":
            case "PetApplyPower":
            case "PetGuardOn":
            case "PetGuardOff":
                Warn(w, e, "（遗物没有「玩家选中的目标」，而且这一档的宠物效果只支持卡牌 —— 请把它放到卡牌上）");
                break;

            case "Block":
                // 「生成调试日志」（V0.2.142，默认关）：目标 + 实际用的格挡值
                DebugLogGen.Target(w, e, RelicAttackTargetExpr(e),
                    IsNegativeAmount(e, useX: false) ? AbsExpr(amt) : blockAmt, inLoop: IsMultiTargetSide(e));
                if (IsNegativeAmount(e, useX: false))
                    // 负数 = 失去 N 点格挡（本体 GainBlock 对非正数什么都不做，得走 LoseBlock；
                    // remover 传我们这边，本体用它记「谁削掉的」）
                    EmitPerCreature(w, e, useX: false, "base.Owner.Creature", "cardPlay.Target", "base.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.LoseBlock(choiceContext, {c}, {AbsExpr(amt)}, base.Owner.Creature);   // 负数 = 失去格挡");
                else if (e.NextTurn)
                {
                    if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，「下回合格挡」无法实现）"); break; }
                    w.Line($"await PowerCmd.Apply<BlockNextTurnPower>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                }
                else
                {
                    // Anchor 的写法：不带 context 也能给格挡
                    EmitPerCreature(w, e, useX: false, "base.Owner.Creature", null, "base.Owner.Creature.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.GainBlock({c}, {blockAmt}, ValueProp.Move, null);");
                }
                break;

            case "Draw":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，抽牌无法实现）"); break; }
                if (e.NextTurn)
                    w.Line($"await PowerCmd.Apply<DrawCardsNextTurnPower>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                else
                    w.Line($"await CardPileCmd.Draw(choiceContext, {amt}, base.Owner);");
                break;

            case "Energy":
                if (e.NextTurn)
                {
                    // 下回合生效：负数（下回合少 N 点）用生成的负债 Power —— 本体 EnergyNextTurnPower 忽略负数
                    if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，「下回合生效」的能量无法实现）"); break; }
                    w.Line(IsNegativeAmount(e, useX: false)
                        ? $"await PowerCmd.Apply<{Naming.From(p).EnergyNextTurnDebtPowerClass}>(choiceContext, base.Owner.Creature, {AbsExpr(amt)}, base.Owner.Creature, null);   // 下回合少 N 点能量"
                        : $"await PowerCmd.Apply<EnergyNextTurnPower>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                }
                else
                    w.Line(GainEnergyLine(e, amt, useX: false, "base.Owner"));
                break;

            case "Heal":
                DebugLogGen.Target(w, e, RelicAttackTargetExpr(e),
                    e.Amount < 0 ? Lit.Dec(-e.Amount) : amt, inLoop: IsMultiTargetSide(e));
                if (e.Amount < 0)
                {
                    if (!hasContext) { Warn(w, e); break; }
                    EmitPerCreature(w, e, useX: false, "base.Owner.Creature", null, "base.Owner.Creature.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.Damage(choiceContext, {c}, {-e.Amount}, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move, null, null);");
                }
                else
                    EmitPerCreature(w, e, useX: false, "base.Owner.Creature", null, "base.Owner.Creature.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.Heal({c}, {amt});");
                break;

            case "HpLoss":
                if (!hasContext) { Warn(w, e); break; }
                DebugLogGen.Target(w, e, RelicAttackTargetExpr(e), amt, inLoop: IsMultiTargetSide(e));
                EmitPerCreature(w, e, useX: false, "base.Owner.Creature", null, "base.Owner.Creature.CombatState.HittableEnemies",
                    c => $"await CreatureCmd.Damage(choiceContext, {c}, {amt}, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move, null, null);");
                break;

            case "MaxHp":
                DebugLogGen.Target(w, e, RelicAttackTargetExpr(e),
                    e.Amount < 0 ? Lit.Dec(-e.Amount) : amt, inLoop: IsMultiTargetSide(e));
                if (e.Amount < 0)
                {
                    if (!hasContext) { Warn(w, e); break; }
                    EmitPerCreature(w, e, useX: false, "base.Owner.Creature", null, "base.Owner.Creature.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.LoseMaxHp(choiceContext, {c}, {-e.Amount}, isFromCard: false);");
                }
                else
                    EmitPerCreature(w, e, useX: false, "base.Owner.Creature", null, "base.Owner.Creature.CombatState.HittableEnemies",
                        c => $"await CreatureCmd.GainMaxHp({c}, {amt});");
                break;

            case "Gold":
                w.Line(GainGoldLine(e, amt, useX: false, "base.Owner"));
                break;

            case "ExtraResource":
                // 额外资源量 = 本体的星星资源。遗物/药水没有「费用」概念，负数直接扣（不会扣成负数）。
                // 这里用字面量而不是 DynamicVar：ExtraResource 不声明变量，访问 DynamicVars 会抛 KeyNotFoundException。
                // 下回合生效：正数走本体的 StarNextTurnPower（它的 GainStars 拒绝负数）。
                if (e.NextTurn && e.Amount > 0)
                    w.Line($"await PowerCmd.Apply<StarNextTurnPower>(choiceContext, base.Owner.Creature, {Lit.Dec(e.Amount)}, base.Owner.Creature, null);   // 下回合开始时获得 {Lit.Dec(e.Amount)} 点额外资源量");
                else if (e.Amount >= 0)
                    w.Line($"await PlayerCmd.GainStars({Lit.Dec(e.Amount)}, base.Owner);");
                else
                    w.Line($"await PlayerCmd.SetStars(System.Math.Max(0m, (decimal)base.Owner.PlayerCombatState.Stars - {Lit.Dec(-e.Amount)}), base.Owner);");
                break;

            case "ApplyPower":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，施加增益/减益无法实现）"); break; }
                if (e.NextTurn)
                    w.Line($"await PowerCmd.Apply<{DelayedPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                else if (e.TargetSide == "Self")
                {
                    w.Line(ApplyPowerInstr(e, useX: false, e.PowerId, "base.Owner.Creature", amt, "base.Owner.Creature", cardSourceExpr: "null"));
                    EmitSlowPercentFix(w, e, "base.Owner.Creature");
                }
                else if (e.TargetSide == "RandomEnemies")
                {
                    // 用户报过：「对 1 个随机敌人施加增益」在遗物上变成了**对所有敌人** ——
                    // 因为以前这里不分目标，一律走「对所有敌人」那条重载。现在按目标分别生成。
                    w.Line($"List<Creature> foes = base.Owner.Creature.CombatState.HittableEnemies.ToList();")
                     .Open($"for (int __relFoeIdx = 0; __relFoeIdx < {RepeatExpr(e, useX: false)} && foes.Count > 0; __relFoeIdx++)")
                     .Line("Creature foe = base.Owner.RunState.Rng.CombatTargets.NextItem(foes);");
                    if (!e.AllowDuplicates) w.Line("foes.Remove(foe);");
                    w.Line(ApplyPowerInstr(e, useX: false, e.PowerId, "foe", amt, "base.Owner.Creature", cardSourceExpr: "null"));
                    EmitSlowPercentFix(w, e, "foe");     // 在循环里（foe 的作用域内），不能拿到循环外面
                    w.Close();
                }
                else if (e.TargetSide == "AllEnemies")
                {
                    w.Line(ApplyPowerInstr(e, useX: false, e.PowerId, "base.Owner.Creature.CombatState.HittableEnemies", amt, "base.Owner.Creature", cardSourceExpr: "null"));
                    // 一次性对全体施加（上面那条重载），这里逐个补百分比
                    EmitSlowPercentFixForAll(w, e);
                }
                else if (e.TargetSide == "AllUnits")
                {
                    // 全体单位（V0.2.132）：两边所有存活单位，各施加一份
                    w.Open(AllUnitsGuardLine)
                     .Open(AllUnitsForeachLine)
                     .Line(ApplyPowerInstr(e, useX: false, e.PowerId, "unit", amt, "base.Owner.Creature", cardSourceExpr: "null"));
                    EmitSlowPercentFix(w, e, "unit");
                    w.Close()
                     .Close();
                }
                else
                {
                    // 「指定敌人」：遗物没有「玩家选中的目标」→ 取可打的第一个敌人（和其它效果同一套约定）
                    w.Line("Creature? foe = base.Owner.Creature.CombatState.HittableEnemies.FirstOrDefault();")
                     .Open("if (foe is not null)")
                     .Line(ApplyPowerInstr(e, useX: false, e.PowerId, "foe", amt, "base.Owner.Creature", cardSourceExpr: "null"));
                    EmitSlowPercentFix(w, e, "foe");
                    w.Close();
                }
                break;

            // 击晕：本体不是状态而是怪物意图（CreatureCmd.Stun），遗物也能用
            case "Stun":
                EmitStun(w, e, useX: false, cardTargetExpr: null,
                    enemiesExpr: "base.Owner.Creature.CombatState.HittableEnemies", playerExpr: "base.Owner");
                break;

            // 临时增益：遗物也能给（本回合 +X，回合结束撤掉）
            case "TempPower":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，临时增益无法实现）"); break; }
                // 「生成调试日志」（V0.2.142，默认关）：目标 + 实际施加的层数
                DebugLogGen.Target(w, e, RelicAttackTargetExpr(e), amt, inLoop: IsMultiTargetSide(e));
                if (e.TargetSide == "Self")
                    w.Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                else if (e.TargetSide == "RandomEnemies")
                {
                    // 同上：随机 N 个不能变成「全体」
                    w.Line($"List<Creature> foes = base.Owner.Creature.CombatState.HittableEnemies.ToList();")
                     .Open($"for (int __relTempIdx = 0; __relTempIdx < {RepeatExpr(e, useX: false)} && foes.Count > 0; __relTempIdx++)")
                     .Line("Creature foe = base.Owner.RunState.Rng.CombatTargets.NextItem(foes);");
                    if (!e.AllowDuplicates) w.Line("foes.Remove(foe);");
                    w.Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, foe, {amt}, base.Owner.Creature, null);")
                     .Close();
                }
                else if (e.TargetSide == "AllEnemies")
                    w.Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, base.Owner.Creature.CombatState.HittableEnemies, {amt}, base.Owner.Creature, null);");
                else if (e.TargetSide == "AllUnits")
                {
                    // 全体单位（V0.2.132）：两边所有存活单位，各打一份临时状态
                    w.Open(AllUnitsGuardLine)
                     .Open(AllUnitsForeachLine)
                     .Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, unit, {amt}, base.Owner.Creature, null);")
                     .Close()
                     .Close();
                }
                else
                {
                    w.Line("Creature? foe = base.Owner.Creature.CombatState.HittableEnemies.FirstOrDefault();")
                     .Open("if (foe is not null)")
                     .Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, foe, {amt}, base.Owner.Creature, null);")
                     .Close();
                }
                break;

            // 给予卡牌关键词：遗物也能给（数值 0 在这里没有意义 —— 遗物不是一张牌）
            case "GiveKeyword":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，给予关键词无法实现）"); break; }
                EmitGiveKeyword(w, p, e, useX: false, "base.Owner", "base.Owner.Creature", "null", selfAllowed: false);
                break;

            // 强化指定卡牌：遗物也能挂（挂在自己身上，只给那一张卡加伤害 / 格挡）
            case "BoostCard":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，强化指定卡牌无法实现）"); break; }
                w.Line(BoostMarker(e));
                w.Line($"await PowerCmd.Apply<{BoostPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                break;

            // 转化为先古卡（用户要求）：只在「获得时」有意义（那时牌组才是稳定的），校验器也这么拦。
            case "AncientTranscend":
                if (!hasContext) { Warn(w, e, "（该触发时机没有 choiceContext，转化为先古卡无法实现）"); break; }
                EmitAncientTranscend(w, p, e, relicEffectIndex);
                break;

            // 转化为先古遗物（用户要求：「先古遗物的替换遗物」）：本体欧洛巴斯之触那条路。
            case "AncientRelicSwap":
                EmitAncientRelicSwap(w, p, e);
                break;

            // ===== 兜底：这个效果种类在遗物上没做 =====
            // 为什么**必须**有 default（问题②）：这个 switch 以前没有 default，卡牌那个大 switch
            // （EmitCardEffectOnce）实现了、遗物这条链没实现的那批种类落在这里会**什么都不生成、也不报错**
            // —— 用户以为配上了，实际那条效果在模组里一行代码都不存在。
            // 现在「效果种类」下拉是所有上下文共用同一份 EffectCatalog.EffectKinds（界面不按上下文过滤），
            // 所以用户真的能在遗物上选到它们；和上面「复制卡牌 / 宠物类」那几条显式 Warn 同一个风格：
            // 生成里留一行看得见的注释，ProfileValidator 再在**生成前**把这几条拦下来（IsCardOnlyKind）。
            default:
                WarnUnsupportedKind(w, e, "遗物");
                break;
        }
    }

    private static void Warn(CodeWriter w, EffectSpec e, string extra = "") =>
        w.Line($"// 该触发时机不支持「{EffectCatalog.FindKind(e.Kind).Display}」{extra}，已忽略。");

    /// <summary>
    /// 遗物 / 药水的 switch 落到 <c>default</c> 时写的那行告警注释。
    ///
    /// 为什么单独写一个而不是复用 <see cref="Warn"/>：<c>Warn</c> 的话术是「该**触发时机**不支持」，
    /// 而这里和触发时机无关 —— 是这个**效果种类**在遗物 / 药水这条链上根本没实现（只做在卡牌上）。
    /// 说错原因会把用户引到改触发时机上去。
    ///
    /// 为什么级别要「显眼」：这两条链以前静默落空（switch 没有 default），用户配完看不到任何反馈；
    /// 光靠注释不够，所以 ProfileValidator 里还有一条专门的校验（见 IsCardOnlyKind：整只遗物 / 整瓶药水
    /// 的效果全是这类种类时给**错误** = 生成出来是个空壳，只是其中一条时给**警告**）。
    /// </summary>
    private static void WarnUnsupportedKind(CodeWriter w, EffectSpec e, string where) =>
        w.Line($"// ⚠⚠ 该效果种类在{where}上**没有实现**（只做在卡牌上）：「{EffectCatalog.FindKind(e.Kind).Display}」"
            + "本次**一行代码都没生成**（以前是静默跳过）。请把它放到卡牌的效果里，或者删掉这条。");

    // ==================== 药水 ====================
    public static string PotionSource(CharacterProfile p, PotionSpec s, int index)
    {
        var n = Naming.From(p);
        string cls = n.PotionClassName(s, index);
        // 「生成调试日志」（V0.2.142）用的临时变量序号：每次生成一个源文件从头开始
        DebugLogGen.Reset();

        var w = new CodeWriter();
        w.Line("// <auto-generated> 自定义药水 </auto-generated>");
        if (s.HasCustomDescription)
            w.Line($"// CET:CustomDescReplace={(s.CustomDescriptionReplaces ? 1 : 0)} CET:CustomDescription={EscapeMarker(s.CustomDescription)}");
        w.Line($"namespace {n.Namespace};")
         .Line()
         .Open($"public sealed class {cls} : PotionModel")
         .Line($"public override PotionRarity Rarity => PotionRarity.{s.Rarity};")
         .Line()
         .Line($"public override PotionUsage Usage => PotionUsage.{s.Usage};")
         .Line()
         .Line($"public override TargetType TargetType => TargetType.{s.TargetType};")
         .Line()
         .Line("protected override IEnumerable<DynamicVar> CanonicalVars =>")
         .Line("[");
        var potionVars = VarNamesOf(s.Effects);
        foreach (var e in s.Effects.Where(x => !HasNoDynamicVar(x))) w.Line($"    {VarDeclaration(e, potionVars, p)},");
        w.Line("];")
         .Line();

        // 鼠标悬停药水描述里的状态 → 弹出那条说明（药水的 ExtraHoverTips 基类是 public）
        // V0.2.164：药水上写了「数值公式」时，顺带把悬停数字的现算挂上去（见 FormulaPreviewRefreshMethod）
        bool potionFormulaPreview = s.Effects.Any(x => x is not null
            && x.UsesAmountFormula && FormulaVarClassOf(x.Kind) is not null);
        w.Raw(FormulaPreviewRefreshMethod(p, s.Effects, potionVars, "base.Owner", "base.Owner.Creature"));
        w.Raw(HoverTipsOverride(s.Effects, isPublic: true, owner: p, refreshFormulaPreview: potionFormulaPreview));

        // OnUse 只能有一个 override：
        //   · 节点图里有「药水被使用时」那一支 → 由 ForgeGraphGen.PotionHooks 生成 OnUse
        //     （那时**不能**再写下面这个空骨架，否则两个签名一样的 override → CS0111，
        //      用户实测的构建日志就是这条：cs\Potions\SparklePotion8.cs(21,35) error CS0111）；
        //   · 没有那一支 → 照旧写骨架，里面跑药水自己的效果列表。
        if (!ForgeGraphGen.HasUseTiming(s))
        {
            w.Line()
             .Open("protected override async Task OnUse(PlayerChoiceContext choiceContext, Creature? target)");

            // 「生成调试日志」（V0.2.142，默认关）：这一段的效果都属于「这瓶药水」
            using (DebugLogGen.Begin(p, "药水", s.Name, cls, "base.Owner.Creature"))
            foreach (var e in s.Effects) EmitPotionEffect(w, p, e, s.TargetType, potionVars);

            w.Close();
        }
        // 锻造节点图：图非空时把它的钩子附加在类末尾（空图 = 一个字符都不写）
        if (ForgeGraphGen.UsesGraph(s))
        {
            string fields = ForgeGraphGen.TimingFields(p, s);
            if (fields.Length > 0) w.Raw(fields);
            string hooks = ForgeGraphGen.PotionHooks(p, s);
            if (hooks.Length > 0) w.Raw(hooks);
        }
        w.Close();
        return w.ToString();
    }

    /// <summary>是否有配置用到「额外获得一回合」。</summary>
    public static bool UsesExtraTurn(CharacterProfile p) => UsesKind(p, "ExtraTurn");

    // ==================== 给予卡牌关键词 ====================

    /// <summary>
    /// 「击晕」的代码（卡牌 / 遗物 / 药水 / 自定义状态触发器共用）。
    /// 本体里「击晕」**不是状态**，而是怪物意图 —— 公开 API 就一句
    /// <c>CreatureCmd.Stun(creature)</c>（本体卡「口哨 Whistle」用的就是它，不需要 choiceContext）。
    /// 所以它不能放进「增益 / 减益」那个下拉里（那里面全是 PowerModel）。
    /// </summary>
    /// <param name="cardTargetExpr">卡牌「指定敌人」的表达式（cardPlay.Target）；遗物 / 药水没有就传 null。</param>
    /// <param name="enemiesExpr">「所有敌人」的表达式。</param>
    /// <param name="playerExpr">玩家表达式（随机挑敌人时取 RNG 用）。</param>
    internal static void EmitStunPublic(CodeWriter w, EffectSpec e, bool useX,
        string? cardTargetExpr, string enemiesExpr, string playerExpr) =>
        EmitStun(w, e, useX, cardTargetExpr, enemiesExpr, playerExpr);

    /// <summary>
    /// 「对某个生物做一件事」那套目标解析的对外入口（<see cref="EmitPerCreature"/>）。
    /// 自定义状态那条链用不着卡牌目标，所以 <paramref name="cardTargetExpr"/> 传 null。
    /// </summary>
    internal static void EmitPerCreaturePublic(CodeWriter w, EffectSpec e, bool useX,
        string selfExpr, string? cardTargetExpr, string enemiesExpr, Func<string, string> body) =>
        EmitPerCreature(w, e, useX, selfExpr, cardTargetExpr, enemiesExpr, body);

    /// <summary>
    /// 「牺牲伙伴」的对外入口（<see cref="EmitPetSacrifice"/>）。
    /// <paramref name="inStatus"/> = true 时按**自定义状态钩子**改写那两处用到 cardPlay 的地方
    /// （收益 = 获得格挡 / 造成伤害）—— 卡牌那条链传 false，生成结果一个字节都不变。
    /// </summary>
    internal static void EmitPetSacrificePublic(CodeWriter w, EffectSpec e, CharacterProfile p, string petVar,
        PetGen.PetDef? petDef = null, string? petVarOverride = null, bool inStatus = false,
        Dictionary<EffectSpec, string>? varMap = null) =>
        EmitPetSacrifice(w, e, p, petVar, varMap, useX: false, petDef, petVarOverride, inStatus);

    private static void EmitStun(CodeWriter w, EffectSpec e, bool useX,
        string? cardTargetExpr, string enemiesExpr, string playerExpr)
    {
        string n = RepeatExpr(e, useX);
        switch (e.TargetSide)
        {
            case "AllEnemies":
                w.Open($"foreach (Creature foe in {enemiesExpr})")
                 .Line("await CreatureCmd.Stun(foe);")
                 .Close();
                break;
            case "AllUnits":
                // 全体单位（V0.2.132）：两边所有存活单位，各打晕一次。
                // ⚠ 战斗状态从 playerExpr 取：卡牌 / 遗物传 base.Owner（Player），
                // 自定义状态传 base.Owner.Player —— 写死 base.Owner.Creature 在状态链上会 CS1061。
                w.Open($"if ({playerExpr}.Creature.CombatState is not null)")
                 .Open($"foreach (Creature unit in {playerExpr}.Creature.CombatState.Creatures.Where(c => c.IsAlive).ToList())")
                 .Line("await CreatureCmd.Stun(unit);")
                 .Close()
                 .Close();
                break;
            case "RandomEnemies":
                // 和卡牌其它「随机敌人」写法一致：挑一只打晕一次，不允许重复时挑过的不再挑
                w.Line($"List<Creature> foes = {enemiesExpr}.ToList();")
                 .Open($"for (int __stunIdx = 0; __stunIdx < {n} && foes.Count > 0; __stunIdx++)")
                 .Line($"Creature foe = {playerExpr}.RunState.Rng.CombatTargets.NextItem(foes);");
                if (!e.AllowDuplicates) w.Line("foes.Remove(foe);");
                w.Line("await CreatureCmd.Stun(foe);")
                 .Close();
                break;
            case "Enemy" when cardTargetExpr is not null:
                w.Line($"await CreatureCmd.Stun({cardTargetExpr});");
                break;
            case "Enemy":
                // 遗物 / 药水没有「玩家选中的目标」：取可打的第一个敌人（和其它效果同一套约定）
                w.Open($"Creature? foe = {enemiesExpr}.FirstOrDefault();")
                 .Open("if (foe is not null)")
                 .Line("await CreatureCmd.Stun(foe);")
                 .Close()
                 .Close();
                break;
            default:
                // 「对自己」：本体也有自晕的场景（怪物给自己上 DIZZY_MOVE），照给
                w.Line($"await CreatureCmd.Stun(base.Owner.Creature);");
                break;
        }
    }

    /// <summary>
    /// 「给予卡牌关键词」的代码（卡牌 / 遗物 / 药水 / 自定义状态触发器共用）。
    /// </summary>
    /// <param name="playerExpr">玩家表达式（卡牌 / 遗物 / 药水是 base.Owner，状态触发器里是 base.Owner.Player）。</param>
    /// <param name="creatureExpr">玩家角色的表达式（临时关键词那个 Power 挂在它身上）。</param>
    /// <param name="sourceExpr">来源模型（卡牌是 this，遗物 / 药水 / 状态是 null）。</param>
    /// <param name="selfAllowed">能不能用「数值 0 = 这张牌自己」（只有卡牌上有「这张牌」）。</param>
    internal static void EmitGiveKeyword(CodeWriter w, CharacterProfile? p, EffectSpec e, bool useX,
        string playerExpr, string creatureExpr, string sourceExpr, bool selfAllowed)
    {
        string kwRaw = (e.GivenKeyword ?? "").Trim();
        // 「给的是哪个关键词」的解析和需求 ⑦ 的「生成出来的卡带关键词」共用一份（见 ResolveKeyword）
        var (customKw, kwEnum, customKey) = ResolveKeyword(kwRaw, p);
        // 回读标记：生成代码里认不出「给的是哪个关键词 / 是不是临时的」
        // 「范围界定」的标记行要写在它**前面**（回读是「先攒着、等这条效果的标记出现时配上去」）
        string? scopeMark = CardScopeMarker(e);
        if (scopeMark is not null) w.Line(scopeMark);
        // 「取几张」非默认档的标记要写在下面那行 CET:GiveKeyword **前面**（回读先攒着、等效果出现时配上）
        CountModeMarker(w, e);
        w.Line($"// CET:GiveKeyword={(customKw ? "custom:" + customKey : kwEnum)} CET:GiveKeywordTemp={(e.TempKeyword ? "1" : "0")}");
        if (customKw && customKey.Length == 0)
        {
            Warn(w, e, "（没选关键词，这条效果什么都不做）");
            return;
        }
        // 需求⑩：这个存档里有没有「卡牌时机 = 被给予自定义关键词」的卡 —— 只有有时才写转发那一句
        //（默认档 / 老存档一个字符都不变）。
        bool notifyTiming = NotifyGivenKeywordTiming(p);
        if (e.Amount <= 0)
        {
            if (!selfAllowed)
            {
                Warn(w, e, "（数值 0 = 这张牌自己，只有卡牌上有「这张牌」—— 请改成 ≥ 1 张）");
                return;
            }
            w.Line("// 数值 0 = 这张牌自己");
            EmitGiveKeywordTo(w, e, "this", creatureExpr, sourceExpr, customKw, kwEnum, customKey, notifyTiming: notifyTiming);
            return;
        }
        string n = (useX && e.AmountIsXEffective ? XVar : Math.Max(1, (int)e.Amount).ToString());
        // ⚠ 不能用 $"PileType.{e.SelectPile}..."：SelectPile = Top（牌顶）时那不是合法的 PileType 名字。
        // PileExpr 会把 Top 映射成抽牌堆，别的值生成的文本和以前逐字一致。
        string pileExpr = PileExpr(e, playerExpr);
        string? pred = CardScopePredicate(e, p);
        CountModeMarker(w, e);
        if (e.CountIsAll)
        {
            // 「全部」：那一摞里符合条件的牌**每一张**都加上关键词（不弹选牌界面）。
            w.Line($"// 全部：给{EffectCatalog.SelectPileZh(e.SelectPile)}里符合条件的牌**全部**加上关键词{ScopeZhSuffix(e)}（不弹选牌界面）");
            w.Open($"foreach (CardModel __kwCard in {CardScopeFiltered(e, p, $"{pileExpr}.Cards")}.ToList())");
            EmitGiveKeywordTo(w, e, "__kwCard", creatureExpr, sourceExpr, customKw, kwEnum, customKey, notifyTiming: notifyTiming);
            w.Close();
            return;
        }
        if (e.CardPick == "Chosen" && !IsPileTop(e))
        {
            if (e.SelectPile == "Hand")
                w.Line($"var __kwCards = (await CardSelectCmd.FromHand(context: choiceContext, player: {playerExpr}, prefs: new CardSelectorPrefs(base.SelectionScreenPrompt, {n}), filter: {pred ?? "null"}, source: {sourceExpr})).ToList();");
            else
                w.Line($"var __kwCards = (await CardSelectCmd.FromCombatPile(choiceContext, {pileExpr}, {playerExpr}, new CardSelectorPrefs(base.SelectionScreenPrompt, {n}){(pred is null ? "" : ", " + pred)})).ToList();");
            w.Line("foreach (CardModel __kwCard in __kwCards)");
            w.Open("");
            EmitGiveKeywordTo(w, e, "__kwCard", creatureExpr, sourceExpr, customKw, kwEnum, customKey, notifyTiming: notifyTiming);
            w.Close();
        }
        else
        {
            string kwScope = CardScopeFiltered(e, p, $"{pileExpr}.Cards");
            w.Line(IsPileTop(e)
                ? $"// 从牌顶（抽牌堆最上面那张）挑 {n} 张（不用自己选）{ScopeZhSuffix(e)}"
                : $"// 随机从{PileZh(e.SelectPile)}挑 {n} 张{ScopeZhSuffix(e)}");
            w.Open($"for (int __kwIdx = 0; __kwIdx < {n}; __kwIdx++)");
            w.Line($"CardModel? __kwCard = {PickOne(e, $"{playerExpr}.RunState.Rng.CombatCardSelection.NextItem({kwScope})", $"{kwScope}.FirstOrDefault()")};");
            w.Line("if (__kwCard is null) break;");
            EmitGiveKeywordTo(w, e, "__kwCard", creatureExpr, sourceExpr, customKw, kwEnum, customKey, notifyTiming: notifyTiming);
            w.Close();
        }
    }

    /// <summary>给某张牌加上关键词（<paramref name="cardExpr"/> 是那张牌的表达式）。</summary>
    private static void EmitGiveKeywordTo(CodeWriter w, EffectSpec e, string cardExpr,
        string creatureExpr, string sourceExpr, bool customKw, string kwEnum, string customKey,
        bool? tempOverride = null, bool notifyTiming = false)
    {
        // 「临时关键词」由调用方决定：需求 ⑦「生成出来的卡带关键词」固定按永久生成（新卡没有「只是这一回合」这一说）
        bool temp = tempOverride ?? e.TempKeyword;
        if (customKw)
        {
            w.Line($"{cardExpr}.AddGivenCustomKeyword({Lit.Str(customKey)});   // 自定义关键词：卡面文字与悬停说明由生成的关键词补丁加上");
            // 需求⑩「卡牌时机 = 被给予自定义关键词」：给关键词这一步就是入口 —— 直接把这件事转给这张牌自己的钩子
            //（生成转发器只在真的用到这个时机时才存在，见 GivenKeywordPatchSource / NotifyGivenKeywordTiming）。
            if (notifyTiming)
                w.Line($"await {Naming.AmbientGivenKeywordTimingClass}.Notify(choiceContext, {cardExpr});"
                    + "   // 需求⑩：这张牌带着「被给予自定义关键词」时机时，跑它自己那条效果 // CET:GivenKeywordNotify");
            if (temp)
                w.Line($"await PowerCmd.Apply(choiceContext, {TempKeywordPowerClassName(e, null)}.CreateForCustom({cardExpr}, {Lit.Str(customKey)}), {creatureExpr}, 1m, {creatureExpr}, {sourceExpr});"
                    + "   // 临时：回合结束时摘掉");
            return;
        }
        if (!temp)
        {
            w.Line($"{cardExpr}.AddKeyword(CardKeyword.{kwEnum});   // 本体 API：卡面文字会立刻刷新");
            return;
        }
        switch (kwEnum)
        {
            case "Retain":
                w.Line($"{cardExpr}.GiveSingleTurnRetain();   // 本体 API：只这一回合保留（回合末自动复位）");
                break;
            case "Sly":
                w.Line($"{cardExpr}.GiveSingleTurnSly();      // 本体 API：只这一回合算奇巧（回合末自动复位）");
                break;
            default:
                w.Line($"{cardExpr}.AddKeyword(CardKeyword.{kwEnum});");
                // 必须走 Create(...)（里面是 ModelDb.Power<T>().ToMutable()）：
                // 直接 new 一个 AbstractModel 会往 ModelDb 注册同名模型，第二次就
                // DuplicateModelException「You have called a constructor on an AbstractModel. Use ModelDb instead.」
                // → 出牌过程抛异常 → 卡牌悬浮在空中、打不出去（用户实测）。
                w.Line($"await PowerCmd.Apply(choiceContext, {TempKeywordPowerClassName(e, null)}.Create({cardExpr}, CardKeyword.{kwEnum}), {creatureExpr}, 1m, {creatureExpr}, {sourceExpr});"
                    + "   // 临时：回合结束时摘掉");
                break;
        }
    }

    /// <summary>
    /// 临时关键词 Power 的类名（兜底用当前角色，见 <see cref="Naming.CurrentCharClass"/>）。
    /// 只在生成 <c>CardSource</c> / <c>RelicSource</c> 之类「已经调过 Naming.From」的地方用，
    /// 所以 <paramref name="owner"/> 一般传 null。
    /// </summary>
    internal static string TempKeywordPowerClassName(EffectSpec? e, CharacterProfile? owner) =>
        owner is null ? Naming.CurrentCharClass + "ForgeTempKeywordPower" : Naming.From(owner).TempKeywordPowerClass;

    /// <summary>存档里有没有「临时关键词」（有才生成那个 Power）。</summary>
    public static bool UsesTempKeywordPower(CharacterProfile p) => GiveKeywordEffects(p).Any(e => e.TempKeyword);

    /// <summary>
    /// 需求⑩：「被给予自定义关键词」这个时机要不要在给关键词那一步转发。
    /// 条件有两个：① 存档里真有卡用了这个时机；② <paramref name="p"/> 拿得到（几个生成入口会传 null）。
    /// 默认档 / 老存档两个都不成立 → 生成结果一个字符都不变。
    /// </summary>
    internal static bool NotifyGivenKeywordTiming(CharacterProfile? p) =>
        p is not null && UsesCardTiming(p, "GivenKeyword");

    /// <summary>存档里所有「给予卡牌关键词」效果（卡的 / 遗物的 / 药水的 / 自定义状态触发的）。</summary>
    public static IEnumerable<EffectSpec> GiveKeywordEffects(CharacterProfile p) =>
        AllEffects(p).Where(e => e.Kind == "GiveKeyword");

    /// <summary>
    /// 存档里所有「生成 / 变化出来的卡带上关键词」效果（需求 ⑦）。只有这四种用得到「生成出来的卡怎么处理」。
    /// </summary>
    public static IEnumerable<EffectSpec> SpawnKeywordEffects(CharacterProfile p) =>
        AllEffects(p).Where(e => e.UsesSpawnOptions && e.HasSpawnKeyword);

    /// <summary>
    /// 存档里有没有给「自定义关键词」的（有才生成注册表 + 那个补丁）。
    /// 需求 ⑦：「生成 / 变化出来的卡带上自定义关键词」用的是同一套注册表 + 卡面 / 悬停补丁，
    /// 所以这里必须把它一起算上，否则光配这一项时生成出来的工程编译不过（AddGivenCustomKeyword 不存在）。
    /// </summary>
    public static bool UsesGivenCustomKeyword(CharacterProfile p) =>
        GiveKeywordEffects(p).Any(e => !EffectCatalog.IsVanillaKeywordName(e.GivenKeyword))
        || SpawnKeywordEffects(p).Any(e => !EffectCatalog.IsVanillaKeywordName(e.SpawnKeyword));

    /// <summary>
    /// 「临时关键词」用的 Power：记住「哪张牌、哪个关键词」，这一回合结束（拥有者那一侧结束时）把它摘掉。
    ///
    /// 保留 / 奇巧不用它 —— 本体自己有单回合标记（GiveSingleTurnRetain / GiveSingleTurnSly）。
    /// 其它本体关键词和自定义关键词都得靠这个：本体没有「只这一回合」的等价物。
    /// 每加一张牌就挂一个实例，所以 InstanceType 必须是 Instanced（否则本体按 Id 合并成一条，
    /// 只记得最后一张牌、最后一关键词）。
    /// </summary>
    public static string TempKeywordPowerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        return new CodeWriter()
            .Line("// <auto-generated> 「给予卡牌关键词」勾了「临时关键词」时用的 Power </auto-generated>")
            .Line($"namespace {n.Namespace};")
            .Line()
            .Line("/// <summary>回合结束时把这次临时给出去的（本体）关键词摘掉。</summary>")
            .Open($"public sealed class {n.TempKeywordPowerClass} : PowerModel")
            .Line("/// <summary>每张牌 / 每个关键词一条，不能按 Id 合并。</summary>")
            .Line("public override PowerInstanceType InstanceType => PowerInstanceType.Instanced;")
            .Line()
            .Line("public override PowerType Type => PowerType.Buff;")
            .Line()
            .Line("public override PowerStackType StackType => PowerStackType.Single;")
            .Line()
            .Line("/// <summary>不给这个内部标记建图标（也就不用去 powers 表查名字 / 图标）。</summary>")
            .Line("protected override bool IsVisibleInternal => false;")
            .Line()
            .Line("/// <summary>要摘掉关键词的那张牌。</summary>")
            .Line("public CardModel? Card;")
            .Line()
            .Line("/// <summary>本体关键词（CustomKey 非空时忽略它）。</summary>")
            .Line("public CardKeyword VanillaKeyword;")
            .Line()
            .Line("/// <summary>自定义关键词的键（空 = 摘的是本体关键词）。</summary>")
            .Line("public string CustomKey = \"\";")
            .Line()
            .Line($"public {n.TempKeywordPowerClass}() {{ }}")
            .Line()
            .Line("/// <summary>")
            .Line("/// 造一个带载荷的**可变副本**（本体关键词版）。")
            .Line("///")
            .Line("/// 为什么不能直接 new：AbstractModel 的构造函数会往 ModelDb 注册模型ID，")
            .Line("/// 第二次 new 同一个类就抛 DuplicateModelException ——")
            .Line("/// 「You have called a constructor on an AbstractModel. Use ModelDb instead.」")
            .Line("/// 那个异常从 OnPlay 里冒出去，表现是**卡牌悬浮在空中、打不出去**（用户实测）。")
            .Line("/// 正确做法：ModelDb.Power<T>() 拿规范模型 → ToMutable() 拿可变副本 → 再填载荷。")
            .Line("/// </summary>")
            .Open($"public static {n.TempKeywordPowerClass} Create(CardModel card, CardKeyword keyword)")
            .Line($"{n.TempKeywordPowerClass} power = ({n.TempKeywordPowerClass})ModelDb.Power<{n.TempKeywordPowerClass}>().ToMutable();")
            .Line("power.Card = card;")
            .Line("power.VanillaKeyword = keyword;")
            .Line("return power;")
            .Close()
            .Line()
            .Line("/// <summary>造一个带载荷的可变副本（自定义关键词版）。</summary>")
            .Open($"public static {n.TempKeywordPowerClass} CreateForCustom(CardModel card, string customKey)")
            .Line($"{n.TempKeywordPowerClass} power = ({n.TempKeywordPowerClass})ModelDb.Power<{n.TempKeywordPowerClass}>().ToMutable();")
            .Line("power.Card = card;")
            .Line("power.CustomKey = customKey ?? \"\";")
            .Line("return power;")
            .Close()
            .Line()
            .Line("/// <summary>这一回合结束：把关键词摘掉，然后自己消失。</summary>")
            .Open("public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)")
            .Open("if (participants.Contains(base.Owner) && Card is not null)")
            .Raw(TempKeywordRemovalBody(p))
            .Close()
            .Line("await PowerCmd.Remove(this);")
            .Close()
            .Close()
            .ToString();
    }

    /// <summary>
    /// 「回合结束时自动打出」用的 Power：记住要打出去的那几张牌，在 <c>BeforeSideTurnEnd</c> 里
    /// 逐张 <c>CardCmd.AutoPlay</c>，然后自毁。
    ///
    /// 为什么用 BeforeSideTurnEnd：本体的回合结束流程是
    /// <c>Hook.BeforeSideTurnEnd</c>（CombatManager.cs:1559）→ <c>DoTurnEnd</c>（:1570，处理手牌里的
    /// OnTurnEndInHand 卡 + 弃手牌）。挂在前面，自动打出的牌会正常离开手牌，
    /// 不会和「回合结束弃手牌」那一步抢同一张牌。
    /// 每挂一次一个实例（InstanceType = Instanced），否则本体按 Id 合并、只记得最后一批牌。
    /// </summary>
    public static string TurnEndPlayPowerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        return new CodeWriter()
            .Line("// <auto-generated> 「回合结束时自动打出」用的 Power </auto-generated>")
            .Line($"namespace {n.Namespace};")
            .Line()
            .Line("/// <summary>本回合结束时，把记住的那几张牌自动打出去。</summary>")
            .Open($"public sealed class {n.TurnEndPlayPowerClass} : PowerModel")
            .Line("/// <summary>每次挂一个实例（要记住不同批次打出的牌）。</summary>")
            .Line("public override PowerInstanceType InstanceType => PowerInstanceType.Instanced;")
            .Line()
            .Line("public override PowerType Type => PowerType.Buff;")
            .Line()
            .Line("public override PowerStackType StackType => PowerStackType.Single;")
            .Line()
            .Line("/// <summary>内部标记：不给它建图标（也就不用去 powers 表查名字 / 图标）。</summary>")
            .Line("protected override bool IsVisibleInternal => false;")
            .Line()
            .Line("/// <summary>本回合结束时要自动打出的牌。</summary>")
            .Line("public List<CardModel> Cards = new();")
            .Line()
            .Line($"public {n.TurnEndPlayPowerClass}() {{ }}")
            .Line()
            .Line("/// <summary>")
            .Line("/// 造一个带载荷的**可变副本**。")
            .Line("/// 不能直接 new：AbstractModel 的构造函数会往 ModelDb 注册模型ID，")
            .Line("/// 第二次 new 同一个类就抛 DuplicateModelException（表现是卡牌悬浮在空中、打不出去）。")
            .Line("/// </summary>")
            .Open($"public static {n.TurnEndPlayPowerClass} Create(IEnumerable<CardModel> cards)")
            .Line($"{n.TurnEndPlayPowerClass} power = ({n.TurnEndPlayPowerClass})ModelDb.Power<{n.TurnEndPlayPowerClass}>().ToMutable();")
            .Line("power.Cards = cards.ToList();")
            .Line("return power;")
            .Close()
            .Line()
            .Line("/// <summary>本回合结束（玩家这一侧）：把记住的牌逐张自动打出去，然后自己消失。</summary>")
            .Open("public override async Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)")
            .Line("if (side != CombatSide.Player || !participants.Contains(base.Owner)) return;")
            .Line("foreach (CardModel __c in Cards.ToList())")
            .Open("")
            // 牌可能已经不在场上了（被消耗 / 被移出战斗）：那就跳过它
            .Line("if (__c.Pile is null || __c.Owner.Creature.IsDead) continue;")
            .Line("await CardCmd.AutoPlay(choiceContext, __c, null);   // 目标为 null 时本体自己随机挑（本体 AutoPlay 的行为）")
            .Close()
            .Line("await PowerCmd.Remove(this);")
            .Close()
            .Close()
            .ToString();
    }

    /// <summary>存档里有没有「回合结束时自动打出」效果（有才生成那个 Power）。</summary>
    public static bool UsesTurnEndPlay(CharacterProfile p) => AllEffects(p).Any(e => e.Kind == "TurnEndPlay");

    /// <summary>
    /// 「这一回合结束要摘掉什么」这段代码体。
    ///
    /// 两种关键词分开写：**只有这一份存档真的用到哪种，才写哪一支** ——
    /// 自定义关键词那支要调 <c>RemoveGivenCustomKeyword</c>（在 GivenKeywords.cs 里，只有「给自定义关键词」时才会生成），
    /// 全都写上的话，只配了本体关键词的存档会 CS1061（用户实测：构建失败）。
    /// </summary>
    private static string TempKeywordRemovalBody(CharacterProfile p)
    {
        var effects = GiveKeywordEffects(p).Where(e => e.TempKeyword).ToList();
        bool anyCustom = effects.Any(e => !EffectCatalog.IsVanillaKeywordName(e.GivenKeyword));
        bool anyVanilla = effects.Any(e => EffectCatalog.IsVanillaKeywordName(e.GivenKeyword));

        var w = new CodeWriter();
        w.Indent().Indent().Indent();       // 类 → 方法 → if：里面的语句是第 3 层缩进（和周围的生成代码对齐）
        if (anyCustom && anyVanilla)
        {
            w.Open("if (CustomKey.Length > 0)")
             .Line("Card.RemoveGivenCustomKeyword(CustomKey);")
             .Close()
             .Line("else")
             .Open("")
             .Line("Card.RemoveKeyword(VanillaKeyword);")
             .Close();
        }
        else if (anyCustom)
        {
            w.Line("Card.RemoveGivenCustomKeyword(CustomKey);");
        }
        else
        {
            w.Line("Card.RemoveKeyword(VanillaKeyword);");
        }
        return w.ToString();
    }

    /// <summary>
    /// 「给予自定义关键词」的运行时支持：一个 <c>CardModel → 关键词键</c> 的注册表 +
    /// 两个 Harmony 补丁（卡面描述 + 悬停说明）。
    ///
    /// 为什么要补丁：自定义关键词在生成期是**写死在卡面描述文本里**的（cards.json），
    /// 运行时给一张牌加词条没法改那段文本 —— <c>CardModel.Description</c> 和
    /// <c>GetDescriptionForPile</c> 都不是 virtual，只能 Postfix 它们。
    /// 好处是**本体卡 / 别的模组的卡也能给**（不限于我们自己生成的卡）。
    /// </summary>
    public static string GivenKeywordPatchSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var timingCards = GivenKeywordTimingCardClasses(p);
        return new CodeWriter()
            .Line("// <auto-generated> 「给予卡牌关键词」：运行时给任意卡牌加自定义关键词（卡面 + 悬停） </auto-generated>")
            .Line("using System;")
            .Line("using System.Collections.Generic;")
            .Line("using System.Linq;")
            .Line("using System.Runtime.CompilerServices;")
            .Line("using MegaCrit.Sts2.Core.HoverTips;")
            .Line("using MegaCrit.Sts2.Core.Localization;")
            .Line("using MegaCrit.Sts2.Core.Models;")
            .Line($"namespace {n.Namespace};")
            .Line()
            .Line("/// <summary>这张牌身上「被给过」的自定义关键词（键）。战斗结束 / 这张牌没了就自然消失。</summary>")
            .Line("public static class ForgeGivenKeywords")
            .Open("")
            .Line("// 用 ConditionalWeakTable：键是卡牌实例本身，牌被回收就跟着没了，不用手动清理、也不会把牌吊住")
            .Line("private static readonly ConditionalWeakTable<CardModel, List<string>> Table = new();")
            .Line()
            .Open("public static void Add(CardModel card, string key)")
            .Line("if (card is null || string.IsNullOrWhiteSpace(key)) return;")
            .Line("List<string> list = Table.GetOrCreateValue(card);")
            .Line("if (!list.Contains(key)) list.Add(key);")
            .Close()
            .Line()
            .Open("public static void Remove(CardModel card, string key)")
            .Line("if (card is null || string.IsNullOrWhiteSpace(key)) return;")
            .Open("if (Table.TryGetValue(card, out List<string>? list))")
            .Line("list.Remove(key);")
            .Close()
            .Close()
            .Line()
            .Open("public static IReadOnlyList<string> Get(CardModel card)")
            .Line("if (card is null) return Array.Empty<string>();")
            .Line("return Table.TryGetValue(card, out List<string>? list) ? list : (IReadOnlyList<string>)Array.Empty<string>();")
            .Close()
            .Close()
            .Line()
            .Line("/// <summary>给卡牌用的两个扩展方法（生成的效果代码直接调）。</summary>")
            .Line("public static class ForgeGivenKeywordExtensions")
            .Open("")
            .Line("public static void AddGivenCustomKeyword(this CardModel card, string key) => ForgeGivenKeywords.Add(card, key);")
            .Line("public static void RemoveGivenCustomKeyword(this CardModel card, string key) => ForgeGivenKeywords.Remove(card, key);")
            .Close()
            .Raw(GivenKeywordTimingDispatcherSource(timingCards))
            .Line()
            .Line("/// <summary>卡面描述：把「给过」的关键词按本体的观感拼在描述最前面（[gold]名字[/gold]。）。</summary>")
            .Line("[HarmonyLib.HarmonyPatch(typeof(CardModel), \"GetDescriptionForPile\")]")
            .Line("internal static class GivenKeywordTextPatch")
            .Open("")
            .Line("[HarmonyLib.HarmonyPostfix]")
            .Open("private static void After(CardModel __instance, ref string __result)")
            .Line("IReadOnlyList<string> keys = ForgeGivenKeywords.Get(__instance);")
            .Line("if (keys.Count == 0) return;")
            .Line("var lines = keys.Select(k => \"[gold]\" + GivenKeywordLoc.Title(k) + \"[/gold]。\");")
            .Line("__result = string.Join(\"\\n\", lines) + (string.IsNullOrEmpty(__result) ? \"\" : \"\\n\" + __result);")
            .Close()
            .Close()
            .Line()
            .Line("/// <summary>悬停提示：鼠标停在卡上时，这些关键词也有说明（和本体关键词一样）。</summary>")
            .Line("[HarmonyLib.HarmonyPatch(typeof(CardModel), \"get_ExtraHoverTips\")]")
            .Line("internal static class GivenKeywordHoverPatch")
            .Open("")
            .Line("[HarmonyLib.HarmonyPostfix]")
            .Open("private static void After(CardModel __instance, ref IEnumerable<IHoverTip> __result)")
            .Line("IReadOnlyList<string> keys = ForgeGivenKeywords.Get(__instance);")
            .Line("if (keys.Count == 0) return;")
            .Line("var list = __result?.ToList() ?? new List<IHoverTip>();")
            .Line("foreach (string k in keys)")
            .Open("")
            .Line("list.Add(new HoverTip(new LocString(\"card_keywords\", k + \".title\"), new LocString(\"card_keywords\", k + \".description\")));")
            .Close()
            .Line("__result = list;")
            .Close()
            .Close()
            .Line()
            .Line("/// <summary>关键词键 → 本地化文本（拿不到就退回键名，不让补丁抛异常）。</summary>")
            .Line("internal static class GivenKeywordLoc")
            .Open("")
            .Open("internal static string Title(string key)")
            .Open("try")
            .Line("return new LocString(\"card_keywords\", key + \".title\").GetFormattedText() ?? key;")
            .Close()
            .Open("catch")
            .Line("return key;")
            .Close()
            .Close()
            .Close()
            .ToString();
    }

    /// <summary>
    /// 需求⑩「卡牌时机 = 被给予自定义关键词」的**转发器**：把「这张牌刚被给了一个自定义关键词」这件事
    /// 交给这张牌自己的钩子方法（<c>ForgeOnGivenCustomKeyword</c>，见 <see cref="EmitCardTimingHooks"/>）。
    ///
    /// 为什么不用本体的钩子：本体根本没有「被给予关键词」的事件 —— 关键词只有 AddKeyword / RemoveKeyword
    /// 两个动作（CardModel 上没有任何广播）。但「给一张牌加上**自定义**关键词」这件事完全是我们自己做的
    /// （生成的 AddGivenCustomKeyword / EmitGiveKeywordTo），所以在那一步直接调用即可，不需要另造机制。
    ///
    /// 这个类只在存档里真有卡用这个时机时才生成（没有 = 一个字符都不变，见 <see cref="GivenKeywordTimingCardClasses"/>）。
    /// </summary>
    private static string GivenKeywordTimingDispatcherSource(IReadOnlyList<string> timingCards)
    {
        if (timingCards.Count == 0) return "";
        var w = new CodeWriter();
        w.Line("/// <summary>需求⑩：把「这张牌被给了自定义关键词」转发给带这个时机的卡（没带就什么都不做）。</summary>")
         .Open($"internal static class {Naming.AmbientGivenKeywordTimingClass}")
         .Open("internal static Task Notify(PlayerChoiceContext choiceContext, CardModel card)")
         .Open("switch (card)");
        foreach (string cls in timingCards)
            w.Line($"case {cls} __given: return __given.ForgeOnGivenCustomKeyword(choiceContext);");
        w.Line("default: return Task.CompletedTask;")
         .Close()
         .Close()
         .Close();
        return w.ToString();
    }

    /// <summary>额外回合用的 Power（照抄本体 MockExtraTurnPower 的写法）。</summary>
    /// <summary>这个配置里有没有「透支能量」效果（有才生成那个负债 Power；只做卡牌）。</summary>
    public static bool UsesEnergyDebt(CharacterProfile p) => UsesKind(p, "OverdraftEnergy");

    /// <summary>
    /// 「透支能量」用的负债 Power：施加时立刻把 N 点能量给玩家；下回合能量重置后再扣掉 N 点，然后自毁。
    ///
    /// 为什么不直接用本体的 <c>EnergyNextTurnPower</c>（下回合加能量）加一个负数：
    /// 它的 <c>AfterEnergyReset</c> 走的是 <c>PlayerCmd.GainEnergy</c>，而 GainEnergy 第一句就是
    /// <c>if (!(amount &lt;= 0m) &amp;&amp; …)</c> —— **负数直接被忽略**（实测读源码确认）。
    /// 扣能量必须用 <c>PlayerCmd.LoseEnergy</c>，它内部 <c>PlayerCombatState.LoseEnergy</c> 会
    /// <c>Math.Clamp(…, 0, …)</c>，所以不会把能量扣成负数。
    /// </summary>
    public static string EnergyDebtPowerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 透支能量用的负债 Power </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>透支：现在拿到 N 点能量，下回合少 N 点。</summary>")
         .Open($"public sealed class {n.EnergyDebtPowerClass} : PowerModel")
         .Line("public override PowerType Type => PowerType.Debuff;")
         .Line()
         .Line("public override PowerStackType StackType => PowerStackType.Counter;")
         .Line()
         .Line("// 施加时立刻把能量给玩家（透支的「现在拿」那一半）")
         .Open("public override async Task AfterApplied(Creature? applier, CardModel? cardSource)")
         .Line("await PlayerCmd.GainEnergy(base.Amount, base.Owner.Player);")
         .Line("await Task.CompletedTask;")
         .Close()
         .Line()
         .Line("// 下回合能量重置后再扣掉（本体 GainEnergy 忽略负数，所以必须自己 LoseEnergy；它会夹到 0）")
         .Open("public override async Task AfterEnergyReset(Player player)")
         .Open("if (player == base.Owner.Player)")
         .Line("await PlayerCmd.LoseEnergy(base.Amount, player);")
         .Line("await PowerCmd.Remove(this);")
         .Close()
         .Close()
         .Close();
        return w.ToString();
    }

    /// <summary>
    /// 「获得能量」填了负数 + 勾了「下回合生效」时用的负债 Power：下回合能量重置后扣掉 N 点，然后自毁。
    ///
    /// 为什么不直接用本体的 <c>EnergyNextTurnPower</c>：它的 <c>AfterEnergyReset</c> 走
    /// <c>PlayerCmd.GainEnergy(base.Amount)</c>，而 GainEnergy 第一句就是 <c>if (!(amount &gt; 0m)) return;</c>
    /// —— 负数（= 想扣能量）被直接忽略。所以这里自己写一个：<c>PlayerCmd.LoseEnergy</c> 才扣得动，
    /// 而且它内部会把能量夹在 0（不会扣成负能量）。
    /// 和「透支能量」那个负债 Power 的区别：那个 <c>AfterApplied</c> 会先把能量给玩家（透支的「现在拿」），
    /// 这个只扣、不给（就是「下回合少 N 点」）。
    /// </summary>
    public static string EnergyNextTurnDebtPowerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 「下回合少 N 点能量」用的负债 Power </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>下回合能量重置后扣掉 N 点能量（本体 GainEnergy 忽略负数，所以必须自己 LoseEnergy）。</summary>")
         .Open($"public sealed class {n.EnergyNextTurnDebtPowerClass} : PowerModel")
         .Line("public override PowerType Type => PowerType.Debuff;")
         .Line()
         .Line("public override PowerStackType StackType => PowerStackType.Counter;")
         .Line()
         .Line("protected override IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> ExtraHoverTips =>")
         .Line("[")
         .Line("    MegaCrit.Sts2.Core.HoverTips.HoverTipFactory.ForEnergy(this),")
         .Line("];")
         .Line()
         .Line("// 下回合能量重置后再扣掉（LoseEnergy 内部会夹到 0，不会变成负能量）")
         .Open("public override async Task AfterEnergyReset(Player player)")
         .Open("if (player == base.Owner.Player)")
         .Line("await PlayerCmd.LoseEnergy(base.Amount, player);")
         .Line("await PowerCmd.Remove(this);")
         .Close()
         .Close()
         .Close();
        return w.ToString();
    }

    /// <summary>这个配置里有没有「获得能量 = 负数 + 下回合生效」（有才生成那个负债 Power）。</summary>
    public static bool UsesEnergyNextTurnDebt(CharacterProfile p) =>
        AllEffects(p).Any(e => e.Kind == "Energy" && e.NextTurn && e.Amount < 0 && !e.AmountIsXEffective);

    /// <summary>这个配置里有没有「生成 / 变化出来的卡：仅在本回合升级」（有才生成那个临时升级 Power）。</summary>
    public static bool UsesTempUpgrade(CharacterProfile p) =>
        AllEffects(p).Any(e => e.UsesSpawnOptions && e.SpawnUpgradedThisTurn);

    /// <summary>这个配置里有没有用「抽牌堆洗过牌」的条件（有才生成记录器 + 补丁）。</summary>
    public static bool UsesShuffleCondition(CharacterProfile p) => UsesCondition(p, "ShuffledThisTurn", "ShuffledThisCombat");

    /// <summary>存档里有没有用到这几种条件（卡牌 / 遗物 / 药水 / 自定义状态的触发器都算）。</summary>
    public static bool UsesCondition(CharacterProfile p, params string[] kinds)
    {
        bool Hit(ConditionSpec? c) => c is not null && !c.IsNone && kinds.Contains(c.Kind, StringComparer.Ordinal);
        foreach (var card in p.AllCards)
        {
            if (Hit(card.Condition)) return true;
            if (card.Effects.Any(e => Hit(e.Condition))) return true;
        }
        foreach (var r in p.Relics)
        {
            if (Hit(r.Condition)) return true;
            if (RelicEffects(r).Any(e => Hit(e.Condition))) return true;
        }
        foreach (var s in p.Potions)
            if (s.Effects.Any(e => Hit(e.Condition))) return true;
        foreach (var cp in CustomPowerGen.Active(p))
            foreach (var t in cp.Triggers)
                if (t.Effects.Any(e => Hit(e.Condition))) return true;
        return false;
    }

    /// <summary>
    /// 「抽牌堆被洗过牌」的记录器 + 补丁。
    ///
    /// 为什么要自己记：本体**没有**任何「洗过牌」的可查询状态 ——
    /// 没有事件、没有战斗历史条目、没有计数器（读源码确认）；
    /// 本体先古遗物「大～抱抱 BiiigHug」自己是靠 `override AfterShuffle(choiceContext, shuffler)`
    /// 在洗牌那一刻反应的，而**条件**要在别的地方（IsPlayable / 遗物效果门控…）随时查询，
    /// 所以这里用一个 Harmony 后缀补丁把「谁洗的、哪一回合、洗了几次」记在静态表里：
    ///   · 本回合洗过 = 记录的回合号 == 当前回合号；
    ///   · 本场战斗洗过 = 记录的 ICombatState 还是当前这一场（换一场自然就 false）。
    /// 注意（本体机制）：开局的洗牌不算（那次只走 ModifyShuffleOrder，不触发 AfterShuffle），
    /// 战斗结束/收尾阶段也不触发。
    /// </summary>
    public static string ShuffleTrackerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 「抽牌堆洗过牌」记录器 + 补丁（本体没有这个状态，只能自己记） </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>记住「谁、哪一回合、洗了几次」，供条件（ShuffledThisTurn / ShuffledThisCombat）查询。</summary>")
         .Open($"internal static class {n.ShuffleTrackerClass}")
         // 每个玩家一条记录：换成另一场战斗（ICombatState 换实例）就重新开始记。
         .Open("private sealed class Rec")
         .Line("public ICombatState? State;")
         .Line("public int Turn;")
         .Line("public int Count;")
         .Close()
         .Line()
         .Line("private static readonly Dictionary<ulong, Rec> ByPlayer = new();")
         .Line()
         .Line("/// <summary>Hook.AfterShuffle 触发时调用（本体的「大～抱抱」也是在这个时机反应的）。</summary>")
         .Open("public static void Note(Player? shuffler)")
         .Line("if (shuffler?.Creature.CombatState is not { } state) return;")
         .Open("if (!ByPlayer.TryGetValue(shuffler.NetId, out Rec? rec) || rec.State != state)")
         .Line("rec = new Rec { State = state };")
         .Line("ByPlayer[shuffler.NetId] = rec;")
         .Close()
         .Line("rec.Turn = shuffler.PlayerCombatState?.TurnNumber ?? 0;")
         .Line("rec.Count++;")
         .Close()
         .Line()
         .Open("private static Rec? Get(Player? player)")
         .Line("if (player?.Creature.CombatState is not { } state) return null;")
         .Line("return ByPlayer.TryGetValue(player.NetId, out Rec? rec) && rec.State == state ? rec : null;")
         .Close()
         .Line()
         .Line("/// <summary>本回合洗过牌（开局的洗牌不算）。</summary>")
         .Line("public static bool ShuffledThisTurn(Player? player) => Get(player) is { } rec && player?.PlayerCombatState is { } pcs && rec.Turn == pcs.TurnNumber;")
         .Line()
         .Line("/// <summary>本场战斗洗过牌（换一场战斗就重新算）。</summary>")
         .Line("public static bool ShuffledThisCombat(Player? player) => Get(player) is not null;")
         .Line()
         .Line("/// <summary>本场战斗洗了几次。</summary>")
         .Line("public static int ShuffleCountThisCombat(Player? player) => Get(player)?.Count ?? 0;")
         .Close()
         .Line()
         .Line("/// <summary>打在 Hook.AfterShuffle 上的后缀补丁：本体的「洗牌之后」那一刻把记录更新掉。</summary>")
         .Line("[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Hooks.Hook), \"AfterShuffle\")]")
         .Open($"internal static class {n.ShuffleTrackerClass}Patch")
         .Line("[HarmonyLib.HarmonyPostfix]")
         .Open("private static void After(Player shuffler)")
         .Line($"try {{ {n.ShuffleTrackerClass}.Note(shuffler); }}")
         .Line("catch (Exception e) { Log.Warn(\"洗牌记录失败：\" + e.Message); }   // 纯记录，出错也不能影响洗牌本身")
         .Close()
         .Close();
        return w.ToString();
    }

    /// <summary>
    /// 「生成 / 变化出来的卡：仅在本回合升级」用的 Power。
    ///
    /// 为什么必须自己写：本体**没有**「临时升级」这种东西 ——
    /// 只有视觉预览的 <c>CardUpgradePreviewType</c>（挂在克隆出来的卡上，不改真卡），
    /// 以及一个反向的先例 <c>DampenPower</c>（挂上时把升级过的卡降级、移除时再升回去，自己记着等级）。
    /// 这里就是 DampenPower 反过来用：<c>Track(card)</c> 里升级并记住「这次真的升上去的那几张」
    /// （本来就升级过的牌不动它），回合结束时把它们降回来。
    /// 战斗里的卡是牌组卡的克隆，所以就算没降回来也不会污染牌组 —— 这个状态只是让「本回合」的语义成立。
    /// </summary>
    public static string TempUpgradePowerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        var w = new CodeWriter();
        w.Line("// <auto-generated> 「生成 / 变化出来的卡：仅在本回合升级」用的临时升级 Power </auto-generated>")
         .Line($"namespace {n.Namespace};")
         .Line()
         .Line("/// <summary>记住这次临时升上去的那几张牌，回合结束时把它们降回来。</summary>")
         .Open($"public sealed class {n.TempUpgradePowerClass} : PowerModel")
         .Line("public override PowerType Type => PowerType.Buff;")
         .Line()
         .Line("public override PowerStackType StackType => PowerStackType.Counter;")
         .Line()
         .Line("// 这次被我们升上去的牌（本来就是升级过的牌不会进这里）")
         .Line("private readonly List<CardModel> _upgraded = [];")
         .Line()
         .Line("/// <summary>把一个刚生成 / 刚变化出来的卡临时升级（已经升级过的不动）。</summary>")
         .Open("public void Track(CardModel card)")
         .Line("if (card.IsUpgraded || !card.IsUpgradable) return;")
         .Line("CardCmd.Upgrade(card);")
         .Line("_upgraded.Add(card);")
         .Close()
         .Line()
         .Line("// 回合结束：把它们降回没升级的样子（只降这次真的升上去的那几张）")
         .Open("public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)")
         .Open("if (participants.Contains(base.Owner))")
         .Open("foreach (CardModel card in _upgraded)")
         .Line("if (card.IsUpgraded) CardCmd.Downgrade(card);")
         .Close()
         .Line("_upgraded.Clear();")
         .Line("await PowerCmd.Remove(this);")
         .Close()
         .Close()
         .Close();
        return w.ToString();
    }

    public static string ExtraTurnPowerSource(CharacterProfile p)
    {
        var n = Naming.From(p);
        return new CodeWriter()
            .Line("// <auto-generated> 额外回合用的 Power </auto-generated>")
            .Line($"namespace {n.Namespace};")
            .Line()
            .Open($"public sealed class {n.ExtraTurnPowerClass} : PowerModel")
            .Line("public override PowerType Type => PowerType.Buff;")
            .Line()
            .Line("public override PowerStackType StackType => PowerStackType.Counter;")
            .Line()
            .Line("public override bool ShouldTakeExtraTurn(Player player) => player == base.Owner.Player;")
            .Line()
            .Open("public override async Task AfterTakingExtraTurn(Player player)")
            .Open("if (player == base.Owner.Player)")
            .Line("await PowerCmd.Decrement(this);")
            .Close()
            .Close()
            .Close()
            .ToString();
    }

    private static void EmitPotionEffect(CodeWriter w, CharacterProfile p, EffectSpec e, string potionTarget,
        Dictionary<EffectSpec, string>? varMap = null)
    {
        if (IsInertZero(e)) return;   // 数值 0：整条丢掉（用户要求：不显示、也不执行）
        // V0.2.164：药水上也能写「数值公式」了 —— 同样写一行标记，「从工程恢复存档」按它认回来
        if (e.UsesAmountFormula) w.Line($"// CET:AmountFormula={EscapeMarker(e.AmountFormula)}");
        // 每条效果自己的条件（用户要求第 6 条：药水页右下角也能选「单条效果的条件」，照遗物页那套）：
        // 不满足时只跳过这一条，别的效果照常执行。
        //
        // ⚠ 这里**只包条件、刻意不包概率**：药水效果的「概率生效」这一栏从界面一直存在，
        // 但生成端从来没为药水生成过掷骰（老缺口）。一起补上会改掉老存档的生成结果
        // （老存档里可能勾过、一直被忽略），而「老存档生成结果逐字不变」是红线 ——
        // 那个缺口改成由**校验器明确报出来**（不再静默），补生成留到用户拍板。
        // ⚠ 老存档不可能带药水条件：校验器以前对 ctx=="Potion" 一律报**错误**
        //（「药水不支持条件选项」），带条件的存档根本生成不出来 —— 所以这一段不会改到任何老存档的输出。
        string? cond = e.Condition is null || e.Condition.IsNone
            ? null
            : ConditionExpr(e.Condition, CondCtx.Potion);
        if (cond is not null)
        {
            w.Line($"// 条件（只对「{EffectCatalog.FindKind(e.Kind).Display}」这条效果）：{ConditionText(e.Condition!)}（不满足时这条效果不触发）");
            w.Open($"if ({cond})");
        }
        EmitRepeated(w, e, x => EmitPotionEffectOnce(x, p, e, potionTarget, varMap));
        if (cond is not null) w.Close();
    }

    /// <summary>药水：按「药水作用目标」展开（自己 / 指定敌人 / 全体敌人）。</summary>
    private static void EmitPotionPerCreature(CodeWriter w, string potionTarget, string allEnemies, Func<string, string> body)
    {
        if (potionTarget == "AllEnemies")
            w.Open($"foreach (Creature foe in {allEnemies})")
             .Line(body("foe"))
             .Close();
        else if (potionTarget == "AnyEnemy")
        {
            w.Open("if (target is not null)")
             .Line(body("target"))
             .Close();
        }
        else
            w.Line(body("base.Owner.Creature"));
    }

    private static void EmitPotionEffectOnce(CodeWriter w, CharacterProfile p, EffectSpec e, string potionTarget,
        Dictionary<EffectSpec, string>? varMap = null)
    {
        // 「下回合生效」的新支持种类（V0.2.133）：药水链也接上。
        if (UsesDelayedEffectBranch(e))
        {
            EmitDelayedPowerApply(w, p, e, "base.Owner.Creature", "base.Owner.Creature");
            return;
        }
        // V0.2.164：「数值公式」在这条链上同样是全内联（药水的 Owner 是 Player，和遗物同一套写法）
        string amt = InlineAmountFormula(p, e, "base.Owner", "base.Owner.Creature", FirstEnemyOf("base.Owner"))
                     ?? VarAccess(e, varMap);
        string blockAmt = InlineAmountFormula(p, e, "base.Owner", "base.Owner.Creature", FirstEnemyOf("base.Owner"))
                          ?? BlockValueAccess(varMap, e);
        // 「直接把缓慢设成 N%」：本体做法是只施加 1 层（层数对「缓慢」没有作用）
        if (IsSlowPercentEffect(e)) amt = "1m";
        string allEnemies = "base.Owner.Creature.CombatState.HittableEnemies";
        // V0.2.132：药水这条链也把新档位写一行回读标记（只在**新档位**出现时才写；
        // 药水实际打谁仍由药水自己的「作用目标」决定，这一栏只影响卡面描述 —— 校验器会提示）。
        if (string.Equals(e.TargetSide, "AllUnits", StringComparison.Ordinal))
            w.Line("// CET:TargetSide=AllUnits");
        else if (string.Equals(e.TargetSide, "AllAllies", StringComparison.Ordinal) && e.AllAlliesExcludePets)
            w.Line("// CET:TargetSide=AllAllies CET:AllyNoPets=1");
        switch (e.Kind)
        {
            case "EndTurn":
                w.Line("PlayerCmd.EndTurn(base.Owner, canBackOut: false);");
                break;

            case "ExtraTurn":
                w.Line($"await PowerCmd.Apply<{Naming.From(p).ExtraTurnPowerClass}>(choiceContext, base.Owner.Creature, 1m, base.Owner.Creature, null);");
                break;

            // 播放音效（V0.2.154）：药水上也能放（SfxCmd 静态，不需要 choiceContext / 目标）
            case "PlaySfx":
                EmitPlaySfx(w, e);
                break;

            // 播放上传的音频文件（V0.2.155）：药水上也能放
            case "PlaySoundFile":
                EmitPlaySoundFile(w, e);
                break;

            case "GenerateCard":
                EmitGenerateCard(w, p, e, tempUpSource: "null");
                break;

            // 获得药水（需求 ⑨）：药水的 base.Owner 就是 Player
            case "GainPotion":
                EmitGainPotion(w, e);
                break;

            case "ExhaustCard":
                EmitExhaustCard(w, p, e);
                break;

            case "DiscardCard":
                EmitDiscardCard(w, p, e);
                break;

            case "UpgradeCard":
                EmitUpgradeCard(w, p, e);
                break;

            case "Scry":
                EmitScry(w, p, e);
                break;
            case "ScrapeDraw":
                EmitScrapeDraw(w, p, e, Lit.Dec(e.Amount));
                break;

            case "FillHand":
                EmitFillHand(w, e);
                break;

            case "CheapenDraw":
                w.Line(SelfContainedMarker(e));
                w.Line(ApplyPowerLine(e, useX: false, Naming.From(p).DrawCostPowerClass, "base.Owner.Creature",
                    Math.Abs((int)e.Amount).ToString(), "base.Owner.Creature", cardSourceExpr: "null") + "   // 抽到就减费");
                break;

            case "Outbreak":
                EmitOutbreak(w, e, Lit.Dec(e.Amount), "null");
                break;

            case "TransformCard":
                EmitTransformCard(w, e, p: p, cardSource: "null");
                break;

            case "TakeFromDraw":
                EmitTakeFromPile(w, p, e, "Draw");
                break;

            case "TakeFromDiscard":
                EmitTakeFromPile(w, p, e, "Discard");
                break;

            // 从消耗牌堆拿牌到手牌（同上：三个上下文都接上了）
            case "TakeFromExhaust":
                EmitTakeFromPile(w, p, e, "Exhaust");
                break;

            // 放置卡牌：药水上同样没有「这张牌自己」→ 数值 ≥ 1 挑牌照常（数值 0 由生成端说清）
            case "PlaceCard":
                EmitPlaceCard(w, p, e, selfExpr: null);
                break;

            // 全局（牌组）类效果：药水的 base.Owner 也是 Player
            case "AddCardGlobal":
            case "TransformCardGlobal":
            case "RemoveCardGlobal":
            case "UpgradeCardGlobal":
                EmitGlobalCardEffect(w, e, "base.Owner", p: p);
                break;

                case "CardReward":
                    EmitCardReward(w, e, "base.Owner");
                    break;

            case "Damage":
                // 「生成调试日志」（V0.2.142，默认关）：目标 + 实际数值。
                // ⚠ 目标是自己的药水本来就不造成伤害 —— 那一条不写日志（免得日志说打了、其实没打）。
                if (potionTarget != "Self")
                    DebugLogGen.Target(w, e, PotionAttackTargetExpr(potionTarget, allEnemies), amt, inLoop: false);
                if (potionTarget == "AllEnemies")
                    w.Line($"await CreatureCmd.Damage(choiceContext, {allEnemies}, {amt}, ValueProp.Move, base.Owner.Creature);");
                else if (potionTarget == "AnyEnemy")
                    w.Line($"await CreatureCmd.Damage(choiceContext, target, {amt}, ValueProp.Move, base.Owner.Creature);");
                else
                    w.Line("// 目标是自己的药水不会造成伤害");
                break;
            case "Block":
                DebugLogGen.Target(w, e, PotionAttackTargetExpr(potionTarget, allEnemies),
                    IsNegativeAmount(e, useX: false) ? AbsExpr(amt) : blockAmt,
                    inLoop: potionTarget == "AllEnemies");
                EmitPotionPerCreature(w, potionTarget, allEnemies,
                    c => IsNegativeAmount(e, useX: false)
                        ? $"await CreatureCmd.LoseBlock(choiceContext, {c}, {AbsExpr(amt)}, base.Owner.Creature);   // 负数 = 失去格挡"
                        : $"await CreatureCmd.GainBlock({c}, {blockAmt}, ValueProp.Move, null);");
                break;
            case "Draw":
                w.Line($"await CardPileCmd.Draw(choiceContext, {amt}, base.Owner);");
                break;
            case "Energy":
                if (e.NextTurn)
                    // 下回合生效：负数（下回合少 N 点）用生成的负债 Power —— 本体 EnergyNextTurnPower 忽略负数
                    w.Line(IsNegativeAmount(e, useX: false)
                        ? $"await PowerCmd.Apply<{Naming.From(p).EnergyNextTurnDebtPowerClass}>(choiceContext, base.Owner.Creature, {AbsExpr(amt)}, base.Owner.Creature, null);   // 下回合少 N 点能量"
                        : $"await PowerCmd.Apply<EnergyNextTurnPower>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                else
                    w.Line(GainEnergyLine(e, amt, useX: false, "base.Owner"));
                break;
            case "Heal":
                DebugLogGen.Target(w, e, PotionAttackTargetExpr(potionTarget, allEnemies),
                    e.Amount < 0 ? Lit.Dec(-e.Amount) : amt, inLoop: potionTarget == "AllEnemies");
                if (e.Amount < 0)
                    EmitPotionPerCreature(w, potionTarget, allEnemies,
                        c => $"await CreatureCmd.Damage(choiceContext, {c}, {-e.Amount}, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move, null, null);");
                else
                    EmitPotionPerCreature(w, potionTarget, allEnemies, c => $"await CreatureCmd.Heal({c}, {amt});");
                break;
            case "HpLoss":
                DebugLogGen.Target(w, e, PotionAttackTargetExpr(potionTarget, allEnemies), amt, inLoop: potionTarget == "AllEnemies");
                EmitPotionPerCreature(w, potionTarget, allEnemies,
                    c => $"await CreatureCmd.Damage(choiceContext, {c}, {amt}, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move, null, null);");
                break;
            case "MaxHp":
                DebugLogGen.Target(w, e, PotionAttackTargetExpr(potionTarget, allEnemies),
                    e.Amount < 0 ? Lit.Dec(-e.Amount) : amt, inLoop: potionTarget == "AllEnemies");
                if (e.Amount < 0)
                    EmitPotionPerCreature(w, potionTarget, allEnemies,
                        c => $"await CreatureCmd.LoseMaxHp(choiceContext, {c}, {-e.Amount}, isFromCard: false);");
                else
                    EmitPotionPerCreature(w, potionTarget, allEnemies, c => $"await CreatureCmd.GainMaxHp({c}, {amt});");
                break;
            case "Gold":
                w.Line(GainGoldLine(e, amt, useX: false, "base.Owner"));
                break;
            case "ExtraResource":
                // 额外资源量 = 本体的星星资源。药水没有费用概念，负数直接扣（不会扣成负数）。
                // 下回合生效：正数走本体的 StarNextTurnPower（它的 GainStars 拒绝负数）。
                if (e.NextTurn && e.Amount > 0)
                    w.Line($"await PowerCmd.Apply<StarNextTurnPower>(choiceContext, base.Owner.Creature, {Lit.Dec(e.Amount)}, base.Owner.Creature, null);   // 下回合开始时获得 {Lit.Dec(e.Amount)} 点额外资源量");
                else if (e.Amount >= 0)
                    w.Line($"await PlayerCmd.GainStars({Lit.Dec(e.Amount)}, base.Owner);");
                else
                    w.Line($"await PlayerCmd.SetStars(System.Math.Max(0m, (decimal)base.Owner.PlayerCombatState.Stars - {Lit.Dec(-e.Amount)}), base.Owner);");
                break;
            case "ApplyPower":
                if (potionTarget == "AllEnemies")
                {
                    w.Open($"foreach (Creature foe in {allEnemies})")
                     .Line(ApplyPowerInstr(e, useX: false, e.PowerId, "foe", amt, "base.Owner.Creature", cardSourceExpr: "null"));
                    if (IsSlowPercentEffect(e))
                        w.Line($"SlowPowerHelper.SetPercent(foe, {e.SlowPercentEffective});   // 本体「缓慢」：直接设成 {e.SlowPercentEffective}%");
                    w.Close();
                }
                else if (potionTarget == "AnyEnemy")
                {
                    w.Line(ApplyPowerInstr(e, useX: false, e.PowerId, "target", amt, "base.Owner.Creature", cardSourceExpr: "null"));
                    EmitSlowPercentFix(w, e, "target");
                }
                else
                {
                    w.Line(ApplyPowerInstr(e, useX: false, e.PowerId, "base.Owner.Creature", amt, "base.Owner.Creature", cardSourceExpr: "null"));
                    EmitSlowPercentFix(w, e, "base.Owner.Creature");
                }
                break;

            // ===== 临时增益：药水也能用（本回合 +X，回合结束撤掉）=====
            case "TempPower":
                // 「生成调试日志」（V0.2.142，默认关）：目标 + 实际施加的层数
                DebugLogGen.Target(w, e, PotionAttackTargetExpr(potionTarget, allEnemies), amt, inLoop: potionTarget == "AllEnemies");
                if (potionTarget == "AllEnemies")
                {
                    w.Open($"foreach (Creature foe in {allEnemies})")
                     .Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, foe, {amt}, base.Owner.Creature, null);")
                     .Close();
                }
                else if (potionTarget == "AnyEnemy")
                {
                    w.Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, target, {amt}, base.Owner.Creature, null);");
                }
                else
                {
                    w.Line($"await PowerCmd.Apply<{TempPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                }
                break;

            // ===== 给予卡牌关键词：药水也能用（数值 0 在药水上没有意义）=====
            case "GiveKeyword":
                EmitGiveKeyword(w, p, e, useX: false, "base.Owner", "base.Owner.Creature", "null", selfAllowed: false);
                break;

            // ===== 强化指定卡牌：药水也能挂 =====
            case "BoostCard":
                w.Line(BoostMarker(e));
                w.Line($"await PowerCmd.Apply<{BoostPowerClassName(e, p)}>(choiceContext, base.Owner.Creature, {amt}, base.Owner.Creature, null);");
                break;

            // ===== 复制卡牌：药水也能用（喝药水复制手里的牌，本体「二刀流」那套）=====
            case "CopyCard":
                EmitCopyCard(w, p, e);
                break;

            // ===== 重放卡牌：药水也能用（本体「士兵炖菜 SoldiersStew」就是药水给一张牌重放）=====
            case "ReplayCard":
                EmitReplayCard(w, p, e);
                break;

            // ===== 回合结束时自动打出：药水上只能填 1 以上（数值 0 = 这张牌自己，药水没有「自己」）=====
            case "TurnEndPlay":
                EmitTurnEndPlay(w, e, p, selfExpr: null, cardSource: "null");
                break;

            // ===== 击晕：药水也能用（按药水的「作用目标」打）=====
            case "Stun":
                if (potionTarget == "AllEnemies")
                    w.Open($"foreach (Creature foe in {allEnemies})")
                     .Line("await CreatureCmd.Stun(foe);")
                     .Close();
                else if (potionTarget == "AnyEnemy")
                    w.Open("if (target is not null)")
                     .Line("await CreatureCmd.Stun(target);")
                     .Close();
                else
                    w.Line("await CreatureCmd.Stun(base.Owner.Creature);");
                break;

            // ===== 召唤伙伴：药水不支持 =====
            // 药水的 base.Owner 也是 Player，技术上能召唤；但本工具**故意不做**（用户要求本档只支持卡牌 + 遗物触发），
            // 所以这里必须留一行注释而不是让 switch 静默落空 —— 否则用户配了「喝药水召唤伙伴」会以为生效了。
            case "SummonPet":
                Warn(w, e, "（「召唤伙伴」只支持卡牌与遗物触发；药水不支持 —— 请改用卡牌或遗物）");
                break;

            case "PetAttack":
            case "PetDamageByMaxHp":
            case "PetDamageByCurHp":
            case "PetDamageByMissingHp":
            case "PetHeal":
            case "PetLoseHp":
            case "PetGainMaxHp":
            case "PetSacrifice":
            case "PetApplyPower":
            case "PetGuardOn":
            case "PetGuardOff":
                Warn(w, e, "（这一档的宠物效果只支持卡牌 —— 药水没有「玩家选中的目标」，请改用卡牌）");
                break;

            // ===== 兜底：这个效果种类在药水上没做（和遗物那条链同一个坑，说明见 EmitRelicEffectOnce 的 default）=====
            default:
                WarnUnsupportedKind(w, e, "药水");
                break;
        }
    }
}




